# ---- persistence helpers ---------------------------------------------------

_FILE_LOCK = threading.RLock()
_CHATS_TX_LOCK = threading.RLock()


class _ChatSnapshot(dict):
    """Revision-aware chats.json snapshot.

    Callers treat ``get_chats()`` as a mutable dict and later call
    ``save_json(CHATS_FILE, chats)``. This subclass keeps that contract while
    remembering the baseline needed to merge independent chat updates at save
    time."""
    def __init__(self, value: dict):
        super().__init__(value)
        self._baseline_chats = copy.deepcopy(value.get("chats", {}))
        self._baseline_order = list(value.get("order", []))


def _chat_payload_digest(value: Any) -> str:
    """Stable digest excluding the internal revision counter."""
    if value is None:
        return "<missing>"
    try:
        payload = copy.deepcopy(value)
        if isinstance(payload, dict):
            payload.pop("_rev", None)
        raw = json.dumps(payload, sort_keys=True, separators=(",", ":"),
                         ensure_ascii=False, default=str)
    except Exception:
        raw = repr(value)
    return hashlib.sha256(raw.encode("utf-8", "replace")).hexdigest()


def _normalize_composer_mode(value: Any) -> str:
    """Collapse the retired Auto composer mode to its real behavior: Agent."""
    mode = str(value or "").strip().lower()
    return mode if mode in {"ide", "research"} else "agent"


def _normalize_chats_data(value: Any) -> dict:
    if not isinstance(value, dict):
        value = {"chats": {}, "order": []}
    value.setdefault("chats", {})
    value.setdefault("order", [])
    if not isinstance(value["chats"], dict):
        value["chats"] = {}
    if not isinstance(value["order"], list):
        value["order"] = []
    # Self-heal: drop order ids with no record and collapse duplicate entries to
    # the first occurrence (a duplicate rendered as two rows that deleted together).
    seen: set = set()
    clean_order = []
    for cid in value["order"]:
        if cid in seen or cid not in value["chats"]:
            continue
        seen.add(cid)
        clean_order.append(cid)
    value["order"] = clean_order
    for cid, record in value["chats"].items():
        if not isinstance(record, dict):
            continue
        if not str(record.get("title") or "").strip():
            record["title"] = "new session"
        record.setdefault("id", cid)
        record.setdefault("messages", [])
        if not isinstance(record.get("messages"), list):
            record["messages"] = []
    for record in value["chats"].values():
        if isinstance(record, dict) and "last_mode" in record:
            record["last_mode"] = _normalize_composer_mode(record.get("last_mode"))
    return value


def _write_json_atomic_unlocked(path: Path, value: Any) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(value, indent=2, ensure_ascii=False), encoding="utf-8")
    # Keep the last good settings.json beside it (.prev): a component that writes
    # a stripped document would otherwise lose the model folder and context.
    if path == SETTINGS_FILE:
        try:
            prev = path.with_suffix(path.suffix + ".prev")
            if path.is_file() and path.stat().st_size > 0:
                content = path.read_text(encoding="utf-8", errors="replace")
                if content.strip() and content != json.dumps(value, ensure_ascii=False, indent=2):
                    prev.write_text(content, encoding="utf-8")
                else:
                    pass
        except Exception:
            pass
    tmp.replace(path)


def _save_chats_snapshot(snapshot: _ChatSnapshot) -> None:
    """Merge only locally-changed chats into the latest on-disk document.

    This prevents chat A's older snapshot from erasing chat B after concurrent
    turns. Same-chat turns are separately single-flight; if a UI mutation races
    an active turn we retain both message histories when one is a prefix and
    otherwise keep the most recent snapshot while recording the conflict.
    """
    with _CHATS_TX_LOCK, _FILE_LOCK:
        current = _normalize_chats_data(load_json(CHATS_FILE, {"chats": {}, "order": []}))
        merged = copy.deepcopy(current)
        base_chats = getattr(snapshot, "_baseline_chats", {}) or {}
        snap_chats = snapshot.get("chats", {}) if isinstance(snapshot.get("chats"), dict) else {}
        current_chats = current.get("chats", {})
        merged_chats = merged.setdefault("chats", {})
        changed_ids = {
            cid for cid in set(base_chats) | set(snap_chats)
            if _chat_payload_digest(base_chats.get(cid)) != _chat_payload_digest(snap_chats.get(cid))
        }
        conflicts = []
        for cid in changed_ids:
            before = base_chats.get(cid)
            proposed = snap_chats.get(cid)
            live = current_chats.get(cid)
            live_changed = _chat_payload_digest(live) != _chat_payload_digest(before)
            if proposed is None:
                # A delete wins only when the chat did not gain new work after
                # this snapshot was loaded. Otherwise preserve the live chat.
                if not live_changed:
                    merged_chats.pop(cid, None)
                else:
                    conflicts.append({"chat_id": cid, "kind": "delete_vs_update"})
                continue
            chosen = copy.deepcopy(proposed)
            if live_changed and isinstance(live, dict):
                pmsgs = chosen.get("messages") if isinstance(chosen.get("messages"), list) else []
                lmsgs = live.get("messages") if isinstance(live.get("messages"), list) else []
                # Preserve an independently-appended tail where histories share
                # an exact prefix. Same-chat generation is single-flight, so
                # this mostly covers rename/pin/settings-style UI mutations.
                if len(pmsgs) <= len(lmsgs) and pmsgs == lmsgs[:len(pmsgs)]:
                    for key, val in chosen.items():
                        if key != "messages":
                            live[key] = copy.deepcopy(val)
                    chosen = copy.deepcopy(live)
                elif len(lmsgs) <= len(pmsgs) and lmsgs == pmsgs[:len(lmsgs)]:
                    pass
                else:
                    conflicts.append({"chat_id": cid, "kind": "divergent_update"})
            chosen["_rev"] = max(
                int((live or {}).get("_rev", 0) or 0) if isinstance(live, dict) else 0,
                int((before or {}).get("_rev", 0) or 0) if isinstance(before, dict) else 0,
            ) + 1
            merged_chats[cid] = chosen

        base_order = getattr(snapshot, "_baseline_order", []) or []
        snap_order = snapshot.get("order", []) if isinstance(snapshot.get("order"), list) else []
        if snap_order != base_order:
            deleted = set(base_chats) - set(snap_chats)
            order = []
            for cid in snap_order:
                if cid in merged_chats and cid not in order:
                    order.append(cid)
            order.extend(cid for cid in current.get("order", [])
                         if cid in merged_chats and cid not in order and cid not in deleted)
            order.extend(cid for cid in merged_chats if cid not in order)
            merged["order"] = order
        else:
            merged["order"] = [cid for cid in current.get("order", []) if cid in merged_chats]
            merged["order"].extend(cid for cid in merged_chats if cid not in merged["order"])
        if conflicts:
            conflict_file = DATA / "chat_conflicts.jsonl"
            try:
                with conflict_file.open("a", encoding="utf-8") as fh:
                    for row in conflicts:
                        fh.write(json.dumps({**row, "ts": int(time.time())}) + "\n")
            except Exception:
                pass
        _write_json_atomic_unlocked(CHATS_FILE, merged)
        # A caller may save the same snapshot more than once (pre-turn fold,
        # mission seed, final persist). Advance its baseline after each save so
        # later writes contain only changes made since this successful commit.
        for cid, row in merged_chats.items():
            if cid in snap_chats and isinstance(snap_chats[cid], dict):
                snap_chats[cid]["_rev"] = row.get("_rev", snap_chats[cid].get("_rev", 0))
        snapshot._baseline_chats = copy.deepcopy(snap_chats)
        snapshot._baseline_order = list(snap_order)


def load_json(path: Path, default: Any) -> Any:
    with _FILE_LOCK:
        if not path.exists():
            return default
        try:
            return json.loads(path.read_text(encoding="utf-8"))
        except Exception as e:
        # Rename a corrupt file aside (.corrupt-<ts>) instead of silently returning
        # the default, so a half-written chats.json can still be salvaged.
            try:
                ts = time.strftime("%Y%m%d-%H%M%S")
                bak = path.with_name(f"{path.name}.corrupt-{ts}")
                path.rename(bak)
                print(f"[load_json] corrupt: {path} -> {bak.name} ({e!r})", file=sys.stderr)
            except Exception as e2:
                print(f"[load_json] corrupt + rename failed: {path} ({e!r}; rename: {e2!r})", file=sys.stderr)
            return default


def save_json(path: Path, value: Any) -> None:
    if path == CHATS_FILE and isinstance(value, _ChatSnapshot):
        _save_chats_snapshot(value)
        return
    with _FILE_LOCK:
        _write_json_atomic_unlocked(path, value)


# ---- public release checks -------------------------------------------------
# This is intentionally anonymous. One bridge instance checks GitHub and every
# browser connected to it reads the same cached result.
_UPDATE_CHECK_LOCK = threading.Lock()
_shutdown_ready = threading.Event()
_UPDATE_AUTO_TTL_S = 12 * 60 * 60
_UPDATE_MANUAL_COOLDOWN_S = 5 * 60
_UPDATE_ERROR_RETRY_S = 30 * 60
_UPDATE_REPO = "mkultraware/accuretta"
_UPDATE_API_URL = f"https://api.github.com/repos/{_UPDATE_REPO}/releases/latest"
_UPDATE_RELEASES_URL = f"https://github.com/{_UPDATE_REPO}/releases/latest"


def _app_version() -> str:
    """Read the visible app version so the splash/UI remains the source."""
    try:
        html = (ROOT / "index.html").read_text(encoding="utf-8")
        match = re.search(r'id=["\']brand-v["\'][^>]*>\s*v?([^<\s]+)', html)
        if match:
            return match.group(1)
    except Exception:
        pass
    return "0.0.0"


def _version_key(value: str) -> tuple:
    """Comparable SemVer-like key. Stable releases sort after prereleases."""
    match = re.search(r"(\d+)\.(\d+)\.(\d+)(?:[-+]([^\s]+))?", str(value or ""))
    if not match:
        return (0, 0, 0, 0, "")
    major, minor, patch = (int(match.group(i)) for i in range(1, 4))
    prerelease = match.group(4) or ""
    return (major, minor, patch, 1 if not prerelease else 0, prerelease)


def _release_summary(body: str, name: str, tag: str) -> str:
    """Return one short plain-text line from GitHub release notes."""
    for raw in str(body or "").splitlines():
        line = raw.strip()
        if not line or line.startswith(("#", "![", "<!--")):
            continue
        line = re.sub(r"^[-*+]\s+", "", line)
        line = re.sub(r"\[([^]]+)]\([^)]+\)", r"\1", line)
        line = re.sub(r"[`*_~>]", "", line).strip()
        if line:
            return line[:177].rstrip() + ("..." if len(line) > 177 else "")
    clean_name = str(name or "").strip()
    if clean_name and clean_name.lower() != str(tag or "").strip().lower():
        return clean_name[:180]
    return "A new Accuretta release is ready."


def _update_response(cache: dict, *, cached: bool, now: float) -> dict:
    current = _app_version()
    release = cache.get("release") if isinstance(cache.get("release"), dict) else None
    latest = (release or {}).get("version") or ""
    return {
        "ok": not bool(cache.get("error")),
        "current_version": current,
        "available": bool(release and _version_key(latest) > _version_key(current)),
        "release": release,
        "cached": cached,
        "checked_at": int(cache.get("checked_at") or 0),
        "next_check_at": int(cache.get("next_allowed_at") or 0),
        "rate_limited": bool(cache.get("rate_limited")),
        "error": str(cache.get("error") or ""),
        "server_time": int(now),
    }


def app_update_status(manual: bool = False, now: float | None = None) -> dict:
    """Check the latest public GitHub release with a durable rate-safe cache."""
    now = float(time.time() if now is None else now)
    if _offline_active:
        return {"ok": True, "available": False, "offline": True, "current_version": _app_version()}
    with _UPDATE_CHECK_LOCK:
        cache = load_json(UPDATE_CHECK_FILE, {})
        if not isinstance(cache, dict):
            cache = {}

        next_allowed = float(cache.get("next_allowed_at") or 0)
        if next_allowed > now:
            return _update_response(cache, cached=True, now=now)

        last_request = float(cache.get("last_request_at") or 0)
        checked_at = float(cache.get("checked_at") or 0)
        if manual and last_request and now - last_request < _UPDATE_MANUAL_COOLDOWN_S:
            return _update_response(cache, cached=True, now=now)
        if not manual and checked_at and now - checked_at < _UPDATE_AUTO_TTL_S:
            return _update_response(cache, cached=True, now=now)

        headers = {
            "Accept": "application/vnd.github+json",
            "User-Agent": f"Accuretta/{_app_version()}",
            "X-GitHub-Api-Version": "2022-11-28",
        }
        if cache.get("etag"):
            headers["If-None-Match"] = str(cache["etag"])
        request = urllib.request.Request(_UPDATE_API_URL, headers=headers)
        cache["last_request_at"] = int(now)
        try:
            with urllib.request.urlopen(request, timeout=6.0) as response:
                payload = json.loads(response.read().decode("utf-8"))
                tag = str(payload.get("tag_name") or "").strip()
                version_match = re.search(r"\d+\.\d+\.\d+(?:[-+][^\s]+)?", tag)
                if not version_match:
                    raise ValueError("latest release has no valid version tag")
                version = version_match.group(0)
                release_url = str(payload.get("html_url") or "")
                expected_prefix = f"https://github.com/{_UPDATE_REPO}/releases/"
                if not release_url.startswith(expected_prefix):
                    release_url = _UPDATE_RELEASES_URL
                cache.update({
                    "checked_at": int(now),
                    "next_allowed_at": 0,
                    "rate_limited": False,
                    "error": "",
                    "etag": response.headers.get("ETag") or "",
                    "release": {
                        "version": version,
                        "tag": tag,
                        "name": str(payload.get("name") or tag)[:180],
                        "summary": _release_summary(payload.get("body") or "", payload.get("name") or "", tag),
                        "url": release_url,
                        "published_at": str(payload.get("published_at") or ""),
                    },
                })
        except urllib.error.HTTPError as exc:
            if exc.code == 304 and cache.get("release"):
                cache.update({"checked_at": int(now), "next_allowed_at": 0,
                              "rate_limited": False, "error": ""})
            elif exc.code == 404:
                # A valid public repository with no published release yet.
                cache.update({"checked_at": int(now), "next_allowed_at": 0,
                              "rate_limited": False, "error": "", "release": None})
            elif exc.code in (403, 429):
                retry_after = exc.headers.get("Retry-After")
                reset_at = exc.headers.get("X-RateLimit-Reset")
                try:
                    blocked_until = now + max(1, int(retry_after)) if retry_after else float(reset_at or 0)
                except (TypeError, ValueError):
                    blocked_until = 0
                if blocked_until <= now:
                    blocked_until = now + 60 * 60
                cache.update({
                    "next_allowed_at": int(blocked_until),
                    "rate_limited": True,
                    "error": "GitHub rate limit reached",
                })
            else:
                cache.update({"next_allowed_at": int(now + _UPDATE_ERROR_RETRY_S),
                              "rate_limited": False, "error": f"GitHub returned {exc.code}"})
        except Exception as exc:
            cache.update({"next_allowed_at": int(now + _UPDATE_ERROR_RETRY_S),
                          "rate_limited": False, "error": str(exc)[:180]})

        save_json(UPDATE_CHECK_FILE, cache)
        return _update_response(cache, cached=False, now=now)


# ---- lifetime savings counters --------------------------------------------
# The "saved vs cloud" totals are persisted here, next to chats.json, and read
# over /api/savings: localStorage is per-browser and wiped by the desktop
# webview's private mode. Tokens only; cost is priced client-side from the
# selected provider, so switching provider re-prices the whole history.
_SAVINGS_LOCK = threading.Lock()
_savings_cache: dict | None = None
_SAVINGS_DEFAULT = {"tok_in": 0, "tok_out": 0, "turns": 0, "since": 0}
_MODEL_RUNTIME_LOCK = threading.Lock()


def _savings_ensure_locked() -> None:
    """Load savings.json into the cache once. Caller must hold _SAVINGS_LOCK."""
    global _savings_cache
    if _savings_cache is not None:
        return
    data = load_json(SAVINGS_FILE, None)
    if not isinstance(data, dict):
        data = dict(_SAVINGS_DEFAULT)
    else:
        for k, v in _SAVINGS_DEFAULT.items():
            data.setdefault(k, v)
    if not data.get("since"):
        data["since"] = int(time.time())   # first-ever run: stamp the start date
    _savings_cache = data


def _savings_get() -> dict:
    with _SAVINGS_LOCK:
        _savings_ensure_locked()
        return dict(_savings_cache)


def _savings_add(tok_in: int, tok_out: int, *, count_turn: bool = True) -> dict:
    """Add tokens to the lifetime counters and persist. Returns a copy of the
    new totals. Never raises. Side calls (sub-agents, compaction, image
    descriptions) pass count_turn=False: their tokens count, but they are not
    model turns the owner took."""
    try:
        ti = max(0, int(tok_in or 0))
        to = max(0, int(tok_out or 0))
    except (TypeError, ValueError):
        ti = to = 0
    with _SAVINGS_LOCK:
        _savings_ensure_locked()
        _savings_cache["tok_in"] += ti
        _savings_cache["tok_out"] += to
        if count_turn and (ti or to):
            _savings_cache["turns"] += 1
        snap = dict(_savings_cache)
    try:
        save_json(SAVINGS_FILE, snap)   # its own lock; keep it out of _SAVINGS_LOCK
    except Exception:
        pass
    return snap


def _savings_note_completion(data) -> None:
    """Count a non-streamed llama-server completion (compaction summary,
    image description, sub-agent step, ...) into the lifetime counter.
    llama-server's usage.prompt_tokens is the whole prompt, cached prefix
    included; timings are the fallback for builds that omit usage."""
    try:
        if not isinstance(data, dict):
            return
        usage = data.get("usage") or {}
        timings = data.get("timings") or {}
        tok_in = int(usage.get("prompt_tokens") or 0)
        if not tok_in and timings:
            tok_in = int(timings.get("cache_n") or 0) + int(timings.get("prompt_n") or 0)
        tok_out = int(usage.get("completion_tokens") or timings.get("predicted_n") or 0)
        if tok_in or tok_out:
            _savings_add(tok_in, tok_out, count_turn=False)
    except Exception:
        pass


def _model_profile_key(model: str) -> str:
    name = Path(str(model or "unknown")).name or "unknown"
    return name[:180]


_MODEL_ADVISOR_BASELINE_TURNS = 25
_MODEL_ADVISOR_BASELINE_SESSIONS = 3
_MODEL_ADVISOR_TRIAL_TURNS = 10
_MODEL_ADVISOR_TRIAL_MAX_AGE_S = 7 * 24 * 3600   # a measuring trial left idle for a week closes itself silently
_MODEL_ADVISOR_OBSERVATION_CAP = 80
_MODEL_ADVISOR_CONFIG_KEYS = (
    "num_ctx", "num_gpu", "num_batch", "n_ubatch", "n_cpu_moe",
    "num_thread", "n_parallel", "kv_cache_type", "kv_cache_type_v",
    "flash_attn", "spec_strategy",
)
# Newer tuner outputs. They join the config snapshot only when set (non-zero),
# so configs recorded before they existed keep their signature and history.
_MODEL_ADVISOR_OPTIONAL_KEYS = ("spec_draft_n_max", "moe_cache_mib")
# What the running llama-server was actually launched with, where settings
# alone can't say (spec_draft_n_max 0 = "auto"). Set at spawn, recorded with
# every turn so speed calibration knows which draft length produced it.
_RUNTIME_LAUNCH: dict = {"spec_draft_n": 0}
_MODEL_ADVISOR_APPLY_KEYS = set(_MODEL_ADVISOR_CONFIG_KEYS) | set(_MODEL_ADVISOR_OPTIONAL_KEYS)
_MODEL_ADVISOR_LABELS = {
    "num_ctx": "Context window", "num_gpu": "GPU layers",
    "num_batch": "Batch size", "n_ubatch": "Micro-batch",
    "n_cpu_moe": "CPU MoE experts", "num_thread": "CPU threads",
    "n_parallel": "Parallel sequences", "kv_cache_type": "KV cache",
    "kv_cache_type_v": "V cache", "flash_attn": "Flash attention",
    "spec_strategy": "Speculative decoding",
    "spec_draft_n_max": "Draft length", "moe_cache_mib": "MoE expert cache",
}


def _model_runtime_config(settings: dict | None = None) -> dict:
    """Small content-free snapshot used to keep unlike configurations apart."""
    s = settings if isinstance(settings, dict) else get_settings()
    out = {}
    for key in _MODEL_ADVISOR_CONFIG_KEYS:
        value = s.get(key)
        if isinstance(value, bool):
            out[key] = value
        elif key in {"kv_cache_type", "kv_cache_type_v", "spec_strategy"}:
            out[key] = str(value or "")[:40]
        else:
            try:
                out[key] = int(value or 0)
            except (TypeError, ValueError):
                out[key] = 0
    for key in _MODEL_ADVISOR_OPTIONAL_KEYS:
        try:
            value = int(s.get(key) or 0)
        except (TypeError, ValueError):
            value = 0
        if value:
            out[key] = value
    # "auto" draft length: record the length the server was launched with.
    # An explicit spec_draft_n_max is already in the snapshot above.
    if (out.get("spec_strategy") == "draft-mtp" and not out.get("spec_draft_n_max")
            and _RUNTIME_LAUNCH.get("spec_draft_n")):
        out["spec_draft_n_eff"] = int(_RUNTIME_LAUNCH["spec_draft_n"])
    return out


def _model_config_signature(snapshot: dict) -> str:
    raw = json.dumps(snapshot or {}, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]


_HARNESS_INTERVENTION_KEYS = (
    "context_retry", "server_retry", "reasoning_guard", "tool_call_repair",
    "empty_reply_retry", "auto_continue", "loop_guard",
)


def _sanitize_interventions(value) -> dict[str, int]:
    source = value if isinstance(value, dict) else {}
    return {
        key: max(0, int(source.get(key, 0) or 0))
        for key in _HARNESS_INTERVENTION_KEYS
    }


def _model_observed(row: dict, observations: list[dict] | None = None) -> dict:
    source = observations if observations is not None else None
    if source is not None:
        turns = len(source)
        completed = sum(int(bool(x.get("completed"))) for x in source)
        prompt_tokens = sum(max(0, int(x.get("prompt_tokens", 0) or 0)) for x in source)
        output_tokens = sum(max(0, int(x.get("output_tokens", 0) or 0)) for x in source)
        rounds = sum(max(0, int(x.get("rounds", 0) or 0)) for x in source)
        calls = sum(max(0, int(x.get("tool_calls", 0) or 0)) for x in source)
        errors = sum(max(0, int(x.get("tool_errors", 0) or 0)) for x in source)
        fallbacks = sum(int(bool(x.get("native_fallback"))) for x in source)
        elapsed_ms = sum(max(0.0, float(x.get("elapsed_ms", 0) or 0)) for x in source)
        prefill_ms = sum(max(0.0, float(x.get("prefill_ms", 0) or 0)) for x in source)
        eval_ms = sum(max(0.0, float(x.get("eval_ms", 0) or 0)) for x in source)
        peaks = sorted(max(0, int(x.get("peak_context_tokens", 0) or 0)) for x in source)
        compactions = sum(max(0, int(x.get("compactions", 0) or 0)) for x in source)
        compaction_failures = sum(max(0, int(x.get("compaction_failures", 0) or 0)) for x in source)
        interventions = {
            key: sum(_sanitize_interventions(x.get("interventions")).get(key, 0)
                     for x in source)
            for key in _HARNESS_INTERVENTION_KEYS
        }
    else:
        turns = max(0, int(row.get("turns", 0) or 0))
        completed = max(0, int(row.get("completed_turns", 0) or 0))
        prompt_tokens = max(0, int(row.get("prompt_tokens", 0) or 0))
        output_tokens = max(0, int(row.get("output_tokens", 0) or 0))
        rounds = max(0, int(row.get("rounds", 0) or 0))
        calls = max(0, int(row.get("tool_calls", 0) or 0))
        errors = max(0, int(row.get("tool_errors", 0) or 0))
        fallbacks = max(0, int(row.get("native_fallback_turns", 0) or 0))
        elapsed_ms = max(0.0, float(row.get("elapsed_s", 0) or 0)) * 1000.0
        prefill_ms = max(0.0, float(row.get("prefill_ms", 0) or 0))
        eval_ms = max(0.0, float(row.get("eval_ms", 0) or 0))
        peaks = sorted(max(0, int(x.get("peak_context_tokens", 0) or 0))
                       for x in (row.get("observations") or []) if isinstance(x, dict))
        compactions = max(0, int(row.get("compactions", 0) or 0))
        compaction_failures = max(0, int(row.get("compaction_failures", 0) or 0))
        interventions = _sanitize_interventions(row.get("interventions"))
    denom_turns = max(1, turns)
    p90_peak = 0
    if peaks:
        p90_peak = peaks[min(len(peaks) - 1, max(0, math.ceil(len(peaks) * 0.90) - 1))]
    avg_peak = (sum(peaks) / len(peaks)) if peaks else (
        float(row.get("peak_context_sum", 0) or 0) / denom_turns)
    decode_seconds = eval_ms / 1000.0
    prompt_seconds = prefill_ms / 1000.0
    elapsed_seconds = elapsed_ms / 1000.0
    return {
        "completion_rate": round(completed / denom_turns, 3),
        "tool_error_rate": round(errors / max(1, calls), 3),
        "avg_rounds": round(rounds / denom_turns, 2),
        "output_tok_s": round(output_tokens / (decode_seconds or elapsed_seconds or 0.001), 2),
        "prompt_tok_s": round(prompt_tokens / (prompt_seconds or 0.001), 2) if prefill_ms else 0.0,
        "avg_peak_context_tokens": round(avg_peak, 1),
        "p90_peak_context_tokens": int(p90_peak or row.get("peak_context_tokens", 0) or 0),
        "native_fallback_rate": round(fallbacks / denom_turns, 3),
        "compactions": compactions,
        "compaction_failures": compaction_failures,
        "interventions": interventions,
    }


def _record_model_observation(model: str, *, prompt_tokens: int = 0,
                              output_tokens: int = 0, rounds: int = 0,
                              tool_calls: int = 0, tool_errors: int = 0,
                              peak_prompt_tokens: int = 0,
                              elapsed_s: float = 0.0, native_fallback: bool = False,
                              completed: bool = True, chat_id: str = "",
                              prompt_ms: float = 0.0, eval_ms: float = 0.0,
                              draft_n: int = 0, draft_accepted: int = 0,
                              compactions: int = 0,
                              compaction_failures: int = 0,
                              tool_outcomes: list | None = None,
                              interventions: dict | None = None) -> None:
    """Local-only, content-free observations from normal use.

    This replaces a mandatory per-model benchmark. It costs no extra inference,
    stores no prompts/results, and can support later recommendations once enough
    real turns have accumulated.  Each turn is also appended to the long-term
    comparison dataset (MODEL_DATASET_FILE, JSONL): per-turn counters plus
    content-free per-tool-call outcomes (tool name, ok flag, exit code, refusal)
    so models can be compared across weeks of real usage.
    """
    try:
        settings = get_settings()
        if not settings.get("passive_model_telemetry", True):
            return
    except Exception:
        return
    key = _model_profile_key(model)
    config = _model_runtime_config(settings)
    config_key = _model_config_signature(config)
    intervention_counts = _sanitize_interventions(interventions)
    now = int(time.time())
    day = time.strftime("%Y-%m-%d", time.localtime(now))
    # A missing chat id contributes no session attribution instead of collapsing
    # a whole day into one fake "session".
    session_key = hashlib.sha256(str(chat_id).encode("utf-8")).hexdigest()[:12] if chat_id else ""
    with _MODEL_RUNTIME_LOCK:
        data = load_json(MODEL_RUNTIME_FILE, {"version": 2, "models": {}})
        if not isinstance(data, dict):
            data = {"version": 2, "models": {}}
        data["version"] = max(2, int(data.get("version", 1) or 1))
        models = data.setdefault("models", {})
        row = models.setdefault(key, {
            "turns": 0, "completed_turns": 0, "prompt_tokens": 0,
            "output_tokens": 0, "rounds": 0, "tool_calls": 0,
            "tool_errors": 0, "elapsed_s": 0.0, "native_fallback_turns": 0,
            "peak_context_tokens": 0, "peak_context_sum": 0,
        })
        row["turns"] = int(row.get("turns", 0)) + 1
        row["completed_turns"] = int(row.get("completed_turns", 0)) + int(bool(completed))
        row["prompt_tokens"] = int(row.get("prompt_tokens", 0)) + max(0, int(prompt_tokens or 0))
        row["output_tokens"] = int(row.get("output_tokens", 0)) + max(0, int(output_tokens or 0))
        row["rounds"] = int(row.get("rounds", 0)) + max(0, int(rounds or 0))
        row["tool_calls"] = int(row.get("tool_calls", 0)) + max(0, int(tool_calls or 0))
        row["tool_errors"] = int(row.get("tool_errors", 0)) + max(0, int(tool_errors or 0))
        _peak = max(0, int(peak_prompt_tokens or 0))
        row["peak_context_tokens"] = max(int(row.get("peak_context_tokens", 0) or 0), _peak)
        row["peak_context_sum"] = int(row.get("peak_context_sum", 0) or 0) + _peak
        row["elapsed_s"] = round(float(row.get("elapsed_s", 0.0)) + max(0.0, float(elapsed_s or 0)), 3)
        row["prefill_ms"] = round(float(row.get("prefill_ms", 0.0)) + max(0.0, float(prompt_ms or 0)), 3)
        row["eval_ms"] = round(float(row.get("eval_ms", 0.0)) + max(0.0, float(eval_ms or 0)), 3)
        row["compactions"] = int(row.get("compactions", 0) or 0) + max(0, int(compactions or 0))
        row["compaction_failures"] = int(row.get("compaction_failures", 0) or 0) + max(0, int(compaction_failures or 0))
        row_interventions = row.setdefault("interventions", {})
        for intervention, count in intervention_counts.items():
            row_interventions[intervention] = int(row_interventions.get(intervention, 0) or 0) + count
        row["native_fallback_turns"] = int(row.get("native_fallback_turns", 0)) + int(bool(native_fallback))
        row["last_seen"] = now
        row["last_context"] = int(_llama_props_ctx() or settings.get("num_ctx") or 0)
        row["active_config"] = config_key

        configs = row.setdefault("configs", {})
        cfg = configs.setdefault(config_key, {
            "settings": config, "first_seen": now, "turns": 0,
            "completed_turns": 0, "prompt_tokens": 0, "output_tokens": 0,
            "rounds": 0, "tool_calls": 0, "tool_errors": 0,
            "elapsed_s": 0.0, "prefill_ms": 0.0, "eval_ms": 0.0,
            "native_fallback_turns": 0, "peak_context_tokens": 0,
            "peak_context_sum": 0, "compactions": 0,
            "compaction_failures": 0, "sessions": [], "days": [],
            "clients": {}, "observations": [],
        })
        cfg["settings"] = config
        cfg["turns"] = int(cfg.get("turns", 0) or 0) + 1
        cfg["completed_turns"] = int(cfg.get("completed_turns", 0) or 0) + int(bool(completed))
        cfg["prompt_tokens"] = int(cfg.get("prompt_tokens", 0) or 0) + max(0, int(prompt_tokens or 0))
        cfg["output_tokens"] = int(cfg.get("output_tokens", 0) or 0) + max(0, int(output_tokens or 0))
        cfg["rounds"] = int(cfg.get("rounds", 0) or 0) + max(0, int(rounds or 0))
        cfg["tool_calls"] = int(cfg.get("tool_calls", 0) or 0) + max(0, int(tool_calls or 0))
        cfg["tool_errors"] = int(cfg.get("tool_errors", 0) or 0) + max(0, int(tool_errors or 0))
        cfg["elapsed_s"] = round(float(cfg.get("elapsed_s", 0.0)) + max(0.0, float(elapsed_s or 0)), 3)
        cfg["prefill_ms"] = round(float(cfg.get("prefill_ms", 0.0)) + max(0.0, float(prompt_ms or 0)), 3)
        cfg["eval_ms"] = round(float(cfg.get("eval_ms", 0.0)) + max(0.0, float(eval_ms or 0)), 3)
        cfg["native_fallback_turns"] = int(cfg.get("native_fallback_turns", 0) or 0) + int(bool(native_fallback))
        cfg["peak_context_tokens"] = max(int(cfg.get("peak_context_tokens", 0) or 0), _peak)
        cfg["peak_context_sum"] = int(cfg.get("peak_context_sum", 0) or 0) + _peak
        cfg["compactions"] = int(cfg.get("compactions", 0) or 0) + max(0, int(compactions or 0))
        cfg["compaction_failures"] = int(cfg.get("compaction_failures", 0) or 0) + max(0, int(compaction_failures or 0))
        cfg_interventions = cfg.setdefault("interventions", {})
        for intervention, count in intervention_counts.items():
            cfg_interventions[intervention] = int(cfg_interventions.get(intervention, 0) or 0) + count
        cfg["last_seen"] = now
        cfg["last_context"] = row["last_context"]
        sessions = [str(x)[:16] for x in (cfg.get("sessions") or []) if x]
        if session_key and session_key not in sessions:
            sessions.append(session_key)
        cfg["sessions"] = sessions[-24:]
        days = [str(x)[:10] for x in (cfg.get("days") or []) if x]
        if day not in days:
            days.append(day)
        cfg["days"] = days[-30:]
        client = _client_context_by_chat.get(chat_id, {}) if chat_id else {}
        client_key = f"{client.get('os') or 'unknown'}:{'remote' if client.get('remote') else 'local'}"
        clients = cfg.setdefault("clients", {})
        clients[client_key] = int(clients.get(client_key, 0) or 0) + 1
        obs = cfg.setdefault("observations", [])
        obs.append({
            "ts": now, "completed": bool(completed),
            "prompt_tokens": max(0, int(prompt_tokens or 0)),
            "output_tokens": max(0, int(output_tokens or 0)),
            "peak_context_tokens": _peak, "rounds": max(0, int(rounds or 0)),
            "tool_calls": max(0, int(tool_calls or 0)),
            "tool_errors": max(0, int(tool_errors or 0)),
            "elapsed_ms": round(max(0.0, float(elapsed_s or 0)) * 1000.0, 2),
            "prefill_ms": round(max(0.0, float(prompt_ms or 0)), 2),
            "eval_ms": round(max(0.0, float(eval_ms or 0)), 2),
            "draft_n": max(0, int(draft_n or 0)),
            "draft_accepted": max(0, int(draft_accepted or 0)),
            "native_fallback": bool(native_fallback),
            "compactions": max(0, int(compactions or 0)),
            "compaction_failures": max(0, int(compaction_failures or 0)),
            "interventions": intervention_counts,
        })
        cfg["observations"] = obs[-_MODEL_ADVISOR_OBSERVATION_CAP:]
        _append_model_dataset({
            "v": 1,
            "ts": now,
            "day": day,
            "model": key,
            "config": config_key,
            "session": session_key,
            "client": client_key,
            "completed": bool(completed),
            "rounds": max(0, int(rounds or 0)),
            "prompt_tokens": max(0, int(prompt_tokens or 0)),
            "output_tokens": max(0, int(output_tokens or 0)),
            "elapsed_ms": round(max(0.0, float(elapsed_s or 0)) * 1000.0, 2),
            "prefill_ms": round(max(0.0, float(prompt_ms or 0)), 2),
            "eval_ms": round(max(0.0, float(eval_ms or 0)), 2),
            "peak_context_tokens": _peak,
            "native_fallback": bool(native_fallback),
            "compactions": max(0, int(compactions or 0)),
            "compaction_failures": max(0, int(compaction_failures or 0)),
            "tool_calls": max(0, int(tool_calls or 0)),
            "tool_errors": max(0, int(tool_errors or 0)),
            "interventions": intervention_counts,
            "tools": _sanitize_tool_outcomes(tool_outcomes),
        })
        save_json(MODEL_RUNTIME_FILE, data)


def _sanitize_tool_outcomes(tool_outcomes) -> list:
    """Reduce raw tool results to content-free {name, ok, exit_code, refused}.

    Tool arguments and result bodies (file contents, paths, error text) are
    never copied — only the call's identity and its binary/numeric outcome.
    """
    out = []
    try:
        source = tool_outcomes if isinstance(tool_outcomes, list) else []
        for item in source[-_MODEL_ADVISOR_OBSERVATION_CAP:]:
            if not isinstance(item, dict):
                continue
            out.append({
                "name": str(item.get("name") or "unknown")[:80],
                "ok": bool(item.get("ok", True)),
                "exit_code": int(item.get("exit_code", 0) or 0),
                "refused": bool(item.get("refused", False)),
            })
    except Exception:
        return []
    return out


def _append_model_dataset(record: dict) -> None:
    """Append one content-free turn record to the long-term comparison dataset.

    JSONL on purpose: append-only, crash-safe, and trivially tail/aggregate-able
    later.  The file lives under ./data so it is gitignored with everything else
    user-local.  Never allowed to raise — a broken disk must not kill a turn.
    """
    try:
        MODEL_DATASET_FILE.parent.mkdir(parents=True, exist_ok=True)
        with open(MODEL_DATASET_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(record, ensure_ascii=False, separators=(",", ":")) + "\n")
    except Exception:
        pass


def _model_runtime_profiles() -> dict:
    data = load_json(MODEL_RUNTIME_FILE, {"version": 1, "models": {}})
    if not isinstance(data, dict):
        data = {"version": 1, "models": {}}
    out = copy.deepcopy(data)
    for row in (out.get("models") or {}).values():
        turns = max(1, int(row.get("turns", 0) or 0))
        row["observed"] = _model_observed(row)
        for cfg in (row.get("configs") or {}).values():
            if not isinstance(cfg, dict):
                continue
            cfg["observed"] = _model_observed(cfg, cfg.get("observations") or None)
            cfg_turns = int(cfg.get("turns", 0) or 0)
            cfg_sessions = len(cfg.get("sessions") or [])
            cfg["confidence"] = ("high" if cfg_turns >= _MODEL_ADVISOR_BASELINE_TURNS
                                 and cfg_sessions >= _MODEL_ADVISOR_BASELINE_SESSIONS
                                 else "warming_up")
        row["confidence"] = "high" if turns >= 25 else "medium" if turns >= 8 else "warming_up"
        advice = []
        observed = row["observed"]
        ctx = int(row.get("last_context", 0) or 0)
        if turns >= 8:
            if observed["native_fallback_rate"] >= 0.25:
                advice.append("Keep text-tool repair enabled; native tool parsing has required frequent fallback.")
            if observed["completion_rate"] < 0.8:
                advice.append("Keep conservative defaults; incomplete turns are too frequent for automatic aggressiveness increases.")
            if ctx and observed["p90_peak_context_tokens"] >= ctx * 0.82:
                advice.append("Normal work approaches the context ceiling; prefer earlier compaction or smaller active tool bundles.")
            if int(row.get("tool_calls", 0) or 0) >= 8 and observed["tool_error_rate"] >= 0.25:
                advice.append("Tool errors are elevated; inspect capability health and action outcomes before changing model settings.")
        row["advice"] = advice
    return out


def _usage_stats() -> dict:
    """Return content-free aggregates for the local Usage stats page."""
    settings = get_settings()
    telemetry_enabled = bool(settings.get("passive_model_telemetry", True))
    profiles = _model_runtime_profiles().get("models") or {}
    models_dir = str(settings.get("models_dir") or "").strip()
    installed_models: set[str] = set()
    known_paths = set(_models_config())
    known_paths.add(str(settings.get("model_path") or ""))
    if models_dir and safe_exists(models_dir) and safe_is_dir(models_dir):
        for item in scan_gguf_dir(models_dir):
            known_paths.add(str(item.get("path") or ""))
    for model_path in known_paths:
        path = Path(model_path)
        if (model_path and path.suffix.lower() == ".gguf" and safe_exists(path)
                and not safe_is_dir(path) and not _is_mmproj_name(path.name)):
            installed_models.add(path.name.casefold())
            installed_models.add(path.stem.casefold())
    # --- model scoring (two passes) -------------------------------------
    # Score = 0.40 * tool_success + 0.30 * completion + 0.15 * speed
    #         + 0.15 * evidence.
    # Rates are Bayesian-smoothed toward the volume-weighted fleet mean. The
    # evidence term (turn count, diminishing returns) is what keeps a lucky
    # 5-turn 100% run from outranking a 200-turn 95% regular; smoothing alone
    # can't, since the regular sets the fleet mean. Raw rates are still reported.
    _raw_models = []
    for name, row in profiles.items():
        if not isinstance(row, dict):
            continue
        if str(name).casefold() not in installed_models:
            continue
        turns = max(0, int(row.get("turns", 0) or 0))
        if turns < 1:
            continue
        observed = row.get("observed") or _model_observed(row)
        calls = max(0, int(row.get("tool_calls", 0) or 0))
        completion = float(observed.get("completion_rate", 0) or 0)
        tool_success = (1.0 - float(observed.get("tool_error_rate", 0) or 0)) if calls else None
        _raw_models.append({
            "model": str(name)[:180],
            "row": row,
            "observed": observed,
            "turns": turns,
            "completed_turns": max(0, int(row.get("completed_turns", 0) or 0)),
            "completion": min(1.0, max(0.0, completion)),
            "calls": calls,
            "tool_success": None if tool_success is None else min(1.0, max(0.0, tool_success)),
            "speed": max(0.0, float(observed.get("output_tok_s", 0) or 0)),
        })
    _fleet_turns = sum(m["turns"] for m in _raw_models)
    _prior_completion = (sum(m["completion"] * m["turns"] for m in _raw_models) / _fleet_turns
                         if _fleet_turns else 0.8)
    _rated_calls = [(m["tool_success"], m["calls"]) for m in _raw_models if m["tool_success"] is not None]
    _prior_tool = (sum(s * c for s, c in _rated_calls) / sum(c for _, c in _rated_calls)
                   if _rated_calls and sum(c for _, c in _rated_calls) else 0.8)
    _prior_speed = (sum(m["speed"] * m["turns"] for m in _raw_models) / _fleet_turns
                    if _fleet_turns else 0.0)
    _TOOL_PRIOR_CALLS = 50.0
    _COMP_PRIOR_TURNS = 10.0
    _SPEED_PRIOR_TURNS = 5.0
    for m in _raw_models:
        m["smooth_completion"] = ((m["completion"] * m["turns"] + _prior_completion * _COMP_PRIOR_TURNS)
                                  / (m["turns"] + _COMP_PRIOR_TURNS))
        if m["tool_success"] is None:
            m["smooth_tool"] = _prior_tool
        else:
            m["smooth_tool"] = ((m["tool_success"] * m["calls"] + _prior_tool * _TOOL_PRIOR_CALLS)
                                / (m["calls"] + _TOOL_PRIOR_CALLS))
        m["smooth_speed"] = ((m["speed"] * m["turns"] + _prior_speed * _SPEED_PRIOR_TURNS)
                             / (m["turns"] + _SPEED_PRIOR_TURNS))
    _speeds = [m["smooth_speed"] for m in _raw_models]
    _smin, _smax = (min(_speeds), max(_speeds)) if _speeds else (0.0, 0.0)
    _sspread = _smax - _smin
    models = []
    for m in _raw_models:
        turns = m["turns"]
        speed_norm = 1.0 if _sspread <= 0 else (m["smooth_speed"] - _smin) / _sspread
        evidence = turns / (turns + 10.0)  # 5->0.33, 25->0.71, 200->0.95
        reliability = (0.40 * m["smooth_tool"] + 0.30 * m["smooth_completion"]
                       + 0.15 * speed_norm + 0.15 * evidence)
        models.append({
            "model": m["model"],
            "turns": turns,
            "completed_turns": m["completed_turns"],
            "completion_rate": round(m["completion"], 3),
            "tool_calls": m["calls"],
            "tool_success": round(m["tool_success"], 3) if m["tool_success"] is not None else None,
            "output_tok_s": float(m["observed"].get("output_tok_s", 0) or 0),
            "avg_elapsed_ms": round(max(0.0, float(m["row"].get("elapsed_s", 0) or 0)) * 1000 / turns, 1),
            "compactions": max(0, int(m["observed"].get("compactions", 0) or 0)),
            "reliability": round(min(1.0, max(0.0, reliability)), 3),
            "confidence": "high" if turns >= 25 else "medium" if turns >= 8 else "warming_up",
            "ranked": turns >= 5,
        })
    models.sort(key=lambda item: (item["ranked"], item["reliability"], item["turns"]), reverse=True)

    chat_data = get_chats()
    chat_titles = {}
    repo_keys = set()
    repo_names = set()
    repo_sessions = 0
    for chat_id, chat in (chat_data.get("chats") or {}).items():
        if not isinstance(chat, dict):
            continue
        session = hashlib.sha256(str(chat_id).encode("utf-8")).hexdigest()[:12]
        chat_titles[session] = str(chat.get("title") or "Untitled task")[:180]
        worktree = chat.get("github_worktree")
        if not isinstance(worktree, dict):
            continue
        owner = str(worktree.get("owner") or "").strip()
        repo = str(worktree.get("repo") or "").strip()
        if not repo:
            continue
        key = f"{owner}/{repo}" if owner else repo
        repo_keys.add(key.casefold())
        repo_names.add(key)
        repo_sessions += 1
    # Repos pushed to from the app count too — not just branch sessions
    # started through the GitHub tab. Deduped against worktree repos.
    try:
        _pushed = load_json(PUSHED_REPOS_FILE, {})
        _pushed_repos = _pushed.get("repos") if isinstance(_pushed, dict) else None
        if isinstance(_pushed_repos, dict):
            for _k, _e in _pushed_repos.items():
                _name = _e.get("name") if isinstance(_e, dict) else None
                _disp = str(_name or _k or "").strip()[:180]
                if not _disp:
                    continue
                repo_keys.add(_disp.casefold())
                repo_names.add(_disp)
    except Exception:
        pass
    try:
        base_unique = max(0, int(settings.get("repos_baseline_unique", 0) or 0))
    except (TypeError, ValueError):
        base_unique = 0
    try:
        base_sessions = max(0, int(settings.get("repos_baseline_sessions", 0) or 0))
    except (TypeError, ValueError):
        base_sessions = 0

    daily = {}
    longest = None
    dataset_turns = 0
    dataset_input = 0
    dataset_output = 0
    dataset_elapsed = 0.0
    interventions = {key: 0 for key in _HARNESS_INTERVENTION_KEYS}
    try:
        with open(MODEL_DATASET_FILE, "r", encoding="utf-8") as handle:
            for line in handle:
                try:
                    item = json.loads(line)
                except Exception:
                    continue
                if not isinstance(item, dict):
                    continue
                day = str(item.get("day") or "")[:10]
                prompt = max(0, int(item.get("prompt_tokens", 0) or 0))
                output = max(0, int(item.get("output_tokens", 0) or 0))
                elapsed = max(0.0, float(item.get("elapsed_ms", 0) or 0))
                dataset_turns += 1
                dataset_input += prompt
                dataset_output += output
                dataset_elapsed += elapsed
                for key, count in _sanitize_interventions(item.get("interventions")).items():
                    interventions[key] += count
                if re.fullmatch(r"\d{4}-\d{2}-\d{2}", day):
                    bucket = daily.setdefault(day, {"day": day, "turns": 0, "tokens": 0, "elapsed_ms": 0.0})
                    bucket["turns"] += 1
                    bucket["tokens"] += prompt + output
                    bucket["elapsed_ms"] += elapsed
                item_model = str(item.get("model") or "Unknown model")[:180]
                model_is_installed = item_model.casefold() in installed_models
                if model_is_installed and (longest is None or elapsed > longest["elapsed_ms"]):
                    session = str(item.get("session") or "")[:16]
                    longest = {
                        "elapsed_ms": round(elapsed, 1),
                        "model": item_model,
                        "day": day,
                        "title": chat_titles.get(session) or "Chat no longer available",
                        "chat_available": session in chat_titles,
                    }
    except (FileNotFoundError, OSError):
        pass

    today = datetime.date.today()
    chart_days = []
    for offset in range(29, -1, -1):
        day = (today - datetime.timedelta(days=offset)).isoformat()
        bucket = daily.get(day) or {"day": day, "turns": 0, "tokens": 0, "elapsed_ms": 0.0}
        chart_days.append({**bucket, "elapsed_ms": round(float(bucket["elapsed_ms"]), 1)})

    activity_days = []
    for offset in range(364, -1, -1):
        day = (today - datetime.timedelta(days=offset)).isoformat()
        bucket = daily.get(day) or {"day": day, "turns": 0, "tokens": 0, "elapsed_ms": 0.0}
        activity_days.append({**bucket, "elapsed_ms": round(float(bucket["elapsed_ms"]), 1)})

    fold = {"attempts": 0, "successful": 0, "failed": 0, "skipped": 0,
            "folded_messages": 0, "folded_tokens": 0}
    benign = {"tail_too_small", "no_messages", "already_compacted", "below_threshold", "busy"}
    try:
        # utf-8-sig: this append-only file has been seen with a BOM, which makes the
        # first json.loads fail and (errors being swallowed) under-counts every session.
        with open(FOLD_EVENTS_FILE, "r", encoding="utf-8-sig") as handle:
            for line in handle:
                try:
                    item = json.loads(line)
                except Exception:
                    continue
                if not isinstance(item, dict):
                    continue
                fold["attempts"] += 1
                if item.get("ok"):
                    fold["successful"] += 1
                    fold["folded_messages"] += max(0, int(item.get("folded", 0) or 0))
                    fold["folded_tokens"] += max(0, int(item.get("folded_tokens", 0) or 0))
                elif str(item.get("outcome") or "") in benign:
                    fold["skipped"] += 1
                else:
                    fold["failed"] += 1
    except (FileNotFoundError, OSError):
        pass

    savings = _savings_get()
    return {
        "generated_at": int(time.time()),
        "telemetry_enabled": telemetry_enabled,
        "privacy": "Local aggregate counters only. Prompts, replies, paths and tool results are not included.",
        "models": models,
        "daily": chart_days,
        "activity": {"days": activity_days, "timezone": "host local time"},
        "totals": {
            "turns": max(dataset_turns, max(0, int(savings.get("turns", 0) or 0))),
            "input_tokens": max(dataset_input, max(0, int(savings.get("tok_in", 0) or 0))),
            "output_tokens": max(dataset_output, max(0, int(savings.get("tok_out", 0) or 0))),
            "elapsed_ms": round(dataset_elapsed, 1),
            "since": max(0, int(savings.get("since", 0) or 0)),
        },
        "savings": savings,
        "compression": fold,
        "interventions": {
            **interventions,
            "total": sum(interventions.values()),
        },
        "repos": {
            "unique": len(repo_keys) + base_unique,
            "sessions": repo_sessions + base_sessions,
            "names": sorted(repo_names, key=str.casefold)[:12],
        },
        "longest": longest,
        "errors": _error_store.summary(),
    }


def _advisor_suggest_settings(settings: dict, observed: dict) -> dict:
    """Return the hardware planner's exact operational settings, if available."""
    model_path = str(settings.get("model_path") or "").strip()
    if not model_path or not safe_exists(model_path):
        return {}
    try:
        vram = float(settings.get("vram_tier_gb") or 0)
        if vram <= 0:
            vram = _free_vram_gb_for_tune()
        if vram <= 0:
            return {}
        current_ctx = max(8192, int(settings.get("num_ctx") or 8192))
        suggested = auto_tune(
            model_path, vram, profile=inspect_model(model_path), min_ctx=current_ctx,
            proven_cfg=_proven_cfg(model_path))
        return {k: suggested[k] for k in _MODEL_ADVISOR_APPLY_KEYS if k in suggested}
    except Exception:
        return {}


def _advisor_recommendation(model: str, config_key: str, cfg: dict,
                            settings: dict) -> dict | None:
    turns = int(cfg.get("turns", 0) or 0)
    sessions = len(cfg.get("sessions") or [])
    if turns < _MODEL_ADVISOR_BASELINE_TURNS or sessions < _MODEL_ADVISOR_BASELINE_SESSIONS:
        return None
    observed = _model_observed(cfg, cfg.get("observations") or None)
    current = _model_runtime_config(settings)
    suggested = _advisor_suggest_settings(settings, observed)
    updates = {k: v for k, v in suggested.items()
               if k in _MODEL_ADVISOR_APPLY_KEYS and current.get(k) != v}
    if not updates:
        return None
    changes = []
    for key in _MODEL_ADVISOR_CONFIG_KEYS:
        if key not in updates:
            continue
        changes.append({
            "key": key, "label": _MODEL_ADVISOR_LABELS.get(key, key),
            "from": current.get(key), "to": updates[key],
        })
    ctx = max(1, int(current.get("num_ctx", 0) or cfg.get("last_context", 0) or 1))
    peak = int(observed.get("p90_peak_context_tokens", 0) or 0)
    pressure = peak / ctx if ctx else 0
    if "num_ctx" in updates and int(updates["num_ctx"] or 0) > ctx:
        reason = (
            f"Across {turns} turns, busy prompts reached {round(pressure * 100)}% of the current context window. "
            "The model and available memory can support more working room with the settings below."
        )
        tradeoff = "More context uses additional memory and very long prompts take longer to process."
    else:
        reason = (
            f"After {turns} turns across {sessions} sessions, this model has a stable local baseline. "
            "The hardware planner found a better fit than the settings currently loaded."
        )
        tradeoff = "The ten-turn trial checks speed and reliability before Accuretta calls the change an improvement."
    rec_id = hashlib.sha256(json.dumps({
        "model": model, "config": config_key, "updates": updates,
    }, sort_keys=True, default=str).encode("utf-8")).hexdigest()[:18]
    return {
        "id": rec_id, "created_at": int(time.time()), "confidence": "high",
        "reason": reason, "tradeoff": tradeoff, "updates": updates,
        "changes": changes, "turns": turns, "sessions": sessions,
        "notified_at": 0,
    }


def _advisor_trial_public(row: dict, active_config: str) -> dict | None:
    trial = row.get("trial") if isinstance(row.get("trial"), dict) else None
    if not trial or trial.get("status") in {"kept", "rolled_back", "aborted"}:
        return None
    cfg = (row.get("configs") or {}).get(active_config) or {}
    progress = max(0, int(cfg.get("turns", 0) or 0) - int(trial.get("start_turns", 0) or 0))
    status = str(trial.get("status") or "measuring")
    if status == "measuring":
        now = int(time.time())
        if active_config != trial.get("candidate_config"):
            # The user changed settings mid-trial. Never fight them: close the
            # comparison silently and leave their settings exactly as they are.
            trial["status"] = "aborted"
            trial["result"] = ("The model configuration changed while the trial was measuring, "
                               "so the comparison was closed without changing anything.")
            trial["closed_at"] = now
            return None
        if (int(trial.get("applied_at", 0) or 0)
                and now - int(trial.get("applied_at", 0) or 0) > _MODEL_ADVISOR_TRIAL_MAX_AGE_S):
            # Idle trial: the recommended settings stay applied, but no verdict
            # is forced from stale data. Close silently.
            trial["status"] = "aborted"
            trial["result"] = ("The trial expired without enough measured use, "
                               "so the comparison was closed without changing anything.")
            trial["closed_at"] = now
            return None
        elif (active_config == trial.get("candidate_config")
                and progress >= _MODEL_ADVISOR_TRIAL_TURNS):
            recent = [x for x in (cfg.get("observations") or [])
                      if int(x.get("ts", 0) or 0) >= int(trial.get("applied_at", 0) or 0)]
            candidate = _model_observed(cfg, recent[-_MODEL_ADVISOR_TRIAL_TURNS:])
            baseline = trial.get("baseline") or {}
            worse_reasons = []
            if candidate["completion_rate"] + 0.08 < float(baseline.get("completion_rate", 0) or 0):
                worse_reasons.append("more turns failed to finish")
            if candidate["tool_error_rate"] > float(baseline.get("tool_error_rate", 0) or 0) + 0.12:
                worse_reasons.append("tool errors increased")
            old_speed = float(baseline.get("output_tok_s", 0) or 0)
            new_speed = float(candidate.get("output_tok_s", 0) or 0)
            if old_speed > 0 and new_speed > 0 and new_speed < old_speed * 0.82:
                worse_reasons.append("response speed fell by more than 18%")
            status = "worse" if worse_reasons else "stable"
            trial["status"] = status
            trial["candidate"] = candidate
            trial["result"] = ("; ".join(worse_reasons) if worse_reasons
                               else "The ten-turn check found no meaningful loss in speed or reliability.")
            status = str(trial.get("status") or status)
    return {
        "id": str(trial.get("id") or ""), "status": status,
        "progress": min(progress, _MODEL_ADVISOR_TRIAL_TURNS),
        "target": _MODEL_ADVISOR_TRIAL_TURNS,
        "result": str(trial.get("result") or ""),
        "changes": list(trial.get("changes") or []),
    }


def _model_health_action(action: str, recommendation_id: str = "") -> dict:
    action = str(action or "").strip().lower()
    settings = get_settings()
    model = _model_profile_key(settings.get("model_path") or settings.get("model") or "")
    runtime_key = _model_profile_key(settings.get("model") or model)
    active_config = _model_config_signature(_model_runtime_config(settings))
    with _MODEL_RUNTIME_LOCK:
        data = load_json(MODEL_RUNTIME_FILE, {"version": 2, "models": {}})
        models = data.get("models") if isinstance(data, dict) else {}
        row = ((models or {}).get(runtime_key) or (models or {}).get(model) or {})
        cfg = (row.get("configs") or {}).get(active_config) or {}
        rec = cfg.get("recommendation") if isinstance(cfg.get("recommendation"), dict) else None
        if action in {"seen", "dismiss", "apply"}:
            if not rec or (recommendation_id and rec.get("id") != recommendation_id):
                return {"ok": False, "error": "recommendation is no longer current"}
            if action == "seen":
                rec["notified_at"] = int(time.time())
                save_json(MODEL_RUNTIME_FILE, data)
                return {"ok": True}
            if action == "dismiss":
                rec["dismissed_at"] = int(time.time())
                save_json(MODEL_RUNTIME_FILE, data)
                return {"ok": True}
            updates = {k: v for k, v in (rec.get("updates") or {}).items()
                       if k in _MODEL_ADVISOR_APPLY_KEYS}
            if not updates:
                return {"ok": False, "error": "recommendation has no applicable settings"}
            previous = {k: settings.get(k) for k in updates}
            settings.update(updates)
            if "spec_strategy" in updates:
                settings["enable_speculative"] = updates["spec_strategy"] != "off"
            candidate_config = _model_config_signature(_model_runtime_config(settings))
            start_turns = int(((row.get("configs") or {}).get(candidate_config) or {}).get("turns", 0) or 0)
            row["trial"] = {
                "id": uuid.uuid4().hex[:16], "recommendation_id": rec.get("id"),
                "status": "measuring", "applied_at": int(time.time()),
                "from_config": active_config, "candidate_config": candidate_config,
                "start_turns": start_turns, "updates": updates, "previous": previous,
                "changes": list(rec.get("changes") or []),
                "baseline": _model_observed(cfg, cfg.get("observations") or None),
            }
            save_json(SETTINGS_FILE, settings)
            if settings.get("model_path"):
                _save_model_config(str(settings["model_path"]), updates)
            save_json(MODEL_RUNTIME_FILE, data)
            broadcast_event({"type": "settings:update"})
            return {"ok": True, "settings": settings, "reload": True,
                    "model_path": settings.get("model_path") or "", "trial": row["trial"]}
        trial = row.get("trial") if isinstance(row.get("trial"), dict) else None
        if action in {"undo", "keep"} and trial:
            if action == "keep":
                trial["status"] = "kept"
                trial["closed_at"] = int(time.time())
                save_json(MODEL_RUNTIME_FILE, data)
                return {"ok": True, "settings": settings, "reload": False}
            previous = {k: v for k, v in (trial.get("previous") or {}).items()
                        if k in _MODEL_ADVISOR_APPLY_KEYS}
            settings.update(previous)
            if "spec_strategy" in previous:
                settings["enable_speculative"] = previous["spec_strategy"] != "off"
            trial["status"] = "rolled_back"
            trial["closed_at"] = int(time.time())
            save_json(SETTINGS_FILE, settings)
            if settings.get("model_path"):
                _save_model_config(str(settings["model_path"]), previous)
            save_json(MODEL_RUNTIME_FILE, data)
            broadcast_event({"type": "settings:update"})
            return {"ok": True, "settings": settings, "reload": True,
                    "model_path": settings.get("model_path") or ""}
    return {"ok": False, "error": "unsupported model health action"}


def _public_model_health() -> dict:
    """Small, path-free snapshot safe for the Settings UI.

    The full runtime profile stays private to the bridge/tool layer.  This view
    exposes only aggregate counters and conservative advice; it never contains
    prompts, generated text, tool arguments/results, or executable paths.
    """
    settings = get_settings()
    enabled = bool(settings.get("passive_model_telemetry", True))
    model = _model_profile_key(settings.get("model_path") or settings.get("model") or "")
    runtime_key = _model_profile_key(settings.get("model") or model)
    active_config = _model_config_signature(_model_runtime_config(settings))
    try:
        with _MODEL_RUNTIME_LOCK:
            data = load_json(MODEL_RUNTIME_FILE, {"version": 2, "models": {}})
            profiles = data.get("models") if isinstance(data, dict) else {}
            row = ((profiles or {}).get(runtime_key) or (profiles or {}).get(model) or {}) if model else {}
            cfg = (row.get("configs") or {}).get(active_config) or {}
            changed = False
            if cfg:
                observed = _model_observed(cfg, cfg.get("observations") or None)
                rec = cfg.get("recommendation") if isinstance(cfg.get("recommendation"), dict) else None
                open_trial = row.get("trial") if isinstance(row.get("trial"), dict) else None
                if open_trial and open_trial.get("status") in {"kept", "rolled_back", "aborted"}:
                    open_trial = None
                if not rec and not open_trial:
                    rec = _advisor_recommendation(model, active_config, cfg, settings)
                    if rec:
                        cfg["recommendation"] = rec
                        changed = True
                if rec and rec.get("dismissed_at"):
                    rec = None
                if rec:
                    # A stored recommendation can go stale once the live settings
                    # catch up with it (e.g. a manual decoder choice landed or
                    # auto-tune adopted the same flags). Drop it instead of
                    # nagging with a change that is no longer a change.
                    _live_cfg = _model_runtime_config(settings)
                    outstanding = {k: v for k, v in (rec.get("updates") or {}).items()
                                   if _live_cfg.get(k) != v}
                    if not outstanding:
                        cfg.pop("recommendation", None)
                        rec = None
                        changed = True
            else:
                observed = _model_observed(row)
                rec = None
            trial_before = copy.deepcopy(row.get("trial"))
            trial = _advisor_trial_public(row, active_config)
            if row.get("trial") != trial_before:
                changed = True
            if changed:
                save_json(MODEL_RUNTIME_FILE, data)
    except Exception:
        row, cfg, observed, rec, trial = {}, {}, {}, None, None
    current = cfg if cfg else row
    turns = max(0, int(current.get("turns", 0) or 0))
    sessions = len(current.get("sessions") or []) if cfg else 0
    comparison = []
    if isinstance(profiles, dict):
        # Content-free cross-model comparison: aggregate counters only, no
        # paths, config details, or any content. The current model is left to
        # the UI (it already renders its own metrics), so this lists others.
        for name, prow in profiles.items():
            if not isinstance(prow, dict) or name in (runtime_key, model):
                continue
            pturns = max(0, int(prow.get("turns", 0) or 0))
            if pturns < 1:
                continue
            pobs = _model_observed(prow)
            comparison.append({
                "model": str(name)[:180],
                "turns": pturns,
                "completion_rate": float(pobs.get("completion_rate", 0) or 0),
                "tool_success": round(1 - float(pobs.get("tool_error_rate", 0) or 0), 3),
                "output_tok_s": float(pobs.get("output_tok_s", 0) or 0),
                "last_seen": max(0, int(prow.get("last_seen", 0) or 0)),
            })
        comparison.sort(key=lambda m: m["turns"], reverse=True)
        comparison = comparison[:5]
    advice = []
    context = max(0, int(current.get("last_context", 0) or settings.get("num_ctx") or 0))
    if turns >= 8 and context and float(observed.get("p90_peak_context_tokens", 0) or 0) >= context * 0.82:
        advice.append("Normal work approaches the context ceiling. The setup advisor will check whether this model can safely use more room.")
    if turns >= 8 and float(observed.get("completion_rate", 0) or 0) < 0.8:
        advice.append("Incomplete turns are elevated. Accuretta will keep conservative settings until reliability improves.")
    return {
        "enabled": enabled,
        "model": model,
        "turns": turns,
        "completed_turns": max(0, int(current.get("completed_turns", 0) or 0)),
        "tool_calls": max(0, int(current.get("tool_calls", 0) or 0)),
        "tool_errors": max(0, int(current.get("tool_errors", 0) or 0)),
        "last_context": context,
        "peak_context_tokens": max(0, int(current.get("peak_context_tokens", 0) or 0)),
        "confidence": ("high" if turns >= _MODEL_ADVISOR_BASELINE_TURNS
                       and sessions >= _MODEL_ADVISOR_BASELINE_SESSIONS else "warming_up"),
        "observed": observed,
        "comparison": comparison,
        "advice": advice,
        "learning": {
            "turns_required": _MODEL_ADVISOR_BASELINE_TURNS,
            "sessions_required": _MODEL_ADVISOR_BASELINE_SESSIONS,
            "turns_remaining": max(0, _MODEL_ADVISOR_BASELINE_TURNS - turns),
            "sessions": sessions,
            "sessions_remaining": max(0, _MODEL_ADVISOR_BASELINE_SESSIONS - sessions),
        },
        "recommendation": copy.deepcopy(rec) if rec and not trial else None,
        "notification_needed": bool(rec and not trial and not rec.get("notified_at")),
        "trial": trial,
        "privacy": ("Local performance numbers only, plus tool names and exit codes in a private "
                    "comparison dataset (model_usage_dataset.jsonl). Prompts, replies, tool "
                    "arguments, tool output, commands, files, screenshots, peer addresses, and "
                    "account names are never stored."),
    }


