# Cap workspace-served file size — keeps a 4GB log from being streamed to a
# browser tab, OOMing both the bridge and the renderer.
_WS_FILE_MAX_BYTES = 50 * 1024 * 1024  # 50 MB


def resolve_workspace_file(root_raw: str, rel_raw: str) -> tuple["Path | None", "dict | None"]:
    """Resolve `<root>/<rel>` and verify the result is strictly inside the
    workspace root. Returns (resolved_path, None) on success, (None, error_dict)
    on rejection. Hardening:
      - root must exactly match a configured workspace folder (no parent dirs)
      - rel must be relative (no absolute paths, no drive letters)
      - .. is allowed in the input string but the resolved path MUST stay
        inside the resolved root (defends against `a/../../../etc`)
      - symlinks that escape the root are rejected (resolve() follows them,
        so the boundary check catches them)
      - .accurettaignore rules apply (consistency with the read tools)
      - file must exist and be a regular file (no dirs, no devices)
    """
    if not root_raw or not rel_raw:
        return None, {"error": "root and path required"}
    # 1. root must be one of the configured workspace folders, exactly
    configured = [normalize_path(f) for f in get_workspace().get("folders", [])]
    root_norm = normalize_path(root_raw)
    if root_norm not in configured:
        return None, {"error": "root not in workspace"}
    # 2. reject obviously-absolute or drive-rooted relatives
    rel = rel_raw.replace("\\", "/").lstrip("/")
    if not rel:
        return None, {"error": "empty path"}
    if os.path.isabs(rel) or (len(rel) >= 2 and rel[1] == ":"):
        return None, {"error": "absolute path not allowed"}
    # 3. resolve and re-check containment
    try:
        root_resolved = Path(root_norm).resolve(strict=True)
    except Exception:
        return None, {"error": "workspace root unreadable"}
    try:
        target_resolved = (root_resolved / rel).resolve(strict=True)
    except FileNotFoundError:
        return None, {"error": "file not found"}
    except Exception as e:
        return None, {"error": f"resolve failed: {e}"}
    try:
        # commonpath() raises ValueError on different drives; that's a reject too
        common = Path(os.path.commonpath([str(root_resolved), str(target_resolved)]))
    except ValueError:
        return None, {"error": "path escapes workspace"}
    if common != root_resolved:
        return None, {"error": "path escapes workspace"}
    # 4. must be a real file
    if not target_resolved.is_file():
        return None, {"error": "not a file"}
    # 5. honour .accurettaignore (same rules the read tools use)
    if is_ignored(str(target_resolved)):
        return None, {"error": "file is ignored by .accurettaignore"}
    return target_resolved, None


def is_ignored(path: str) -> bool:
    """True if `path` matches a rule in the enclosing workspace's .accurettaignore."""
    root = _workspace_root_for(path)
    if not root:
        return False
    rules = _read_ignore_rules(root)
    if not rules:
        return False
    rel = os.path.relpath(normalize_path(path), root).replace("\\", "/")
    if rel == "." or rel.startswith(".."):
        return False
    base = os.path.basename(rel)
    ignored = False
    for neg, pat in rules:
        # match against basename for patterns without a slash; match full rel path
        # for patterns that contain a slash (so `build/*.map` works).
        hit = False
        if "/" in pat:
            if fnmatch.fnmatch(rel, pat) or fnmatch.fnmatch(rel, pat.rstrip("/") + "/*") or any(
                fnmatch.fnmatch(rel, pat + "/" + "*") for _ in [0]
            ):
                hit = True
        else:
            # bare pattern: match any basename along the path
            parts = rel.split("/")
            if any(fnmatch.fnmatch(p, pat) for p in parts) or fnmatch.fnmatch(base, pat):
                hit = True
        if hit:
            ignored = not neg
    return ignored


# ---- registry guardrails ---------------------------------------------------
# Registry writes have the highest blast radius of anything the agent can do
# on Windows, so protection is split by hive:
#
#   - SYSTEM hives (HKLM, HKCR, HKU): hard-refused at the bridge; no approval
#     card is shown.
#   - USER hives (HKCU, HKCC): routed to the REGISTRY EDIT approval card with
#     hold-to-approve, so a single mis-click can't push a write through.
#
# Opaque imports (`reg import file.reg`, `regedit /s file.reg`) count as SYSTEM
# because the target hive isn't visible in the command, and .reg files in the
# wild routinely write HKLM.
_REG_SYSTEM_HIVES = (
    "HKLM:", "HKCR:", "HKU:",
    "HKEY_LOCAL_MACHINE", "HKEY_CLASSES_ROOT", "HKEY_USERS",
)
_REG_USER_HIVES = (
    "HKCU:", "HKCC:",
    "HKEY_CURRENT_USER", "HKEY_CURRENT_CONFIG",
)
_REG_WRITE_VERBS = re.compile(
    r"\b("
    r"Set-ItemProperty|New-ItemProperty|Remove-ItemProperty|Clear-ItemProperty"
    r"|New-Item|Remove-Item|Rename-Item|Copy-Item|Move-Item"
    r"|reg\s+(?:add|delete|copy|restore)"
    r")\b",
    re.IGNORECASE,
)
_REG_OPAQUE_IMPORT = re.compile(
    r"\b(reg\s+import\b|regedit(?:\.exe)?\s+(?:/s\b|-s\b))",
    re.IGNORECASE,
)
_REG_LAUNCH_REGEDIT = re.compile(
    r"\b(Start-Process\s+regedit|^\s*regedit(?:\.exe)?\b|;\s*regedit(?:\.exe)?\b)",
    re.IGNORECASE,
)


def registry_assess(cmd: str) -> dict:
    """Classify whether a PowerShell/cmd string writes to the registry, and
    at what blast-radius. Returns {"level": "none"|"user"|"system",
    "targets": [matched hive references]}.

    Conservative on ambiguity — `reg import` / `regedit /s` and bare
    `regedit` launches escalate to "system" because their actual targets
    aren't visible in the cmd string.
    """
    if not cmd:
        return {"level": "none", "targets": []}
    # Opaque imports / regedit launches: can't see the target, assume worst.
    if _REG_OPAQUE_IMPORT.search(cmd) or _REG_LAUNCH_REGEDIT.search(cmd):
        return {"level": "system", "targets": ["(opaque: .reg file or regedit launch)"]}
    # A write verb alone isn't enough (Set-ItemProperty / New-Item also work on
    # filesystem PSDrives); a hive reference must be present too.
    if not _REG_WRITE_VERBS.search(cmd):
        return {"level": "none", "targets": []}
    system_hits: list[str] = []
    user_hits: list[str] = []
    # Match hive prefix + the path that follows it. Stop at whitespace,
    # quote, comma, semicolon, or backtick (PowerShell line continuation).
    for hive in _REG_SYSTEM_HIVES:
        for m in re.finditer(re.escape(hive) + r"[\\:\w.()$ -]*", cmd, re.IGNORECASE):
            system_hits.append(m.group(0).strip())
    for hive in _REG_USER_HIVES:
        for m in re.finditer(re.escape(hive) + r"[\\:\w.()$ -]*", cmd, re.IGNORECASE):
            user_hits.append(m.group(0).strip())
    if system_hits:
        # Dedupe preserving order. User hits ride along so the approval card shows the
        # full picture, though the level comes from the more dangerous one.
        seen = set()
        targets = []
        for t in system_hits + user_hits:
            if t.lower() not in seen:
                seen.add(t.lower())
                targets.append(t)
        return {"level": "system", "targets": targets}
    if user_hits:
        seen = set()
        targets = []
        for t in user_hits:
            if t.lower() not in seen:
                seen.add(t.lower())
                targets.append(t)
        return {"level": "user", "targets": targets}
    # Write verb found but no hive reference → not a registry write
    # (e.g. Set-ItemProperty against a filesystem path).
    return {"level": "none", "targets": []}


def _notch_registry_diff(cmd: str) -> dict:
    """Read-only old/new rows for a registry gate's diff view (notch overlay).

    Parses the PENDING command (never executes it), then reads the CURRENT
    value with `reg query` — a strictly read-only binary, invoked with a
    fixed argv and no shell. Only `reg add` / `reg delete` and simple
    PowerShell *-ItemProperty forms are parsed; anything else returns an
    empty result and the gate card shows the command without a diff.
    Fails toward the hold: parsing never affects the gate kind.
    """
    empty = {"path": "", "diff": []}
    if not cmd or sys.platform != "win32":
        return empty

    hives = ("HKLM", "HKCU", "HKCR", "HKU", "HKCC",
             "HKEY_LOCAL_MACHINE", "HKEY_CURRENT_USER", "HKEY_CLASSES_ROOT",
             "HKEY_USERS", "HKEY_CURRENT_CONFIG")

    def _clean_key(k: str) -> str:
        k = k.strip().strip('"').replace("/", "\\")
        # PowerShell drive form -> reg.exe form (HKCU:\Software -> HKCU\Software)
        k = re.sub(r"^(HK[A-Z]{2}|HKEY_[A-Z_]+):\\?", lambda m: m.group(1) + "\\", k, flags=re.I)
        return k

    def _valid_key(k: str) -> bool:
        if not k or len(k) > 512:
            return False
        if not any(k.upper().startswith(h.upper() + "\\") for h in hives):
            return False
        # Conservative charset: letters, digits, spaces and common path chars
        # only. Nothing here is ever shelled out (fixed argv), but tight
        # validation keeps weird input from reaching even reg.exe query.
        return bool(re.fullmatch(r"[A-Za-z0-9 _\-.(){}\\]+", k))

    def _query(key: str, value: str) -> tuple[str, str] | None:
        """(type, data) of the current value, or None when unreadable."""
        import subprocess
        argv = ["reg", "query", key]
        if value:
            argv += ["/v", value]
        try:
            r = subprocess.run(argv, capture_output=True, text=True, timeout=8,
                               creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        except Exception:
            return None
        if r.returncode != 0:
            return None
        for line in r.stdout.splitlines():
            m = re.match(r"\s*(\S.*?)\s{2,}(REG_\w+)\s+(.*)$", line)
            if m and (not value or m.group(1).strip().lower() == value.lower()):
                return m.group(2), m.group(3).strip()
        return None

    # --- reg add "KEY" /v NAME /t TYPE /d DATA [/f] ---
    m = re.search(r"\breg(?:\.exe)?\s+add\s+(\"[^\"]+\"|\S+)", cmd, re.I)
    if m:
        key = _clean_key(m.group(1))
        if not _valid_key(key):
            return empty
        vm = re.search(r"\s/v\s+(\"[^\"]+\"|\S+)", cmd, re.I)
        tm = re.search(r"\s/t\s+(REG_\w+)", cmd, re.I)
        dm = re.search(r"\s/d\s+(\"[^\"]*\"|\S+)", cmd, re.I)
        value = (vm.group(1).strip('"') if vm else "(Default)")
        vtype = (tm.group(1) if tm else "REG_SZ")
        data = (dm.group(1).strip('"') if dm else "")
        old = _query(key, "" if value == "(Default)" else value)
        new_row = f"{value}  {vtype}  {data}"
        if old:
            return {"path": key, "diff": [["-", f"{value}  {old[0]}  {old[1]}"], ["+", new_row]]}
        return {"path": key, "diff": [["+", new_row]]}

    # --- reg delete "KEY" [/v NAME] [/f] ---
    m = re.search(r"\breg(?:\.exe)?\s+delete\s+(\"[^\"]+\"|\S+)", cmd, re.I)
    if m:
        key = _clean_key(m.group(1))
        if not _valid_key(key):
            return empty
        vm = re.search(r"\s/v\s+(\"[^\"]+\"|\S+)", cmd, re.I)
        if vm:
            value = vm.group(1).strip('"')
            old = _query(key, value)
            if old:
                return {"path": key, "diff": [["-", f"{value}  {old[0]}  {old[1]}"]]}
            return {"path": key, "diff": [["-", value]]}
        return {"path": key, "diff": [["-", "(entire key)"]]}

    # --- PowerShell Set/New-ItemProperty -Path HKCU:\... -Name X -Value Y ---
    m = re.search(r"\b(?:Set|New)-ItemProperty\b", cmd, re.I)
    if m:
        pm = re.search(r"-Path\s+(\"[^\"]+\"|'[^']+'|\S+)", cmd, re.I)
        nm = re.search(r"-Name\s+(\"[^\"]+\"|'[^']+'|\S+)", cmd, re.I)
        if not pm or not nm:
            return empty
        key = _clean_key(pm.group(1).strip("\"'"))
        if not _valid_key(key):
            return empty
        value = nm.group(1).strip("\"'")
        vm = re.search(r"-Value\s+(\"[^\"]*\"|'[^']*'|\S+)", cmd, re.I)
        data = vm.group(1).strip("\"'") if vm else ""
        old = _query(key, value)
        new_row = f"{value}  {data}"
        if old:
            return {"path": key, "diff": [["-", f"{value}  {old[0]}  {old[1]}"], ["+", new_row]]}
        return {"path": key, "diff": [["+", new_row]]}

    return empty


# ---- bridge self-protection ------------------------------------------------
# Models iterating on a web UI sometimes kill the python process running this
# file along with the dev server they meant to restart. Approval doesn't help
# (the model has lost track of which python is which), so any tool call naming
# bridge.py, the bridge's PID, or destructive verbs against port 8787 is
# refused regardless of approval state.

_BRIDGE_FILE_ABS = ""
try:
    _BRIDGE_FILE_ABS = str(Path(__file__).resolve()).lower()
except Exception:
    _BRIDGE_FILE_ABS = ""

_BRIDGE_PID = os.getpid()

# Patterns matched against the raw PowerShell command string.
_PROT_BRIDGE_FILE_RE = re.compile(r"\bbridge\.py\b", re.IGNORECASE)
_PROT_DESTROY_FILE_RE = re.compile(
    r"\b(remove-item|del|erase|rd|rmdir|move-item|out-file|set-content|add-content|"
    r"clear-content|new-item\s+-force)\b",
    re.IGNORECASE,
)
_PROT_KILL_VERB_RE = re.compile(
    r"\b(stop-process|taskkill|tskill|kill)\b",
    re.IGNORECASE,
)
_PROT_PORT_RE = re.compile(r"(?<!\d)8787(?!\d)")


def is_bridge_self_path(path: str) -> bool:
    """True if `path` resolves to this running bridge.py."""
    if not path or not _BRIDGE_FILE_ABS:
        return False
    try:
        return str(Path(path).resolve()).lower() == _BRIDGE_FILE_ABS
    except Exception:
        return False


def bridge_self_threat(cmd: str) -> str | None:
    """Return a refusal reason if `cmd` would kill or corrupt the bridge.
    Pattern-only check — runs before approval so even an approved Stop-Process
    against our PID gets refused. Returns None if the command is safe."""
    if not cmd:
        return None

    # Direct PID reference + a kill verb.
    if str(_BRIDGE_PID) in cmd and _PROT_KILL_VERB_RE.search(cmd):
        # Avoid false positives: the PID has to appear as a standalone token,
        # not as a substring of some unrelated number.
        if re.search(rf"(?<!\d){_BRIDGE_PID}(?!\d)", cmd):
            return f"command targets the bridge's own process (pid {_BRIDGE_PID})"

    # bridge.py + a destructive file verb.
    if _PROT_BRIDGE_FILE_RE.search(cmd) and _PROT_DESTROY_FILE_RE.search(cmd):
        return "command would overwrite or delete bridge.py"

    # Port 8787 + a kill verb. `Get-NetTCPConnection -LocalPort 8787` on its
    # own is fine (read-only); only refuse when paired with a process killer.
    if _PROT_PORT_RE.search(cmd) and _PROT_KILL_VERB_RE.search(cmd):
        return f"command would kill the bridge's listener (port {PORT})"

    return None


# ---- approval policy (soft / medium / hard) --------------------------------
# approval_mode drives how much the agent may do without asking:
#   soft   = autonomous except deletions, program launches, desktop actions and
#            protected ops (registry / System32) - those still prompt, the
#            protected ones via the hold-to-approve card.
#   medium = "trust writes": in-workspace file writes/edits auto-approve.
#   hard   = every action prompts.
# The REFUSE set (drive wipes, fork bombs, bridge self-harm) is mode-independent.

_SOFT_PROMPT_KINDS = {"delete", "registry", "launch"}
_SOFT_COMMAND_KINDS = {"powershell", "sandbox", "session", "git", "test"}
# Tool kinds soft mode runs without asking: analysis tools that read, or write
# only their own output. A kind not named here or handled by its own rule asks,
# so a new tool can't slip through soft mode unreviewed.
_SOFT_AUTO_KINDS = {
    "analyze_pcap", "decompile_apk", "carve_file", "extract_archive", "extract_squashfs",
    "event_log", "ghidra_analyze", "network_snapshot", "parse_event_log", "persistence_hunt",
    "recon_s3", "save_skill", "secret_scan",
}
_MCP_SOFT_BLOCK = re.compile(r"delete|remove|drop|destroy|terminate|unregister", re.IGNORECASE)

# git verbs that only read the repo: the only ones soft mode runs freely.
# Everything else (commit, push, checkout, reset, clean, ...) prompts. The git
# tools pass their argv in details, so request_approval can tell read from
# write without regex guesswork.
_GIT_READONLY_VERBS = {
    "status", "log", "diff", "show", "remote", "rev-parse",
    "ls-files", "ls-tree", "grep", "blame",
}
_GIT_REMOTE_MUTATING_VERBS = {
    "add", "remove", "rm", "rename", "set-head", "set-branches",
    "set-url", "prune", "update",
}


def _git_argv_is_readonly(argv) -> bool:
    if not isinstance(argv, list) or not argv or not isinstance(argv[0], str):
        return False
    verb = argv[0].lower()
    if verb not in _GIT_READONLY_VERBS:
        return False
    if verb != "remote":
        return True
    subcommand = next((str(arg).lower() for arg in argv[1:]
                       if isinstance(arg, str) and not arg.startswith("-")), "")
    return subcommand not in _GIT_REMOTE_MUTATING_VERBS


def _approval_mode() -> str:
    """soft|medium|hard. Legacy fallback: auto_approve_write -> medium/hard."""
    try:
        m = str(get_settings().get("approval_mode") or "").strip().lower()
        if m in ("soft", "medium", "hard"):
            return m
        return "medium" if get_settings().get("auto_approve_write") else "hard"
    except Exception:
        return "hard"


_SOFT_DESTRUCTIVE_RES = [re.compile(p, re.IGNORECASE) for p in (
    r"\bremove-item\b",
    r"\bdel(?:ete)?\s+[/a-z0-9(\"\']",
    r"\berase\s+[/a-z0-9(\"\']",
    r"\brd\s+/s", r"\brmdir\s+/s", r"\brmdir\s+[a-z0-9~./]",
    r"\brm\s+-", r"\brm\s+[/~.]", r"\brm\s+[a-z0-9_]",
    r"\bunlink\s+", r"\bshred\s+",
    r"\breg\s+(?:add|delete|import|restore|copy)\b", r"\bregedit\b",
    r"\bset-itemproperty\b", r"\bnew-itemproperty\b",
    r"\bremove-itemproperty\b", r"\bclear-itemproperty\b",
    r"\bformat\s+[a-z]:", r"\bdisk" r"part\b", r"\bmkfs\b", r"\bwipefs\b", r"\bdd\s+[^|;&]*\bof=/dev/",
    r"\bgit\s+reset\s+--hard", r"\bgit\s+clean\s+-\w*f",
    r"\bgit\s+push\s+[^&|;]*(?:--force\w*|-f(?:\s|$))", r"\bgit\s+rm\b", r"\bgit\s+branch\s+-D\b",
)]


def _is_destructive_command(cmd: str) -> bool:
    """True when a shell/git command line deletes or overwrites data. Matches
    deletion VERBS with arguments (word-bounded), not substrings, so 'firm',
    'model', an 'rm' inside a path, or 'delete' in prose don't trip it. Soft
    approval mode: destructive -> still prompts, everything else runs."""
    if not cmd:
        return False
    return any(p.search(cmd) for p in _SOFT_DESTRUCTIVE_RES)


_SOFT_SENSITIVE_COMMAND_RES = [re.compile(p, re.IGNORECASE) for p in (
    r"\bstart-process\b", r"\binvoke-item\b", r"\bexplorer(?:\.exe)?\b",
    r"\btaskkill\b", r"\bstop-process\b", r"\bkill(?:all)?\b",
    r"\bshutdown\b", r"\brestart-computer\b", r"\bstop-computer\b",
    r"\bsc(?:\.exe)?\s+(?:create|config|delete|start|stop)\b",
    r"\b(?:new|set|disable|enable|unregister)-scheduledtask\b",
    r"\bnetsh\b", r"\bset-netfirewall", r"\bbcdedit\b",
    r"\brunas\b", r"\bstart-process\b[^\r\n]*\b-verb\s+runas\b",
    r"\b(?:set-content|out-file)\b", r"(?<![<>=])>(?![>=])",
    # Running code that isn't on disk for review. `| iex` and download|shell
    # are refused outright by _clickfix_cmd; these are the variants it lets
    # through: a plain pipe into a shell, installs straight from a URL or git
    # remote, and classic Windows download-to-disk vectors.
    r"\|\s*(?:sh|bash|zsh|dash|ksh|pwsh|powershell)(?:\.exe)?\b",
    r"\bpip3?\s+install\b[^\r\n;&|]*(?:https?://|git\+|\.git(?:\s|$))",
    r"\b(?:npm|pnpm|yarn)\s+(?:install|i|add)\b[^\r\n;&|]*(?:https?://|git\+|github:|gitlab:|bitbucket:)",
    r"\bcertutil(?:\.exe)?\b[^\r\n]*-urlcache\b",
    r"\b(?:downloadstring|downloadfile|downloaddata)\b",
)]


def _soft_command_needs_approval_raw(cmd: str) -> bool:
    """Raw-text soft check, used when a command line hands text to another
    evaluator (iex, cmd /c, bash -c, ...): quoted strings are then commands,
    so nothing can be read as plain data."""
    text = cmd or ""
    git_match = re.search(r"\bgit(?:\.exe)?\s+([a-z][a-z-]*)\b", text, re.IGNORECASE)
    mutating_git = False
    if git_match:
        verb = git_match.group(1).lower()
        mutating_git = verb not in _GIT_READONLY_VERBS
        if verb == "remote":
            remote_tail = text[git_match.end():]
            remote_subcommand = re.match(r"\s*(?:-\S+\s+)*([a-z][a-z-]*)", remote_tail, re.IGNORECASE)
            mutating_git = bool(remote_subcommand
                                and remote_subcommand.group(1).lower() in _GIT_REMOTE_MUTATING_VERBS)
    return (_is_destructive_command(text) or mutating_git
            or any(pattern.search(text) for pattern in _SOFT_SENSITIVE_COMMAND_RES))


# ---- soft-mode command assessment ---------------------------------------------
# Soft mode should stop only for commands that can do real damage. Grepping the
# raw text stopped on a `2>&1`, a `<script>` inside a regex, or the word
# "delete" in an echo. The assessment reads the command instead:
#   - only command words count: quoted strings, here-strings, heredocs and
#     comments are data. A line that hands text to another evaluator (iex,
#     cmd /c, bash -c, ...) falls back to the raw-text check, and a
#     double-quoted string holding `$(...)` stays code, since it runs;
#   - redirects to the null device and stream merges (2>&1) are ignored;
#   - writes and deletions pass only when every target resolves to a literal
#     path inside a workspace project or the temp folder (deletions inside a
#     project, never a project or workspace root). Relative paths need an
#     explicit `cd` first: the bridge's own cwd is the app folder;
#   - Start-Process / Invoke-Item may open a document, not a program, and may
#     start a dev tool (python, node, npm, ...) in the background;
#   - git may also clone, fetch, init and add;
#   - copies and moves into system, startup, profile, .ssh or app folders ask;
#   - code the command runs is read too (see "code a command runs" below).
# Anything it cannot resolve (a path in an unknown variable, a pipeline-fed
# Remove-Item) still asks.

# Evaluators whose text can't be followed: iex, cmd /c, wsl, ... (PowerShell
# -Command and, in the sandbox, bash -c are read like any other command).
_SOFT_EVALUATOR_RE = re.compile(
    r"\b(?:iex|invoke-expression|invoke-command|wmic)\b|scriptblock\]::create|invokecommand\."
    r"|\bcmd(?:\.exe)?\s+/[ckr]\b|\bwsl(?:\.exe)?\b",
    re.IGNORECASE)
_SOFT_HOST_SHELL_C_RE = re.compile(r"\b(?:bash|sh|zsh|dash|ksh)(?:\.exe)?\s+-\w*c\b", re.IGNORECASE)
_SOFT_OPAQUE_HEADS = {"iex", "invoke-expression", "invoke-command", "wmic", "wsl"}

# Patterns from the raw lists that the assessment resolves structurally
# (deletions, file writes, redirects, launches); every other pattern in those
# lists still asks whenever it appears in the command words.
_SOFT_STRUCTURAL_PATTERNS = {
    r"\bremove-item\b", r"\bdel(?:ete)?\s+[/a-z0-9(\"\']", r"\berase\s+[/a-z0-9(\"\']",
    r"\brd\s+/s", r"\brmdir\s+/s", r"\brmdir\s+[a-z0-9~./]",
    r"\brm\s+-", r"\brm\s+[/~.]", r"\brm\s+[a-z0-9_]",
    r"\bgit\s+rm\b",
    r"\bstart-process\b", r"\binvoke-item\b", r"\b(?:set-content|out-file)\b",
    r"(?<![<>=])>(?![>=])",
}
_SOFT_ALWAYS_ASK_RES = [
    p for p in (*_SOFT_DESTRUCTIVE_RES, *_SOFT_SENSITIVE_COMMAND_RES)
    if p.pattern not in _SOFT_STRUCTURAL_PATTERNS
] + [re.compile(p, re.IGNORECASE) for p in (
    r"\bschtasks(?:\.exe)?\b",
    r"\bfind\b[^\r\n;|]*\s-(?:delete|exec(?:dir)?)\b",
)]
assert all(any(p.pattern == s for p in (*_SOFT_DESTRUCTIVE_RES, *_SOFT_SENSITIVE_COMMAND_RES))
           for s in _SOFT_STRUCTURAL_PATTERNS), "structural pattern missing from the raw lists"
# These judge a command by its arguments (an install URL, a download source),
# which are often quoted, so they are matched with the literals put back.
_SOFT_ARGUMENT_RES = [p for p in _SOFT_ALWAYS_ASK_RES
                      if any(w in p.pattern for w in ("pip3", "(?:npm|pnpm|yarn)", "certutil", "downloadstring"))]
assert len(_SOFT_ARGUMENT_RES) == 4, "argument-sensitive soft patterns changed"
# What each always-ask pattern means, for the approval card. First match wins.
_SOFT_PATTERN_LABELS = (
    (("unlink", "shred"), "deletes files"),
    (("reg\\s", "regedit", "itemproperty"), "changes the Windows registry"),
    (("format", "disk", "mkfs", "wipefs", "of=/dev"), "formats or overwrites a disk"),
    (("git\\s+reset", "git\\s+clean", "git\\s+push", "git\\s+branch"), "rewrites or deletes Git history"),
    (("explorer",), "opens File Explorer"),
    (("taskkill", "stop-process", "kill"), "stops a running program"),
    (("shutdown", "restart-computer", "stop-computer"), "shuts down or restarts the computer"),
    (("\\bsc(",), "changes a Windows service"),
    (("scheduledtask", "schtasks"), "changes scheduled tasks"),
    (("netsh", "netfirewall"), "changes network or firewall settings"),
    (("bcdedit",), "changes boot settings"),
    (("runas",), "runs with administrator or another user's rights"),
    (("|\\s*(?:sh",), "pipes text straight into a shell"),
    (("pip3", "npm"), "installs a package straight from a URL or Git"),
    (("certutil", "download"), "downloads a file with a Windows download tool"),
    (("find",), "deletes files matched by find"),
)


def _soft_pattern_label(pattern: re.Pattern) -> str:
    for needles, label in _SOFT_PATTERN_LABELS:
        if any(n in pattern.pattern for n in needles):
            return label
    return "matches a risky command pattern"


# HTTP DELETE against an API removes remote data; the method is often quoted.
_SOFT_HTTP_DELETE_RE = re.compile(r"(?:-method|-x|--request)\s*[=\s]\s*[\"']?delete\b", re.IGNORECASE)

_SOFT_DELETE_VERBS = {"remove-item", "ri", "rm", "del", "erase", "rmdir", "rd"}
_SOFT_WRITE_VERBS = {"set-content", "sc", "add-content", "ac", "out-file"}
_SOFT_PLACE_VERBS = {"copy-item", "cp", "copy", "cpi", "move-item", "mv", "move", "mi",
                     "rename-item", "ren", "rni", "new-item", "ni", "tee-object", "tee",
                     "expand-archive"}
_SOFT_OPEN_VERBS = {"start-process", "start", "saps", "invoke-item", "ii"}
_SOFT_CD_VERBS = {"cd", "set-location", "sl", "chdir", "pushd", "push-location"}
_SOFT_PREFIX_WORDS = {"then", "do", "else", "elif", "sudo", "nohup", "time", "exec",
                      "xargs", "env", "command", "builtin", "!"}
_SOFT_GIT_EXTRA_VERBS = {"clone", "fetch", "init", "add"}
_SOFT_DOC_EXTS = {".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp", ".svg", ".ico",
                  ".mp4", ".webm", ".mov", ".mkv", ".avi", ".mp3", ".wav", ".flac", ".ogg",
                  ".pdf", ".html", ".htm", ".txt", ".md", ".csv", ".json", ".log"}
_SOFT_VALUE_PARAMS = {"-erroraction", "-ea", "-warningaction", "-wa", "-credential",
                      "-stream", "-encoding", "-itemtype", "-type", "-value", "-name",
                      "-newname", "-width", "-inputobject", "-windowstyle", "-workingdirectory"}
_SOFT_NULL_TARGETS = {"$null", "nul", "/dev/null", "null"}


def _shell_subexpressions(raw: str, posix: bool) -> list[str]:
    """Bodies of $(...) (balanced) and, in POSIX, `...` inside a string."""
    subs, i = [], 0
    while True:
        i = raw.find("$(", i)
        if i == -1:
            break
        depth, j = 1, i + 2
        while j < len(raw) and depth:
            depth += {"(": 1, ")": -1}.get(raw[j], 0)
            j += 1
        subs.append(raw[i + 2:j - 1] if depth == 0 else raw[i + 2:])
        i = j
    if posix:
        subs += re.findall(r"`([^`]*)`", raw)
    return subs


def _shell_code_view(cmd: str, posix: bool) -> tuple[str, list[str]]:
    """Return the command with every quoted string, here-string, heredoc body
    and comment replaced by a numbered placeholder `"N"` (comments by a
    space), plus the literal values by number. Subexpressions inside an
    expanding literal (`$(...)`, POSIX backticks) still run, so their bodies
    follow the placeholder as code."""
    out: list[str] = []
    lits: list[str] = []

    def literal(raw: str, value: str, expands: bool) -> None:
        out.append(f'"{len(lits)}"')
        lits.append(value)
        if expands:
            # Subexpressions inside an expanding string run: keep them as code.
            for sub in _shell_subexpressions(raw, posix):
                out.append(f" ( {sub} ) ")

    i, n = 0, len(cmd)
    while i < n:
        c = cmd[i]
        word_start = i == 0 or cmd[i - 1] in " \t\r\n;|&(){}"
        if not posix and c == "@" and cmd.startswith(('@"', "@'"), i):
            m = re.compile(r"@([\"'])\r?\n(.*?)\r?\n\1@", re.S).match(cmd, i)
            if m:
                literal(m.group(0), m.group(2), m.group(1) == '"')
                i = m.end()
                continue
        if posix and cmd.startswith("<<", i) and not cmd.startswith("<<<", i):
            m = re.compile(r"<<-?\s*(['\"]?)(\w+)\1").match(cmd, i)
            line_end = cmd.find("\n", i)
            if m and line_end != -1:
                term = re.compile(r"^\t*" + re.escape(m.group(2)) + r"[ \t]*\r?$", re.M).search(cmd, line_end + 1)
                if term:
                    body = cmd[line_end + 1:term.start()]
                    out.append(cmd[i:line_end + 1])
                    literal(body, body, not m.group(1))
                    i = term.end()
                    continue
        if not posix and cmd.startswith("<#", i):
            end = cmd.find("#>", i + 2)
            if end == -1:
                out.append(cmd[i:])
                break
            out.append(" ")
            i = end + 2
            continue
        if c == "#" and word_start:
            end = cmd.find("\n", i)
            out.append(" ")
            i = n if end == -1 else end
            continue
        if c in "'\"":
            j = i + 1
            while j < n:
                ch = cmd[j]
                if c == '"' and ((posix and ch == "\\") or (not posix and ch == "`")):
                    j += 2
                    continue
                if ch == c:
                    if not posix and j + 1 < n and cmd[j + 1] == c:   # '' / "" escape
                        j += 2
                        continue
                    break
                j += 1
            if j >= n:                       # unterminated: keep the rest as code
                out.append(cmd[i:])
                break
            literal(cmd[i:j + 1], cmd[i + 1:j], c == '"')
            i = j + 1
            continue
        out.append(c)
        i += 1
    return "".join(out), lits


def _soft_split_commands(code: str, lits: list[str]) -> list[tuple[str, list[str], str]]:
    """(command word, argument tokens, head as written) for every simple
    command in the code view, in order. Splits on ; | & newlines and
    braces/parens, and skips leading keywords and wrappers (then, sudo,
    xargs, ...)."""
    commands = []
    for chunk in re.split(r"\|\||&&|[;|&\n{}()]", code):
        tokens = chunk.split()
        while tokens and tokens[0].lower() in _SOFT_PREFIX_WORDS:
            tokens = tokens[1:]
        if tokens:
            head = tokens[0]
            quoted = re.fullmatch(r'"(\d+)"', head)
            if quoted:                       # & "Remove-Item" path, & "C:\tools\x.exe"
                head = lits[int(quoted.group(1))]
            name = head.lower().replace("/", "\\").rsplit("\\", 1)[-1].removesuffix(".exe")
            commands.append((name, tokens[1:], tokens[0]))
    return commands


def _soft_assignments(code: str, lits: list[str], posix: bool) -> dict[str, str]:
    """Variables assigned a single literal (`$dir = "C:\\x"`, `d=/tmp/x`).
    A variable assigned more than once, or from anything else, is unknown."""
    seen: dict[str, str | None] = {}
    if posix:
        pattern = r"(?:^|[\s;&|])([A-Za-z_]\w*)=(\"(\d+)\"|[^\s;&|\"]*)"
    else:
        pattern = r"\$([A-Za-z_]\w*)\s*=\s*(\"(\d+)\"|[^\s;|]*)"
    for m in re.finditer(pattern, code):
        name = m.group(1).lower()
        value = lits[int(m.group(3))] if m.group(3) is not None else m.group(2)
        seen[name] = None if name in seen else value
    return {k: v for k, v in seen.items() if v is not None}


def _soft_expand(text: str, variables: dict[str, str], posix: bool, depth: int = 0) -> str | None:
    """Expand $var / ${var} / $env:NAME / %NAME% / ~ in a path. None when a
    variable is unknown, so the caller treats the path as unresolved."""
    unknown = False

    def var(m: re.Match) -> str:
        nonlocal unknown
        env, name = m.group(1), m.group(2)
        if env:
            value = os.environ.get(name)
        elif name.upper() == "HOME":
            value = "/root" if posix else str(Path.home())
        elif posix and name == "TMPDIR":
            value = "/tmp"
        else:
            value = variables.get(name.lower())
            if value is not None:
                value = _soft_expand(value, variables, posix, depth + 1) if depth < 4 else None
        if value is None:
            unknown = True
            return ""
        return value

    def cmd_env(m: re.Match) -> str:
        nonlocal unknown
        value = os.environ.get(m.group(1))
        if value is None:
            unknown = True
            return ""
        return value

    out = re.sub(r"\$\{?(env:)?([A-Za-z_]\w*)\}?", var, text, flags=re.IGNORECASE)
    out = re.sub(r"%([A-Za-z_]\w*)%", cmd_env, out)
    if out.startswith("~"):
        out = ("/root" if posix else str(Path.home())) + out[1:]
    return None if unknown else out


def _soft_resolve(token: str, lits: list[str], variables: dict[str, str],
                  cwd: str | None, posix: bool) -> tuple[str, str] | None:
    """Resolve one argument token to (zone, normalized path). Zone "guest" is a
    path inside the WSL sandbox (not a mounted Windows drive); "host" is a
    Windows path. None when the path cannot be known for certain."""
    token = token.rstrip(",")
    m = re.fullmatch(r'"(\d+)"', token)
    text = lits[int(m.group(1))] if m else token
    if not m and ('"' in token or "'" in token or "`" in token):
        return None
    text = _soft_expand(text.strip(), variables, posix)
    if not text or re.search(r"[$`@{}]", text):
        return None
    if posix:
        mnt = re.fullmatch(r"/mnt/([a-zA-Z])(/.*)?", text)
        if mnt:
            text = f"{mnt.group(1).upper()}:" + (mnt.group(2) or "/").replace("/", "\\")
        elif text.startswith("/"):
            return "guest", posixpath.normpath(text)
        else:
            if not cwd:
                return None
            joined = posixpath.join(cwd, text) if cwd.startswith("/") else os.path.join(cwd, text)
            if cwd.startswith("/"):
                return "guest", posixpath.normpath(joined)
            text = joined
    if not re.match(r"^[a-zA-Z]:[\\/]|^\\\\", text):
        if not cwd or cwd.startswith("/"):
            return None
        text = os.path.join(cwd, text)
    return "host", os.path.normcase(os.path.normpath(text))


def _soft_temp_roots() -> list[str]:
    roots = {tempfile.gettempdir(), os.environ.get("TEMP") or "", os.environ.get("TMP") or ""}
    return [os.path.normcase(os.path.normpath(r)) for r in roots if r]


def _soft_depth_under(path: str, root: str) -> int:
    """Path components below root, or -1 when path is not inside root."""
    rel = os.path.relpath(path, root) if os.path.splitdrive(path)[0] == os.path.splitdrive(root)[0] else ".."
    if rel == ".":
        return 0
    if rel.startswith(".."):
        return -1
    return len(Path(rel).parts)


def _soft_target_ok(resolved: tuple[str, str] | None, *, delete: bool) -> bool:
    """Writes: anywhere in the workspace or temp. Deletions: inside a project
    folder (two levels below a workspace root), a single top-level file, or
    inside temp. A wildcard is
    only allowed in the last component; a match-all `*` counts as the folder."""
    if resolved is None:
        return False
    zone, path = resolved
    sep = "/" if zone == "guest" else "\\"
    parts = path.split(sep)
    if any(ch in "".join(parts[:-1]) for ch in "*?["):
        return False
    wildcard = any(ch in parts[-1] for ch in "*?[")
    base = sep.join(parts[:-1]) if wildcard else path
    # `x\*.png` is narrower than its folder; a bare `*` is the whole folder.
    extra = 1 if wildcard and parts[-1] not in ("*", "*.*") else 0
    if zone == "guest":
        return (len([p for p in base.split("/") if p]) + extra) >= 2
    for root in _soft_temp_roots():
        depth = _soft_depth_under(base, root)
        if depth >= 0 and depth + extra >= 1:
            return True
    for root in _workspace_roots():
        depth = _soft_depth_under(base, root)
        if depth >= 0 and depth + extra >= (2 if delete else 1):
            return True
        # One existing file at the top of the workspace is a small loss; a
        # top-level folder is a whole project.
        if delete and depth == 1 and not wildcard and os.path.isfile(path):
            return True
    return False


def _soft_protected(resolved: tuple[str, str] | None) -> bool:
    """Destinations whose change persists or reaches outside the project:
    Windows / Program Files / ProgramData, startup folders, PowerShell profile
    folders, ~/.ssh and shell dotfiles, and the app's own folder."""
    if resolved is None or resolved[0] != "host":
        return False
    path = resolved[1]
    home = Path.home()
    roots = [os.environ.get(k) for k in ("WINDIR", "ProgramFiles", "ProgramFiles(x86)", "ProgramData")]
    roots += [str(home / ".ssh"), str(home / "Documents" / "WindowsPowerShell"),
              str(home / "Documents" / "PowerShell"), str(ROOT), str(DATA)]
    appdata = os.environ.get("APPDATA")
    if appdata:
        roots.append(os.path.join(appdata, "Microsoft", "Windows", "Start Menu", "Programs", "Startup"))
    roots += [str(home / name) for name in (".bashrc", ".bash_profile", ".profile", ".zshrc",
                                            ".gitconfig", ".npmrc", ".pypirc")]
    for root in filter(None, roots):
        if _soft_depth_under(path, os.path.normcase(os.path.normpath(root))) >= 0:
            return True
    return False


def _soft_positional(args: list[str], path_params: tuple[str, ...]) -> tuple[list[str], list[str], set[str]]:
    """Split PowerShell-style arguments into (path-param values, positionals,
    other flags seen). Values of known value-taking parameters are skipped."""
    named, positional, flags = [], [], set()
    i = 0
    while i < len(args):
        a = args[i]
        low = a.lower()
        if low.startswith("-") and len(low) > 1 and not re.match(r"^-\d", low):
            key = low.split(":", 1)[0]
            flags.add(key)
            if key in path_params:
                if ":" in a:
                    named.append(a.split(":", 1)[1])
                elif i + 1 < len(args):
                    named.append(args[i + 1])
                    i += 1
            elif key in _SOFT_VALUE_PARAMS or key in ("-filter", "-include", "-exclude",
                                                      "-argumentlist", "-args", "-verb",
                                                      "-destination", "-destinationpath"):
                i += 1
        elif a == "--":
            positional.extend(args[i + 1:])
            break
        else:
            positional.extend(x for x in a.split(",") if x)
        i += 1
    return named, positional, flags


def _soft_param_values(args: list[str], params: tuple[str, ...]) -> list[str]:
    """Values given for any of `params` (`-Destination x` or `-Destination:x`)."""
    values = []
    for i, a in enumerate(args):
        key, _, inline = a.partition(":")
        if key.lower() in params:
            if inline:
                values.append(inline)
            elif i + 1 < len(args):
                values.append(args[i + 1])
    return values


# ---- code a command runs ------------------------------------------------------
# The command line is only half the story when it runs code. Reading it alone
# let `python -c "shutil.rmtree(...)"`, `node -e`, or a cleanup.py the model
# had just written run without a question. Soft now reads that code too:
#   - PowerShell scripts, `powershell -Command` text and, in the sandbox, shell
#     scripts and `bash -c` text go through this same assessment;
#   - Python and JavaScript (-c / -e code, heredocs and pipes into the
#     interpreter, script files) are scanned for deletions, registry writes,
#     shell commands that would ask on their own, and writes into protected
#     folders. A deletion passes when the code runs from inside the workspace
#     or temp (or works from its own folder there) and names no path outside;
#   - code that can't be read (a missing or huge script, -EncodedCommand)
#     asks.
# A tripwire for a careless or misled model, not a sandbox: code that pulls its
# damage from another module, or builds paths at runtime, still gets through.

_SOFT_PY_NAME_RE = re.compile(r"python[\d.]*w?|py")
_SOFT_JS_RUNNERS = {"node", "deno", "bun", "tsx", "ts-node"}
_SOFT_PS_HOSTS = {"powershell", "pwsh"}
_SOFT_SH_HOSTS = {"bash", "sh", "zsh", "dash", "ksh"}
_SOFT_SCRIPT_EXTS = {".py": "python", ".pyw": "python", ".js": "js", ".mjs": "js", ".cjs": "js",
                     ".ts": "js", ".mts": "js", ".ps1": "ps", ".sh": "sh", ".bash": "sh"}
# Start-Process may run these in the background. Running them in the
# foreground already passes, so this is the same check (their code is read).
_SOFT_DEV_TOOLS = {"python", "python3", "pythonw", "py", "node", "deno", "bun", "tsx", "ts-node",
                   "npm", "npx", "pnpm", "yarn", "uv", "uvicorn", "java", "dotnet", "go", "cargo"}
_SOFT_SCRIPT_MAX_BYTES = 1_000_000

_SOFT_CODE_DELETE_RES = {
    "python": re.compile(r"\b(?:shutil\.rmtree|rmtree|os\.(?:remove|unlink|rmdir|removedirs)|send2trash)\b"
                         r"|\.(?:unlink|rmdir)\s*\("),
    "js": re.compile(r"\b(?:rmSync|rmdirSync|unlinkSync|rimraf|emptyDirSync|removeSync|Deno\.remove(?:Sync)?)\b"
                     r"|\b(?:fse?|fsp|promises)\.(?:rm|rmdir|unlink|remove|emptyDir)\s*\("
                     r"|(?<![.\w])(?:rm|rmdir|unlink)\s*\("),
}
_SOFT_CODE_WRITE_RES = {
    "python": re.compile(r"\bopen\s*\([^)]*['\"][rbt+]*[wax]|\bwrite_(?:text|bytes)\b"
                         r"|\bshutil\.(?:copy\w*|move)\b|\bos\.(?:rename|replace|symlink)\b"),
    "js": re.compile(r"\b(?:writeFile|appendFile|copyFile|createWriteStream|cpSync|symlink)\w*"
                     r"|\b(?:fse?|fsp|promises)\.(?:rename|cp|copy|move)\w*\s*\("),
}
_SOFT_CODE_SPAWN_RE = re.compile(
    r"\b(?:subprocess|os\.system|os\.popen|Popen|child_process|execSync|execFileSync|spawnSync|"
    r"execa|Deno\.Command|Bun\.spawn|shelljs)\b|(?<![.\w])(?:exec|spawn|execFile)\s*\(")
# A destructive program as the first item of an argv list: ["rm", "-rf", x].
_SOFT_CODE_ARGV_RE = re.compile(
    r"[\[(,]\s*[rbuf]?['\"](?:rm|del|erase|rmdir|rd|remove-item|reg|regedit|schtasks|sc|taskkill|"
    r"shutdown|format|diskpart|bcdedit|netsh|cipher|vssadmin|takeown|icacls)(?:\.exe)?['\"]",
    re.IGNORECASE)
_SOFT_CODE_REGISTRY_RE = re.compile(r"\bwinreg\.(?:SetValue\w*|DeleteKey\w*|DeleteValue|CreateKey\w*)")
# Reaching for the home folder or a system folder through the environment.
_SOFT_CODE_HOME_RE = re.compile(
    r"\b(?:expanduser|Path\.home|homedir|USERPROFILE|APPDATA|LOCALAPPDATA|HOMEPATH|HOMEDRIVE|"
    r"PROGRAMDATA|SYSTEMROOT|WINDIR|OneDrive|HOME)\b|['\"`]~[\\/]")
_SOFT_CODE_SELF_DIR_RE = re.compile(r"__file__|__dirname|import\.meta|Deno\.mainModule|sys\.argv\[0\]")
_SOFT_CODE_STRING_RE = re.compile(r"[rRbBuUfF]{0,2}(\"\"\"|'''|\"|'|`)(.*?)(?<!\\)\1", re.DOTALL)
# Shell patterns that mean the same in code as on the command line; the rest
# (redirects, Start-Process, kill, installs) are ordinary inside a program.
_SOFT_CODE_SHELL_RES = [p for p in (*_SOFT_DESTRUCTIVE_RES, *_SOFT_ALWAYS_ASK_RES)
                        if not any(w in p.pattern for w in (
                            "kill(?:all)", "explorer", "pip3", "npm", "certutil", "download",
                            "|\\s*(?:sh", "find\\b", "itemproperty"))]


_SOFT_DOWNLOAD_RE = re.compile(
    r"\b(?:iwr|irm|invoke-webrequest|invoke-restmethod|start-bitstransfer|wget|curl(?:\.exe)?)\b"
    r"|\b(?:downloadfile|downloadstring)\b|-outfile\b", re.IGNORECASE)


def _soft_local_path(resolved: tuple[str, str]) -> str:
    """Where this side can open a resolved path (sandbox paths through
    \\\\wsl.localhost)."""
    zone, path = resolved
    if zone == "guest":
        return "\\\\wsl.localhost\\" + SANDBOX_DISTRO + path.replace("/", "\\")
    return path


def _soft_read_script(resolved: tuple[str, str] | None) -> str | None:
    """Text of a script about to run, or None when it can't be read (missing,
    unresolved, too large). A folder runs its entry file (index.js, the
    package.json main, __main__.py)."""
    if resolved is None:
        return None
    path = _soft_local_path(resolved)
    if os.path.isdir(path):
        main = None
        try:
            with open(os.path.join(path, "package.json"), encoding="utf-8") as f:
                main = json.load(f).get("main")
        except (OSError, ValueError, AttributeError):
            pass
        for name in filter(None, (main, "index.js", "index.mjs", "__main__.py")):
            if os.path.isfile(os.path.join(path, name)):
                path = os.path.join(path, name)
                break
    try:
        if os.path.getsize(path) > _SOFT_SCRIPT_MAX_BYTES:
            return None
        with open(path, encoding="utf-8", errors="replace") as f:
            return f.read()
    except OSError:
        return None


def _soft_code_run(name: str, head: str, args: list[str], posix: bool) -> tuple[str, str, str | None] | None:
    """What code a simple command runs: (language, how, token). `how` is
    "inline" (token holds the code), "file" (token is the script path),
    "command" (PowerShell -Command text), "stdin" or "opaque". None when the
    command runs no code soft can read, e.g. `python -m http.server`."""
    ext = os.path.splitext(name)[1]
    if ext in _SOFT_SCRIPT_EXTS and not name.startswith("-"):
        lang = _SOFT_SCRIPT_EXTS[ext]
        return (lang, "file", head) if lang != "sh" or posix else None
    if _SOFT_PY_NAME_RE.fullmatch(name):
        lang, inline, valued = "python", {"-c"}, {"-x", "-w", "-q"}
    elif name in _SOFT_JS_RUNNERS:
        if name == "node" and any(a.lower() in ("-c", "--check") for a in args):
            return None                      # syntax check only
        lang, inline = "js", {"-e", "--eval", "-p", "--print"}
        valued = {"-r", "--require", "--import", "--loader", "--input-type", "--env-file", "--conditions"}
        if name in ("deno", "bun") and args:
            sub = args[0].lower()
            if sub == "eval":
                return "js", "inline", next((a for a in args[1:] if not a.startswith("-")), None)
            if sub == "run":
                args = args[1:]
            elif name == "deno" or os.path.splitext(sub)[1] not in _SOFT_SCRIPT_EXTS:
                return None                  # deno fmt, bun install, bun x ...
    elif name in _SOFT_PS_HOSTS:
        i = 0
        while i < len(args):
            low = args[i].lower()
            if low in ("-file", "-f"):
                return "ps", "file", args[i + 1] if i + 1 < len(args) else None
            if low in ("-command", "-c"):
                return "ps", "command", " ".join(args[i + 1:])
            if low in ("-encodedcommand", "-enc", "-e", "-ec"):
                return "ps", "opaque", None
            if low in ("-executionpolicy", "-ep", "-windowstyle", "-outputformat", "-inputformat",
                       "-configurationname", "-version", "-psconsolefile", "-workingdirectory", "-wd"):
                i += 2
                continue
            if not low.startswith("-"):
                rest = " ".join(args[i:])
                return ("ps", "file", args[i]) if name == "pwsh" else ("ps", "command", rest)
            i += 1
        return None
    elif name in _SOFT_SH_HOSTS and posix:
        for i, a in enumerate(args):
            if re.fullmatch(r"-\w*c", a):
                return "sh", "inline", args[i + 1] if i + 1 < len(args) else None
            if not a.startswith("-"):
                return "sh", "file", a
        return None
    else:
        return None
    i = 0
    while i < len(args):
        a = args[i]
        low = a.lower()
        if low in inline:
            return lang, "inline", args[i + 1] if i + 1 < len(args) else None
        if lang == "python" and low == "-m":
            return None
        if a == "-":
            return lang, "stdin", None
        if low in valued:
            i += 2
            continue
        if a.startswith("<"):                # heredoc / redirect feeding stdin
            return lang, "stdin", None
        if re.match(r"[\d*]?>|&>", a):       # output redirect: `2>&1`, `> out.txt`
            i += 1 if re.search(r">.", a.lstrip("&")) or a.endswith("&1") else 2
            continue
        if not a.startswith("-"):
            return lang, "file", a
        i += 1
    return (lang, "stdin", None) if not args else None


def _soft_scan_code(code: str, lang: str, label: str, *, base_ok: bool, self_dir_ok: bool,
                    posix: bool) -> list[str]:
    """Concerns for Python or JavaScript source about to run. `base_ok`: the
    process runs from inside the workspace or temp. `self_dir_ok`: the code's
    own file sits there (it counts when the code builds paths from it)."""
    concerns = []
    strings = [m.group(2) for m in _SOFT_CODE_STRING_RE.finditer(code)]
    outside, protected = [], []
    for s in strings:
        value = s.replace("\\\\", "\\").strip()
        if not (re.match(r"^[a-zA-Z]:[\\/]|^\\\\|^~[\\/]", value) or (posix and value.startswith("/"))):
            if value.startswith(".." + os.sep) or value.startswith("../") or value == "..":
                outside.append(value)
            continue
        res = _soft_resolve('"0"', [value], {}, None, posix)
        if _soft_protected(res):
            protected.append(value)
        if not _soft_target_ok(res, delete=False):
            outside.append(value)
    if _SOFT_CODE_DELETE_RES[lang].search(code):
        here_ok = base_ok or (self_dir_ok and bool(_SOFT_CODE_SELF_DIR_RE.search(code)))
        if outside:
            concerns.append(f"{label} deletes files and names a path outside your workspace: {outside[0][:120]}")
        elif _SOFT_CODE_HOME_RE.search(code):
            concerns.append(f"{label} deletes files and reaches for your home or a system folder")
        elif not here_ok:
            concerns.append(f"{label} deletes files and runs from outside your workspace")
    if protected and _SOFT_CODE_WRITE_RES[lang].search(code):
        concerns.append(f"{label} writes into a protected folder: {protected[0][:120]}")
    if _SOFT_CODE_REGISTRY_RE.search(code):
        concerns.append(f"{label} changes the Windows registry")
    if _SOFT_CODE_SPAWN_RE.search(code):
        if _SOFT_CODE_ARGV_RE.search(code):
            concerns.append(f"{label} runs a program that deletes or changes the system")
        for s in strings:
            hit = next((p for p in _SOFT_CODE_SHELL_RES if p.search(s)), None)
            if hit:
                concerns.append(f"{label} runs a shell command that {_soft_pattern_label(hit)}"
                                if hit in _SOFT_ALWAYS_ASK_RES
                                else f"{label} runs a shell command that deletes files")
                break
    return concerns


def _soft_code_concerns(run: tuple[str, str, str | None], lits: list[str], variables: dict[str, str],
                        cwd: str | None, posix: bool, kind: str, stdin_code: str | None,
                        depth: int, command_text: str) -> list[str]:
    """Concerns for the code one command runs (see _soft_code_run)."""
    lang, how, token = run
    if depth >= 3:
        return ["runs code nested too deep to check"]
    if how == "opaque":
        return ["runs an encoded PowerShell command that can't be read"]
    def literal(tok: str | None) -> str | None:
        if tok is None:
            return None
        return re.sub(r'"(\d+)"', lambda m: lits[int(m.group(1))], tok)
    if how == "file":
        # The script resolves against the real process folder (the app folder
        # on the host when nothing cd'd), unlike deletions, which need a cd.
        res = _soft_resolve(token, lits, variables, cwd or (None if posix else os.getcwd()),
                            posix) if token else None
        shown = (lits[int(token[1:-1])] if token and re.fullmatch(r'"\d+"', token) else token) or "?"
        label = f"script {os.path.basename(shown.replace('/', os.sep))}"
        code = _soft_read_script(res)
        if code is None and res is not None and not os.path.exists(_soft_local_path(res)):
            # Not there yet: either the same command writes it (its text is
            # in the command, so read that), downloads it, or it fails.
            if _SOFT_DOWNLOAD_RE.search(command_text):
                return [f"runs a script the same command downloads: {shown}"]
            base = os.path.basename(res[1].replace("/", "\\").rsplit("\\", 1)[-1]).lower()
            if command_text.lower().count(base) < 2:
                return []
            code, label = "\n".join(lits), f"{label} (written by this command)"
        if code is None:
            return [f"runs a script that can't be read: {shown}"]
        sep = "/" if res[0] == "guest" else "\\"
        script_dir = res[1].rsplit(sep, 1)[0] or sep
        self_dir_ok = _soft_target_ok((res[0], script_dir), delete=False)
    else:
        code = stdin_code if how == "stdin" else literal(token)
        if code is None:
            return [f"runs {'Python' if lang == 'python' else 'code'} from input that can't be read"]
        label = {"python": "the Python code", "js": "the JavaScript code",
                 "ps": "powershell -Command", "sh": "bash -c"}[lang]
        script_dir, self_dir_ok = None, False
    if lang in ("ps", "sh"):
        inner_kind = "sandbox" if lang == "sh" else ("session" if kind == "session" else "powershell")
        preset = {"psscriptroot": script_dir} if lang == "ps" and script_dir else {}
        inner = _soft_command_concerns(code, inner_kind, cwd, _depth=depth + 1, _vars=preset)
        if how == "file":
            # Build and helper scripts cd around and write to computed paths;
            # inside a script only writes known to land outside still ask.
            inner = [c for c in inner if not c.startswith("writes somewhere that can't be checked")]
        return [f"{label}: {c}" for c in inner]
    base_zone = "guest" if posix and cwd and cwd.startswith("/") else "host"
    base_ok = bool(cwd) and _soft_target_ok((base_zone, cwd), delete=False)
    return _soft_scan_code(code, lang, label, base_ok=base_ok, self_dir_ok=self_dir_ok, posix=posix)


def _soft_delete_reason(res: tuple[str, str] | None, shown: str) -> str:
    """Why a deletion target asks, in words that name what would be lost."""
    if res is None:
        return f"deletes something that can't be checked: {shown}"
    if res[0] == "guest":
        return f"deletes a top-level folder in the sandbox: {shown}"
    path = res[1].rstrip("\\*")
    for root in _workspace_roots():
        depth = _soft_depth_under(path, root)
        if depth == 0:
            return f"deletes your whole workspace folder: {shown}"
        if depth == 1:
            if os.path.isdir(path) or not os.path.splitext(path)[1]:
                return f"deletes a whole project folder: {shown}"
            return f"deletes a file at the top of your workspace that isn't there yet: {shown}"
        if depth >= 2:
            return f"deletes something that can't be checked: {shown}"
    if any(_soft_depth_under(path, root) == 0 for root in _soft_temp_roots()):
        return f"deletes the whole temp folder: {shown}"
    return f"deletes outside your workspace: {shown}"


def _soft_command_concerns(cmd: str, kind: str = "powershell", cwd: str | None = None, *,
                           code_out: list | None = None, _depth: int = 0,
                           _vars: dict[str, str] | None = None) -> list[str]:
    """Why soft mode should ask before running this command line; empty when
    it can run. See the section comment above for the rules. Concerns that
    come from code the command runs are also added to `code_out` (/goal gates
    on those, since its own check only reads the command line)."""
    text = cmd or ""
    if not text.strip():
        return []
    posix = kind == "sandbox"
    code, lits = _shell_code_view(text, posix)
    commands = _soft_split_commands(code, lits)
    if (_SOFT_EVALUATOR_RE.search(code) or (not posix and _SOFT_HOST_SHELL_C_RE.search(code))
            or any(name in _SOFT_OPAQUE_HEADS or (name == "cmd" and any(a.lower() in ("/c", "/k", "/r") for a in args))
                   for name, args, _ in commands)):
        # Merges and null-device redirects never write anything.
        raw = re.sub(r"[\d*]?>&\d|[\d*]?>\s*(?:\$null|nul|/dev/null)(?![\w/])", " ", text, flags=re.IGNORECASE)
        if _soft_command_needs_approval_raw(raw):
            reasons = ["passes text to another shell (cmd /c, iex, ...), so it can't be checked"]
            if code_out is not None:
                code_out.extend(reasons)
            return reasons
        return []
    concerns: list[str] = []
    # Literals put back (separators blanked) for the argument-sensitive patterns.
    inlined = re.sub(r'"(\d+)"',
                     lambda m: '"' + re.sub(r"[\r\n;|&]", " ", lits[int(m.group(1))]) + '"', code)
    for pattern in _SOFT_ALWAYS_ASK_RES:
        if pattern.search(inlined if pattern in _SOFT_ARGUMENT_RES else code):
            concerns.append(_soft_pattern_label(pattern))
    if _SOFT_HTTP_DELETE_RE.search(text):
        concerns.append("sends an HTTP DELETE request")

    variables = {**(_vars or {}), **_soft_assignments(code, lits, posix)}
    resolve = lambda tok: _soft_resolve(tok, lits, variables, cur_cwd, posix)  # noqa: E731

    def show(tok: str) -> str:
        m = re.fullmatch(r'"(\d+)",?', tok)
        return lits[int(m.group(1))] if m else tok

    # Code fed on stdin: heredoc bodies (in order) and literals or variables
    # piped straight into an interpreter.
    heredocs = [lits[int(m.group(2))] for m in re.finditer(r"<<-?\s*(['\"]?)\w+\1[^\n]*\n\"(\d+)\"", code)]
    piped = []
    for m in re.finditer(r"(?:\"(\d+)\"|\$(\w+))\s*\|\s*(?:&\s*)?(?:python[\d.]*w?|py|node|deno|bun)(?:\.exe)?\b",
                         code, re.IGNORECASE):
        piped.append(lits[int(m.group(1))] if m.group(1) else variables.get(m.group(2).lower()))

    def code_concerns(run, run_cwd, args) -> list[str]:
        stdin_code = None
        if run[1] == "stdin":
            fed = any(a.startswith("<<") and not a.startswith("<<<") for a in args)
            if fed and heredocs_left:
                stdin_code = heredocs_left.pop(0)
            elif piped:
                stdin_code = piped.pop(0)
            elif not args:
                return []                    # a bare REPL start (session input)
        found = _soft_code_concerns(run, lits, variables, run_cwd, posix, kind, stdin_code, _depth, text)
        if code_out is not None:
            code_out.extend(found)
        return found

    # Redirects: drop stream merges and null-device targets, check the rest.
    cur_cwd = cwd
    redirect_code = re.sub(r"[\d*]?>&\d", " ", code)
    for chunk_cwd, chunk in _soft_cwd_chunks(redirect_code, lits, variables, cwd, posix):
        cur_cwd = chunk_cwd
        for m in re.finditer(r"(?:&|[\d*])?>>?\s*([^\s;|&)]+)", chunk):
            target = m.group(1)
            literal_target = lits[int(target[1:-1])] if re.fullmatch(r'"\d+"', target) else target
            if literal_target.lower() in _SOFT_NULL_TARGETS:
                continue
            res = resolve(target)
            if not _soft_target_ok(res, delete=False):
                concerns.append(f"writes somewhere that can't be checked: {literal_target}" if res is None
                                else f"writes outside your workspace: {literal_target}")

    cur_cwd = cwd
    heredocs_left = list(heredocs)
    for name, args, head in commands:
        if name in _SOFT_CD_VERBS:
            dest = next((a for a in args if not a.startswith("-")), None)
            res = _soft_resolve(dest, lits, variables, cur_cwd, posix) if dest else None
            cur_cwd = res[1] if res else None
            continue
        if name in ("popd", "pop-location"):
            cur_cwd = None
            continue
        run = _soft_code_run(name, head, args, posix)
        if (run and not posix and re.fullmatch(r'"\d+"', head)
                and not re.search(r"(?:&|(?:^|[\s;(])\.)\s*" + re.escape(head), code)):
            run = None                       # a bare string is output, not a call: $c.IndexOf("x.js")
        if run:
            concerns += code_concerns(run, cur_cwd, args)
            continue
        if any(a.startswith("<<") and not a.startswith("<<<") for a in args) and heredocs_left:
            heredocs_left.pop(0)             # cat > file <<EOF: the body is data
        if name == "git":
            verb, rest = None, list(args)
            while rest:
                tok = rest.pop(0)
                if tok in ("-C", "-c", "--git-dir", "--work-tree"):
                    rest = rest[1:]
                elif not tok.startswith("-"):
                    verb = tok.lower()
                    break
            if verb and verb not in _GIT_READONLY_VERBS and verb not in _SOFT_GIT_EXTRA_VERBS:
                concerns.append(f"changes the Git repository (git {verb})")
            elif verb == "remote":
                sub = next((a.lower() for a in rest if not a.startswith("-")), "")
                if sub in _GIT_REMOTE_MUTATING_VERBS:
                    concerns.append(f"changes the Git repository (git remote {sub})")
            continue
        if name in _SOFT_DELETE_VERBS:
            if posix:
                targets = [a for a in args if not a.startswith("-")]
                contents = False
            else:
                named, positional, flags = _soft_positional(args, ("-path", "-literalpath"))
                targets = named + positional
                contents = bool(flags & {"-filter", "-include", "-exclude"})
            if not targets:
                concerns.append(f"runs {name} on files that aren't known in advance")
            for t in targets:
                res = resolve(t)
                if res and contents:
                    sep = "/" if res[0] == "guest" else "\\"
                    res = (res[0], res[1].rstrip(sep) + sep + "*")
                if not _soft_target_ok(res, delete=True):
                    concerns.append(_soft_delete_reason(res, show(t)))
            continue
        if name in _SOFT_WRITE_VERBS and not posix:
            named, positional, _ = _soft_positional(args, ("-path", "-literalpath", "-filepath"))
            targets = named or positional[:1]
            if not targets:
                concerns.append(f"runs {name} on files that aren't known in advance")
            for t in targets:
                res = resolve(t)
                if not _soft_target_ok(res, delete=False):
                    concerns.append(f"writes somewhere that can't be checked: {show(t)}" if res is None
                                    else f"writes outside your workspace: {show(t)}")
            continue
        if name in _SOFT_PLACE_VERBS:
            copying = name in ("copy-item", "cp", "copy", "cpi", "expand-archive", "tee-object", "tee")
            if posix:
                paths = [a for a in args if not a.startswith("-")]
                checked = paths[-1:] if copying else paths
            else:
                named, positional, _ = _soft_positional(args, ("-path", "-literalpath", "-filepath"))
                dest = _soft_param_values(args, ("-destination", "-destinationpath"))
                if copying and name not in ("tee-object", "tee"):
                    checked = dest or positional[1:2]
                else:
                    checked = named + positional + dest
            for t in checked:
                if _soft_protected(resolve(t)):
                    concerns.append(f"puts files in a protected folder ({name}): {show(t)}")
            continue
        if name in _SOFT_OPEN_VERBS and not posix:
            named, positional, flags = _soft_positional(args, ("-filepath", "-path", "-literalpath"))
            target = (named or positional or [None])[0]
            tool = show(target).lower().replace("/", "\\").rsplit("\\", 1)[-1].removesuffix(".exe") if target else ""
            if tool in _SOFT_DEV_TOOLS and not flags & {"-verb", "-credential"}:
                # A dev server or script in the background: check it as if run directly.
                pieces, i = [], 0
                while i < len(args):
                    if args[i].lower() in ("-argumentlist", "-args"):
                        j = i + 1
                        while j < len(args) and not re.match(r"-[a-z]", args[j], re.IGNORECASE):
                            pieces += [p for p in args[j].split(",") if p]
                            j += 1
                        break
                    i += 1
                values = [show(p) for p in pieces]
                argline = values[0] if len(values) == 1 else " ".join(
                    f'"{v}"' if " " in v and not v.startswith('"') else v for v in values)
                workdir = _soft_param_values(args, ("-workingdirectory",))
                wd_res = resolve(workdir[0]) if workdir else None
                run_cwd = wd_res[1] if wd_res else (None if workdir else cur_cwd)
                inner = _soft_command_concerns(f"{tool} {argline}", kind, run_cwd, code_out=code_out,
                                               _depth=_depth + 1)
                concerns += [f"background {tool}: {c}" for c in inner]
                continue
            res = resolve(target) if target else None
            is_doc = bool(res) and os.path.splitext(res[1])[1].lower() in _SOFT_DOC_EXTS
            if flags & {"-argumentlist", "-args", "-verb"} or not is_doc:
                concerns.append(f"launches a program, not just a document ({name})")
            continue
    return list(dict.fromkeys(concerns))      # dedupe, keep order


def _soft_cwd_chunks(code: str, lits: list[str], variables: dict[str, str],
                     cwd: str | None, posix: bool):
    """Yield (cwd in effect, chunk) for each command chunk, following literal
    cd / Set-Location / Push-Location so relative redirect targets resolve."""
    cur = cwd
    for chunk in re.split(r"\|\||&&|[;\n]", code):
        tokens = chunk.split()
        while tokens and tokens[0].lower() in _SOFT_PREFIX_WORDS:
            tokens = tokens[1:]
        if tokens and tokens[0].lower() in _SOFT_CD_VERBS:
            dest = next((a for a in tokens[1:] if not a.startswith("-")), None)
            res = _soft_resolve(dest, lits, variables, cur, posix) if dest else None
            cur = res[1] if res else None
            continue
        if tokens and tokens[0].lower() in ("popd", "pop-location"):
            cur = None
            continue
        yield cur, chunk


def _soft_command_needs_approval(cmd: str, kind: str = "powershell", cwd: str | None = None) -> bool:
    """Keep Soft useful for normal project work without silently allowing
    commands that delete/overwrite data outside the project, launch or kill
    apps, or change core operating-system state."""
    return bool(_soft_command_concerns(cmd, kind, cwd))


def _diff_preview_rows(old: str, new: str, max_rows: int = 400,
                       max_chars: int = 160) -> tuple[list, int, int]:
    """+N/−M preview for approval gates, as [op, text] row pairs.

    The notch's gate card scrolls through these. Capped so the broadcast
    payload stays bounded: at most max_rows rows are attached, but adds/dels
    count every changed line. Pure difflib — no external diff process."""
    old_lines = str(old or "").splitlines()
    new_lines = str(new or "").splitlines()
    adds = dels = 0
    rows: list = []
    for line in difflib.unified_diff(old_lines, new_lines, lineterm="", n=0):
        if line.startswith(("---", "+++")):
            continue
        op = line[:1]
        if op not in ("+", "-"):
            continue                      # '@@' hunk headers and equal lines
        text = line[1:].rstrip("\r")
        if op == "+":
            adds += 1
        else:
            dels += 1
        if len(rows) < max_rows:
            shown = text[:max_chars] + "…" if len(text) > max_chars else text
            rows.append([op, shown])
    return rows, adds, dels


def _critical_path_gate(path: str, kind: str, title: str) -> dict | None:
    """Hold-to-approve gate for writes under Windows/System32. Returns an error
    dict when denied, None when the path isn't protected or the user
    held-and-approved. Never auto-approves (details['critical'])."""
    if not is_blocked_path(path):
        return None
    approval = request_approval(
        title=title,
        command=f"modify protected system path: {path}",
        details={"kind": kind, "critical": True, "path": path},
    )
    if approval.get("decision") != "approve":
        return {"error": f"user denied protected-path change ({approval.get('status')})"}
    return None


# ---- approval queue --------------------------------------------------------

_approvals: dict[str, dict] = {}
_approval_events: dict[str, threading.Event] = {}
_approvals_lock = threading.Lock()


# Approval kinds that are ordinary in-workspace file writes; "trust writes"
# skips the prompt for them. The calling tools have already checked the path
# is inside the workspace and not a blocked system path.
_SAFE_WRITE_KINDS = {"write_file", "edit_file", "replace_ast_node"}


# Desktop input kinds: the repetitive click/type/keys/scroll/focus actions that
# drive a browser or app. In soft mode they run without a prompt when (A) the
# user's own last message asked for on-screen interaction, or (B) the user
# flipped the per-session desktop switch. Program launch and window close are
# deliberately excluded. Web-tainted desktop actions never reach auto-approve
# (force_prompt is set upstream), so a hostile page cannot drive the mouse.
_DESKTOP_INPUT_KINDS = {
    "desktop.click", "desktop.type", "desktop.keys", "desktop.scroll",
    "desktop.set_value", "desktop.invoke", "desktop.focus",
}
# One token in the session-allow set unlocks every desktop input kind at once, so
# "Allow desktop input for this session" is a single switch, not per-action.
_DESKTOP_SESSION_SENTINEL = "desktop.input.*"


# Kinds the user chose "Always allow (this session)" for — auto-approved until
# the bridge restarts. Never persisted to disk; destructive kinds never enter it
# (the UI only offers "always allow" on safe operations).
_approval_session_allow: set[str] = set()


# ---- /goal full-autonomy mode ---------------------------------------------
# "/goal" latches hands-free mode on for the chat: approvals auto-pass except
# deletions and other destructive actions. The latch persists across turns until
# "/goal off" (or stop / end / done / cancel) or a click on the Goal chip;
# "/goal <task>" latches and runs the task. Critical / force_prompt /
# web-tainted / protected-path requests are excluded before the goal check, so
# /goal cannot bypass the ClickFix guard or a protected-path gate.
#
# The latch lives in memory (a bridge restart clears it) and is mirrored onto
# chat["goal_mode"] so it survives a UI reload and is rehydrated next turn.
#
# Kinds below stay gated even under /goal: they delete data or make a
# hard-to-reverse change. remote_* act on a paired Mac (a separate device) and
# desktop.close can discard unsaved work.
_GOAL_GATE_KINDS = {
    "delete", "registry", "dangerous_import",
    "remote_shell", "remote_file_write", "remote_file_copy",
    "desktop.close",
}
_goal_mode_chats: set[str] = set()
_goal_mode_lock = threading.Lock()


def _set_goal_mode(chat_id: str, on: bool) -> None:
    if not chat_id:
        return
    with _goal_mode_lock:
        if on:
            _goal_mode_chats.add(chat_id)
        else:
            _goal_mode_chats.discard(chat_id)


def _chat_in_goal_mode(chat_id: str) -> bool:
    if not chat_id:
        return False
    with _goal_mode_lock:
        return chat_id in _goal_mode_chats


_GOAL_OFF_RE = re.compile(r"^\s*/goal\s+(off|stop|end|done|cancel)\b\s*$", re.IGNORECASE)
_GOAL_COMMAND_RE = re.compile(r"^\s*/goal\b[ \t]*(.*)$", re.IGNORECASE | re.DOTALL)


def _parse_goal_command(text: str) -> tuple[str, str | None]:
    """Parse a leading /goal slash command. Returns (remaining_task, action):
      - "/goal off|stop|end|done|cancel"  -> ("", "off")
      - "/goal on" | "/goal start" | "/goal" -> ("", "on")   (latch, no task)
      - "/goal <task>"                    -> (task, "on")    (latch + run task)
      - no /goal                          -> (text, None)    (unchanged)
    """
    t = text or ""
    if _GOAL_OFF_RE.match(t):
        return "", "off"
    m = _GOAL_COMMAND_RE.match(t)
    if not m:
        return t, None
    rest = m.group(1).strip()
    if rest.lower() in ("on", "start"):
        rest = ""
    return rest, "on"


def _goal_action_is_gated(kind, command: str, cwd: str | None = None) -> bool:
    """True when a request must keep its approval gate even under /goal: a
    deletion/destructive kind, a shell/git command line that deletes or
    overwrites data (rm, del, format, reg delete, git reset --hard, force
    push, ...), or code it runs that soft mode would stop for."""
    if kind in _GOAL_GATE_KINDS or _is_destructive_command(command or ""):
        return True
    if kind in _SOFT_COMMAND_KINDS and kind != "git":
        code_concerns: list[str] = []
        try:
            _soft_command_concerns(command or "", kind, cwd, code_out=code_concerns)
        except Exception:
            return True
        return bool(code_concerns)
    return False


def _apply_goal_latch(chat_id: str, on: bool) -> bool:
    """Set the hands-free latch for a chat, mirror it onto the persisted chat
    dict (so it survives a UI reload and is rehydrated next turn), and broadcast
    the goal_mode state to every surface. Returns the new active state."""
    _set_goal_mode(chat_id, on)
    try:
        chats = get_chats()
        chat = chats.get("chats", {}).get(chat_id)
        if chat is not None and bool(chat.get("goal_mode")) != bool(on):
            chat["goal_mode"] = bool(on)
            save_json(CHATS_FILE, chats)
    except Exception:
        pass
    broadcast_event({"type": "goal_mode", "chat_id": chat_id, "active": bool(on)})
    return bool(on)


def _desktop_session_unlocked() -> bool:
    return _DESKTOP_SESSION_SENTINEL in _approval_session_allow

# ---- web-taint tracking ----------------------------------------------------
# ClickFix for LLMs: page content (web_fetch, browser-MCP snapshots) can carry
# hidden instructions steering the agent into an install or shell command. Once
# untrusted web content enters the context, any write/execute approval within
# the window is forced to prompt, bypassing soft-mode auto-approve and session
# remembers.
_WEB_TAINT_WINDOW_S = 180.0
_web_taint_at: float = 0.0
_web_taint_lock = threading.Lock()


def _mark_web_taint() -> None:
    global _web_taint_at
    with _web_taint_lock:
        _web_taint_at = time.time()


def _recent_web_taint() -> bool:
    with _web_taint_lock:
        return (time.time() - _web_taint_at) < _WEB_TAINT_WINDOW_S


# ---- browser-interaction intent (ClickFix click gating) ---------------------
# Playwright MCP interactive verbs (click/fill/type/...) run freely only when the
# user's own last message asked for page interaction; a page-driven "click the
# download button" goes through an approval card even in soft mode.
_last_user_text: str = ""

_BROWSER_INTENT_RE = re.compile(
    r"\b(click|fill|type|press|select|check|submit|login|log\s+in|sign\s+in|"
    r"signin|register|complete|captcha|verify|button|form|scroll|hover|upload|"
    r"download|input|toggle|agree|accept)\b",
    re.IGNORECASE,
)


_DESKTOP_INTENT_RE = re.compile(
    r"\b(open|launch|start|focus|close|click|type|press|select|toggle|scroll|"
    r"control|operate|interact|use)\b[^\n]{0,80}\b(app|application|window|"
    r"desktop|screen|computer|notepad|calculator|explorer|browser|excel|word)\b|"
    r"\b(app|application|window|desktop|screen|computer|notepad|calculator|"
    r"explorer|browser|excel|word)\b[^\n]{0,80}\b(open|launch|start|focus|"
    r"close|click|type|press|select|toggle|scroll|control|operate|interact|use)\b|"
    r"(?:^|[.!?]\s+)(?:please\s+)?(?:open|launch|start|close)\s+\S+",
    re.IGNORECASE | re.MULTILINE,
)


def _user_asked_browser_interaction() -> bool:
    return bool(_BROWSER_INTENT_RE.search(_last_user_text or ""))


def _user_asked_desktop_interaction(text: str) -> bool:
    return bool(_DESKTOP_INTENT_RE.search(str(text or "")))


def _is_desktop_approval_kind(kind: str) -> bool:
    return str(kind or "").startswith(("desktop_", "desktop."))


# Playwright MCP verbs that MUTATE page state (as opposed to reads like
# snapshot/screenshot/navigate). Interactive verbs are the ClickFix surface.
_INTERACTIVE_MCP_RE = re.compile(
    r"\b(click|dblclick|fill|type|press|check|uncheck|select_option|upload_file|"
    r"drag_and_drop|hover|scroll_into_view|submit|keyboard|mouse|download|"
    r"browser_evaluate|evaluate)\b",
    re.IGNORECASE,
)

# MCP tools whose output is untrusted PAGE content (browser/server reads).
_MCP_BROWSER_TOOL_RE = re.compile(
    r"(playwright|browser|page)", re.IGNORECASE,
)


def request_approval(title: str, command: str, details: dict | None = None, timeout_s: int = 600) -> dict:
    """Create a pending approval, block the worker until the user responds, and
    return the decision. Soft mode allows routine, non-destructive project work;
    medium trusts only validated in-workspace writes; hard prompts for every
    action. Critical, remote, web-tainted and forced actions always keep their
    stricter gate."""
    details = details or {}
    kind = details.get("kind")
    # Web-taint gate: untrusted web/MCP content entered the context recently and
    # this request writes or executes. That is the ClickFix chain, so prompt even
    # in soft mode and even for a session-remembered kind.
    if (details.get("web_tainted") is None
            and _recent_web_taint()
            and (kind in _SOFT_COMMAND_KINDS
                 or kind in _SAFE_WRITE_KINDS
                 or _is_desktop_approval_kind(kind))):
        details["web_tainted"] = True
        details["force_prompt"] = True
    # The frontend may only offer "remember for this session" on kinds the
    # bridge actually honors in decide_approval (safe writes + MCP tools + the
    # desktop input group, which ticks the single per-session switch).
    details.setdefault("allow_always",
                       bool(kind) and (kind in _SAFE_WRITE_KINDS or kind.startswith("mcp_")
                                       or kind in _DESKTOP_INPUT_KINDS))
    if kind in _DESKTOP_INPUT_KINDS:
        details.setdefault("allow_always_label", "Allow desktop input for this session")
    try:
        if not details.get("critical") and not details.get("force_prompt"):
            # /goal: auto-pass everything except destructive actions, overriding the
            # soft/medium/hard mode. Critical, force_prompt and web-tainted requests were
            # already excluded above; destructive ones fall through to the normal gate.
            if _chat_in_goal_mode(_get_current_chat()):
                if _goal_action_is_gated(kind, command, details.get("cwd")):
                    details.setdefault("goal_gated", True)
                else:
                    return {"status": "goal-auto-approved", "decision": "approve",
                            "auto": True, "goal": True, "details": details}
            # protected ops and explicitly remote mutations NEVER auto-approve
            mode = _approval_mode()
            if kind and kind in _approval_session_allow:
                return {"status": "session-approved", "decision": "approve", "auto": True, "details": details}
            # (B) The per-session desktop switch: one sentinel unlocks every
            # desktop input kind, in any mode (an explicit user opt-in, like other
            # session-remembers). force_prompt / web-taint still override above.
            if kind in _DESKTOP_INPUT_KINDS and _desktop_session_unlocked():
                return {"status": "session-approved", "decision": "approve", "auto": True, "details": details}
            if mode != "hard" and kind in _SAFE_WRITE_KINDS:
                return {"status": "auto-approved", "decision": "approve", "auto": True, "details": details}
            if mode == "soft":
                if kind in _SOFT_PROMPT_KINDS:
                    pass                                    # delete/registry/launch stay gated
                elif _is_desktop_approval_kind(kind):
                    # (A) Intent: desktop INPUT runs free in soft mode when the
                    # user's own last message asked for on-screen/browser action.
                    # Launch/close are not input kinds, so they still prompt.
                    if kind in _DESKTOP_INPUT_KINDS and _user_asked_desktop_interaction(_last_user_text):
                        return {"status": "auto-approved", "decision": "approve", "auto": True, "details": details}
                    # otherwise desktop stays gated
                elif (kind or "").startswith("mcp_"):
                    if not _MCP_SOFT_BLOCK.search(kind):    # playwright runs free; delete-ish MCP still prompts
                        return {"status": "auto-approved", "decision": "approve", "auto": True, "details": details}
                elif kind in _SOFT_COMMAND_KINDS:           # shell-ish: deletions still prompt
                    if kind == "git":
                        # git read verbs may run free in soft mode; any mutating verb prompts, since
                        # the destructive regex can't catch every history-rewriting git command.
                        argv = details.get("argv")
                        if _git_argv_is_readonly(argv):
                            concerns = _soft_command_concerns(command or "")
                        else:
                            verb = argv[0] if isinstance(argv, list) and argv else "command"
                            concerns = [f"changes the Git repository (git {verb})"]
                    else:
                        concerns = _soft_command_concerns(command or "", kind, details.get("cwd"))
                    if not concerns:
                        return {"status": "auto-approved", "decision": "approve", "auto": True, "details": details}
                    # Shown on the approval card: why Soft stopped for this one.
                    details["soft_reasons"] = concerns[:4]
                elif kind in _SOFT_AUTO_KINDS:
                    return {"status": "auto-approved", "decision": "approve", "auto": True, "details": details}
    except Exception:
        pass
    aid = uuid.uuid4().hex[:12]
    ev = threading.Event()
    entry = {
        "id": aid,
        "chat_id": _get_current_chat(),
        "title": title,
        "command": command,
        "details": details or {},
        "created": time.time(),
        "status": "pending",
        "decision": None,
    }
    with _approvals_lock:
        _approvals[aid] = entry
        _approval_events[aid] = ev
    save_json(PENDING_DIR / f"{aid}.json", entry)
    broadcast_event({"type": "approval:new", "approval": entry})
    deadline = time.monotonic() + timeout_s
    got = False
    while time.monotonic() < deadline:
        if _steering.pending(_current_chat_id.get()):
            decide_approval(aid, "deny")
        if ev.wait(timeout=min(.2, max(0, deadline - time.monotonic()))):
            got = True
            break
    with _approvals_lock:
        final = _approvals.pop(aid, entry)
        _approval_events.pop(aid, None)
    (PENDING_DIR / f"{aid}.json").unlink(missing_ok=True)
    if not got:
        final["status"] = "timeout"
        final["decision"] = "deny"
    return final


def decide_approval(aid: str, decision: str, always: bool = False) -> bool:
    with _approvals_lock:
        entry = _approvals.get(aid)
        ev = _approval_events.get(aid)
        if not entry or not ev:
            return False
        entry["decision"] = "approve" if decision == "approve" else "deny"
        entry["status"] = "decided"
        if always and entry["decision"] == "approve":
            kind = (entry.get("details") or {}).get("kind")
            # Session-allow only safe kinds, whatever the client asked to remember.
            if kind and (kind in _SAFE_WRITE_KINDS or kind.startswith("mcp_")):
                _approval_session_allow.add(kind)
            # A desktop input kind flips the ONE sentinel, so the whole input
            # group (click/type/keys/scroll/focus) is unlocked for the session.
            elif kind in _DESKTOP_INPUT_KINDS:
                _approval_session_allow.add(_DESKTOP_SESSION_SENTINEL)
        ev.set()
    broadcast_event({"type": "approval:decided", "id": aid, "decision": entry["decision"]})
    return True


def list_approvals() -> list[dict]:
    with _approvals_lock:
        return [dict(v) for v in _approvals.values() if v.get("status") == "pending"]


# ---- notch overlay (lite desktop widget) -------------------------------------
# A small transparent always-on-top island (accuretta-notch.html) rendered by its
# own host process and wired to this bridge over /api/events + the REST API:
# notch_host.py on Windows (Win32 + pywebview's WebView2), notch_host_mac.py on
# macOS (AppKit + WebKit via PyObjC). Being a separate process, it keeps working
# while the main window is minimized; it dies with the bridge (atexit + its own
# health poll).

_notch_proc = None
_notch_lock = threading.Lock()


def _notch_host_script() -> Path | None:
    """The overlay host for this platform, or None where there is none."""
    if sys.platform == "win32":
        return ROOT / "notch_host.py"
    if sys.platform == "darwin":
        return ROOT / "notch_host_mac.py"
    return None


def _notch_host_available() -> bool:
    script = _notch_host_script()
    if script is None or not script.is_file() or not (ROOT / "accuretta-notch.html").is_file():
        return False
    try:
        import importlib.util
        if sys.platform == "darwin":
            return all(importlib.util.find_spec(m) is not None for m in ("AppKit", "WebKit", "objc"))
        spec = importlib.util.find_spec("webview")
        if not (spec and spec.submodule_search_locations):
            return False
        lib = Path(list(spec.submodule_search_locations)[0]) / "lib" / "Microsoft.Web.WebView2.Core.dll"
        return lib.is_file()
    except Exception:
        return False


def notch_start() -> bool:
    """Spawn the overlay host process (idempotent)."""
    global _notch_proc
    import subprocess
    with _notch_lock:
        if _notch_proc is not None and _notch_proc.poll() is None:
            return True
        if not _notch_host_available():
            return False
        env = dict(os.environ)
        env["ACCURETTA_PORT"] = str(PORT)
        try:
            _notch_proc = subprocess.Popen(
                [sys.executable, str(_notch_host_script())],
                cwd=str(ROOT), env=env,
                stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL, close_fds=True,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            return True
        except Exception:
            _notch_proc = None
            return False


def notch_stop() -> None:
    global _notch_proc
    with _notch_lock:
        proc, _notch_proc = _notch_proc, None
    if proc is not None and proc.poll() is None:
        try:
            proc.terminate()
            proc.wait(timeout=5)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass


def notch_sync() -> None:
    """Start/stop the overlay so it matches the notch_enabled setting."""
    if get_settings().get("notch_enabled"):
        notch_start()
    else:
        notch_stop()


# ---- SSE event bus ---------------------------------------------------------
# Reconnect-friendly pub/sub. Each broadcast gets a monotonic id and goes into a
# small ring buffer (EVENT_LOG_MAX). The SSE handler replays anything after the
# request's `Last-Event-ID`, then resumes the live stream, so brief disconnects
# don't lose tool_result or approval events. Subscribers get the snapshot id at
# subscribe time, so replay and live queue never duplicate an event.

from collections import deque

EVENT_LOG_MAX = 256

_subscribers: list[Queue] = []
_subs_lock = threading.Lock()
_event_log: deque = deque(maxlen=EVENT_LOG_MAX)  # holds (id, evt) tuples
_event_log_id = 0  # monotonic counter, only incremented under _subs_lock


def subscribe() -> tuple[Queue, int]:
    """Returns (queue, snapshot_id): the highest event id that existed before this
    subscription. The SSE handler replays only up to it; anything newer arrives
    via the queue."""
    q: Queue = Queue(maxsize=1024)
    with _subs_lock:
        _subscribers.append(q)
        return q, _event_log_id


def unsubscribe(q: Queue) -> None:
    with _subs_lock:
        if q in _subscribers:
            _subscribers.remove(q)


# Event types forwarded live but excluded from the resume ring buffer (see
# broadcast_event). ctx_fill fires once per agentic round.
_TRANSIENT_EVENT_TYPES = frozenset({"ctx_fill", "summary_folding"})

# Token deltas normally travel over the chat POST response, but the notch
# mirrors turns running on another surface and only sees them here. They are
# best-effort: never logged (one token per ring slot would flush approvals out
# of the resume log in seconds) and dropped under backpressure rather than
# evicting a durable event.
_BEST_EFFORT_EVENT_TYPES = frozenset({"delta", "thinking_delta", "tool_progress"})

# Count of events discarded for a slow subscriber (queue full). Never removes
# the subscriber; surfaced only so a persistent flood is observable.
_dropped_event_count = 0


def broadcast_event(evt: dict) -> None:
    global _event_log_id, _dropped_event_count
    best_effort = evt.get("type") in _BEST_EFFORT_EVENT_TYPES
    with _subs_lock:
        logged = dict(evt)
        if not best_effort:
            # Per-round gauge noise goes to live subscribers but is not logged; a long
            # turn would otherwise flush resumable state out of the ring buffer.
            transient = evt.get("type") in _TRANSIENT_EVENT_TYPES
            if not transient:
                _event_log_id += 1
            evt_id = _event_log_id if not transient else None
            # Tag a copy so the caller's dict isn't mutated. The SSE handler writes
            # evt['_id'] into the wire `id:` field for Last-Event-ID resume.
            if evt_id is not None:
                logged["_id"] = evt_id
                _event_log.append((evt_id, logged))
        for q in _subscribers:
            try:
                q.put_nowait(logged)
            except Full:
                if best_effort:
                    # A token is expendable; a durable event is not. Drop the
                    # chatter, keep the queue untouched.
                    _dropped_event_count += 1
                    continue
                # A slow subscriber must not be silently unsubscribed while its HTTP stream
                # stays open (EventSource would never notice and reconnect). Drop its oldest
                # queued event instead.
                try:
                    q.get_nowait()
                    q.put_nowait(logged)
                    _dropped_event_count += 1
                except Exception:
                    pass
            except Exception:
                pass


def replay_events_since(since_id: int, up_to_id: int) -> list:
    """Return logged events with since_id < id <= up_to_id, in order.
    Snapshot under the lock so we don't iterate a deque mid-append."""
    with _subs_lock:
        return [(i, e) for (i, e) in _event_log if since_id < i <= up_to_id]


# ---- tool implementations --------------------------------------------------

def tool_list_directory(args: dict) -> dict:
    path = normalize_path(args.get("path") or str(Path.home()))
    if is_blocked_path(path):
        return {"error": "path blocked (Windows/System32)"}
    if not os.path.isdir(path):
        return {"error": f"not a directory: {path}", "expected_type": "directory",
                "actual_type": "file" if os.path.isfile(path) else "unknown"}
    out = []
    skipped = 0
    try:
        for entry in sorted(os.listdir(path)):
            full = os.path.join(path, entry)
            if is_ignored(full):
                skipped += 1
                continue
            try:
                st = os.stat(full)
                out.append({
                    "name": entry,
                    "path": full,
                    "dir": os.path.isdir(full),
                    "size": st.st_size if os.path.isfile(full) else None,
                    "mtime": int(st.st_mtime),
                })
            except Exception:
                continue
    except PermissionError as e:
        return {"error": f"permission denied: {e}"}
    resp = {"path": path, "entries": out[:200]}
    if skipped:
        resp["ignored"] = skipped
    if len(out) > 200:
        resp["truncated"] = True
    return resp


# Cap on extracted PDF text; matches the 64 KB binary cap used elsewhere.
_PDF_TEXT_CAP = 64 * 1024


def _extract_pdf_text(path: str) -> dict:
    """Pull a text rendering out of a PDF for the model to read.

    Tries pypdf, then pdfplumber (better with table-like layouts), then fails
    with an install hint. Scanned (image-only) PDFs have no text layer; that is
    flagged explicitly so the model suggests OCR instead of reporting an empty
    file."""
    try:
        from pypdf import PdfReader  # type: ignore
    except Exception:
        try:
            # very old envs sometimes only have PyPDF2 — same API
            from PyPDF2 import PdfReader  # type: ignore
        except Exception:
            PdfReader = None  # type: ignore

    pages_text: list[str] = []
    page_count = 0
    backend_used = ""
    last_err = ""

    if PdfReader is not None:
        try:
            reader = PdfReader(path)
            page_count = len(reader.pages)
            for i, page in enumerate(reader.pages):
                try:
                    t = page.extract_text() or ""
                except Exception as e:
                    t = f"[page {i + 1}: extraction error — {e}]"
                if t.strip():
                    pages_text.append(f"--- page {i + 1} ---\n{t.rstrip()}")
                # short-circuit if we already blew the cap
                if sum(len(p) for p in pages_text) > _PDF_TEXT_CAP:
                    break
            backend_used = "pypdf"
        except Exception as e:
            last_err = f"pypdf failed: {e}"

    # If pypdf gave us nothing usable, try pdfplumber (better with tables).
    if not pages_text:
        try:
            import pdfplumber  # type: ignore
            with pdfplumber.open(path) as pdf:
                page_count = len(pdf.pages)
                for i, page in enumerate(pdf.pages):
                    try:
                        t = page.extract_text() or ""
                    except Exception as e:
                        t = f"[page {i + 1}: extraction error — {e}]"
                    if t.strip():
                        pages_text.append(f"--- page {i + 1} ---\n{t.rstrip()}")
                    if sum(len(p) for p in pages_text) > _PDF_TEXT_CAP:
                        break
            backend_used = "pdfplumber"
        except ImportError:
            pass
        except Exception as e:
            last_err = (last_err + " · " if last_err else "") + f"pdfplumber failed: {e}"

    if PdfReader is None and not backend_used:
        return {
            "error": (
                "PDF text extraction needs pypdf. Install with:\n"
                "  pip install pypdf\n"
                "(optional, better for tables: pip install pdfplumber)"
            )
        }

    text = "\n\n".join(pages_text).strip()
    if not text:
        # Empty extract usually means a scanned/image-only PDF, or the PDF
        # was malformed. Either way the model needs to know it's not blank.
        msg = (
            f"[no extractable text — PDF appears to be scanned (image-only) "
            f"or has no text layer; {page_count} page(s) found]"
        )
        if last_err:
            msg += f"\n[extractor note: {last_err}]"
        return {
            "path": path,
            "content": msg,
            "truncated": False,
            "size": os.path.getsize(path),
            "pdf": {"pages": page_count, "backend": backend_used or "none", "empty": True},
        }

    truncated = len(text) > _PDF_TEXT_CAP
    if truncated:
        text = text[:_PDF_TEXT_CAP] + "\n\n[... PDF truncated to 64 KB ...]"
    return {
        "path": path,
        "content": text,
        "truncated": truncated,
        "size": os.path.getsize(path),
        "pdf": {"pages": page_count, "backend": backend_used, "empty": False},
    }


# ---- file read-state tracking (anti-stale / anti-clobber) -----------------
# Record each file's on-disk hash when the model reads it, per chat, and refuse
# a full overwrite of a file it never read (or that changed since): the main
# cause of "it undid its own fix" on long tasks.
_chat_file_reads: dict[str, dict[str, str]] = {}
_chat_file_reads_lock = threading.Lock()


def _file_md5(path: str) -> str:
    import hashlib
    try:
        return hashlib.md5(Path(path).read_bytes()).hexdigest()
    except Exception:
        return ""


def _record_file_read(path: str) -> None:
    cid = _get_current_chat()
    if not cid:
        return
    h = _file_md5(path)
    if h:
        with _chat_file_reads_lock:
            _chat_file_reads.setdefault(cid, {})[normalize_path(path)] = h


def _file_staleness(path: str) -> str:
    """'' = the model's view is current. Otherwise a short reason it may be stale."""
    cid = _get_current_chat()
    if not cid or not os.path.isfile(path):
        return ""
    npath = normalize_path(path)
    with _chat_file_reads_lock:
        seen = _chat_file_reads.get(cid, {}).get(npath)
    if seen is None:
        return "never read this session"
    cur = _file_md5(path)
    if cur and cur != seen:
        return "changed since you last read it"
    return ""


def tool_read_file(args: dict) -> dict:
    path = normalize_path(args.get("path") or "")
    if not path or not os.path.isfile(path):
        return {"error": f"not a file: {path}"}
    if is_blocked_path(path):
        return {"error": "path blocked (Windows/System32)"}
    if not is_in_workspace(path):
        return {"error": "path outside workspace. Add folder in Workspace panel."}
    if is_ignored(path):
        return {"error": f"path ignored by .accurettaignore: {path}"}
    # PDFs are binary containers; read as UTF-8 they are garbage. Route them
    # through the extractor, which returns page-numbered text or a clear note for
    # scanned PDFs.
    if path.lower().endswith(".pdf"):
        return _extract_pdf_text(path)
    # Line-based pagination via `offset` (0-indexed starting line). A truncated
    # response says explicitly that repeating the same call returns the same chunk,
    # because models otherwise loop on read_file hoping for fresh bytes.
    offset = max(0, int(args.get("offset") or 0))
    limit = max(0, int(args.get("limit") or 0))
    # 20KB chunk: enough for a function or a chunk of HTML, yet small enough that
    # the serialized result stays under the read_file result cap (32000) so
    # compress_tool_result never truncates it a second time. Keep the two in sync.
    BYTE_CAP = 20 * 1024
    try:
        try:
            full_text = Path(path).read_text(encoding="utf-8-sig")
        except UnicodeDecodeError:
            full_text = Path(path).read_bytes().decode("latin-1", errors="replace")
        total_size = len(full_text.encode("utf-8", errors="replace"))
        lines = full_text.splitlines(keepends=True)
        total_lines = len(lines)
        _record_file_read(path)  # the model has now seen this file's current state
        if offset >= total_lines and total_lines > 0:
            return {
                "path": path,
                "content": "",
                "offset": offset,
                "total_lines": total_lines,
                "size": total_size,
                "note": (
                    f"offset {offset} is past EOF — file has {total_lines} lines "
                    f"(0-indexed: 0..{total_lines - 1}). Nothing to read here."
                ),
            }
        # Walk lines from offset until BYTE_CAP, always including at least one line
        # so a giant single-line minified file still returns something.
        chunk_parts: list[str] = []
        byte_count = 0
        end = offset
        for i in range(offset, total_lines):
            line_bytes = len(lines[i].encode("utf-8", errors="replace"))
            if (byte_count + line_bytes > BYTE_CAP or (limit and i - offset >= limit)) and chunk_parts:
                break
            chunk_parts.append(lines[i])
            byte_count += line_bytes
            end = i + 1
        chunk = "".join(chunk_parts)
        truncated = end < total_lines
        out: dict = {
            "path": path,
            "content": chunk,
            "offset": offset,
            "lines_returned": end - offset,
            "total_lines": total_lines,
            "size": total_size,
            "truncated": truncated,
        }
        if truncated:
            out["next_offset"] = end
            out["hint"] = (
                f"This is the COMPLETE, untruncated chunk for lines {offset}-{end - 1} "
                f"of {total_lines}. To read the next chunk, call read_file with "
                f"offset={end}. To jump straight to the part you need instead of "
                f"paging, call grep_files (search for a string) or read_skeleton "
                f"(code structure/signatures). Retrying with the same args returns "
                f"the same bytes — the file is fixed on disk."
            )
        return out
    except Exception as e:
        return {"error": str(e)}

def _run_linter(path: str) -> str:
    """Run a fast linter on the file. Returns error message if failed, empty string if passed."""
    import subprocess
    ext = os.path.splitext(path)[1].lower()
    
    if ext == ".py":
        try:
            res = subprocess.run(
                ["flake8", "--isolated", "--select=E9,F821,F822,F823", path],
                capture_output=True,
                text=True,
                timeout=5,
                creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0),
            )
            if res.returncode == 0:
                return ""
            if res.stdout.strip():
                return f"flake8 syntax/name error:\n{res.stdout.strip()}"
        except Exception:
            pass
        # flake8 missing or inconclusive: an in-process compile still catches a real
        # syntax error, so a broken edit doesn't come back looking clean.
        try:
            compile(Path(path).read_text(encoding="utf-8", errors="replace"), path, "exec")
        except SyntaxError as e:
            return f"python syntax error: {e.msg} (line {e.lineno})"
        except Exception:
            pass
            
    elif ext in [".js", ".jsx", ".ts", ".tsx"]:
        dirpath = os.path.dirname(path)
        has_pkg = False
        while dirpath and dirpath != os.path.dirname(dirpath):
            if os.path.isfile(os.path.join(dirpath, "package.json")):
                has_pkg = True
                break
            dirpath = os.path.dirname(dirpath)
            
        if has_pkg:
            try:
                cmd = ["npx", "--no", "eslint", path]
                res = subprocess.run(
                    cmd,
                    capture_output=True,
                    text=True,
                    timeout=10,
                    creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0),
                )
                if res.returncode != 0:
                    return f"eslint error:\n{res.stdout.strip()}"
            except Exception:
                pass

    elif ext == ".json":
        try:
            json.loads(Path(path).read_text(encoding="utf-8", errors="replace"))
        except ValueError as e:
            return f"invalid JSON: {e}"
        except Exception:
            pass

    elif ext in (".yaml", ".yml"):
        try:
            import yaml  # type: ignore
        except Exception:
            return ""
        try:
            yaml.safe_load(Path(path).read_text(encoding="utf-8", errors="replace"))
        except Exception as e:
            return f"invalid YAML: {e}"
    return ""


# ---- per-turn undo journal -------------------------------------------------
# Snapshot a file's prior state right before a mutating tool writes it, so a
# whole turn's file changes can be reverted from the UI in one click. Turns run
# serially, so one in-memory journal plus one on-disk copy per turn is enough.
# Restore writes prior content back or deletes files the turn created;
# directories and binary/unreadable files are not offered for undo.
_UNDO_DIR = DATA / "undo"
_undo_store = UndoStore(_UNDO_DIR)


def _emit_chat_event(evt: dict) -> None:
    """Emit an SSE event on the active chat's live stream, if one is running."""
    try:
        cid = _current_chat_id.get()
        emit = _chat_emitters.get(cid) if cid else None
        if emit:
            emit(evt)
    except Exception:
        pass


def _undo_begin_turn(chat_id: str) -> None:
    _undo_store.begin(chat_id)


def _undo_snapshot(path: str) -> None:
    _undo_store.snapshot(normalize_path(path))


def _open_folder_in_file_manager(raw_path: str) -> dict:
    """Open a folder in the OS file manager (Explorer/Finder/xdg-open).

    The only guard is a protected system path (Windows/System32, registry hives,
    ...); the agent can't write there anyway, so this never blocks a folder it
    actually saved to."""
    p = str(raw_path or "").strip()
    if not p:
        return {"error": "no path"}
    try:
        real = Path(os.path.realpath(p))
    except Exception:
        return {"error": "bad path"}
    if not real.is_dir():
        return {"error": "not a folder"}
    if is_blocked_path(str(real)):
        return {"error": "cannot open a protected system folder"}
    try:
        if os.name == "nt":
            os.startfile(str(real))  # type: ignore[attr-defined]
        elif sys.platform == "darwin":
            subprocess.Popen(["open", str(real)])
        else:
            subprocess.Popen(["xdg-open", str(real)])
    except Exception as e:
        return {"error": f"could not open: {e}"}
    return {"ok": True, "path": str(real)}


def _undo_commit_turn() -> dict | None:
    return _undo_store.commit()


def _undo_restore(turn_id: str, *, chat_id: str = "", file_index: int | None = None) -> dict:
    result = _undo_store.restore(str(turn_id or "").strip(), chat_id=chat_id, file_index=file_index)
    if result.get("ok"):
        snapshot = get_chats()
        for chat in snapshot.get("chats", {}).values():
            for item in chat.get("undo_turns", []):
                if item.get("turn_id") == turn_id:
                    item["undone"] = result.get("remaining", 0) == 0
                    if file_index is not None and 0 <= file_index < len(item.get("files", [])):
                        item["files"][file_index]["restorable"] = False
                        item["files"][file_index]["undone"] = True
        save_json(CHATS_FILE, snapshot)
    broadcast_event({"type": "workspace:update"})
    return result


def _with_code_check(result: dict, findings: str) -> dict:
    if findings:
        result["code_check"] = {"status": "issues_found", "details": findings,
                                "introduced_by_edit": "unknown"}
        result["verification_guidance"] = (
            "The file change was saved. The code check found issues; whether they predate "
            "this edit is unknown. Compare with the previous version, address issues caused "
            "by this change, and report unresolved issues. Do not repeat the write just "
            "because the check found issues."
        )
    return result


# Text files keep their own line endings and BOM. Path.write_text() on Windows
# writes every "\n" as "\r\n", so one edit_file call on an LF file used to flip
# every line ending: git showed the whole file as changed and LF-enforcing
# formatters failed. Edits work on LF text; the original format is restored on
# write.
_UTF8_BOM = b"\xef\xbb\xbf"


def _decode_text_file(raw: bytes) -> tuple[str, str, bool]:
    """(text with LF line endings, the file's line ending, whether it has a BOM)."""
    bom = raw.startswith(_UTF8_BOM)
    text = raw.decode("utf-8-sig")
    eol = "\r\n" if text.count("\r\n") * 2 > text.count("\n") else "\n"
    return text.replace("\r\n", "\n"), eol, bom


def _encode_text_file(text: str, eol: str, bom: bool) -> bytes:
    text = text.replace("\r\n", "\n")
    if eol != "\n":
        text = text.replace("\n", eol)
    return (_UTF8_BOM if bom else b"") + text.encode("utf-8")


def _new_file_eol(path: str) -> str:
    """Line ending for a new file: CRLF for batch files, else what a sibling
    with the same extension uses, else LF."""
    ext = os.path.splitext(path)[1].lower()
    if ext in (".bat", ".cmd"):
        return "\r\n"
    if ext:
        try:
            for sibling in sorted(Path(path).parent.glob(f"*{ext}"))[:5]:
                if sibling.is_file():
                    sample = sibling.read_bytes()[:65536]
                    if b"\n" in sample:
                        return "\r\n" if sample.count(b"\r\n") * 2 > sample.count(b"\n") else "\n"
        except OSError:
            pass
    return "\n"


def _closest_region(text: str, needle: str, context: int = 2, max_lines: int = 12) -> str:
    """Numbered file lines that best match the first line of a missed old_text,
    so the model can correct the edit without reading the whole file again."""
    lines = text.splitlines()
    want = needle.strip().splitlines() or [needle.strip()]
    first = want[0].strip()
    if not first:
        return ""
    best_i, best_score = -1, 0.0
    for i, line in enumerate(lines):
        score = difflib.SequenceMatcher(None, line.strip(), first).ratio()
        if score > best_score:
            best_i, best_score = i, score
    if best_i < 0 or best_score < 0.6:
        return ""
    lo = max(0, best_i - context)
    hi = min(len(lines), best_i + len(want) + context, lo + max_lines)
    return "\n".join(f"{n + 1}: {lines[n]}" for n in range(lo, hi))


# Content of a write the anti-clobber guard blocked, kept so a confirmed retry
# with force=true does not have to send the whole file again. One per chat and
# path; it expires after 30 minutes and goes with any successful write there.
_blocked_writes: dict[tuple[str, str], tuple[float, str]] = {}
_BLOCKED_WRITE_TTL_S = 1800


def _blocked_write_key(path: str) -> tuple[str, str]:
    return _get_current_chat() or "", os.path.normcase(normalize_path(path or ""))


def _blocked_write(path: str) -> str | None:
    key = _blocked_write_key(path)
    entry = _blocked_writes.get(key)
    if entry and time.time() - entry[0] > _BLOCKED_WRITE_TTL_S:
        _blocked_writes.pop(key, None)
        entry = None
    return entry[1] if entry else None


def tool_write_file(args: dict) -> dict:
    path = normalize_path(args.get("path") or "")
    content = args.get("content")
    # Append adds a chunk at the end of the file, so a large file can be built
    # in parts that each fit comfortably in one reply.
    append = str(args.get("mode") or "overwrite").strip().lower() == "append"
    source_meta: dict = {}
    if not path:
        return {"error": "missing path"}
    if args.get("source"):
        if isinstance(content, str) and content.strip():
            return {"error": "refused: provide either content or source, not both. No file was written."}
        block, source_error = _visible_code_source(args)
        if source_error:
            return {"error": source_error}
        content = block["content"]
        source_meta = {
            "source": "visible_chat_code_block",
            "language": block["language"],
            "message_index": block["message_index"],
        }
    elif args.get("force") and not (isinstance(content, str) and content.strip()):
        content = _blocked_write(path)
        if content is not None:
            source_meta = {"source": "blocked_write"}
    if not isinstance(content, str) or not content.strip():
        return {"error": "refused: content or source is empty or missing. No file was written."}
    if is_bridge_self_path(path):
        return {"error": "refused: bridge.py is the running server — edit it from your real IDE, not from a chat tool call. Restart the bridge afterward."}
    _cerr = _critical_path_gate(path, "write_file", "PROTECTED PATH - write under Windows/System32")
    if _cerr:
        return _cerr
    if not is_in_workspace(path):
        return {"error": "path outside workspace. Add folder in Workspace panel."}
    if is_ignored(path):
        return {"error": f"path ignored by .accurettaignore: {path}"}
    # Anti-clobber: refuse to overwrite an existing file the model hasn't read this
    # session (or that changed since). An empty file is exempt: it is usually the
    # leftover of an earlier failed write (arguments stripped by llama.cpp's
    # parser), there is nothing in it to protect, and blocking would deadlock the
    # agent in a "exists -> never read -> blocked" loop.
    _existing_len = 0
    try:
        _existing_len = os.path.getsize(path) if os.path.isfile(path) else 0
    except OSError:
        pass
    if os.path.isfile(path) and not bool(args.get("force")):
        stale = ("" if _existing_len == 0 else _file_staleness(path))
        if stale:
            _blocked_writes[_blocked_write_key(path)] = (time.time(), content)
            while len(_blocked_writes) > 8:
                _blocked_writes.pop(next(iter(_blocked_writes)))
            return {"error": (f"write blocked: this file exists and was {stale}. Call read_file on it "
                              f"first so you overwrite the CURRENT contents, not a stale assumption — "
                          f"then write_file again. If you truly mean to replace the whole file, pass "
                              f"force=true. To write the content you just sent, call write_file with "
                              f"this path and force=true and leave out content."),
                    "path": path, "reason": stale}
    # Rewrite-loop breaker: refuse the Nth full rewrite of the same file in one
    # turn. The model can't verify a fresh version is better and spirals into
    # "let me rewrite from scratch"; this forces targeted edits instead.
    _npath = normalize_path(path)
    _prior = _write_count(_npath)
    if (not append and os.path.isfile(path) and _prior >= REWRITE_LOOP_LIMIT
            and not bool(args.get("force_rewrite"))):
        return {"error": (f"rewrite loop blocked: you have already rewritten this file {_prior} time(s) this "
                          f"turn and it IS saved. STOP rewriting from scratch — you cannot verify a fresh "
                          f"version is better and you are spiralling. Instead: if a SPECIFIC thing is wrong, "
                              f"use edit_file for a targeted change, or check the saved result against the request. "
                              f"The rewrite limit does not establish correctness. Only pass force_rewrite=true with a concrete reason."),
                    "path": path, "rewrites_this_turn": _prior, "loop_breaker": True, "not_executed": True}
    # Diff preview rows for the approval card (the notch renders them). Read-only
    # peek; the write itself happens only after the decision.
    _old_for_diff = ""
    try:
        if os.path.isfile(path):
            _old_for_diff = Path(path).read_text(encoding="utf-8", errors="replace")
    except Exception:
        _old_for_diff = ""
    _diff_rows, _adds, _dels = _diff_preview_rows(
        _old_for_diff, _old_for_diff + content if append else content)
    _wf_details = {"kind": "write_file", "path": path, "bytes": len(content.encode('utf-8'))}
    if append:
        _wf_details["mode"] = "append"
    if _diff_rows:
        _wf_details["diff"] = _diff_rows
        _wf_details["diff_counts"] = {"adds": _adds, "dels": _dels}
    _verb = "Add-Content" if append else "Set-Content"
    approval = request_approval(
        title="Append to file" if append else "Write file",
        command=f'{_verb} -Path "{path}" -Value <{len(content)} chars>',
        details=_wf_details,
    )
    if approval.get("decision") != "approve":
        return {"error": f"user denied write ({approval.get('status')})"}
    _undo_snapshot(path)
    try:
        old_text, eol, bom = "", _new_file_eol(path), False
        if os.path.isfile(path):
            try:
                old_text, eol, bom = _decode_text_file(Path(path).read_bytes())
            except (OSError, UnicodeDecodeError):
                if append:
                    return {"error": f"cannot append: {path} is not readable UTF-8 text. No file was written."}
        content = content.replace("\r\n", "\n")
        new_text = old_text + content if append else content
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        Path(path).write_bytes(_encode_text_file(new_text, eol, bom))
        _blocked_writes.pop(_blocked_write_key(path), None)
        _undo_store.checkpoint(path)
        _record_file_read(path)  # our hash now matches what we just wrote
        if not append:
            _record_write(_npath)    # count this rewrite for the loop-breaker

        import difflib
        diff = list(difflib.unified_diff(
            old_text.splitlines(keepends=True),
            new_text.splitlines(keepends=True),
            n=0
        ))
        added = 0
        deleted = 0
        for line in diff:
            if line.startswith('+') and not line.startswith('+++'):
                added += 1
            elif line.startswith('-') and not line.startswith('---'):
                deleted += 1
                
        lint_err = _run_linter(path)
        result = {"ok": True, "path": path, "bytes": len(content.encode("utf-8")), "added": added, "deleted": deleted}
        if append:
            result["mode"] = "append"
            result["total_bytes"] = len(new_text.encode("utf-8"))
        _with_code_check(result, lint_err)
        result.update(source_meta)
        if not append and _write_count(_npath) >= 2:
            result["warning"] = ("you have now rewritten this file from scratch. If it still isn't right, make a "
                                 "TARGETED edit_file fix next — do NOT rewrite the whole file again, you'll spiral.")
        return result
    except Exception as e:
        return {"error": str(e)}


def tool_edit_file(args: dict) -> dict:
    """Apply surgical search-and-replace edits to an existing file.
    Each edit finds old_text and replaces it with new_text.
    old_text must be unique or an exact single match — ambiguous matches are rejected.
    """
    path = normalize_path(args.get("path") or "")
    edits = args.get("edits") or []
    if not path:
        return {"error": "missing path"}
    if not isinstance(edits, list) or not edits:
        return {"error": "edits must be a non-empty list of {old_text, new_text}"}
    if is_bridge_self_path(path):
        return {"error": "refused: bridge.py is the running server — edit it from your real IDE, not from a chat tool call. Restart the bridge afterward."}
    _cerr = _critical_path_gate(path, "edit_file", "PROTECTED PATH - edit under Windows/System32")
    if _cerr:
        return _cerr
    if not is_in_workspace(path):
        return {"error": "path outside workspace. Add folder in Workspace panel."}
    if is_ignored(path):
        return {"error": f"path ignored by .accurettaignore: {path}"}
    if not os.path.isfile(path):
        return {"error": f"not a file: {path}"}

    try:
        text, eol, bom = _decode_text_file(Path(path).read_bytes())
    except (OSError, UnicodeDecodeError) as e:
        return {"error": f"read failed: {e}"}

    applied = []
    errors = []
    modified = text

    for i, edit in enumerate(edits):
        if not isinstance(edit, dict):
            errors.append(f"edit {i}: each edit must be an object with old_text and new_text")
            continue
        old = str(edit.get("old_text", edit.get("old_string", "")) or "").replace("\r\n", "\n")
        new = str(edit.get("new_text", edit.get("new_string", "")) or "").replace("\r\n", "\n")
        if not old:
            errors.append(f"edit {i}: old_text is empty")
            continue

        count = modified.count(old)
        if count == 0:
            # try stripping common surrounding whitespace for a fuzzy match
            old_stripped = old.strip()
            if old_stripped and old_stripped != old:
                count = modified.count(old_stripped)
                if count == 1:
                    # The file keeps its own whitespace around the match, so the
                    # replacement drops the model's: "\t" + "    x" mixed tabs and spaces.
                    modified = modified.replace(old_stripped, new.strip(), 1)
                    applied.append({"edit": i, "match": "fuzzy", "old": old[:60], "new": new[:60]})
                    continue
                elif count > 1:
                    errors.append(f"edit {i}: fuzzy match '{old[:40]}' appears {count} times — ambiguous")
                    continue
            hint = _closest_region(modified, old)
            errors.append(f"edit {i}: '{old[:40]}' not found in file"
                          + (f". Closest lines in the file now:\n{hint}" if hint else ""))
            continue
        elif count > 1:
            errors.append(f"edit {i}: '{old[:40]}' appears {count} times — must be unique")
            continue
        else:
            modified = modified.replace(old, new, 1)
            applied.append({"edit": i, "match": "exact", "old": old[:60], "new": new[:60]})

    if errors:
        return {
            "error": "; ".join(errors),
            "applied": len(applied),
            "failed": len(errors),
            "path": path,
        }

    # approval: show a diff-like summary
    diff_lines = []
    for a in applied:
        diff_lines.append(f"- {a['old'][:50]}")
        diff_lines.append(f"+ {a['new'][:50]}")
    preview = "\n".join(diff_lines) if diff_lines else "(no preview)"
    _ef_details = {"kind": "edit_file", "path": path, "edits": len(applied), "preview": preview}
    # Full line diff for the approval card (the notch scrolls through it).
    _diff_rows, _adds, _dels = _diff_preview_rows(text, modified)
    if _diff_rows:
        _ef_details["diff"] = _diff_rows
        _ef_details["diff_counts"] = {"adds": _adds, "dels": _dels}
    approval = request_approval(
        title="Edit file",
        command=f'edit {len(applied)} location(s) in "{path}"',
        details=_ef_details,
    )
    if approval.get("decision") != "approve":
        return {"error": f"user denied edit ({approval.get('status')})"}
    _undo_snapshot(path)

    try:
        import difflib
        diff = list(difflib.unified_diff(
            text.splitlines(keepends=True),
            modified.splitlines(keepends=True),
            n=0
        ))
        added = 0
        deleted = 0
        for line in diff:
            if line.startswith('+') and not line.startswith('+++'):
                added += 1
            elif line.startswith('-') and not line.startswith('---'):
                deleted += 1

        Path(path).write_bytes(_encode_text_file(modified, eol, bom))
        _undo_store.checkpoint(path)
        _record_file_read(path)  # keep our hash current after our own edit

        lint_err = _run_linter(path)
        return _with_code_check({
            "ok": True,
            "path": path,
            "edits_applied": len(applied),
            "bytes": len(modified.encode("utf-8")),
            "added": added,
            "deleted": deleted,
        }, lint_err)
    except Exception as e:
        return {"error": str(e)}

def tool_replace_ast_node(args: dict) -> dict:
    """Surgical AST-based replacement. Provide path, node_type, node_name, and new_text."""
    path = normalize_path(args.get("path") or "")
    node_type = args.get("node_type") or ""
    node_name = args.get("node_name") or ""
    new_text = args.get("new_text", "")
    
    if not path or not node_type or not node_name or not new_text:
        return {"error": "Missing required arguments: path, node_type, node_name, new_text"}
        
    ext = os.path.splitext(path)[1].lower()
    try:
        import tree_sitter
    except ImportError:
        return {"error": "tree-sitter is not installed. Please pip install tree-sitter"}
        
    lang_module = None
    if ext == ".py":
        try:
            import tree_sitter_python
            lang_module = tree_sitter_python.language()
        except ImportError:
            pass
    elif ext in [".js", ".jsx"]:
        try:
            import tree_sitter_javascript
            lang_module = tree_sitter_javascript.language()
        except ImportError:
            pass
    elif ext in [".ts", ".tsx"]:
        try:
            import tree_sitter_typescript
            lang_module = tree_sitter_typescript.language_typescript() if ext == ".ts" else tree_sitter_typescript.language_tsx()
        except ImportError:
            pass
            
    if not lang_module:
        return {"error": f"AST editing not supported for file extension {ext} or tree-sitter plugin missing"}
        
    try:
        lang = tree_sitter.Language(lang_module)
        parser = tree_sitter.Parser(lang)
    except Exception as e:
        return {"error": f"Failed to initialize tree-sitter parser: {e}"}
    
    try:
        source_bytes = Path(path).read_bytes()
    except Exception as e:
        return {"error": f"Failed to read file: {e}"}
        
    tree = parser.parse(source_bytes)
    
    found_node = None
    def traverse(node):
        nonlocal found_node
        if found_node:
            return
        if node.type == node_type:
            name_node = node.child_by_field_name('name')
            if name_node and name_node.text.decode('utf8') == node_name:
                found_node = node
                return
            for child in node.children:
                if child.type == 'identifier' and child.text.decode('utf8') == node_name:
                    found_node = node
                    return
        for child in node.children:
            traverse(child)
            
    traverse(tree.root_node)
    
    if not found_node:
        return {"error": f"Could not find node of type '{node_type}' with name '{node_name}'"}
        
    start = found_node.start_byte
    end = found_node.end_byte
    
    new_bytes = source_bytes[:start] + new_text.encode('utf8') + source_bytes[end:]
    
    approval = request_approval(
        title="AST Replace",
        command=f'Replace {node_type} {node_name} in {os.path.basename(path)}',
        details={"kind": "replace_ast_node", "path": path, "preview": new_text[:200] + "..."},
    )
    if approval.get("decision") != "approve":
        return {"error": f"user denied edit ({approval.get('status')})"}
        
    Path(path).write_bytes(new_bytes)
    
    lint_err = _run_linter(path)
    return _with_code_check({"ok": True, "path": path, "replaced_node": node_name}, lint_err)


def tool_find_references(args: dict) -> dict:
    """Find deterministic references to a symbol using AST."""
    symbol = args.get("symbol") or ""
    if not symbol:
        return {"error": "Missing symbol string"}
        
    import tree_sitter
    try:
        import tree_sitter_python
        lang_py = tree_sitter.Language(tree_sitter_python.language())
    except ImportError:
        lang_py = None
        
    try:
        import tree_sitter_javascript
        lang_js = tree_sitter.Language(tree_sitter_javascript.language())
    except ImportError:
        lang_js = None
        
    try:
        import tree_sitter_typescript
        lang_ts = tree_sitter.Language(tree_sitter_typescript.language_typescript())
        lang_tsx = tree_sitter.Language(tree_sitter_typescript.language_tsx())
    except ImportError:
        lang_ts = None
        lang_tsx = None
        
    hits = []
    folders = get_workspace().get("folders", [])
    if not folders:
        return {"error": "No workspace folders configured"}
        
    target_bytes = symbol.encode('utf8')
        
    for folder in folders:
        for root, dirs, files in os.walk(folder):
            dirs[:] = [d for d in dirs if not is_ignored(os.path.join(root, d))]
            for fname in files:
                fpath = os.path.join(root, fname)
                if is_ignored(fpath):
                    continue
                    
                ext = os.path.splitext(fname)[1].lower()
                lang = None
                if ext == ".py":
                    lang = lang_py
                elif ext in [".js", ".jsx"]:
                    lang = lang_js
                elif ext == ".ts":
                    lang = lang_ts
                elif ext == ".tsx":
                    lang = lang_tsx
                    
                if not lang:
                    continue
                    
                try:
                    content = Path(fpath).read_bytes()
                except Exception:
                    continue
                    
                if target_bytes not in content:
                    continue
                    
                try:
                    parser = tree_sitter.Parser(lang)
                    tree = parser.parse(content)
                except Exception:
                    continue
                
                code_lines = content.decode('utf8', errors='replace').splitlines()
                
                def traverse(node):
                    if len(node.children) == 0 and node.text == target_bytes:
                        line_start = node.start_point[0]
                        if line_start < len(code_lines):
                            hits.append({
                                "file": fpath,
                                "line": line_start + 1,
                                "code": code_lines[line_start].strip()
                            })
                    for child in node.children:
                        traverse(child)
                traverse(tree.root_node)
                
    unique_hits = []
    seen = set()
    for h in hits:
        k = (h["file"], h["line"])
        if k not in seen:
            seen.add(k)
            unique_hits.append(h)
            
    return {"symbol": symbol, "matches": unique_hits[:100]}


# ---- symbol index (find_symbol) -------------------------------------------
# Reuses the tree-sitter grammars already loaded for AST edits. Answers "where is
# X DEFINED" (find_references answers "where is X used") plus single-file outline.
# In-memory mtime cache so repeat lookups don't reparse. No embeddings, no server.
_SYMBOL_DEF_TYPES = {
    "py": {"function_definition": "function", "class_definition": "class"},
    "js": {"function_declaration": "function", "generator_function_declaration": "function",
           "class_declaration": "class", "method_definition": "method"},
    "ts": {"function_declaration": "function", "generator_function_declaration": "function",
           "class_declaration": "class", "abstract_class_declaration": "class",
           "method_definition": "method", "interface_declaration": "interface",
           "type_alias_declaration": "type", "enum_declaration": "enum"},
}
_SYMBOL_CACHE: dict = {}   # fpath -> (mtime, [ {name,kind,line,sig} ])

def _symbols_in_file(fpath: str, lang, kinds: dict) -> list:
    import tree_sitter
    try:
        mtime = os.path.getmtime(fpath)
    except Exception:
        return []
    cached = _SYMBOL_CACHE.get(fpath)
    if cached and cached[0] == mtime:
        return cached[1]
    try:
        content = Path(fpath).read_bytes()
        parser = tree_sitter.Parser(lang)
        tree = parser.parse(content)
    except Exception:
        return []
    syms: list = []
    def name_of(node):
        n = node.child_by_field_name("name")
        if n is not None:
            try:
                return n.text.decode("utf8", "replace")
            except Exception:
                return ""
        return ""
    def first_line(node):
        try:
            t = node.text.decode("utf8", "replace")
        except Exception:
            return ""
        return (t.splitlines()[0].strip() if t else "")[:120]
    def visit(node):
        kind = kinds.get(node.type)
        if kind:
            nm = name_of(node)
            if nm:
                syms.append({"name": nm, "kind": kind, "line": node.start_point[0] + 1, "sig": first_line(node)})
        elif node.type == "variable_declarator":
            val = node.child_by_field_name("value")
            if val is not None and val.type in ("arrow_function", "function", "function_expression"):
                nm = name_of(node)
                if nm:
                    syms.append({"name": nm, "kind": "function", "line": node.start_point[0] + 1, "sig": first_line(node)})
        for c in node.children:
            visit(c)
    visit(tree.root_node)
    _SYMBOL_CACHE[fpath] = (mtime, syms)
    return syms

def tool_find_symbol(args: dict) -> dict:
    """Where a symbol is DEFINED across the workspace (with signature), or outline
    one file's definitions. Complements find_references (which finds uses)."""
    name = (args.get("name") or "").strip()
    only_path = normalize_path(args.get("path") or "") if args.get("path") else ""
    if not name and not only_path:
        return {"error": "pass name (symbol to locate) and/or path (file to outline)"}

    import tree_sitter
    langs = {}
    try:
        import tree_sitter_python
        langs["py"] = (tree_sitter.Language(tree_sitter_python.language()), _SYMBOL_DEF_TYPES["py"])
    except Exception:
        pass
    try:
        import tree_sitter_javascript
        langs["js"] = (tree_sitter.Language(tree_sitter_javascript.language()), _SYMBOL_DEF_TYPES["js"])
    except Exception:
        pass
    try:
        import tree_sitter_typescript
        langs["ts"] = (tree_sitter.Language(tree_sitter_typescript.language_typescript()), _SYMBOL_DEF_TYPES["ts"])
        langs["tsx"] = (tree_sitter.Language(tree_sitter_typescript.language_tsx()), _SYMBOL_DEF_TYPES["ts"])
    except Exception:
        pass
    if not langs:
        return {"error": "tree-sitter language grammars not installed"}

    def lang_for(ext):
        if ext == ".py":
            return langs.get("py")
        if ext in (".js", ".jsx"):
            return langs.get("js")
        if ext == ".ts":
            return langs.get("ts")
        if ext == ".tsx":
            return langs.get("tsx")
        return None

    if only_path:
        lf = lang_for(os.path.splitext(only_path)[1].lower())
        if not lf:
            return {"error": f"unsupported file type for outline: {only_path}"}
        syms = _symbols_in_file(only_path, lf[0], lf[1])
        if name:
            syms = [s for s in syms if s["name"] == name]
        return {"path": only_path, "symbols": syms[:200]}

    folders = get_workspace().get("folders", [])
    if not folders:
        return {"error": "No workspace folders configured"}
    target = name.encode("utf8")
    hits = []
    for folder in folders:
        for root, dirs, files in os.walk(folder):
            dirs[:] = [d for d in dirs if not is_ignored(os.path.join(root, d))]
            for fname in files:
                fpath = os.path.join(root, fname)
                if is_ignored(fpath):
                    continue
                lf = lang_for(os.path.splitext(fname)[1].lower())
                if not lf:
                    continue
                try:
                    if target not in Path(fpath).read_bytes():
                        continue
                except Exception:
                    continue
                for s in _symbols_in_file(fpath, lf[0], lf[1]):
                    if s["name"] == name:
                        hits.append({"file": fpath, "line": s["line"], "kind": s["kind"], "sig": s["sig"]})
            if len(hits) >= 100:
                break
    return {"symbol": name, "definitions": hits[:100]}


def tool_delete_file(args: dict) -> dict:
    path = normalize_path(args.get("path") or "")
    if not path or not os.path.exists(path):
        return {"error": f"not found: {path}"}
    if is_bridge_self_path(path):
        return {"error": "refused: bridge.py is the running server — won't delete the file backing this process."}
    _cerr = _critical_path_gate(path, "delete", "PROTECTED PATH - delete under Windows/System32")
    if _cerr:
        return _cerr
    if not is_in_workspace(path):
        return {"error": "path outside workspace"}
    approval = request_approval(
        title="Delete",
        command=f'Remove-Item -Path "{path}" -Recurse -Force',
        details={"kind": "delete", "path": path, "dir": os.path.isdir(path)},
    )
    if approval.get("decision") != "approve":
        return {"error": f"user denied delete ({approval.get('status')})"}
    _undo_snapshot(path)
    try:
        if os.path.isdir(path):
            shutil.rmtree(path)
        else:
            os.remove(path)
        _undo_store.checkpoint(path)
        return {"ok": True, "path": path}
    except Exception as e:
        return {"error": str(e)}


def _execution_tool_name(fallback: str) -> str:
    return _current_tool_name.get() or _resolve_tool_name(fallback)


def _emit_execution_event(state: str, target: str, command: str, *,
                          cwd: str = "", chat_id: str = "", **details) -> None:
    """Report the real command lifecycle, separately from the model tool call."""
    cid = chat_id or _current_chat_id.get() or _get_current_chat()
    emit = _chat_emitters.get(cid) if cid else None
    if not emit:
        return
    event = {
        "type": f"command_{state}",
        "name": _execution_tool_name("run_powershell"),
        "call_id": _current_tool_call_id.get(),
        "target": target,
        "command": command,
        "cwd": cwd,
    }
    event.update({k: v for k, v in details.items() if v is not None})
    try:
        emit(event)
    except Exception:
        pass


def _execution_not_run(message: str, target: str, command: str, *,
                       reason: str = "blocked", cwd: str = "", **details) -> dict:
    event_details = dict(details)
    event_details.setdefault("reason", reason)
    event_details.setdefault("message", message)
    _emit_execution_event("not_executed", target, command, cwd=cwd,
                          **event_details)
    result = {
        "error": message,
        "not_executed": True,
        "executed": False,
        "execution_target": target,
        "execution_state": reason,
    }
    result.update(details)
    return result


def _emit_tool_stream(name: str, text: str, chat_id: str = "", target: str = "",
                      call_id: str = "") -> None:
    """If a chat turn is active, emit a tool_stream SSE event.

    Reader threads do not inherit ContextVars, so subprocess callers capture
    the chat id before spawning and pass it explicitly.
    """
    cid = chat_id or _current_chat_id.get()
    emit = _chat_emitters.get(cid) if cid else None
    if emit:
        try:
            emit({
                "type": "tool_stream",
                "name": _execution_tool_name(name),
                "call_id": call_id or _current_tool_call_id.get(),
                "target": target,
                "text": text[:240],
            })
        except Exception:
            pass


_cmd_history_lock = threading.Lock()


def _append_cmd_history(entry: dict) -> None:
    """Append a started host or WSL command to cmd_history.jsonl, then trim
    the file to CMD_HISTORY_MAX lines if it's grown past that. Failures are
    swallowed — command logging must never block a tool call from returning."""
    try:
        DATA.mkdir(parents=True, exist_ok=True)
        with _cmd_history_lock:
            with open(CMD_HISTORY_FILE, "a", encoding="utf-8") as f:
                f.write(json.dumps(entry, ensure_ascii=False, default=str) + "\n")
            # Cheap rotation: the file is capped (a few hundred KB at worst), so rewrite
            # it with the trailing CMD_HISTORY_MAX entries when it grows too long.
            try:
                with open(CMD_HISTORY_FILE, "r", encoding="utf-8") as f:
                    lines = f.readlines()
                if len(lines) > CMD_HISTORY_MAX + 200:  # only rotate when meaningfully over
                    keep = lines[-CMD_HISTORY_MAX:]
                    with open(CMD_HISTORY_FILE, "w", encoding="utf-8") as f:
                        f.writelines(keep)
            except Exception:
                pass
    except Exception:
        pass


def _read_cmd_history(limit: int = 200, chat_id: str = "") -> list[dict]:
    """Return the last `limit` history entries, newest first. Optionally
    filter to entries that ran in a specific chat."""
    if not CMD_HISTORY_FILE.exists():
        return []
    out: list[dict] = []
    try:
        with _cmd_history_lock:
            with open(CMD_HISTORY_FILE, "r", encoding="utf-8") as f:
                lines = f.readlines()
    except Exception:
        return []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            entry = json.loads(line)
        except Exception:
            continue
        if chat_id and entry.get("chat_id") != chat_id:
            continue
        out.append(entry)
    out.reverse()
    return out[:limit]


# The shell command currently running per chat, so the UI's kill button can
# terminate just that process while the turn continues (the tool returns a
# killed result). Tools run sequentially, so one live command per chat.
_running_cmds_lock = threading.Lock()
_running_cmds: dict[str, subprocess.Popen] = {}
_running_cmd_targets: dict[str, str] = {}
# Procs terminated via the kill button. Windows TerminateProcess sets exit code
# 1 (indistinguishable from a real exit 1 by returncode), so we mark the kill
# explicitly and read it back in _run_powershell.
_killed_procs: set = set()


def _trusted_windows_binary(*relative_parts: str) -> str:
    if os.name != "nt":
        return ""
    windows_root = os.environ.get("SystemRoot") or os.environ.get("WINDIR") or r"C:\Windows"
    for system_dir in ("Sysnative", "System32"):
        candidate = os.path.abspath(os.path.join(windows_root, system_dir, *relative_parts))
        if os.path.isfile(candidate):
            return candidate
    return ""


def _trusted_node_binary() -> str:
    if os.name == "nt":
        roots = [os.environ.get("ProgramFiles"), os.environ.get("ProgramFiles(x86)")]
        for root in filter(None, roots):
            candidate = os.path.abspath(os.path.join(root, "nodejs", "node.exe"))
            if os.path.isfile(candidate):
                return candidate
    current = os.path.normcase(os.path.abspath(os.getcwd()))
    workspace = os.path.normcase(os.path.abspath(str(ROOT)))
    for raw_dir in os.environ.get("PATH", "").split(os.pathsep):
        if not raw_dir or not os.path.isabs(raw_dir):
            continue
        directory = os.path.normcase(os.path.abspath(raw_dir))
        if directory == current or directory == workspace or directory.startswith(workspace + os.sep):
            continue
        candidate = os.path.join(directory, "node.exe" if os.name == "nt" else "node")
        if os.path.isfile(candidate):
            return candidate
    return ""


def _terminate_process_tree(proc: subprocess.Popen, target: str) -> bool:
    if proc.poll() is not None:
        return True
    if target == "sandbox":
        rc, _ = _wsl_run(["--terminate", SANDBOX_DISTRO], timeout=30)
        try:
            proc.wait(timeout=5)
        except Exception:
            pass
        return rc == 0 or proc.poll() is not None
    if os.name == "nt":
        taskkill = _trusted_windows_binary("taskkill.exe")
        if taskkill:
            try:
                result = subprocess.run(
                    [taskkill, "/PID", str(proc.pid), "/T", "/F"],
                    capture_output=True, text=True, timeout=30,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )
                try:
                    proc.wait(timeout=5)
                except Exception:
                    pass
                if result.returncode == 0 or proc.poll() is not None:
                    return True
            except Exception:
                pass
    try:
        proc.kill()
        proc.wait(timeout=5)
        return True
    except Exception:
        return proc.poll() is not None


def _kill_current_command(chat_id: str) -> bool:
    """Kill the shell command currently running for this chat, if any."""
    with _running_cmds_lock:
        proc = _running_cmds.get(chat_id or "")
        target = _running_cmd_targets.get(chat_id or "", "host")
        if proc is not None:
            _killed_procs.add(proc)
    if proc is None:
        return False
    try:
        if _terminate_process_tree(proc, target):
            return True
        raise RuntimeError("process tree did not stop")
    except Exception:
        with _running_cmds_lock:
            _killed_procs.discard(proc)
        return False


# Model-facing commands run inside a small wrapper. Windows PowerShell 5.1
# reads BOM-less UTF-8 files as ANSI and writes the pipe in the OEM code page,
# so non-ASCII text came back garbled; the prelude makes both UTF-8. The status
# line reports $? and $LASTEXITCODE: with -Command the process exit code follows
# $? of the last statement, so a program that succeeded but wrote to a
# redirected stderr (`node x 2>&1`) came back as exit 1.
_PS_STATUS = "__ACCURETTA_STATUS__"
_PS_ERROR_ID_RE = re.compile(r"FullyQualifiedErrorId\s*:\s*([\w.,]+)")


def _ps_script(cmd: str) -> str:
    return (
        "[Console]::OutputEncoding = [Text.UTF8Encoding]::new($false)\n"
        "$OutputEncoding = [Text.UTF8Encoding]::new($false)\n"
        "$PSDefaultParameterValues['Get-Content:Encoding'] = 'UTF8'\n"
        "$PSDefaultParameterValues['Select-String:Encoding'] = 'UTF8'\n"
        "$global:LASTEXITCODE = 0\n"
        f"{cmd}\n"
        f"$__accOk = $?; Write-Output \"{_PS_STATUS}$__accOk;$LASTEXITCODE\""
    )


def _ps_outcome(stdout: str, stderr: str, returncode: int) -> tuple[str, bool, int]:
    """(stdout without the status line, success, exit code) of a wrapped command.

    The last program's own exit code wins. Error records that are only a
    program's stderr lines (NativeCommandError) do not make a run fail."""
    head, sep, tail = stdout.rpartition(_PS_STATUS)
    if not sep:
        return stdout, returncode == 0, returncode
    ps_ok, _, code_txt = tail.strip().partition(";")
    code_txt = code_txt.strip()
    program_code = int(code_txt) if code_txt.lstrip("-").isdigit() else 0
    if program_code:
        return head, False, program_code
    if ps_ok == "True":
        return head, True, 0
    ids = _PS_ERROR_ID_RE.findall(head + stderr)
    if ids and all(i.startswith("NativeCommandError") for i in ids):
        return head, True, 0
    return head, False, returncode or 1


def _default_command_cwd() -> str:
    """The folder a host command runs in when the model names none: the chat's
    branch worktree or project, else the first workspace folder."""
    try:
        chat = (get_chats().get("chats", {}) or {}).get(_get_current_chat()) or {}
        for meta in (_github_worktree_metadata(chat.get("github_worktree")),
                     _project_workspace_metadata(chat.get("project_workspace"))):
            if meta and os.path.isdir(meta["path"]):
                return normalize_path(meta["path"])
    except Exception:
        pass
    for folder in get_workspace().get("folders", []) or []:
        if isinstance(folder, str) and folder.strip() and os.path.isdir(folder):
            return normalize_path(folder)
    return os.getcwd()


def _run_powershell(cmd: str, timeout: int = 120, max_stdout: int = 16000,
                    cwd: str | None = None, wrap: bool = False) -> dict:
    t_start = time.time()
    stream_chat_id = _current_chat_id.get() or _get_current_chat()
    stream_tool_name = _execution_tool_name("run_powershell")
    stream_call_id = _current_tool_call_id.get()
    process_cwd = cwd or os.getcwd()
    powershell_exe = _trusted_windows_binary("WindowsPowerShell", "v1.0", "powershell.exe")
    if not powershell_exe:
        return _execution_not_run(
            "Trusted Windows PowerShell executable was not found in the Windows system directory.",
            "host", cmd, reason="spawn_error", cwd=process_cwd, spawn_error=True,
        )
    try:
        proc = subprocess.Popen(
            [powershell_exe, "-NoProfile", "-NonInteractive", "-Command",
             _ps_script(cmd) if wrap else cmd],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
            encoding="utf-8" if wrap else None, errors="replace" if wrap else None,
            cwd=process_cwd,
            creationflags=subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0,
        )
    except Exception as e:
        _append_cmd_history({
            "ts": int(t_start * 1000),
            "chat_id": _get_current_chat(),
            "command": cmd,
            "exit": -1,
            "ok": False,
            "duration_ms": int((time.time() - t_start) * 1000),
            "stdout": "",
            "stderr": str(e),
            "spawn_error": True,
            "target": "host",
            "tool": stream_tool_name,
            "call_id": stream_call_id,
        })
        return _execution_not_run(str(e), "host", cmd, reason="spawn_error",
                                  cwd=process_cwd, spawn_error=True)

    out_lines: list[str] = []
    err_lines: list[str] = []

    def reader(pipe, sink, name):
        try:
            for line in iter(pipe.readline, ""):
                sink.append(line)
                if wrap and _PS_STATUS in line:
                    continue
                _emit_tool_stream(stream_tool_name, line.rstrip("\n\r"), stream_chat_id,
                                  target="host", call_id=stream_call_id)
            pipe.close()
        except Exception:
            pass

    t_out = threading.Thread(target=reader, args=(proc.stdout, out_lines, "run_powershell"), daemon=True)
    t_err = threading.Thread(target=reader, args=(proc.stderr, err_lines, "run_powershell"), daemon=True)

    # Register for the per-command kill button before announcing the spawn.
    _cid = stream_chat_id or ""
    if _cid:
        with _running_cmds_lock:
            _running_cmds[_cid] = proc
            _running_cmd_targets[_cid] = "host"
    _emit_execution_event("spawned", "host", cmd, cwd=process_cwd,
                          chat_id=stream_chat_id, pid=proc.pid)
    t_out.start()
    t_err.start()
    try:
        timed_out = False
        try:
            proc.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            _terminate_process_tree(proc, "host")
            timed_out = True
            try:
                proc.wait(timeout=5)
            except Exception:
                pass

        t_out.join(timeout=5)
        t_err.join(timeout=5)

        stdout = "".join(out_lines)[-max_stdout:]
        stderr = "".join(err_lines)[-4000:]
        # Was this terminated by the kill button? Check the explicit marker
        # (returncode alone can't tell on Windows) plus the POSIX negative code.
        with _running_cmds_lock:
            killed = proc in _killed_procs
        if proc.returncode is not None and proc.returncode < 0:
            killed = True
        ok, exit_code = proc.returncode == 0, proc.returncode
        if wrap and not (timed_out or killed):
            stdout, ok, exit_code = _ps_outcome(stdout, stderr, proc.returncode)
        result = {
            "ok": ok,
            "exit": exit_code,
            "exit_code": exit_code,
            "stdout": stdout,
            "stderr": stderr,
            "executed": True,
            "execution_target": "host",
        }
        if wrap and exit_code != proc.returncode:
            result["powershell_exit_code"] = proc.returncode
        if wrap:
            result["cwd"] = process_cwd
        if timed_out:
            result["timed_out"] = True
            result["error"] = f"timeout after {timeout}s"
        elif killed:
            result["killed"] = True
            result["error"] = "command was killed"
        duration_ms = int((time.time() - t_start) * 1000)
        _append_cmd_history({
            "ts": int(t_start * 1000),
            "chat_id": stream_chat_id,
            "command": cmd,
            "exit": exit_code,
            "ok": result["ok"],
            "duration_ms": duration_ms,
            "stdout": stdout,
            "stderr": stderr,
            "killed": killed,
            "timed_out": timed_out,
            "target": "host",
            "tool": stream_tool_name,
            "call_id": stream_call_id,
        })
        _emit_execution_event("finished", "host", cmd, cwd=process_cwd,
                              chat_id=stream_chat_id, exit_code=exit_code,
                              killed=killed, timed_out=timed_out,
                              duration_ms=duration_ms)
        return result
    finally:
        with _running_cmds_lock:
            if _cid and _running_cmds.get(_cid) is proc:
                _running_cmds.pop(_cid, None)
                _running_cmd_targets.pop(_cid, None)
            _killed_procs.discard(proc)


def _catastrophic_cmd(cmd: str) -> str | None:
    """Refuse (not merely prompt) commands that would wipe the machine or the
    user's data: whole-drive/profile recursive deletes, disk format/wipe, fork
    bombs, raw-disk overwrites. Deliberately narrow, so deleting a build folder
    still goes through normal approval. Returns a short reason, else None."""
    if not cmd:
        return None
    c = " ".join(cmd.lower().split())   # collapse whitespace so patterns stay simple
    standalone = [
        (r"\bformat\s+[a-z]:", "formats a drive"),
        (r"\bdiskpart\b", "runs diskpart (can wipe partitions)"),
        (r"\b(clear-disk|format-volume|remove-partition|initialize-disk)\b", "destroys a disk or partition"),
        (r"\bcipher\s+/w", "wipes free space (cipher /w)"),
        (r":\(\)\s*\{\s*:\s*\|\s*:\s*&\s*\}\s*;\s*:", "is a fork bomb"),
        (r"\bdd\b.*\bof=/dev/(sd|nvme|hd|disk)", "raw-writes a disk device (dd)"),
        (r"\bmkfs\.", "formats a filesystem (mkfs)"),
        (r">\s*/dev/(sd|nvme|hd)[a-z0-9]", "overwrites a raw disk device"),
    ]
    for pat, why in standalone:
        if re.search(pat, c):
            return why
    recurse_delete = bool(
        re.search(r"remove-item\b.*\brecurse\b.*\bforce\b", c)
        or re.search(r"remove-item\b.*\bforce\b.*\brecurse\b", c)
        or re.search(r"\brm\s+-\w*r\w*f\b|\brm\s+-\w*f\w*r\b", c)
        or re.search(r"\b(rd|rmdir)\s+/s\b", c)
        or re.search(r"\bdel\s+/s\b", c)
    )
    if recurse_delete:
        targets = [
            r"\s[a-z]:\\?(?:$|\s|['\"|&;])",            # a bare drive root, e.g. C:\
            r"[a-z]:\\windows\b",                       # C:\Windows
            r"[a-z]:\\users\b(?![\\a-z0-9])",           # the WHOLE C:\Users
            r"\$env:systemroot\b|\$env:windir\b",
            r"\$env:userprofile(?![\\a-z0-9])|\$home(?![\\/\w])",
            r"\brm\s+-\w+\s+/\s*(?:$|\*)",              # rm -rf /  or  rm -rf /*
            r"\brm\s+-\w+\s+~\s*(?:$|/\*)",             # rm -rf ~  or  rm -rf ~/*
            r"/mnt/[a-z](?![/\w])",                     # a Windows drive mounted in WSL, e.g. /mnt/c
            r"/mnt/[a-z]/\*",                           # /mnt/c/*  — everything on the drive
            r"/mnt/[a-z]/users(?![/\w])",               # the whole Users tree via WSL
        ]
        for pat in targets:
            if re.search(pat, c):
                return "would recursively force-delete a drive root, Windows, or your whole profile"
    return None


# ---- ClickFix hard-block ----------------------------------------------------
# `iwr <url> | iex`, `curl <url> | sh`, `irm <url>; iex $x`: one command that
# downloads and executes remote content. No legitimate agent task pipes a
# download straight into an interpreter, so these are refused outright (never
# queued for approval), like the catastrophic tier. A plain `... | iex` is
# refused too: iex is PowerShell's "execute this string" verb and has no
# read-only meaning. Returns a short reason if refused, else None.
_CLICKFIX_DL_EXEC = re.compile(
    r"\b(?:iwr|irm|invoke-webrequest|invoke-restmethod|curl|wget)\b"
    r"[^\r\n]{0,400}\|\s*(?:iex\b|invoke-expression\b|sh\b|bash\b|pwsh\b|powershell\b)",
    re.IGNORECASE,
)
_CLICKFIX_FETCH_THEN_EXEC = re.compile(
    r"\b(?:iwr|irm|invoke-webrequest|invoke-restmethod|curl|wget)\b"
    r"[^\r\n]{0,400}\b(?:iex|invoke-expression)\b",
    re.IGNORECASE,
)
_CLICKFIX_PIPE_EXEC = re.compile(
    r"\|\s*(?:iex\b|invoke-expression\b)",
    re.IGNORECASE,
)


def _clickfix_cmd(cmd: str) -> str | None:
    if not cmd:
        return None
    c = " ".join(cmd.lower().split())
    if _CLICKFIX_DL_EXEC.search(c):
        return "downloads and executes a remote script in one pipeline"
    if _CLICKFIX_FETCH_THEN_EXEC.search(c):
        return "fetches remote content and runs it through iex"
    if _CLICKFIX_PIPE_EXEC.search(c):
        return "pipes command output straight into iex (an execute-anything verb)"
    return None


_HOST_CODE_EXEC_RE = re.compile(
    r"(?:^|[;&|]\s*)"
    r"(?:&\s*)?"
    r"(?:node(?:\.exe)?|python(?:3|w)?(?:\.exe)?|py(?:\.exe)?|deno|bun|"
    r"ruby|perl|php|java|dotnet|npx|pnpm\s+(?:run|exec|test|start|install|add)|"
    r"npm\s+(?:run|exec|test|start|install|ci|update)|"
    r"yarn\s+(?:run|test|start|install|add)|uv\s+run|poetry\s+run|pipenv\s+run|"
    r"pytest|tox|nox|jest|vitest|mocha|tsx|ts-node|"
    r"cargo\s+(?:run|test|build)|go\s+(?:run|test)|dotnet\s+(?:run|test|build)|"
    r"(?:make|msbuild|gradle|mvn)(?:\.exe)?|"
    r"git\s+(?:checkout|switch|merge|rebase|commit|pull|push|clone|submodule)|"
    r"cmd(?:\.exe)?\s+/c|powershell(?:\.exe)?|"
    r"pwsh(?:\.exe)?|wsl(?:\.exe)?|bash|sh|cscript|wscript|mshta|rundll32|"
    r"invoke-expression|iex|add-type|"
    r"[^\s;&|]+\.(?:exe|com|ps1|bat|cmd|js|vbs|wsf|hta|jar))\b",
    re.IGNORECASE,
)

_WSL_HOST_INTEROP_RE = re.compile(
    r"(?:^|[;&|]\s*)(?:&\s*)?"
    r"(?:cmd|powershell|pwsh|wscript|cscript|mshta|rundll32|reg|regedit|"
    r"explorer|start|schtasks|sc)(?:\.exe)?\b|"
    r"(?:^|[\s;&|])(?:/mnt/[a-z]/[^\s;&|]*\.exe)\b",
    re.IGNORECASE,
)


def _host_command_executes_code(command: str) -> bool:
    """Conservatively identify host commands that execute code or scripts."""
    return bool(_HOST_CODE_EXEC_RE.search(str(command or "").strip()))


def tool_run_powershell(args: dict) -> dict:
    return _run_host_command(str(args.get("command") or ""), str(args.get("cwd") or ""),
                             args.get("timeout", 120))


def _run_host_command(cmd: str, requested_cwd: str, timeout, code_preview: str = "") -> dict:
    """Guard, approve and run one model-requested PowerShell command.

    code_preview is the script a launcher command runs (run_python). It comes
    from the harness, never from model arguments, so the approval card cannot
    show text the command does not run."""
    cmd = (cmd or "").strip()
    if not cmd:
        return {"error": "empty command"}
    requested_cwd = (requested_cwd or "").strip()
    process_cwd = normalize_path(requested_cwd) if requested_cwd else _default_command_cwd()
    if requested_cwd:
        if not os.path.isdir(process_cwd):
            return {"error": f"cwd is not a directory: {process_cwd}", "not_executed": True}
        if not is_in_workspace(process_cwd):
            return {"error": "cwd is outside the workspace. Add the folder in the Workspace panel.",
                    "not_executed": True}
    _emit_execution_event("requested", "host", cmd, cwd=process_cwd)

    def not_run(message: str, reason: str, **details) -> dict:
        return _execution_not_run(message, "host", cmd, reason=reason,
                                  cwd=process_cwd, **details)

    threat = bridge_self_threat(cmd)
    if threat:
        return not_run(
            (
                f"refused: {threat}. Accuretta won't terminate or overwrite its own "
                "server through a tool call — restart the bridge yourself if you "
                "really mean to. If you're trying to kill a different python "
                "process (flask dev server, etc.), target it by exact PID rather "
                "than 'all python.exe' or 'whatever listens on 8787'."
            ),
            "self_protection", refused_command=cmd)
    catastrophic = _catastrophic_cmd(cmd)
    if catastrophic:
        return not_run(
            (
                f"refused: this command {catastrophic}. Accuretta hard-blocks "
                "whole-machine / whole-drive destruction — it never even reaches "
                "the approval queue. If you truly intend this, run it yourself."
            ),
            "catastrophic", refused_command=cmd, catastrophic=True)
    clickfix = _clickfix_cmd(cmd)
    if clickfix:
        return not_run(
            (
                f"refused: this command {clickfix} — the ClickFix signature "
                "(remote content piped into an interpreter). Accuretta hard-blocks "
                "download-and-execute pipelines; they never reach the approval "
                "queue. If you truly intend this, run it yourself."
            ),
            "clickfix", refused_command=cmd, clickfix=True)
    # The registry check runs before the generic powershell approval. Both tiers
    # use the hold-to-approve CRITICAL card (never auto-approved in any mode);
    # system hives get the loudest wording.
    reg = registry_assess(cmd)
    if reg["level"] == "system":
        approval = request_approval(
            title="REGISTRY EDIT (SYSTEM hive - can brick Windows)",
            command=cmd,
            details={"kind": "registry", "level": "system", "targets": reg["targets"], "critical": True},
        )
        if approval.get("decision") != "approve":
            return not_run(f"user denied SYSTEM registry edit ({approval.get('status')})",
                           "denied")
    elif reg["level"] == "user":
        approval = request_approval(
            title="REGISTRY EDIT (user hive)",
            command=cmd,
            details={"kind": "registry", "level": "user", "targets": reg["targets"], "critical": True},
        )
        if approval.get("decision") != "approve":
            return not_run(f"user denied registry edit ({approval.get('status')})",
                           "denied")
    else:
        executes_code = bool(code_preview) or _host_command_executes_code(cmd)
        red_team_context = bool(_rt_authorized_mission(_rt_context_chat()))
        details = {
            "kind": "powershell",
            "target": "host",
            "executes_code": executes_code,
            "red_team_context": red_team_context,
        }
        if code_preview:
            details["code_preview"] = code_preview[:6000]
        approval = request_approval(
            title=("Host code execution" if executes_code else "Command on Windows host"),
            command=cmd,
            details=details,
        )
        if approval.get("decision") != "approve":
            return not_run(f"user denied command ({approval.get('status')})", "denied")
    return _run_powershell(cmd, timeout=int(timeout or 120), cwd=process_cwd, wrap=True)


def _python_launcher(cwd: str) -> list[str]:
    """argv prefix for Python: the project's virtual environment when it has one,
    else the py launcher, else python on PATH."""
    for venv in (".venv", "venv", "env"):
        candidate = Path(cwd) / venv / ("Scripts/python.exe" if os.name == "nt" else "bin/python")
        if candidate.is_file():
            return [str(candidate)]
    launcher = shutil.which("py") if os.name == "nt" else None
    if launcher:
        return [launcher, "-3"]
    found = shutil.which("python") or shutil.which("python3")
    return [found] if found else []


def tool_run_python(args: dict) -> dict:
    """Run model-written Python from a temporary script file.

    Python pasted into a PowerShell here-string breaks on `$`, quotes and
    backticks. The script runs through the run_powershell path, so the same
    approval rules apply and Soft mode reads the script file it runs."""
    code = str(args.get("code") or "")
    if not code.strip():
        return {"error": "empty code", "not_executed": True}
    for check in (bridge_self_threat, _catastrophic_cmd):
        reason = check(code)
        if reason:
            return {"error": f"refused: this script {reason}.", "not_executed": True}
    requested_cwd = str(args.get("cwd") or "").strip()
    cwd = normalize_path(requested_cwd) if requested_cwd else _default_command_cwd()
    launcher = _python_launcher(cwd)
    if not launcher:
        return {"error": "No Python interpreter was found. Install Python or create a .venv in the project.",
                "not_executed": True}
    script_dir = Path(tempfile.gettempdir()) / "accuretta-run-python"
    script_dir.mkdir(parents=True, exist_ok=True)
    script = script_dir / f"run_{uuid.uuid4().hex[:12]}.py"
    script.write_text(code, encoding="utf-8")
    command = ('& "' + launcher[0] + '"' + "".join(f" {a}" for a in launcher[1:])
               + f' -X utf8 "{script}"')
    try:
        return _run_host_command(command, requested_cwd, args.get("timeout", 120), code_preview=code)
    finally:
        try:
            script.unlink()
        except OSError:
            pass


_REMOTE_READ_ONLY_COMMANDS = {
    "pwd", "whoami", "id", "uname", "sw_vers", "date", "uptime", "hostname",
    "which", "df", "ps", "pgrep", "groups",
}


def _remote_command_refusal(command: str) -> str:
    cmd = str(command or "").strip()
    catastrophic = _catastrophic_cmd(cmd)
    if catastrophic:
        return f"this command {catastrophic}"
    lowered = " ".join(cmd.lower().split())
    rules = (
        (r"(^|[;&|]\s*)(sudo|doas|su)(\s|$)", "requests elevated or another user's privileges"),
        (r"\bdiskutil\s+(erase|partition|apfs\s+delete|secureerase)", "can erase or repartition a disk"),
        (r"\bcsrutil\b", "changes macOS System Integrity Protection"),
        (r"\bsecurity\s+authorizationdb\b", "changes macOS authorization policy"),
        (r"\blaunchctl\s+(bootstrap|bootout)\s+system\b", "changes system launch services"),
    )
    for pattern, reason in rules:
        if re.search(pattern, lowered):
            return reason
    return ""


def _remote_command_is_read_only(command: str) -> bool:
    cmd = str(command or "").strip()
    if not cmd or any(token in cmd for token in ("\n", "\r", ";", "&&", "||", "|", ">", "<", "`", "$(")):
        return False
    try:
        parts = shlex.split(cmd, posix=True)
    except ValueError:
        return False
    if not parts:
        return False
    first = parts[0]
    if first in _REMOTE_READ_ONLY_COMMANDS:
        return not any(arg in {"-delete", "--delete"} for arg in parts[1:])
    if first == "brew" and len(parts) > 1:
        return parts[1] in {"list", "config", "doctor"}
    if first in {"python", "python3", "node", "npm", "ruby", "clang", "swift", "xcodebuild"}:
        return len(parts) == 2 and parts[1] in {"--version", "-V", "-v"}
    return False


def _remote_text_result(result: dict) -> dict:
    raw = result.pop("stdout_bytes", b"") or b""
    result["stdout"] = raw.decode("utf-8", "replace")
    return result


def tool_remote_shell(args: dict) -> dict:
    row = _selected_remote_machine(args)
    if not row:
        return {"error": "No verified Mac is selected. Pair it in Settings, then choose it in the top bar."}
    command = str(args.get("command") or "").strip()
    if not command:
        return {"error": "command is required"}
    refused = _remote_command_refusal(command)
    if refused:
        return {
            "error": f"refused: {refused}. Run it yourself on the Mac if that is genuinely intended.",
            "refused_command": command,
        }
    if not _remote_command_is_read_only(command):
        approval = request_approval(
            title=f"Run on {row.get('label') or 'paired Mac'}",
            command=command,
            details={
                "kind": "remote_shell", "force_prompt": True,
                "machine": row.get("id"), "target": row.get("label"),
            },
        )
        if approval.get("decision") != "approve":
            return {"error": f"user denied remote command ({approval.get('status')})"}
    result = _run_remote_process(
        row, command, timeout=args.get("timeout"), max_stdout=240_000,
        stream_name="remote_shell",
    )
    return _remote_text_result(result)


def tool_remote_list_directory(args: dict) -> dict:
    row = _selected_remote_machine(args)
    if not row:
        return {"error": "No verified Mac is selected."}
    try:
        path = _normalize_remote_path(row, args.get("path") or "~/Desktop")
    except ValueError as exc:
        return {"error": str(exc)}
    path, path_error = _confirm_remote_path(row, path, directory=True)
    if path_error:
        return {"error": path_error}
    command = f"LC_ALL=C ls -laO -- {shlex.quote(path)}"
    result = _remote_text_result(_run_remote_process(row, command, max_stdout=240_000, stream_name=""))
    result["path"] = path
    return result


def _remote_file_metadata(row: dict, path: str) -> dict:
    path, path_error = _confirm_remote_path(row, path)
    if path_error:
        return {"ok": False, "error": path_error}
    quoted = shlex.quote(path)
    command = (
        f"test -f {quoted} || exit 44; "
        f"size=$(stat -f '%z' -- {quoted}) || exit 45; "
        f"hash=$(shasum -a 256 -- {quoted} | awk '{{print $1}}') || exit 46; "
        "printf '%s %s\\n' \"$size\" \"$hash\""
    )
    result = _remote_text_result(_run_remote_process(row, command, timeout=30, max_stdout=4096, stream_name=""))
    if not result.get("ok"):
        return result
    match = re.search(r"^(\d+)\s+([0-9a-fA-F]{64})\s*$", result.get("stdout") or "", re.MULTILINE)
    if not match:
        return {"ok": False, "error": "The Mac returned invalid file metadata."}
    return {"ok": True, "path": path, "size": int(match.group(1)), "sha256": match.group(2).lower()}


def tool_remote_read_file(args: dict) -> dict:
    row = _selected_remote_machine(args)
    if not row:
        return {"error": "No verified Mac is selected."}
    try:
        path = _normalize_remote_path(row, args.get("path") or "")
        offset = max(0, int(args.get("offset") or 0))
        length = max(1, min(int(args.get("length") or 65536), 262144))
    except (ValueError, TypeError) as exc:
        return {"error": str(exc)}
    meta = _remote_file_metadata(row, path)
    if not meta.get("ok"):
        return {"error": meta.get("stderr") or meta.get("error") or "Remote file not found."}
    path = meta["path"]
    command = f"dd if={shlex.quote(path)} bs=1 skip={offset} count={length} 2>/dev/null"
    result = _run_remote_process(row, command, timeout=60, max_stdout=length, stream_name="")
    if not result.get("ok"):
        return {"error": result.get("stderr") or result.get("error") or "Remote read failed."}
    raw = result.get("stdout_bytes") or b""
    with _remote_file_reads_lock:
        _remote_file_reads[(_get_current_chat() or "", str(row.get("id")), path)] = meta["sha256"]
    try:
        content = raw.decode("utf-8")
        binary = False
    except UnicodeDecodeError:
        content = _b64.b64encode(raw).decode("ascii")
        binary = True
    return {
        "ok": True, "path": path, "offset": offset, "bytes": len(raw),
        "size": meta["size"], "sha256": meta["sha256"],
        "content": content, "binary_base64": binary,
        "truncated": offset + len(raw) < meta["size"],
    }


def _remote_write_bytes(row: dict, path: str, payload: bytes,
                        expected_sha256: str = "") -> dict:
    quoted = shlex.quote(path)
    expected = str(expected_sha256 or "").lower()
    guard = ""
    if expected:
        guard = (
            f"current=$(shasum -a 256 -- {quoted} 2>/dev/null | awk '{{print $1}}'); "
            f"test \"$current\" = {shlex.quote(expected)} || "
            "{ printf 'STALE_REMOTE_FILE\\n' >&2; exit 73; }; "
        )
    command = (
        "set -eu; "
        f"dest={quoted}; parent=$(dirname -- \"$dest\"); test -d \"$parent\"; "
        f"{guard}"
        "tmp=\"${dest}.accuretta.$$\"; trap 'rm -f -- \"$tmp\"' EXIT HUP INT TERM; "
        "cat > \"$tmp\"; "
        "if test -e \"$dest\"; then mode=$(stat -f '%Lp' -- \"$dest\"); chmod \"$mode\" \"$tmp\"; fi; "
        "mv -f -- \"$tmp\" \"$dest\"; trap - EXIT HUP INT TERM"
    )
    result = _run_remote_process(
        row, command, timeout=max(60, int(len(payload) / 250_000) + 30),
        stdin=payload, max_stdout=4096, stream_name="",
    )
    if result.get("exit") == 73 or "STALE_REMOTE_FILE" in str(result.get("stderr") or ""):
        return {"ok": False, "error": "The Mac file changed since it was read. Read it again before overwriting it.", "stale": True}
    return _remote_text_result(result)


def _remote_payload_limit() -> int:
    try:
        mb = max(1, min(int(get_settings().get("remote_file_max_mb") or 100), 1024))
    except Exception:
        mb = 100
    return mb * 1024 * 1024


def _remote_expected_hash(row: dict, path: str, explicit: str = "") -> str:
    expected = str(explicit or "").strip().lower()
    if expected:
        return expected
    with _remote_file_reads_lock:
        return _remote_file_reads.get(
            (_get_current_chat() or "", str(row.get("id")), path), "")


def _remote_write_approved_payload(row: dict, path: str, payload: bytes,
                                   expected_sha256: str = "",
                                   title: str = "Write file on paired Mac") -> dict:
    if len(payload) > _remote_payload_limit():
        return {"error": "File exceeds the configured remote transfer limit."}
    approval = request_approval(
        title=title,
        command=f"Write {len(payload)} bytes to {path}",
        details={
            "kind": "remote_file_write", "force_prompt": True,
            "machine": row.get("id"), "path": path,
            "bytes": len(payload), "sha256": hashlib.sha256(payload).hexdigest(),
        },
    )
    if approval.get("decision") != "approve":
        return {"error": f"user denied remote file write ({approval.get('status')})"}
    result = _remote_write_bytes(row, path, payload, expected_sha256)
    if result.get("ok"):
        result.update({
            "path": path, "bytes": len(payload),
            "sha256": hashlib.sha256(payload).hexdigest(),
        })
    return result


_CHAT_CODE_FENCE_RE = re.compile(r"```([^\r\n`]*)\r?\n([\s\S]*?)```", re.MULTILINE)


def _visible_assistant_text(text: str) -> str:
    """Mirror the UI reasoning boundary for exports and completion checks."""
    # Legacy marker-form reasoning is closed first, so an answer line such as
    # `ResponseEntity<T> ok()` is never mistaken for the reasoning boundary.
    raw = _close_think_marker(str(text or ""))
    close_re = re.compile(
        r"</(?:think|thinking|reasoning)>|<\|/thinking\|>|"
        r"\[/(?:thought|thinking|reasoning|scratchpad)\]",
        re.IGNORECASE,
    )
    closes = list(close_re.finditer(raw))
    if closes:
        visible = raw[closes[-1].end():]
    else:
        open_re = re.compile(
            r"<(?:think|thinking|reasoning)>|<\|thinking\|>|"
            r"\[(?:thought|thinking|reasoning|scratchpad)\]",
            re.IGNORECASE,
        )
        opener = open_re.search(raw)
        if not opener:
            visible = raw
        else:
            visible = raw[:opener.start()]
            thinking = raw[opener.start():]
            implicit = re.search(
                r"</?tool_call>|<\|tool_call>|<call:[a-zA-Z0-9_\-]+>|"
                r"\[TOOL_CALLS\]|```(?:tool_call|tool_code)",
                thinking, re.IGNORECASE,
            )
            if implicit and implicit.start() > 0:
                visible += thinking[implicit.start():]
            else:
                response = re.search(r"\n\s*response(?:[ \t]*\r?\n)?", thinking,
                                     re.IGNORECASE)
                if response and response.start() > 0:
                    visible += thinking[response.end():]
    return re.sub(
        r"</?(?:think|thinking|reasoning)>|<\|/?thinking\|>|"
        r"\[/?(?:thought|thinking|reasoning|scratchpad)\]",
        "", visible, flags=re.IGNORECASE,
    )


def _visible_final_answer(text: str) -> str:
    """What the user can actually see after reasoning/tool markup is removed."""
    return _strip_unparsed_tool_markup(_visible_assistant_text(text)).strip()


# Assistant messages of the turn in progress, published by run_chat_turn before
# it runs a round's tools, so write_file(source='visible_code_block') can copy a
# fence from the current turn, including the reply that makes the call.
_live_turn_messages: dict[str, list[dict]] = {}


_FILE_IN_PARTS = ("write the file in parts: write_file with the first part (about 150 lines), "
                  "then write_file mode='append' for each next part")


def _recent_visible_code_blocks(chat_id: str, language: str = "") -> list[dict]:
    wanted = str(language or "").strip().lower()
    chat = (get_chats().get("chats", {}) or {}).get(chat_id) or {}
    saved = [(i, m) for i, m in enumerate(chat.get("messages") or [])
             if not m.get("_internal")]
    live = [(len(chat.get("messages") or []) + i, m)
            for i, m in enumerate(_live_turn_messages.get(chat_id) or [])]
    blocks: list[dict] = []
    for message_index, message in saved + live:
        if (message.get("role") != "assistant"
                or not isinstance(message.get("content"), str)):
            continue
        visible = _visible_assistant_text(message.get("content") or "")
        for match in _CHAT_CODE_FENCE_RE.finditer(visible):
            info = (match.group(1) or "").strip()
            lang = (info.split(None, 1)[0] if info else "text").lower()
            if lang in {"tool_code", "tool_call"}:
                continue
            if wanted and lang != wanted:
                continue
            blocks.append({
                "content": match.group(2), "language": lang,
                "info": info, "message_index": message_index,
                "live": message_index >= len(chat.get("messages") or []),
            })
    return blocks


# Fence languages and file extensions that name the same kind of code. A block is
# refused only when both sides are known here and differ.
_CODE_FAMILIES = {
    "html": ("html", "htm", "xhtml"),
    "css": ("css",),
    "javascript": ("js", "javascript", "mjs", "cjs", "jsx", "ts", "typescript", "tsx"),
    "python": ("py", "python", "python3", "pyw"),
    "powershell": ("ps1", "psm1", "powershell", "pwsh"),
    "shell": ("sh", "bash", "zsh"),
    "batch": ("bat", "cmd", "batch"),
    "json": ("json", "jsonc"),
    "markdown": ("md", "markdown"),
    "java": ("java",),
    "csharp": ("cs", "csharp"),
    "go": ("go", "golang"),
    "rust": ("rs", "rust"),
    "ruby": ("rb", "ruby"),
    "sql": ("sql",),
    "yaml": ("yaml", "yml"),
    "c/c++": ("c", "h", "cpp", "cc", "cxx", "hpp", "c++"),
}
_CODE_FAMILY_OF = {name: family for family, names in _CODE_FAMILIES.items() for name in names}


def _code_only_in_thinking(chat_id: str) -> bool:
    """The reply that makes the call has a code fence in its thinking and none in view."""
    live = _live_turn_messages.get(chat_id) or []
    content = str(live[-1].get("content") or "") if live else ""
    thinking, _ = _split_leading_think(_close_think_marker(content))
    if "```" not in thinking:
        return False
    for match in _CHAT_CODE_FENCE_RE.finditer(_visible_assistant_text(content)):
        info = (match.group(1) or "").strip()
        if (info.split(None, 1)[0].lower() if info else "text") not in {"tool_code", "tool_call"}:
            return False
    return True


def _visible_code_source(args: dict) -> tuple[dict, str]:
    """Resolve a prior visible code fence selected by a write tool call."""
    if str(args.get("source") or "").strip().lower() != "visible_code_block":
        return {}, "source must be 'visible_code_block'. No file was written."
    try:
        index = max(0, min(int(args.get("index") or 0), 50))
    except (ValueError, TypeError) as exc:
        return {}, str(exc)
    chat_id = _get_current_chat() or ""
    blocks = _recent_visible_code_blocks(chat_id, str(args.get("language") or ""))
    write_it = "Pass the file text in content instead."
    if index >= len(blocks):
        return {}, (
            "No matching visible code block exists in this chat. "
            f"Found {len(blocks)} matching blocks. {write_it}"
        )
    block = blocks[-1 - index]
    name = os.path.basename(str(args.get("path") or ""))
    want = _CODE_FAMILY_OF.get(os.path.splitext(name)[1].lstrip(".").lower())
    have = _CODE_FAMILY_OF.get(block["language"])
    if want and have and want != have:
        return {}, (f"refused: the newest visible code block is {block['language']}, but {name} "
                    f"needs {want} code. No file was written. {write_it}")
    if not block["live"] and _code_only_in_thinking(chat_id):
        return {}, ("refused: this reply has its code only in your thinking, which is not visible "
                    "and is not kept. The newest visible code block is from an earlier message, so "
                    f"no file was written. {write_it}")
    return block, ""


def _cleanup_remote_staging(max_age_s: int = 86400) -> None:
    cutoff = time.time() - max_age_s
    try:
        for path in REMOTE_STAGING_DIR.glob("*.part"):
            try:
                if path.stat().st_mtime < cutoff:
                    path.unlink(missing_ok=True)
            except Exception:
                pass
    except Exception:
        pass


def tool_remote_file_begin(args: dict) -> dict:
    """Open one path-bound staged write. Approval is intentionally paid here once."""
    row = _selected_remote_machine(args)
    if not row:
        return {"error": "No verified Mac is selected."}
    try:
        path = _normalize_remote_path(row, args.get("path") or "")
    except ValueError as exc:
        return {"error": str(exc)}
    path, path_error = _confirm_remote_path(row, path)
    if path_error:
        return {"error": path_error}
    approval = request_approval(
        title=f"Prepare a large file on {row.get('label') or 'paired Mac'}",
        command=f"Assemble one file in chunks, then write atomically to {path}",
        details={
            "kind": "remote_file_write", "force_prompt": True,
            "machine": row.get("id"), "path": path,
            "max_bytes": _remote_payload_limit(),
        },
    )
    if approval.get("decision") != "approve":
        return {"error": f"user denied remote file write ({approval.get('status')})"}
    REMOTE_STAGING_DIR.mkdir(parents=True, exist_ok=True)
    _cleanup_remote_staging()
    upload_id = uuid.uuid4().hex
    staging_path = REMOTE_STAGING_DIR / f"{upload_id}.part"
    staging_path.touch(exist_ok=False)
    _protect_remote_private_key(staging_path)
    record = {
        "id": upload_id, "chat_id": _get_current_chat() or "",
        "machine_id": str(row.get("id") or ""), "path": path,
        "staging_path": staging_path, "bytes": 0, "chunks": 0,
        "created": time.time(),
        "expected_sha256": _remote_expected_hash(row, path),
    }
    with _remote_staged_writes_lock:
        _remote_staged_writes[upload_id] = record
    return {
        "ok": True, "upload_id": upload_id, "path": path,
        "chunk_chars_max": 6000, "bytes": 0, "chunks": 0,
        "note": "Append the file in order, then commit it. Do not repeat earlier chunks.",
    }


def _owned_remote_stage(upload_id: str) -> tuple[dict | None, str]:
    token = str(upload_id or "").strip()
    with _remote_staged_writes_lock:
        record = _remote_staged_writes.get(token)
    if not record:
        return None, "Unknown or expired staged-write id. Start again with remote_file_begin."
    if record.get("chat_id") != (_get_current_chat() or ""):
        return None, "This staged write belongs to another chat."
    if time.time() - float(record.get("created") or 0) > 86400:
        with _remote_staged_writes_lock:
            _remote_staged_writes.pop(token, None)
        try:
            Path(record["staging_path"]).unlink(missing_ok=True)
        except Exception:
            pass
        return None, "This staged write expired. Start it again."
    return record, ""


def tool_remote_file_append(args: dict) -> dict:
    record, error = _owned_remote_stage(args.get("upload_id") or "")
    if error:
        return {"error": error}
    content = args.get("content")
    if not isinstance(content, str) or not content:
        return {"error": "Chunk content is empty. Re-emit only this missing chunk."}
    if len(content) > 8000:
        return {"error": "Chunk is too large. Split it into chunks of at most 6000 characters."}
    payload = content.encode("utf-8")
    if int(record.get("bytes") or 0) + len(payload) > _remote_payload_limit():
        return {"error": "Staged file exceeds the configured remote transfer limit."}
    staging_path = Path(record["staging_path"])
    with _remote_staged_writes_lock:
        with staging_path.open("ab") as handle:
            handle.write(payload)
        record["bytes"] = int(record.get("bytes") or 0) + len(payload)
        record["chunks"] = int(record.get("chunks") or 0) + 1
        total = int(record["bytes"])
        chunks = int(record["chunks"])
    return {
        "ok": True, "upload_id": record["id"], "path": record["path"],
        "bytes": total, "chunks": chunks, "chunk_bytes": len(payload),
    }


def tool_remote_file_commit(args: dict) -> dict:
    record, error = _owned_remote_stage(args.get("upload_id") or "")
    if error:
        return {"error": error}
    row = _remote_machine(str(record.get("machine_id") or ""))
    if not row or row.get("status") != "ready":
        return {"error": "The paired Mac is unavailable. The staged file is retained for a later retry."}
    path, path_error = _confirm_remote_path(row, str(record.get("path") or ""))
    if path_error:
        return {"error": path_error}
    if path != record.get("path"):
        return {"error": "The resolved destination changed after approval. Start the staged write again."}
    staging_path = Path(record["staging_path"])
    payload = staging_path.read_bytes()
    if not payload:
        return {"error": "Staged file is empty. Append content before committing."}
    actual_sha = hashlib.sha256(payload).hexdigest()
    wanted_sha = str(args.get("sha256") or "").strip().lower()
    if wanted_sha and wanted_sha != actual_sha:
        return {
            "error": "Staged content SHA-256 does not match the expected value.",
            "actual_sha256": actual_sha,
        }
    result = _remote_write_bytes(
        row, path, payload, str(record.get("expected_sha256") or ""))
    if not result.get("ok"):
        result["upload_id"] = record["id"]
        result["retained"] = True
        return result
    with _remote_staged_writes_lock:
        _remote_staged_writes.pop(record["id"], None)
    staging_path.unlink(missing_ok=True)
    result = _remote_text_result(result) if "stdout_bytes" in result else result
    result.update({
        "ok": True, "path": path, "bytes": len(payload),
        "chunks": int(record.get("chunks") or 0), "sha256": actual_sha,
    })
    return result


def tool_remote_file_abort(args: dict) -> dict:
    record, error = _owned_remote_stage(args.get("upload_id") or "")
    if error:
        return {"error": error}
    with _remote_staged_writes_lock:
        _remote_staged_writes.pop(record["id"], None)
    Path(record["staging_path"]).unlink(missing_ok=True)
    return {"ok": True, "upload_id": record["id"], "aborted": True}


def tool_remote_write_file(args: dict) -> dict:
    row = _selected_remote_machine(args)
    if not row:
        return {"error": "No verified Mac is selected."}
    try:
        path = _normalize_remote_path(row, args.get("path") or "")
    except ValueError as exc:
        return {"error": str(exc)}
    path, path_error = _confirm_remote_path(row, path)
    if path_error:
        return {"error": path_error}
    content = args.get("content")
    source_meta: dict = {}
    if args.get("source"):
        if isinstance(content, str) and content.strip():
            return {"error": "refused: provide either content or source, not both. No file was written."}
        block, source_error = _visible_code_source(args)
        if source_error:
            return {"error": source_error}
        content = block["content"]
        source_meta = {
            "source": "visible_chat_code_block",
            "language": block["language"],
            "message_index": block["message_index"],
        }
    if not isinstance(content, str) or not content.strip():
        return {"error": "refused: content or source is empty or missing. No file was written."}
    payload = content.encode("utf-8")
    expected = _remote_expected_hash(row, path, args.get("expected_sha256") or "")
    result = _remote_write_approved_payload(
        row, path, payload, expected,
        title=f"Write file on {row.get('label') or 'paired Mac'}",
    )
    if result.get("ok"):
        result.update(source_meta)
    return result


def tool_remote_copy_to(args: dict) -> dict:
    row = _selected_remote_machine(args)
    if not row:
        return {"error": "No verified Mac is selected."}
    source = normalize_path(args.get("source") or "")
    if not is_in_workspace(source) or not os.path.isfile(source):
        return {"error": "Source must be an existing file inside the PC workspace."}
    try:
        destination = _normalize_remote_path(row, args.get("destination") or "")
    except ValueError as exc:
        return {"error": str(exc)}
    destination, path_error = _confirm_remote_path(row, destination)
    if path_error:
        return {"error": path_error}
    size = os.path.getsize(source)
    if size > _remote_payload_limit():
        return {"error": "File exceeds the configured remote transfer limit."}
    approval = request_approval(
        title=f"Copy file to {row.get('label') or 'paired Mac'}",
        command=f"{source} -> {destination} ({size} bytes)",
        details={"kind": "remote_file_copy", "force_prompt": True, "machine": row.get("id"), "path": destination},
    )
    if approval.get("decision") != "approve":
        return {"error": f"user denied file transfer ({approval.get('status')})"}
    payload = Path(source).read_bytes()
    result = _remote_write_bytes(row, destination, payload)
    if result.get("ok"):
        result.update({"source": source, "destination": destination, "bytes": size})
    return result


def tool_remote_copy_from(args: dict) -> dict:
    row = _selected_remote_machine(args)
    if not row:
        return {"error": "No verified Mac is selected."}
    try:
        source = _normalize_remote_path(row, args.get("source") or "")
    except ValueError as exc:
        return {"error": str(exc)}
    destination = normalize_path(args.get("destination") or "")
    if not is_in_workspace(destination):
        return {"error": "Destination must be inside the PC workspace."}
    meta = _remote_file_metadata(row, source)
    if not meta.get("ok"):
        return {"error": meta.get("stderr") or meta.get("error") or "Remote file not found."}
    if meta["size"] > _remote_payload_limit():
        return {"error": "File exceeds the configured remote transfer limit."}
    source = meta["path"]
    approval = request_approval(
        title=f"Copy file from {row.get('label') or 'paired Mac'}",
        command=f"{source} -> {destination} ({meta['size']} bytes)",
        details={"kind": "remote_file_copy", "force_prompt": True, "machine": row.get("id"), "path": source},
    )
    if approval.get("decision") != "approve":
        return {"error": f"user denied file transfer ({approval.get('status')})"}
    result = _run_remote_process(row, f"cat -- {shlex.quote(source)}", timeout=max(60, int(meta["size"] / 250_000) + 30),
                                 max_stdout=meta["size"] + 1, stream_name="")
    if not result.get("ok"):
        return {"error": result.get("stderr") or result.get("error") or "Remote transfer failed."}
    payload = result.get("stdout_bytes") or b""
    if len(payload) != meta["size"] or hashlib.sha256(payload).hexdigest() != meta["sha256"]:
        return {"error": "Transferred bytes failed the size or SHA-256 integrity check."}
    dest_path = Path(destination)
    dest_path.parent.mkdir(parents=True, exist_ok=True)
    tmp = dest_path.with_name(dest_path.name + ".accuretta.part")
    tmp.write_bytes(payload)
    tmp.replace(dest_path)
    return {"ok": True, "source": source, "destination": destination, "bytes": len(payload), "sha256": meta["sha256"]}


# ---- interactive sessions --------------------------------------------------
# A long-lived child process that the agent and the user (via the shared Shell
# tab) drive statefully across many tool calls: reverse shells, ssh, REPLs,
# debuggers, DB clients. A reader thread drains output into a capped buffer
# with absolute offsets, so the model (its cursor) and the UI (its since=) can
# each tail it. Pipes, not a PTY: line-based interaction works everywhere, but
# full-screen TUIs and TTY-only password prompts may misbehave.
_SESSION_BUF_CAP = 200_000   # chars kept per session

class Session:
    def __init__(self, sid: str, command: str):
        self.id = sid
        self.command = command
        self.created = time.time()
        self._proc: subprocess.Popen | None = None
        self._out = ""      # recent output (front-trimmed at the cap)
        self._base = 0      # absolute offset of _out[0] (chars already dropped)
        self._cursor = 0    # the model's read cursor (absolute)
        self._lock = threading.Lock()

    def start(self, cwd: str | None = None) -> None:
        shell_executable = None
        if sys.platform == "win32":
            shell_executable = _trusted_windows_binary("cmd.exe")
            if not shell_executable:
                raise RuntimeError(
                    "Trusted Windows command processor was not found in the system directory."
                )
        self._proc = subprocess.Popen(
            self.command,
            shell=True,
            executable=shell_executable,
            cwd=cwd or None,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            bufsize=1,
            encoding="utf-8",
            errors="replace",
            creationflags=(subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0),
        )
        threading.Thread(target=self._pump, name=f"session-{self.id}", daemon=True).start()

    def _append(self, text: str) -> None:
        with self._lock:
            self._out += text
            if len(self._out) > _SESSION_BUF_CAP:
                drop = len(self._out) - _SESSION_BUF_CAP
                self._out = self._out[drop:]
                self._base += drop

    def _pump(self) -> None:
        try:
            if not self._proc or not self._proc.stdout:
                return
            for line in iter(self._proc.stdout.readline, ""):
                self._append(line)
        except Exception:
            pass

    def alive(self) -> bool:
        return self._proc is not None and self._proc.poll() is None

    def exit_code(self):
        return None if self._proc is None else self._proc.poll()

    def send(self, text: str, enter: bool = True) -> bool:
        if not self.alive() or not self._proc or not self._proc.stdin:
            return False
        try:
            data = text + ("\n" if enter and not text.endswith("\n") else "")
            self._proc.stdin.write(data)
            self._proc.stdin.flush()
            self._append(data)
            return True
        except Exception:
            return False

    def read_since(self, offset: int):
        with self._lock:
            start = max(0, offset - self._base)
            return self._out[start:], self._base + len(self._out)

    def read_model(self, cap: int = 12000) -> str:
        text, newcur = self.read_since(self._cursor)
        self._cursor = newcur
        if len(text) > cap:
            text = "… [earlier output truncated — read again for more] …\n" + text[-cap:]
        return text

    def stop(self) -> bool:
        proc = self._proc
        if proc is None or proc.poll() is not None:
            return True
        try:
            _terminate_process_tree(proc, "host")
        except Exception:
            return proc.poll() is not None
        return proc.poll() is not None

    def info(self) -> dict:
        return {"id": self.id, "command": self.command, "alive": self.alive(),
                "exit_code": self.exit_code(), "created": self.created}


class SessionManager:
    def __init__(self):
        self._sessions: dict[str, Session] = {}
        self._lock = threading.Lock()
        self._n = 0

    def create(self, command: str, cwd: str | None = None) -> Session:
        with self._lock:
            self._n += 1
            sid = f"s{self._n}"
        s = Session(sid, command)
        s.start(cwd=cwd)
        with self._lock:
            self._sessions[sid] = s
        return s

    def get(self, sid: str | None) -> Session | None:
        with self._lock:
            return self._sessions.get(sid or "")

    def list(self) -> list:
        with self._lock:
            return [s.info() for s in self._sessions.values()]

    def stop(self, sid: str) -> bool:
        s = self.get(sid)
        if s:
            return s.stop()
        return False

    def stop_all(self) -> None:
        with self._lock:
            sessions = list(self._sessions.values())
        for s in sessions:
            s.stop()


_session_mgr = SessionManager()


def _session_wait(ms) -> None:
    try:
        ms = int(ms)
    except Exception:
        ms = 600
    ms = max(0, min(ms, 6000))
    if ms:
        time.sleep(ms / 1000.0)


def _session_not_executed(message: str, **details) -> dict:
    result = {
        "error": message,
        "not_executed": True,
        "executed": False,
        "execution_target": "host",
    }
    result.update(details)
    return result


def _session_workspace_cwd(requested: str = "") -> tuple[str, str]:
    configured = [
        normalize_path(folder)
        for folder in (get_workspace().get("folders", []) or [])
        if isinstance(folder, str) and folder.strip()
    ]
    roots = configured or [normalize_path(str(ROOT))]
    cwd = normalize_path(requested or roots[0])
    normalized_cwd = os.path.normcase(os.path.abspath(cwd))
    inside = False
    for root in roots:
        normalized_root = os.path.normcase(os.path.abspath(root))
        try:
            if os.path.commonpath([normalized_cwd, normalized_root]) == normalized_root:
                inside = True
                break
        except ValueError:
            continue
    if not inside or is_blocked_path(cwd):
        return "", "CWD is outside configured workspace bounds."
    if not os.path.isdir(cwd):
        return "", f"CWD is not a directory: {cwd}"
    return cwd, ""


def tool_session_start(args: dict) -> dict:
    command = (args.get("command") or ("powershell" if sys.platform == "win32" else "bash")).strip()
    if not command:
        return _session_not_executed("empty command")
    cwd, cwd_error = _session_workspace_cwd(str(args.get("cwd") or ""))
    if cwd_error:
        return _session_not_executed(cwd_error, scope_blocked=True)
    if sys.platform == "win32" and command.lower() in {"powershell", "powershell.exe"}:
        powershell_exe = _trusted_windows_binary("WindowsPowerShell", "v1.0", "powershell.exe")
        if not powershell_exe:
            return _session_not_executed(
                "Trusted Windows PowerShell executable was not found.", spawn_error=True)
        command = f'"{powershell_exe}" -NoLogo -NoProfile'
    threat = bridge_self_threat(command)
    if threat:
        return _session_not_executed(
            f"refused: {threat}", refused_command=command, self_protection=True)
    catastrophic = _catastrophic_cmd(command)
    if catastrophic:
        return _session_not_executed(
            f"refused: this command {catastrophic}. Run it yourself if you truly mean to.",
            refused_command=command, catastrophic=True)
    clickfix = _clickfix_cmd(command)
    if clickfix:
        return _session_not_executed(
            f"refused: this command {clickfix} (ClickFix signature). Run it yourself if you truly mean to.",
            refused_command=command, clickfix=True)
    approval = request_approval(
        title="Start persistent process on Windows host",
        command=command,
        details={
            "kind": "session", "target": "host", "cwd": cwd,
            "executes_code": True,
            "red_team_context": bool(_rt_authorized_mission(_rt_context_chat())),
        },
    )
    if approval.get("decision") != "approve":
        return _session_not_executed(
            f"user denied session ({approval.get('status')})")
    try:
        s = _session_mgr.create(command, cwd=cwd)
    except Exception as e:
        return _session_not_executed(str(e), spawn_error=True)
    _session_wait(args.get("wait_ms", 600))
    return {
        "session_id": s.id, "alive": s.alive(), "output": s.read_model(),
        "executed": True, "execution_target": "host", "cwd": cwd,
        "note": "Interactive session started. Drive it with session_send (input=command), "
                "poll new output with session_read, and end it with session_stop.",
    }


def tool_session_send(args: dict) -> dict:
    sid = args.get("session_id") or args.get("id")
    s = _session_mgr.get(sid)
    if not s:
        return _session_not_executed(
            f"no such session: {sid}", sessions=_session_mgr.list())
    if not s.alive():
        return _session_not_executed(
            f"session {sid} has exited", exit_code=s.exit_code())
    text = args.get("input")
    if text is None:
        text = args.get("text", "")
    text = str(text)
    threat = bridge_self_threat(text)
    if threat:
        return _session_not_executed(
            f"refused: {threat}", refused_input=text, self_protection=True)
    catastrophic = _catastrophic_cmd(text)
    if catastrophic:
        return _session_not_executed(
            f"refused: this input {catastrophic}. Run it yourself if you truly mean to.",
            refused_input=text, catastrophic=True)
    clickfix = _clickfix_cmd(text)
    if clickfix:
        return _session_not_executed(
            f"refused: this input {clickfix} (ClickFix signature). Run it yourself if you truly mean to.",
            refused_input=text, clickfix=True)
    approval = request_approval(
        title="Send input to persistent Windows host process",
        command=text,
        details={
            "kind": "session", "session_id": sid, "target": "host",
            "executes_code": True,
            "red_team_context": bool(_rt_authorized_mission(_rt_context_chat())),
        },
    )
    if approval.get("decision") != "approve":
        return _session_not_executed(
            f"user denied input ({approval.get('status')})")
    if not s.send(text, enter=bool(args.get("enter", True))):
        return _session_not_executed(
            "failed to write to session (it may have exited)", alive=s.alive())
    _session_wait(args.get("wait_ms", 700))
    return {"session_id": sid, "alive": s.alive(), "output": s.read_model(),
            "executed": True, "execution_target": "host"}


def tool_session_read(args: dict) -> dict:
    sid = args.get("session_id") or args.get("id")
    s = _session_mgr.get(sid)
    if not s:
        return _session_not_executed(
            f"no such session: {sid}", sessions=_session_mgr.list())
    _session_wait(args.get("wait_ms", 0))
    return {"session_id": sid, "alive": s.alive(), "exit_code": s.exit_code(), "output": s.read_model()}


def tool_session_stop(args: dict) -> dict:
    sid = args.get("session_id") or args.get("id")
    if not sid:
        return _session_not_executed(
            "session_id required", sessions=_session_mgr.list())
    session = _session_mgr.get(sid)
    if not session:
        return _session_not_executed(
            f"no such session: {sid}", session_id=sid,
            sessions=_session_mgr.list())
    stopped = _session_mgr.stop(sid)
    alive = session.alive()
    result = {
        "session_id": sid,
        "stopped": bool(stopped and not alive),
        "alive": alive,
        "executed": True,
        "execution_target": "host",
    }
    if not result["stopped"]:
        result["error"] = "failed to stop the persistent process tree"
    return result


def tool_session_list(args: dict) -> dict:
    return {"sessions": _session_mgr.list()}


_NETSNAP_PS = r"""
$ErrorActionPreference = 'SilentlyContinue'
$conns = Get-NetTCPConnection -State Established,Listen |
    Select-Object LocalAddress, LocalPort, RemoteAddress, RemotePort, State, OwningProcess
$udp = Get-NetUDPEndpoint |
    Select-Object LocalAddress, LocalPort, OwningProcess
$dns = Get-DnsClientCache |
    Where-Object { $_.Type -eq 'A' -or $_.Type -eq 'AAAA' -or $_.Type -eq 1 -or $_.Type -eq 28 } |
    Sort-Object TimeToLive -Descending |
    Select-Object -First 60 -Property Entry, Name, Type, TimeToLive
$procs = @{}
$ids = @($conns.OwningProcess) + @($udp.OwningProcess) | Sort-Object -Unique
# One CIM pass for all pids (command lines + paths), then one signature pass
# per UNIQUE path (capped; hashing big exes is the slow part).
$cmdlines = @{}
$pidToPath = @{}
try {
    $cim = Get-CimInstance Win32_Process | Where-Object { $ids -contains $_.ProcessId }
    foreach ($p in $cim) {
        $cmdlines[[string]$p.ProcessId] = [string]$p.CommandLine
        if ($p.ExecutablePath) { $pidToPath[[string]$p.ProcessId] = [string]$p.ExecutablePath }
    }
} catch {}
$sigCache = @{}
$sigCount = 0
$sigSw = [System.Diagnostics.Stopwatch]::StartNew()
foreach ($path in @($pidToPath.Values | Sort-Object -Unique)) {
    if ($sigCount -ge 20 -or $sigSw.ElapsedMilliseconds -gt 12000) { break }
    $vi = $null
    try { $vi = (Get-Item -LiteralPath $path -ErrorAction SilentlyContinue).VersionInfo } catch {}
    $signed = $null
    if ($vi) {
        try {
            $len = (Get-Item -LiteralPath $path -ErrorAction SilentlyContinue).Length
            if ($len -lt 500MB) {
                $sigCount++
                $sig = Get-AuthenticodeSignature -LiteralPath $path -ErrorAction SilentlyContinue
                if ($sig -and $sig.Status -eq 'Valid') { $signed = $true }
                elseif ($sig -and $sig.Status -eq 'NotSigned') { $signed = $false }
            }
        } catch {}
    }
    $sigCache[$path] = @{
        company = if ($vi -and $vi.CompanyName) { [string]$vi.CompanyName } else { '' }
        desc = if ($vi -and $vi.FileDescription) { [string]$vi.FileDescription } else { '' }
        signed = $signed
    }
}
foreach ($procId in $ids) {
    if (-not $procId) { continue }
    $path = $pidToPath[[string]$procId]
    $meta = if ($path -and $sigCache.ContainsKey($path)) { $sigCache[$path] } else { $null }
    $procs[[string]$procId] = @{
        name = (Get-Process -Id $procId -ErrorAction SilentlyContinue).ProcessName
        path = $path
        company = $(if ($meta) { $meta.company } else { '' })
        desc = $(if ($meta) { $meta.desc } else { '' })
        signed = $(if ($meta) { $meta.signed } else { $null })
        cmdline = $(if ($cmdlines[[string]$procId]) { $cmdlines[[string]$procId] } else { '' })
    }
}
@{ 
    tcp = @($conns)
    udp = @($udp)
    dns_cache = @($dns)
    processes = $procs
} | ConvertTo-Json -Depth 5 -Compress
"""

