def tool_git_fetch(args: dict) -> dict:
    cwd, err = _resolve_git_cwd(args.get("path") or "")
    if err:
        return err
    argv = ["fetch"]
    if args.get("all"):
        argv.append("--all")
    if args.get("prune"):
        argv.append("--prune")
    if args.get("tags"):
        argv.append("--tags")
    remote = (args.get("remote") or "").strip()
    if remote:
        argv.append(remote)
    refusal = _git_approve("git fetch", cwd, argv)
    if refusal:
        return refusal
    return _run_git(cwd, argv, timeout=180)


def tool_git_checkout(args: dict) -> dict:
    cwd, err = _resolve_git_cwd(args.get("path") or "")
    if err:
        return err
    target = (args.get("target") or "").strip()
    if not target:
        return {"error": "`target` is required (branch, ref, or '--' file)"}
    argv = ["checkout"]
    if args.get("create"):
        argv.append("-b")
    argv.append(target)
    files = args.get("files")
    if isinstance(files, str):
        files = [files]
    if files:
        argv.append("--")
        argv.extend(files)
    refusal = _git_approve("git checkout", cwd, argv)
    if refusal:
        return refusal
    return _run_git(cwd, argv, timeout=60)


def tool_git_restore(args: dict) -> dict:
    cwd, err = _resolve_git_cwd(args.get("path") or "")
    if err:
        return err
    files = args.get("files")
    if isinstance(files, str):
        files = [files]
    if not files:
        return {"error": "`files` is required (list of paths to restore)"}
    argv = ["restore"]
    if args.get("staged"):
        argv.append("--staged")
    if args.get("worktree", True) and not args.get("staged"):
        # default behavior of `git restore` is worktree; nothing to add
        pass
    if args.get("source"):
        argv.extend(["--source", str(args["source"])])
    argv.append("--")
    argv.extend(files)
    refusal = _git_approve("git restore", cwd, argv, extra={"files": files})
    if refusal:
        return refusal
    return _run_git(cwd, argv, timeout=30)


def tool_git_reset(args: dict) -> dict:
    cwd, err = _resolve_git_cwd(args.get("path") or "")
    if err:
        return err
    mode = (args.get("mode") or "mixed").strip().lower()
    if mode not in {"soft", "mixed", "hard", "keep", "merge"}:
        return {"error": "mode must be one of: soft, mixed, hard, keep, merge"}
    argv = ["reset", f"--{mode}"]
    target = (args.get("target") or "").strip()
    if target:
        argv.append(target)
    title = f"git reset --{mode}"
    refusal = _git_approve(title, cwd, argv)
    if refusal:
        return refusal
    return _run_git(cwd, argv, timeout=60)


def tool_git_init(args: dict) -> dict:
    cwd, err = _resolve_git_cwd(args.get("path") or "")
    if err:
        return err
    argv = ["init"]
    initial_branch = (args.get("initial_branch") or "").strip()
    if initial_branch:
        argv.extend(["-b", initial_branch])
    refusal = _git_approve("git init", cwd, argv)
    if refusal:
        return refusal
    return _run_git(cwd, argv, timeout=20)


def tool_git_clone(args: dict) -> dict:
    """Clone into a directory inside the workspace. `dest` must be a workspace path."""
    url = (args.get("url") or "").strip()
    if not url:
        return {"error": "`url` is required"}
    dest = (args.get("dest") or "").strip()
    if not dest:
        return {"error": "`dest` is required (directory inside workspace; will be created)"}
    dest_norm = normalize_path(dest)
    parent = str(Path(dest_norm).parent)
    if not is_in_workspace(parent):
        return {"error": "dest is outside the workspace"}
    _cerr = _critical_path_gate(dest_norm, "git", "PROTECTED PATH - git clone destination under Windows/System32")
    if _cerr:
        return _cerr
    if os.path.exists(dest_norm) and os.listdir(dest_norm):
        return {"error": f"dest already exists and is non-empty: {dest_norm}"}
    Path(parent).mkdir(parents=True, exist_ok=True)
    argv = ["clone", url, dest_norm]
    depth = args.get("depth")
    if depth and int(depth) > 0:
        argv.extend(["--depth", str(int(depth))])
    branch = (args.get("branch") or "").strip()
    if branch:
        argv.extend(["--branch", branch])
    refusal = _git_approve("git clone", parent, argv, extra={"url": url, "dest": dest_norm})
    if refusal:
        return refusal
    # Clone runs in the parent (cwd doesn't matter much for clone with explicit dest).
    return _run_git(parent, argv, timeout=900)


# ---- github integration ----------------------------------------------------
# GitHub Activity dashboard + branch workflow. The PAT stays in
# data/github_cred.json and never leaves the bridge; the frontend only sees the
# connected state (login + avatar). All calls use the helpers below with a hard
# timeout so a hung request can't wedge a worker.

GITHUB_CRED_FILE = DATA / "github_cred.json"
GITHUB_REST_API = "https://api.github.com"
GITHUB_GRAPHQL_API = "https://api.github.com/graphql"
_GITHUB_OWNER_RE = re.compile(r"^[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$")
_GITHUB_REPO_RE = re.compile(r"^[A-Za-z0-9_.-]{1,100}$")
_GITHUB_BRANCH_RE = re.compile(r"^[A-Za-z0-9._/-]{1,256}$")
_GITHUB_BRANCH_BAD = re.compile(r"(^|/)\.\.|@{|^/|/$|^-|(^|/)\.(git|lock)(/|$)|\.\.$")


def _github_cred() -> dict:
    cred = load_json(GITHUB_CRED_FILE, {})
    return cred if isinstance(cred, dict) else {}


def _github_save_cred(pat: str, login: str = "", avatar_url: str = "") -> None:
    save_json(GITHUB_CRED_FILE, {"pat": pat, "login": login, "avatar_url": avatar_url})


def _github_headers(token: str | None = None) -> dict:
    t = token if token is not None else (_github_cred().get("pat") or "")
    return {
        "Authorization": f"Bearer {t}",
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "User-Agent": "Accuretta",
    }


def _github_rest(method: str, path: str, body: dict | None = None,
                 token: str | None = None, timeout: int = 25) -> tuple[int, dict]:
    """Raw GitHub REST call. Returns (status, parsed_json)."""
    data = json.dumps(body).encode("utf-8") if body is not None else None
    req = urllib.request.Request(
        GITHUB_REST_API + path, data=data, method=method, headers=_github_headers(token))
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode("utf-8", "replace")
            try:
                return resp.status, json.loads(raw) if raw else {}
            except Exception:
                return resp.status, {"message": raw[:500]}
    except urllib.error.HTTPError as e:
        raw = e.read().decode("utf-8", "replace")
        try:
            return e.code, json.loads(raw) if raw else {}
        except Exception:
            return e.code, {"message": raw[:500]}
    except Exception as e:
        return 0, {"message": str(e)}


def _github_rest_h(method: str, path: str, body: dict | None = None,
                   token: str | None = None, timeout: int = 25) -> tuple[int, dict, object]:
    """Like _github_rest but also returns the response headers object.

    GitHub reports the permission level a token actually carries on the
    requested resource via the `x-accepted-github-permissions` header, which
    is what makes 403s explainable without guessing.
    """
    data = json.dumps(body).encode("utf-8") if body is not None else None
    req = urllib.request.Request(
        GITHUB_REST_API + path, data=data, method=method, headers=_github_headers(token))
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode("utf-8", "replace")
            try:
                return resp.status, (json.loads(raw) if raw else {}), resp.headers
            except Exception:
                return resp.status, {"message": raw[:500]}, resp.headers
    except urllib.error.HTTPError as e:
        raw = e.read().decode("utf-8", "replace")
        try:
            return e.code, (json.loads(raw) if raw else {}), e.headers
        except Exception:
            return e.code, {"message": raw[:500]}, e.headers
    except Exception as e:
        return 0, {"message": str(e)}, {}


def _github_graphql(query: str, token: str | None = None, timeout: int = 30,
                    variables: dict | None = None) -> tuple[int, dict]:
    """Raw GitHub GraphQL call. Returns (status, parsed_json)."""
    request_body = {"query": query}
    if variables is not None:
        request_body["variables"] = variables
    payload = json.dumps(request_body).encode("utf-8")
    req = urllib.request.Request(
        GITHUB_GRAPHQL_API, data=payload, method="POST", headers=_github_headers(token))
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode("utf-8", "replace")
            return resp.status, json.loads(raw) if raw else {}
    except urllib.error.HTTPError as e:
        raw = e.read().decode("utf-8", "replace")
        try:
            return e.code, json.loads(raw) if raw else {}
        except Exception:
            return e.code, {"message": raw[:500]}
    except Exception as e:
        return 0, {"message": str(e)}


_GH_ACTIVITY_QUERY = """
query AccurettaActivity {
  viewer {
    login
    contributionsCollection {
      contributionCalendar {
        totalContributions
        weeks {
          contributionDays {
            date
            contributionCount
          }
        }
      }
    }
    repositories(first: 3, orderBy: {field: PUSHED_AT, direction: DESC},
                 ownerAffiliations: [OWNER, COLLABORATOR, ORGANIZATION_MEMBER]) {
      nodes {
        name
        owner { login }
        stargazerCount
        pushedAt
        defaultBranchRef { name }
      }
      pageInfo { hasNextPage endCursor }
    }
  }
}
"""

_GH_REPOS_QUERY = """
query AccurettaRepositories($first: Int!, $after: String) {
  viewer {
    repositories(first: $first, after: $after,
                 orderBy: {field: PUSHED_AT, direction: DESC},
                 ownerAffiliations: [OWNER, COLLABORATOR, ORGANIZATION_MEMBER]) {
      nodes {
        name
        owner { login }
        stargazerCount
        pushedAt
        defaultBranchRef { name }
      }
      pageInfo { hasNextPage endCursor }
    }
  }
}
"""


def _github_repo_page(connection: object) -> tuple[list[dict], dict]:
    """Normalize a GitHub repository connection for the browser."""
    conn = connection if isinstance(connection, dict) else {}
    repos = []
    for node in conn.get("nodes", []) or []:
        if not isinstance(node, dict):
            continue
        repos.append({
            "name": node.get("name", ""),
            "owner": ((node.get("owner") or {}) or {}).get("login", ""),
            "stars": int(node.get("stargazerCount") or 0),
            "pushed_at": node.get("pushedAt", ""),
            "default_branch": ((node.get("defaultBranchRef") or {}) or {}).get("name", "main"),
        })
    raw_page = conn.get("pageInfo") if isinstance(conn.get("pageInfo"), dict) else {}
    page_info = {
        "has_next": bool(raw_page.get("hasNextPage")),
        "cursor": str(raw_page.get("endCursor") or ""),
    }
    return repos, page_info


def _github_repositories(first: int = 12, after: str = "") -> dict:
    """Fetch one token-authorized page of recently pushed repositories."""
    cred = _github_cred()
    pat = cred.get("pat") or ""
    if not pat:
        return {"connected": False, "error": "not connected"}
    limit = max(1, min(int(first or 12), 50))
    status, data = _github_graphql(
        _GH_REPOS_QUERY,
        token=pat,
        variables={"first": limit, "after": after or None},
    )
    if status != 200:
        return {"connected": False,
                "error": str(data.get("message") or data.get("errors") or f"HTTP {status}")}
    errors = data.get("errors")
    if errors:
        first_error = errors[0] if isinstance(errors, list) and errors else errors
        return {"connected": False, "error": str(
            first_error.get("message") if isinstance(first_error, dict) else first_error)}
    viewer = (data.get("data") or {}).get("viewer") or {}
    repos, page_info = _github_repo_page(viewer.get("repositories"))
    return {"connected": True, "repos": repos, "page_info": page_info}


def _gh_quartile_levels(counts: list[int]) -> list[int]:
    """Map contribution counts to the 0-4 GitHub grid levels.

    GitHub's graph buckets non-zero days by quartiles of the non-zero
    distribution (the schema exposes no `level` field on
    ContributionCalendarDay, so we reproduce the grid server-side).
    """
    nonzero = sorted(c for c in counts if c > 0)
    if not nonzero:
        return [0] * len(counts)

    def quartile(idx: int) -> float:
        pos = (len(nonzero) - 1) * idx / 3.0
        lo = math.floor(pos)
        hi = math.ceil(pos)
        if lo == hi:
            return float(nonzero[lo])
        return nonzero[lo] * (hi - pos) + nonzero[hi] * (pos - lo)

    q1, q2, q3 = quartile(1), quartile(2), quartile(3)
    out = []
    for c in counts:
        if c <= 0:
            out.append(0)
        elif c > q3:
            out.append(4)
        elif c > q2:
            out.append(3)
        elif c > q1:
            out.append(2)
        else:
            out.append(1)
    return out


def _github_activity() -> dict:
    """Contribution calendar plus the first page of recently pushed repos."""
    cred = _github_cred()
    pat = cred.get("pat") or ""
    if not pat:
        return {"connected": False, "error": "not connected"}
    status, data = _github_graphql(_GH_ACTIVITY_QUERY, token=pat)
    if status != 200:
        return {"connected": False,
                "error": str(data.get("message") or data.get("errors") or f"HTTP {status}")}
    errors = data.get("errors")
    if errors:
        first = errors[0] if isinstance(errors, list) and errors else errors
        return {"connected": False, "error": str(first.get("message") if isinstance(first, dict) else first)}
    viewer = (data.get("data") or {}).get("viewer") or {}
    cal = ((viewer.get("contributionsCollection") or {}).get("contributionCalendar")) or {}
    weeks = []
    raw_days: list[dict] = []
    for w in cal.get("weeks", []) or []:
        if not isinstance(w, dict):
            continue
        days = []
        for d in w.get("contributionDays", []) or []:
            if not isinstance(d, dict):
                continue
            count = int(d.get("contributionCount") or 0)
            raw_days.append({"date": d.get("date", ""), "count": count})
            days.append({"date": d.get("date", ""), "count": count})
        weeks.append(days)
    # ContributionCalendarDay has no `level` field in the GraphQL schema, so
    # derive the grid intensity the same way GitHub's own graph does.
    flat = [d["count"] for d in raw_days]
    levels = _gh_quartile_levels(flat)
    li = 0
    for w in weeks:
        for d in w:
            d["level"] = levels[li]
            li += 1
    repos, page_info = _github_repo_page(viewer.get("repositories"))
    return {
        "connected": True,
        "login": viewer.get("login") or cred.get("login", ""),
        "avatar_url": cred.get("avatar_url", ""),
        "total_contributions": int(cal.get("totalContributions") or 0),
        "weeks": weeks,
        "repos": repos,
        "repos_page": page_info,
    }


def _github_valid_branch_name(name: str) -> str | None:
    name = (name or "").strip()
    if not _GITHUB_BRANCH_RE.fullmatch(name):
        return "invalid branch name — use letters, digits, dots, underscores, slashes and hyphens (max 256 chars)"
    if _GITHUB_BRANCH_BAD.search(name):
        return "invalid branch name — no `..`, no `@{`, no leading/trailing slash or dash, no `.git`/`.lock` segments"
    return None


def _github_worktree_metadata(raw: object) -> dict | None:
    """Validate the private context attached to a GitHub branch session."""
    if not isinstance(raw, dict):
        return None
    owner = str(raw.get("owner") or "").strip()
    repo = str(raw.get("repo") or "").strip()
    branch = str(raw.get("branch") or "").strip()
    path = normalize_path(str(raw.get("path") or ""))
    if (not _GITHUB_OWNER_RE.fullmatch(owner)
            or not _GITHUB_REPO_RE.fullmatch(repo)
            or _github_valid_branch_name(branch)
            or not path
            or not _workspace_root_for(path)
            or not (Path(path) / ".git").exists()):
        return None
    return {"owner": owner, "repo": repo, "branch": branch, "path": path}


def _github_worktree_prompt(chat: dict | None) -> str:
    """Render a branch session's private repo context for the model."""
    worktree = _github_worktree_metadata((chat or {}).get("github_worktree"))
    if not worktree:
        return ""
    return (
        "active GitHub worktree for this chat:\n"
        f"- repository: {worktree['owner']}/{worktree['repo']}\n"
        f"- expected branch: {worktree['branch']}\n"
        f"- local path: {worktree['path']}\n"
        "Treat this as the user's current project. For code work, inspect this path first "
        "and keep changes inside it unless the user explicitly names another project. "
        "Before branch-sensitive work, verify the branch with git_status."
    )


def _project_workspace_metadata(raw: object) -> dict | None:
    """Validate the private context attached to a project chat.

    New-project sessions carry git metadata (branch, publication). A folder
    picked from the composer is any directory inside a configured workspace
    root, so only path membership and a matching label are required."""
    if not isinstance(raw, dict):
        return None
    path = normalize_path(str(raw.get("path") or ""))
    if not path or not _workspace_root_for(path) or not Path(path).is_dir():
        return None
    name = str(raw.get("name") or "").strip() or Path(path).name
    branch = str(raw.get("branch") or "").strip()
    owner = str(raw.get("owner") or "").strip()
    if (not name
            or len(name) > 120
            or re.search(r"[\r\n\x00]", name)
            or Path(path).name.lower() != name.lower()
            or (branch and _github_valid_branch_name(branch))
            or (owner and not _GITHUB_OWNER_RE.fullmatch(owner))):
        return None
    return {
        "name": name,
        "path": path,
        "branch": branch,
        "brief": str(raw.get("brief") or "").strip()[:4000],
        "published": bool(raw.get("published")),
        "owner": owner,
    }


def _project_workspace_prompt(chat: dict | None) -> str:
    """Render a new project's private workspace context for the model."""
    project = _project_workspace_metadata((chat or {}).get("project_workspace"))
    if not project:
        return ""
    lines = [
        "active project for this chat:",
        f"- project: {project['name']}",
        f"- local path: {project['path']}",
    ]
    if project["branch"]:
        lines.append(f"- expected branch: {project['branch']}")
    if project["owner"] or (Path(project["path"]) / ".git").exists():
        lines.append(f"- GitHub publication: {'published' if project['published'] else 'local only'}")
    if project["brief"]:
        lines.append(f"- initial brief: {project['brief']}")
    lines.append(
        "Treat this as the user's current project. Inspect this path first and keep "
        "project files inside it unless the user explicitly says otherwise."
    )
    return "\n".join(lines)


def _project_workspace_root(requested: str = "") -> str | None:
    """Resolve a selected workspace root without accepting arbitrary subfolders."""
    roots = [normalize_path(str(folder)) for folder in get_workspace().get("folders", []) or []
             if str(folder or "").strip()]
    if not roots:
        return None
    if not requested:
        return roots[0]
    wanted = normalize_path(requested)
    return next((root for root in roots if os.path.normcase(root) == os.path.normcase(wanted)), None)


def _github_create_project(name: str, brief: str = "", workspace_root: str = "",
                           publish: bool = False, private: bool = True) -> dict:
    """Create a safe local git project and optionally publish an empty GitHub repo."""
    name = (name or "").strip()
    if not _GITHUB_REPO_RE.fullmatch(name) or name in {".", ".."} or name.endswith("."):
        return {"error": "invalid project name; use letters, digits, dots, underscores and hyphens (max 100 characters)"}
    if os.name == "nt" and name.split(".", 1)[0].upper() in {
        "CON", "PRN", "AUX", "NUL", "COM1", "COM2", "COM3", "COM4", "COM5",
        "COM6", "COM7", "COM8", "COM9", "LPT1", "LPT2", "LPT3", "LPT4",
        "LPT5", "LPT6", "LPT7", "LPT8", "LPT9",
    }:
        return {"error": "that project name is reserved by Windows"}
    root = _project_workspace_root(workspace_root)
    if not root:
        return {"error": "choose one of the configured workspace folders"}
    root_path = Path(root)
    destination = root_path / name
    try:
        resolved_destination = destination.resolve()
        if os.path.normcase(str(resolved_destination.parent)) != os.path.normcase(str(root_path.resolve())):
            return {"error": "project path escapes the selected workspace folder"}
        if destination.exists():
            return {"error": f"a folder named `{name}` already exists in that workspace"}
        destination.mkdir(parents=False, exist_ok=False)
    except Exception as exc:
        return {"error": f"could not create the project folder: {exc}"}

    initialized = _run_git(str(destination), ["init", "-b", "main"], timeout=60)
    if not initialized.get("ok"):
        initialized = _run_git(str(destination), ["init"], timeout=60)
        if initialized.get("ok"):
            initialized = _run_git(
                str(destination), ["symbolic-ref", "HEAD", "refs/heads/main"], timeout=30)
    if not initialized.get("ok"):
        try:
            shutil.rmtree(destination)
        except Exception:
            pass
        detail = str(initialized.get("stderr") or initialized.get("error") or "unknown error")[:500]
        return {"error": f"git could not initialize the project: {detail}"}

    result = {
        "ok": True,
        "name": name,
        "path": str(destination.resolve()),
        "branch": "main",
        "published": False,
        "remote_ready": False,
    }
    if not publish:
        return result

    pat = _github_cred().get("pat") or ""
    if not pat:
        result["publish_error"] = "GitHub is not connected. The local project was still created."
        return result
    status, remote, _headers = _github_rest_h("POST", "/user/repos", {
        "name": name,
        "description": (brief or "").strip()[:350],
        "private": bool(private),
        "auto_init": False,
    }, token=pat)
    if status != 201:
        message = str(remote.get("message") or remote.get("errors") or f"HTTP {status}")
        if status == 403:
            message = ("GitHub refused repository creation. Give the fine-grained token "
                       "Administration: Read and write, then retry publishing. The local project was still created.")
        else:
            message = f"GitHub repository creation failed: {message}. The local project was still created."
        result["publish_error"] = message
        return result

    owner = str(((remote.get("owner") or {}) or {}).get("login") or _github_cred().get("login") or "")
    clone_url = str(remote.get("clone_url") or "")
    result.update({
        "published": True,
        "owner": owner,
        "repo": str(remote.get("name") or name),
        "html_url": str(remote.get("html_url") or ""),
    })
    if not clone_url:
        result["publish_error"] = "GitHub created the repository but returned no clone URL. Add the remote manually."
        return result
    remote_result = _run_git(str(destination), ["remote", "add", "origin", clone_url], timeout=30)
    if not remote_result.get("ok"):
        detail = str(remote_result.get("stderr") or remote_result.get("error") or "unknown error")[:300]
        result["publish_error"] = f"GitHub created the repository, but wiring the local remote failed: {detail}"
        return result
    result["remote_ready"] = True
    return result


def _github_find_workspace_repo(repo: str) -> str | None:
    """Locate a repo directory (with .git) inside the configured workspace folders."""
    wanted = repo.lower()
    for folder in get_workspace().get("folders", []) or []:
        try:
            for child in Path(folder).iterdir():
                if (child.is_dir() and child.name.lower() == wanted
                        and (child / ".git").exists()):
                    return str(child.resolve())
        except Exception:
            continue
    return None


def _github_branch_flow(owner: str, repo: str, branch: str) -> dict:
    """Create the remote branch, then clone/fetch and check it out in the workspace."""
    cred = _github_cred()
    pat = cred.get("pat") or ""
    if not pat:
        return {"error": "GitHub is not connected — add a personal access token in Settings → GitHub integration."}
    # 1. repo metadata -> default branch name (also capture the permission
    #    level GitHub reports the token actually has on this repo)
    status, data, headers = _github_rest_h("GET", f"/repos/{owner}/{repo}")
    if status != 200:
        msg = str(data.get("message") or data.get("errors") or f"HTTP {status}")
        return {"error": f"could not read repo {owner}/{repo}: {msg}"}
    default_branch = str(data.get("default_branch") or "main").strip()
    accepted_perms = (headers.get("x-accepted-github-permissions") or "") if headers else ""
    # 2. SHA of the default branch tip
    status, ref = _github_rest(
        "GET", f"/repos/{owner}/{repo}/git/ref/heads/{urllib.parse.quote(default_branch, safe='/')}")
    if status != 200:
        return {"error": f"could not read the default branch ref: "
                         f"{str(ref.get('message') or f'HTTP {status}')}"}
    sha = str(((ref.get("object") or {}) or {}).get("sha") or "")
    if not sha:
        return {"error": "the default branch ref returned no sha"}
    # 3. create the new ref (422 "already exists" is treated as success)
    status, created = _github_rest("POST", f"/repos/{owner}/{repo}/git/refs",
                                   {"ref": f"refs/heads/{branch}", "sha": sha})
    if status not in (200, 201):
        msg = str(created.get("message") or f"HTTP {status}")
        if "already exists" in msg.lower():
            pass
        elif status == 403:
            low = msg.lower()
            if "authoriz" in low and "resource owner" in low:
                return {"error": (f"GitHub hasn't authorized this token for {owner}/{repo} — "
                                  f"if the repo belongs to an organization, approve the "
                                  f"fine-grained PAT under its settings, then retry.")}
            have = accepted_perms or "unknown"
            return {"error": (f"GitHub refused branch creation — the personal access token "
                              f"carries `{have}` on {owner}/{repo}, but creating a branch "
                              f"needs `Contents: Read and write` (Metadata: Read is "
                              f"automatic). Edit the token's Repository permissions in "
                              f"GitHub and retry — no new token required.")}
        else:
            return {"error": f"could not create branch `{branch}`: {msg}"}
    # 4. local checkout — repos are only ever cloned into the Accuretta workspace
    repo_dir = _github_find_workspace_repo(repo)
    cloned = False
    if not repo_dir:
        folders = [f for f in get_workspace().get("folders", []) or [] if str(f or "").strip()]
        if not folders:
            return {"error": "no workspace folder configured — cannot clone the repo locally"}
        dest = Path(folders[0]) / repo
        if dest.exists() and any(dest.iterdir()):
            return {"error": f"{owner}/{repo} isn't cloned in the workspace, but a folder "
                             f"named `{repo}` already exists there and isn't a git repo"}
        dest.parent.mkdir(parents=True, exist_ok=True)
        clone_url = f"https://github.com/{owner}/{repo}.git"
        argv = ["clone"]
        if pat:
            auth = _b64.b64encode(f"x-access-token:{pat}".encode("utf-8")).decode("ascii")
            argv += ["-c", f"http.extraHeader=Authorization: Basic {auth}"]
        argv += ["--", clone_url, str(dest)]
        result = _run_git(str(dest.parent), argv, timeout=900)
        if not result.get("ok"):
            return {"error": f"clone into the workspace failed: "
                             f"{str(result.get('stderr') or result.get('stdout') or result.get('error') or 'unknown')[:500]}"}
        repo_dir = str(dest.resolve())
        cloned = True
    # 5. fetch (brings in the new branch) and switch to it
    fetch = _run_git(repo_dir, ["fetch", "origin", "--prune"], timeout=300)
    if not fetch.get("ok"):
        return {"error": f"git fetch failed: "
                         f"{str(fetch.get('stderr') or fetch.get('error') or 'unknown')[:500]}"}
    switch = _run_git(repo_dir, ["switch", "-c", branch, f"origin/{branch}"], timeout=120)
    if not switch.get("ok"):
        switch = _run_git(repo_dir, ["switch", "-c", branch], timeout=120)
    if not switch.get("ok"):
        return {"error": f"git switch failed: "
                         f"{str(switch.get('stderr') or switch.get('error') or 'unknown')[:500]}"}
    return {"ok": True, "owner": owner, "repo": repo, "branch": branch,
            "default_branch": default_branch, "sha": sha,
            "repo_dir": repo_dir, "cloned": cloned}


def _chat_note(chat_id: str, text: str) -> dict:
    """Append a UI-only note to a chat's persisted history (never replayed to the model)."""
    if not chat_id or not text:
        return {"error": "chat_id and text are required"}
    chats = get_chats()
    chat = (chats.get("chats", {}) or {}).get(chat_id)
    if not chat:
        return {"error": "no such chat"}
    chat.setdefault("messages", [])
    chat["messages"].append({
        "role": "system", "content": str(text)[:2000],
        "t": int(time.time()), "_note": True,
    })
    if len(chat["messages"]) > CHAT_HISTORY_MAX:
        chat["messages"] = chat["messages"][-CHAT_HISTORY_MAX:]
    save_json(CHATS_FILE, chats)
    broadcast_event({"type": "chat:note", "chat_id": chat_id, "content": str(text)[:2000]})
    return {"ok": True}


