# Per-tool result caps for the model context. Unlisted tools use
# _tool_result_cap() (16K for analysis tools, 4K otherwise). network_snapshot
# routinely returns ~20 KB on a busy host and is useless chopped mid-JSON;
# scan_apk with deep:true on a real APK lands around 30-40 KB.
_TOOL_RESULT_CAPS = {
    "security_coverage": 24000,
    "compare_evidence": 16000,
    "review_finding": 12000,
    "record_finding": 12000,
    # read_file pages its own 20KB chunks with an offset hint. This cap must sit
    # above the serialized chunk or compress_tool_result elides it a second time,
    # mangling the chunk and the continuation hint.
    "read_file": 32000,

    # Accessibility snapshots are structured UI trees. Four kilobytes leaves
    # only a handful of controls and makes blind navigation useless; 24K keeps
    # a practical window view while remaining tolerable for local contexts.
    "desktop_snapshot": 24000,
    "desktop_invoke": 16000,
    "desktop_set_value": 16000,
    "desktop_scroll": 16000,

    "scan_secrets": 48000,
    "parse_evtx": 48000,
    "analyze_pcap": 48000,
    "check_deps": 24000,
    "parse_event_logs": 32000,   # up to 500 log entries, each with a ~900-char message
    "persistence_hunt": 24000,   # full inventory can be a few hundred entries

    "network_snapshot": 32000,
    # Native-vision descriptions (mmproj + selected GGUF): the model's own
    # detailed read of an image/page render. 12K keeps a full design read.
    "web_view_image": 12000,
    "web_render": 12000,
    "web_watch_video": 12000,
    # recon_subdomains can return a few hundred CT-log subdomains; the rest
    # are compact JSON. Give the suite room so the report isn't chopped.
    "recon_subdomains": 32000,
    "recon_dns": 16000,
    "recon_port_scan": 16000,
    "recon_content_discovery": 24000,
    "recon_check_exposure": 16000,
    "recon_subdomain_takeover": 24000,
    "recon_cve_match": 24000,
    "recon_injection_probe": 16000,
    "recon_open_services": 16000,
    # The full bundle catalog behind list_more_tools is big; a blind
    # "_truncated" envelope makes models re-emit the call with the same args.
    "list_more_tools": 48000,
    # Large exploit responses are summarized (status/headers/preview) with the
    # full body in the evidence receipt; small responses keep their body. This
    # cap covers either shape and the receipt summary.
    "http_request": 16000,
    "rt_browser": 32000,
    # Interactive sessions self-cap their output in read_model(); these are the
    # outer safety nets for the serialized envelope.
    "session_start": 16000,
    "session_send": 16000,
    "session_read": 16000,
    "sql_injection": 16000,  # dumped rows can be large
    "fuzz": 16000,           # many per-value response summaries
    "batch_probe": 16000,    # hits across many endpoints
    "scan_js_secrets": 48000,  # exact values, including complete private-key blocks
    "tcp_send": 32000,         # raw service/bot output can be verbose
    "scan_apk": 48000,
    "decompile_apk": 24000,
    # ghidra_analyze: imports + exports + 200 strings + a decompiled function fits
    # in 32K on real .so files; 40K leaves room for a chunky decompile.
    "ghidra_analyze": 40000,
    # binary_inspect: header + sections + imports reach 20-30 KB on a dll with
    # hundreds of imports; 32K shows the full import table.
    "binary_inspect": 32000,
    # yara_scan: matches across a directory can balloon. 32K is enough room
    # for a full report on ~50 hit files without trampling the rest of context.
    "yara_scan": 32000,
    # git_diff with a multi-file refactor easily clears 50K. The model needs
    # the whole patch to write an accurate commit message; truncation here
    # produces fabricated change descriptions.
    "git_diff": 64000,
    "git_show": 48000,
    "git_log": 24000,
    # Skill bodies are user-curated procedures; the cap keeps a loaded skill
    # from crowding out the conversation (tool_load_skill also refuses over-cap
    # files outright, so compress never has to chop a procedure mid-step).
    "load_skill": SKILL_BODY_CAP_CHARS,
}

# Aging for replayed tool results. The caps above apply once, at append time;
# after that a 64K git_diff would be replayed on every request. At request
# assembly (_sanitize_messages_for_openai) any tool message older than the last
# _TOOL_RESULT_KEEP_RECENT messages is replaced with a compact stub naming the
# tool. The stored chat keeps the full content (the fold and truncate_messages
# still see it). Position-from-end is the only input, so the stub text is
# byte-identical every turn (prompt-cache friendly), and the model can always
# re-call the tool.
_TOOL_RESULT_KEEP_RECENT = 24


def _tool_result_cap(name: str) -> int:
    if name in _TOOL_RESULT_CAPS:
        return _TOOL_RESULT_CAPS[name]
    # Playwright aria snapshots run big even compressed, and chopping them
    # mid-tree sends models into a re-snapshot loop. 24K keeps the tree usable on
    # all but the largest pages.
    if name.startswith("mcp_playwright_"):
        return 24000
    return 16000 if name in _ANALYSIS_TOOL_NAMES else 4000


# Fields known to carry the bulk of a tool's output. They are elided in place
# (head + marker + tail) before serializing, so the JSON stays valid and the
# trailing diagnostics (errors are usually at the bottom of stdout) survive.
_BULK_TOOL_FIELDS = ("stdout", "stderr", "content", "text", "output", "html", "body")


def _elide_text(s: str, cap: int) -> str:
    """Head/tail line-aware elision. Keep ~half the budget on each end with
    a one-line summary marker between them. cap is in characters (consistent
    with the rest of the tool-result pipeline). Returns s unchanged when
    s already fits."""
    if not isinstance(s, str) or len(s) <= cap:
        return s
    lines = s.split("\n")
    # Single-blob with no newlines (e.g. a giant base64 PNG): char-level
    # slice is the only sane fallback.
    if len(lines) <= 4:
        half = max(1, (cap - 80) // 2)
        return s[:half] + f"\n… [{len(s) - cap} chars elided] …\n" + s[-half:]
    # Line-aware elision: greedily fill head and tail keeping them roughly
    # balanced by char count. Tokens scale ~linearly with chars for typical
    # text, so this also balances by token cost.
    target_each = max(256, (cap - 80) // 2)
    head_lines: list[str] = []
    tail_lines: list[str] = []
    head_chars = 0
    tail_chars = 0
    i = 0
    j = len(lines) - 1
    while i <= j and (head_chars < target_each or tail_chars < target_each):
        if head_chars <= tail_chars:
            head_lines.append(lines[i])
            head_chars += len(lines[i]) + 1
            i += 1
        else:
            tail_lines.append(lines[j])
            tail_chars += len(lines[j]) + 1
            j -= 1
        if i > j:
            break
    omitted = j - i + 1
    if omitted <= 0:
        return s  # ate the whole thing, no elision needed
    omitted_chars = sum(len(lines[k]) + 1 for k in range(i, j + 1))
    marker = f"… [{omitted} of {len(lines)} lines elided · {omitted_chars} chars] …"
    return "\n".join(head_lines) + "\n" + marker + "\n" + "\n".join(reversed(tail_lines))


def _truncation_envelope(result: Any, cap: int, original_chars: int) -> str:
    """Last-resort fallback. Returns a tiny, *valid* JSON object describing
    that the result was too large even after compression. Never produces
    malformed JSON — the model treats this as a structured "I tried, it
    didn't fit" message instead of walking off a cliff into truncated bytes."""
    keys = list(result.keys()) if isinstance(result, dict) else None
    return json.dumps({
        "_truncated": True,
        **({"research_source_id": result["research_source_id"],
            "research_recovery": "Read stored source text using research_notebook(source_id=research_source_id, offset=0); follow next_offset."}
           if isinstance(result, dict) and result.get("research_source_id") else {}),
        **({"evidence_receipt": {"id": result["evidence_receipt"]["id"]},
            "evidence_recovery": "Read the recorded result with security_coverage(evidence_id=..., offset=0); do not repeat network requests to recover output."}
           if isinstance(result, dict) and isinstance(result.get("evidence_receipt"), dict) and result["evidence_receipt"].get("id") else {}),
        "_note": (
            f"tool result exceeded {cap} chars even after head/tail elision "
            f"(original ~{original_chars} chars). "
            f"Re-run the tool with a tighter scope or a smaller range."
        ),
        "keys_present": keys,
    }, ensure_ascii=False)


_PLAIN_RESULT_SHOWN = frozenset({
    "ok", "exit", "exit_code", "stdout", "stderr", "executed", "execution_target", "cwd",
    "content", "path", "offset", "lines_returned", "total_lines", "size", "truncated",
    "next_offset", "hint", "matches", "files", "pattern", "root", "match_count", "files_scanned",
    "files_skipped_binary", "files_skipped_size",
})


def _plain_tool_text(name: str, result: dict) -> str | None:
    """Plain-text view of a successful file read, search or shell result.

    As JSON, every quote, backslash and newline in code or command output is
    escaped (about 14% more characters in real sessions), and the model has to
    undo that before it copies text into edit_file's old_text. Other fields of
    the result follow the header as "key: value" lines."""
    if result.get("error"):
        return None
    if name == "read_file" and isinstance(result.get("content"), str) and "lines_returned" in result:
        first = int(result.get("offset") or 0) + 1
        last = first + int(result.get("lines_returned") or 0) - 1
        head = f"[{result.get('path')} | lines {first}-{last} of {result.get('total_lines')}"
        if result.get("truncated"):
            head += f" | more: read_file offset={result.get('next_offset')}"
        body = result["content"]
    elif name == "grep_files" and isinstance(result.get("matches"), list):
        head = (f"[grep {result.get('pattern')!r} in {result.get('root')} | "
                f"{result.get('match_count', len(result['matches']))} matches, "
                f"{result.get('files_scanned', '?')} files scanned"
                + (" | truncated" if result.get("truncated") else ""))
        lines: list[str] = []
        if isinstance(result.get("files"), list):
            lines = [f"{f.get('path')} ({f.get('count')})" for f in result["files"] if isinstance(f, dict)]
        current = None
        for m in result["matches"]:
            if not isinstance(m, dict):
                continue
            if m.get("path") != current:
                current = m.get("path")
                lines.append(str(current))
            line_no = int(m.get("line") or 0)
            before = m.get("before") or []
            lines += [f"  {line_no - len(before) + k}- {text}" for k, text in enumerate(before)]
            lines.append(f"  {line_no}: {m.get('text')}")
            lines += [f"  {line_no + 1 + k}- {text}" for k, text in enumerate(m.get("after") or [])]
        body = "\n".join(lines) if lines else "(no matches)"
    elif name in ("run_powershell", "run_python") and isinstance(result.get("stdout"), str):
        head = f"[exit {result.get('exit_code')}" + (f" | cwd {result['cwd']}" if result.get("cwd") else "")
        body = result["stdout"]
        if result.get("stderr"):
            body += ("" if not body or body.endswith("\n") else "\n") + "[stderr]\n" + result["stderr"]
    else:
        return None
    extras = []
    for key, value in result.items():
        if key in _PLAIN_RESULT_SHOWN or value in (None, "", [], {}):
            continue
        shown = value if isinstance(value, (str, int, float, bool)) else json.dumps(
            value, ensure_ascii=False, default=str)
        extras.append(f"{key}: {str(shown)[:600]}")
    return head + "]\n" + "".join(e + "\n" for e in extras) + body


def compress_tool_result(name: str, result: Any, cap: int) -> str:
    """Serialize a tool result as JSON for the model, applying line-aware
    head/tail elision to known bulk fields BEFORE serializing. Errors are
    never elided (they're always small and always critical). Iteratively
    tightens the per-field budget if JSON escaping overhead pushes the
    result over cap; falls back to a minimal truncation envelope rather
    than producing malformed JSON."""
    # Non-dict results (lists, scalars). For lists we elide the JSON-string
    # form; for scalars we just serialize. Both stay valid JSON because we
    # only ever return either the full serialization or the safe envelope.
    if not isinstance(result, dict):
        s = json.dumps(result, ensure_ascii=False, default=str)
        if len(s) <= cap:
            return s
        # Try to keep a head sample of the list as a separate JSON; otherwise
        # fall through to the envelope.
        if isinstance(result, list) and len(result) > 4:
            for keep in (200, 100, 50, 20, 10, 5):
                if keep >= len(result):
                    continue
                sample = result[:keep]
                sampled = {
                    "_truncated": True,
                    "_note": f"showing first {keep} of {len(result)} items",
                    "items": sample,
                }
                ss = json.dumps(sampled, ensure_ascii=False, default=str)
                if len(ss) <= cap:
                    return ss
        return _truncation_envelope(result, cap, len(s))

    # Errors: never compress, always pass through verbatim. They're critical
    # and almost always small. If a tool somehow returns an error PLUS a
    # huge stdout (rare), strip the bulk fields rather than chopping the
    # error message itself.
    if isinstance(result.get("error"), str) and len(result["error"]) < cap // 2:
        s = json.dumps(result, ensure_ascii=False, default=str)
        if len(s) <= cap:
            return s
        slim = {k: v for k, v in result.items() if k not in _BULK_TOOL_FIELDS}
        slim["_note"] = "bulk fields stripped — error preserved verbatim"
        ss = json.dumps(slim, ensure_ascii=False, default=str)
        if len(ss) <= cap:
            return ss
        return _truncation_envelope(result, cap, len(s))

    plain = _plain_tool_text(name, result)
    if plain is not None:
        return _elide_text(plain, cap)

    # HTTP results are the biggest single source of context bloat: one page can
    # carry a megabyte of boilerplate. Once the full response is in an evidence
    # receipt, show status/metadata/headers plus a body preview instead of raw
    # HTML/JSON. The receipt reader pages through the untouched body later.
    if name == "http_request":
        result = _http_model_view(result)

    s_full = json.dumps(result, ensure_ascii=False, default=str)
    if len(s_full) <= cap:
        return s_full

    # In-place compression of bulk fields. The budget is split across the fields
    # present so {stdout: 100KB, stderr: 50KB} shrink proportionally, and is
    # tightened iteratively because JSON escaping inflates the serialized size by
    # a few percent.
    bulk_present = [
        k for k in _BULK_TOOL_FIELDS
        if isinstance(result.get(k), str) and len(result[k]) > 200
    ]
    if bulk_present:
        scratch = dict(result)
        for k in bulk_present:
            scratch[k] = ""
        overhead = len(json.dumps(scratch, ensure_ascii=False, default=str))
        # Start with the full available budget per field, then halve until
        # the serialized result fits or the per-field budget would be too
        # small to be useful.
        base_budget = max(256, (cap - overhead) // len(bulk_present))
        for attempt in range(6):
            per_field = max(256, base_budget >> attempt)
            compressed = dict(result)
            for k in bulk_present:
                compressed[k] = _elide_text(result[k], per_field)
            s = json.dumps(compressed, ensure_ascii=False, default=str)
            if len(s) <= cap:
                return s
            if per_field <= 256:
                break  # can't tighten further usefully

    # Large list-valued fields (tool catalogs, folder listings, match sets):
    # sample the head of each so the model still sees real entries and a count and
    # knows to re-call with narrower args. The blind envelope below hides
    # everything, which makes models re-emit the same call in a loop.
    big_list_fields = sorted(
        k for k, v in result.items()
        if isinstance(v, list) and len(v) > 5 and k not in _BULK_TOOL_FIELDS)
    if big_list_fields:
        for sample_n in (200, 100, 50, 20, 10, 5):
            sampled = dict(result)
            for k in big_list_fields:
                items = result[k]
                if len(items) > sample_n:
                    sampled[k] = items[:sample_n]
            s = json.dumps(sampled, ensure_ascii=False, default=str)
            if len(s) <= cap:
                sampled["_truncated"] = True
                bodies = "; ".join(
                    f"{k}: showing first {sample_n} of {len(result[k])} items"
                    for k in big_list_fields if len(result[k]) > sample_n)
                sampled["_note"] = (bodies +
                                    " — re-call the tool with narrower/filtered args "
                                    "to see the rest")
                return json.dumps(sampled, ensure_ascii=False, default=str)

    # Final fallback: minimal envelope. Always valid JSON.
    return _truncation_envelope(result, cap, len(s_full))


# Red-team tools are gated behind `red_team_enabled` so a normal coding turn
# doesn't pay their schema tokens. This is the heavier active-testing set: held
# out of Target Recon and exposed from the start of an explicitly authorized
# Red Team assessment (see _rt_incl_exploit_for / _active_tools). Every name
# here must stay a real breach tool; the recon set below is always on when
# red_team_enabled.
