def _base_core_tool_names(chat_id: str = "") -> set[str]:
    """Choose a schema core that leaves actual room for the conversation.

    Model-agnostic: lean balanced core is the default at any ctx (static cost
    stays <20% even on 8k windows); full legacy core is opt-in via
    tool_verbosity=full. IDE mode gets its own smaller core. Tiny/small tiers
    still guard very small ctx windows regardless of verbosity.
    """
    try:
        settings = get_settings()
    except Exception:
        settings = {}
    try:
        ctx = _llama_props_ctx() or int(settings.get("num_ctx") or 32768)
    except Exception:
        ctx = 32768
    if ctx <= 8192:
        return _TINY_CTX_CORE_TOOL_NAMES
    if ctx <= 16384:
        return _SMALL_CTX_CORE_TOOL_NAMES
    if (settings.get("tool_verbosity") or "lean") == "full":
        return _CORE_TOOL_NAMES
    # Mode-aware: IDE turns never need sessions/host/RT/analysis schemas.
    try:
        mode = ""
        if chat_id:
            chat = (get_chats().get("chats", {}) or {}).get(chat_id)
            if isinstance(chat, dict) and chat.get("last_mode"):
                mode = _normalize_composer_mode(chat.get("last_mode"))
        if not mode:
            mode = _normalize_composer_mode(settings.get("composer_mode") or "agent")
    except Exception:
        mode = "agent"
    if mode == "ide":
        return _IDE_CORE_TOOL_NAMES
    return _BALANCED_CORE_TOOL_NAMES


# ---- skills: user-curated markdown procedures -------------------------------
# A skill is a plain .md file in skills/ with a `---` frontmatter block:
#   ---
#   name: rt-report-loop
#   description: Produce engagement reports for red-team missions...
#   budget: 2400          # token-ish estimate shown in the picker (informational)
#   ---
#   <procedure body>
# One active slot per chat; loading replaces the previous skill. The body
# reaches the model two ways: a model-side load_skill returns it as a tool
# result, and a user pick via # injects it into the recency tail every turn
# (run_chat_turn + _active_skill_section).

_FRONTMATTER_RE = re.compile(r"^---[ \t]*\r?\n(.*?)\r?\n---[ \t]*\r?\n", re.DOTALL)
_SKILL_NAME_RE = re.compile(r"^[A-Za-z0-9._-]{1,80}$")
_SKILLS_CACHE: dict[str, tuple[float, dict[str, dict]]] = {}


def _parse_skill_frontmatter(text: str) -> dict:
    m = _FRONTMATTER_RE.match(text)
    if not m:
        return {}
    out: dict[str, object] = {}
    for raw in m.group(1).splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or ":" not in line:
            continue
        k, v = line.split(":", 1)
        value = v.strip()
        if value.startswith('"') and value.endswith('"'):
            try:
                value = json.loads(value)
            except (TypeError, ValueError, json.JSONDecodeError):
                value = value[1:-1]
        elif value.startswith("'") and value.endswith("'"):
            value = value[1:-1]
        out[k.strip().lower()] = value
    return out


def _scan_skills() -> dict[str, dict]:
    """name -> {name, description, budget, path, mtime, body_chars}.
    Cached on the directory's newest mtime (like .accurettaignore rules). A
    missing skills/ dir is never cached — it is rechecked so the first file
    the user drops in is picked up immediately."""
    directories = [ROOT / "builtin_skills", SKILLS_DIR]
    paths = [p for directory in directories if directory.is_dir() for p in sorted(directory.glob("*.md"))]
    try:
        mtime = tuple((str(p), p.stat().st_mtime_ns, p.stat().st_size) for p in paths)
    except Exception:
        mtime = 0.0
    cached = _SKILLS_CACHE.get(str(SKILLS_DIR))
    if cached and cached[0] == mtime:
        return cached[1]
    found: dict[str, dict] = {}
    for p in paths:
        try:
            text = p.read_text(encoding="utf-8", errors="replace")
            size = text.count("\n") + 1
            if len(text) > SKILL_MAX_BODY_CHARS:
                continue
        except Exception:
            continue
        m = _FRONTMATTER_RE.match(text)
        body = text[m.end():].strip() if m else text.strip()
        if not body:
            continue
        fm = _parse_skill_frontmatter(text)
        name = str(fm.get("name") or p.stem).strip()
        if not name or not _SKILL_NAME_RE.fullmatch(name):
            continue
        try:
            budget = int(str(fm.get("budget") or "0"))
        except (TypeError, ValueError):
            budget = 0
        found[name] = {
            "name": name,
            "description": str(fm.get("description") or "").strip(),
            "budget": max(0, budget),
            "path": str(p),
            "mtime": p.stat().st_mtime,
            "body_chars": len(body),
            "lines": size,
        }
    _SKILLS_CACHE[str(SKILLS_DIR)] = (mtime, found)
    return found


def _skills_catalog() -> list[dict]:
    return [
        {"name": s["name"], "description": s["description"][:220],
         "budget": s["budget"], "body_chars": s["body_chars"], "lines": s["lines"]}
        for s in sorted(_scan_skills().values(), key=lambda x: x["name"].lower())
    ]


def _read_skill_body(entry: dict) -> str | None:
    try:
        text = Path(entry["path"]).read_text(encoding="utf-8", errors="replace")
    except Exception:
        return None
    m = _FRONTMATTER_RE.match(text)
    return (text[m.end():].strip() if m else text.strip()) or None


def _skill_slug(value: str) -> str:
    """Turn a user-facing title into a safe skill name and filename stem."""
    raw = re.sub(r"(?i)\.(?:md|markdown|mdown|mkd)$", "", str(value or "").strip())
    slug = re.sub(r"[^A-Za-z0-9._-]+", "-", raw)
    slug = re.sub(r"[-_.]{2,}", "-", slug).strip("-._").lower()
    return slug[:80].rstrip("-._")


def _skill_description(value: str, body: str, name: str) -> str:
    description = " ".join(str(value or "").split())
    if not description:
        for raw in body.splitlines():
            line = re.sub(r"^[#>*+\-\d.()\s]+", "", raw).strip()
            if line:
                description = f"Use when the user asks to follow this procedure: {line}"
                break
    return (description or f"Use when the user asks to follow the {name} procedure.")[:220]


def _skill_token_budget(body: str) -> tuple[int, str]:
    """Count the loaded body with llama.cpp's tokenizer, with the normal fallback."""
    exact = _llama_tokenize(body)
    if exact is not None:
        return max(1, int(exact)), "model_tokenizer"
    return max(1, int(math.ceil(_approx_tokens(body)))), "conservative_estimate"


def tool_save_skill(args: dict) -> dict:
    """Create an Accuretta skill from pasted Markdown or a workspace .md file."""
    supplied = args.get("content")
    raw_source_path = str(args.get("source_path") or "").strip()
    source_path = normalize_path(raw_source_path) if raw_source_path else ""
    if supplied is not None and source_path:
        return {"error": "provide either content or source_path, not both"}
    if supplied is None and not source_path:
        return {"error": "provide pasted Markdown in content or a .md source_path"}

    source_name = ""
    if source_path:
        source = Path(source_path)
        if source.suffix.lower() not in {".md", ".markdown", ".mdown", ".mkd"}:
            return {"error": "source_path must be a Markdown file"}
        if not is_in_workspace(source_path):
            return {"error": "source_path is outside the configured workspace"}
        if not source.is_file():
            return {"error": f"Markdown source not found: {source_path}"}
        try:
            text = source.read_text(encoding="utf-8", errors="replace")
        except Exception as exc:
            return {"error": f"could not read Markdown source: {exc}"}
        source_name = source.stem
    elif isinstance(supplied, str):
        text = supplied
    else:
        return {"error": "content must be Markdown text"}

    text = text.lstrip("\ufeff")
    match = _FRONTMATTER_RE.match(text)
    frontmatter = _parse_skill_frontmatter(text)
    body = (text[match.end():] if match else text).strip()
    if not body:
        return {"error": "refused: the skill body is empty"}
    if len(body) > SKILL_BODY_CAP_CHARS:
        return {"error": (f"skill body is {len(body)} chars, over the "
                          f"{SKILL_BODY_CAP_CHARS}-char load cap; shorten it first")}

    requested_name = str(args.get("name") or frontmatter.get("name") or source_name).strip()
    name = _skill_slug(requested_name)
    if not name or not _SKILL_NAME_RE.fullmatch(name):
        return {"error": "a skill name is required; use letters, numbers, dots, underscores, or hyphens"}
    description = _skill_description(
        str(args.get("description") or frontmatter.get("description") or ""), body, name)
    budget, budget_source = _skill_token_budget(body)

    destination = SKILLS_DIR / f"{name}.md"
    overwrite = bool(args.get("overwrite"))
    existed = destination.exists()
    if existed and not overwrite:
        return {"error": (f"skill '{name}' already exists; pass overwrite=true only if the user "
                          "asked to replace it"),
                "path": str(destination)}

    rendered = ("---\n"
                f"name: {json.dumps(name, ensure_ascii=False)}\n"
                f"description: {json.dumps(description, ensure_ascii=False)}\n"
                f"budget: {budget}\n"
                "---\n\n"
                f"{body}\n")
    chat_id = _get_current_chat() or ""
    call_id = _current_tool_call_id.get()
    approval = request_approval(
        title="Save skill",
        command=f'Save Accuretta skill "{name}" to "{destination}"',
        details={"kind": "save_skill", "path": str(destination),
                 "bytes": len(rendered.encode("utf-8")), "budget": budget},
    )
    if approval.get("decision") != "approve":
        try:
            broadcast_event({"type": "skill:save_finished", "chat_id": chat_id,
                             "call_id": call_id, "skill": name, "outcome": "cancelled"})
        except Exception:
            pass
        return {"error": f"user denied skill save ({approval.get('status')})"}

    temp_path = destination.with_name(f".{destination.name}.{uuid.uuid4().hex}.tmp")
    try:
        broadcast_event({"type": "skill:saving", "chat_id": chat_id,
                         "call_id": call_id, "skill": name})
    except Exception:
        pass
    try:
        SKILLS_DIR.mkdir(parents=True, exist_ok=True)
        _undo_snapshot(str(destination))
        temp_path.write_text(rendered, encoding="utf-8")
        os.replace(temp_path, destination)
        _undo_store.checkpoint(str(destination))
        _SKILLS_CACHE.clear()
        saved_entry = _scan_skills().get(name)
        if not saved_entry or saved_entry.get("budget") != budget:
            raise ValueError("saved file did not pass the skill catalog validation")
        broadcast_event({"type": "skills:update", "skill": name})
    except Exception as exc:
        try:
            temp_path.unlink(missing_ok=True)
        except Exception:
            pass
        try:
            broadcast_event({"type": "skill:save_finished", "chat_id": chat_id,
                             "call_id": call_id, "skill": name, "outcome": "failed"})
        except Exception:
            pass
        return {"error": f"could not save skill: {exc}"}

    try:
        broadcast_event({"type": "skill:save_finished", "chat_id": chat_id,
                         "call_id": call_id, "skill": name,
                         "outcome": "saved", "budget": budget})
    except Exception:
        pass

    return {
        "ok": True,
        "skill": name,
        "description": description,
        "budget": budget,
        "budget_source": budget_source,
        "body_chars": len(body),
        "path": str(destination),
        "overwritten": existed,
        "note": f"saved '{name}' and refreshed the skill catalog",
    }


def _set_active_skill(chat_id: str, skill_name: str | None, budget: int = 0):
    """Persist the user-chosen active skill on the chat record (survives chat
    reloads; serialized like fold_mark/summary_through). Swapping replaces."""
    if not chat_id:
        return
    try:
        chats = get_chats()
        chat = (chats.get("chats") or {}).get(chat_id)
        if chat is None:
            return
        if skill_name:
            chat["active_skill"] = skill_name
            chat["active_skill_budget"] = max(0, int(budget or 0))
        else:
            chat.pop("active_skill", None)
            chat.pop("active_skill_budget", None)
        save_json(CHATS_FILE, chats)
    except Exception:
        pass


def tool_load_skill(args: dict) -> dict:
    """Load a user-curated skill (markdown procedure from skills/) into this
    chat. One active slot per chat — loading replaces the previous skill."""
    name = str(args.get("name") or "").strip()
    chat_id = str(args.get("chat_id") or "") or (_get_current_chat() or "")
    catalog = _scan_skills()
    if not name:
        _set_active_skill(chat_id, None)
        try:
            broadcast_event({"type": "skill:cleared", "chat_id": chat_id})
        except Exception:
            pass
        return {"skill": None, "active": False,
                "note": "active skill cleared"}
    entry = catalog.get(name)
    if entry is None:
        return {"error": f"unknown skill '{name}' — available: {sorted(catalog)}",
                "available": sorted(catalog)}
    body = _read_skill_body(entry)
    if body is None:
        return {"error": f"skill '{name}' could not be read from disk"}
    if len(body) > SKILL_BODY_CAP_CHARS:
        return {"error": f"skill '{name}' body is {len(body)} chars — over the "
                         f"{SKILL_BODY_CAP_CHARS}-char load cap; trim the file"}
    replaced = None
    if chat_id:
        try:
            prev = (get_chats().get("chats") or {}).get(chat_id, {}).get("active_skill")
            if prev and prev != name:
                replaced = prev
        except Exception:
            pass
    _set_active_skill(chat_id, name, budget=entry["budget"])
    try:
        ev = {"type": "skill:loaded", "chat_id": chat_id, "skill": name,
              "budget": entry["budget"], "body_chars": entry["body_chars"]}
        if replaced:
            ev["replaced"] = replaced
        broadcast_event(ev)
    except Exception:
        pass
    result: dict = {"skill": name, "active": True,
                    "description": entry["description"],
                    "budget": entry["budget"],
                    "body_chars": entry["body_chars"],
                    "content": body}
    if replaced:
        result["replaced"] = replaced
        result["note"] = f"loaded '{name}', replacing the previously active skill '{replaced}'"
    return result


def _active_skill_section(chat: dict) -> str:
    """Formatted ACTIVE SKILL section for a chat record, or "" when none.

    run_chat_turn appends this to the recency tail (like mission/pins) so the
    body the user picked via # reaches the model every turn; the context
    estimator mirrors it. A model-side load_skill carries the body in its own
    tool result instead."""
    try:
        name = str((chat or {}).get("active_skill") or "").strip()
    except Exception:
        name = ""
    if not name:
        return ""
    entry = _scan_skills().get(name)
    if not entry:
        return ""
    body = _read_skill_body(entry)
    if not body:
        return ""
    body = body[:SKILL_BODY_CAP_CHARS]
    return (
        "=== ACTIVE SKILL: " + name + " (user-loaded — follow this procedure "
        "for the current request; its steps beat improvisation; re-derive nothing "
        "it already provides) ===\n" + body
    )


def _unlock_bundle(chat_id: str, bundle: str) -> bool:
    """Load a bundle's schemas for this chat. Returns True if the bundle was
    newly unlocked (False = unknown bundle or already loaded)."""
    if not chat_id or bundle not in _TOOL_BUNDLES:
        return False
    with _TOOL_BUNDLE_LOCK:
        st = _unlocked_bundles_by_chat.setdefault(chat_id, set())
        if bundle in st:
            return False
        st.add(bundle)
    try:
        broadcast_event({"type": "tools_unlocked", "chat_id": chat_id, "bundle": bundle})
    except Exception:
        pass
    return True


def _unavailable_runtime_tools() -> dict[str, str]:
    """Strict dependency failures that would make a tool fail every call."""
    missing: dict[str, str] = {}
    if not _HAVE_PYAUTOGUI:
        for n in ("desktop_click", "desktop_type_text", "desktop_press_keys"):
            missing[n] = "raw mouse/keyboard fallback requires pyautogui"
    if not _HAVE_PYAUTOGUI or not _HAVE_PIL:
        for n in ("screenshot", "describe_screen"):
            missing[n] = "screen capture requires pyautogui and Pillow"
    elif not _vision_observation_available():
        for n in ("screenshot", "describe_screen"):
            missing[n] = "no vision backend is loaded; use desktop_snapshot"
    if not _HAVE_PGW:
        for n in ("list_windows", "desktop_focus_window", "desktop_close_window"):
            missing[n] = "window control requires pygetwindow"
    if not _HAVE_UIA:
        for n in ("desktop_snapshot", "desktop_invoke", "desktop_set_value", "desktop_scroll"):
            missing[n] = "blind semantic control requires uiautomation on Windows"
    if not _HAVE_PLAYWRIGHT:
        missing["rt_browser"] = "requires playwright and its Chromium browser"
        missing["web_render"] = "requires playwright and its Chromium browser"
    if not _resolve_ytdlp_cmd() or not shutil.which("ffmpeg"):
        missing["web_watch_video"] = "requires yt-dlp (pip install yt-dlp) and ffmpeg on PATH"
    if not _HAVE_SQUASHFS:
        missing["extract_squashfs"] = "requires PySquashfsImage"
    if not _HAVE_CAPSTONE:
        missing["disasm_at"] = "requires capstone"
    if not _resolve_jadx_bin():
        missing["decompile_apk"] = "requires JADX"
    if not _HAVE_PYGHIDRA:
        missing["ghidra_analyze"] = "requires pyghidra and Ghidra/JDK"
    if not _HAVE_YARA:
        missing["yara_scan"] = "requires yara-python"
    if not (_HAVE_EVTX_RUST or _HAVE_EVTX_PY):
        missing["parse_evtx"] = "requires evtx or python-evtx"
    if not _HAVE_DPKT:
        missing["analyze_pcap"] = "requires dpkt"
    return missing


def _excluded_tools(include_exploit: bool = True, chat_id: str = "") -> set[str]:
    """The tool names hidden by CURRENT settings — the single source of truth
    for both _active_tools and the lazy-bundle visibility filter, so the two
    can never drift apart."""
    s = get_settings()
    excluded: set[str] = set()
    if "subagents" not in _model_features(str(s.get("model_path") or "")):
        excluded.add(subagents.SPAWN_TOOL)
    if not s.get("desktop_enabled"):
        excluded |= _DESKTOP_TOOL_NAMES
    if not s.get("red_team_enabled"):
        excluded |= _RED_TEAM_TOOL_NAMES
    else:
        chat = None
        if chat_id:
            try:
                chat = (get_chats().get("chats", {}) or {}).get(chat_id)
            except Exception:
                chat = None
        # The global toggle makes the capability available; a fresh per-chat
        # UI authorization record makes the red-team schemas visible.
        if not _rt_authorized_mission(chat):
            excluded |= _RED_TEAM_TOOL_NAMES
        elif _rt_passive_mission(chat):
            excluded |= set(TOOLS) - _RT_PASSIVE_ALLOWED_TOOL_NAMES
        elif not include_exploit:
            excluded |= _RT_EXPLOIT_TOOL_NAMES
        # A program or client that bans automated testing loses the scanner
        # and fuzzer schemas entirely — pruning beats a runtime refusal, which
        # small models treat as a loop invitation.
        _mission = _rt_mission_get(chat) if isinstance(chat, dict) else None
        if _mission and _mission.get("automated_allowed") is False:
            excluded |= _RT_AUTOMATED_TOOL_NAMES
    if not s.get("analysis_tools_enabled"):
        excluded |= _ANALYSIS_SUITE_TOOL_NAMES
    if (not s.get("remote_access_enabled", True)
            or not any(m.get("status") == "ready" and m.get("enabled", True)
                       for m in _load_remote_machines().get("machines", []))):
        excluded |= _REMOTE_TOOL_NAMES
    # The sandbox tool is only useful once the guest is provisioned; don't pay
    # its token cost (or tempt the model to call it) before then.
    if not _sandbox_ready_cached():
        excluded.add("sandbox_run")
    # Do not spend scarce context advertising tools which are guaranteed to
    # fail on this machine. capability_report remains visible and explains
    # exactly what is missing and how to restore the capability.
    excluded |= set(_unavailable_runtime_tools())
    return excluded


def _visible_tool_names(include_exploit: bool = True, chat_id: str = "") -> set[str]:
    """Core + this chat's unlocked bundles, minus settings-gated tools and any
    name that isn't actually registered (MCP tools disappear when their server
    dies between unlock and request)."""
    excluded = _excluded_tools(include_exploit, chat_id)
    if _research_context(chat_id)[1]:
        return {name for name in RESEARCH_TOOLS | {subagents.SPAWN_TOOL}
                if name in TOOLS and name not in excluded
                and _execution_target_allows_tool(name, chat_id)}
    visible: set[str] = set(_base_core_tool_names(chat_id))
    visible.add("verification_guidance")
    if subagents.SPAWN_TOOL not in excluded:
        visible.add(subagents.SPAWN_TOOL)
    if get_settings().get("red_team_enabled") and chat_id:
        if _rt_authorized_mission((get_chats().get("chats", {}) or {}).get(chat_id)):
            visible |= _SECURITY_REVIEW_TOOLS
            # Findings ledger is RT-only in lean mode; auto-load so missions
            # never lose record_finding to the lazy bundle.
            visible |= {"record_finding", "list_findings"}
    active_rt = False
    if chat_id:
        try:
            _chat = (get_chats().get("chats", {}) or {}).get(chat_id)
        except Exception:
            _chat = None
        # An authorized gate launch is itself the request to use the suite:
        # auto-load discovery tools for any mission and active-testing tools for Red
        # Team mode, rather than relying on a small model to find the bundle loader.
        active_rt = bool(_rt_authorized_mission(_chat))
        if active_rt:
            if _rt_passive_mission(_chat):
                visible |= _RT_PASSIVE_TOOL_NAMES | {"web_search"}
            else:
                visible |= _RT_RECON_TOOL_NAMES
            if include_exploit and not _rt_passive_mission(_chat):
                visible |= _RT_EXPLOIT_TOOL_NAMES
        for b in _unlocked_bundles_by_chat.get(chat_id, ()):
            btools = _TOOL_BUNDLES.get(b)
            if btools is None:
                if b == "mcp":
                    visible |= {n for n in TOOLS if n.startswith("mcp_")}
                continue
            visible |= btools
    if active_rt:
        visible -= _DESKTOP_TOOL_NAMES
        # Only the playwright MCP server stays visible during a mission: its
        # calls are URL-filtered at the wrapper (same gate as rt_browser),
        # which is what makes a third-party browser safe to extend the
        # first-party worker. Every other MCP connector remains hidden.
        visible = {n for n in visible
                   if not (n.startswith("mcp_") and not n.startswith("mcp_playwright_"))}
    # Execution target is a backend capability boundary. Project only the
    # selected device's file/shell surface instead of relying on prose routing.
    visible = {n for n in visible if _execution_target_allows_tool(n, chat_id)}
    if _selected_execution_target(chat_id) != "host":
        visible |= _REMOTE_TOOL_NAMES
    # The system prompt advertises the guest whenever it is ready. Keep the
    # actual schema in lockstep so the model never substitutes host PowerShell
    # merely because the sandbox bundle was still lazy-hidden.
    if "sandbox_run" in TOOLS and "sandbox_run" not in excluded:
        visible.add("sandbox_run")
    return {n for n in visible if n in TOOLS and n not in excluded}


def tool_list_more_tools(args: dict) -> dict:
    """Probe tool for the lazy tool bundles: shows which specialized bundles
    exist (and which are loaded), or loads one by name so its schemas join the
    tool list for the rest of this chat."""
    chat_id = _get_current_chat()
    bundle = str(args.get("bundle") or "").strip().lower()
    excluded = _excluded_tools(True, chat_id)
    enabled: dict[str, list[str]] = {}
    for bname, btools in _TOOL_BUNDLES.items():
        if btools is None:
            btools = {n for n in TOOLS if n.startswith("mcp_")}
        if not btools:
            continue
        # Advertise only bundles at least one of whose tools the current
        # settings would actually load (desktop / red-team / analysis gates).
        usable = sorted(
            n for n in btools
            if n in TOOLS and n not in excluded
            and _execution_target_allows_tool(n, chat_id)
        )
        if usable:
            enabled[bname] = usable
    if not bundle:
        loaded = set(_unlocked_bundles_by_chat.get(chat_id, ()))
        return {
            "note": "Call again with one of the bundle names shown below to inspect its tools and load it into this chat's schema.",
            "core": sorted(
                n for n in _base_core_tool_names(chat_id)
                if n in TOOLS and n not in excluded
                and _execution_target_allows_tool(n, chat_id)
            ),
            "bundles": {b: {"tools": names, "loaded": b in loaded}
                        for b, names in enabled.items()},
        }
    if bundle not in enabled:
        return {"error": f"unknown bundle '{bundle}' — available: {sorted(enabled)}"}
    names = enabled[bundle]
    details = {n: (TOOLS[n].get("description", "") or "")[:400] for n in names}
    loaded_now = _unlock_bundle(chat_id, bundle)
    return {
        "bundle": bundle,
        "loaded": True,
        "loaded_now": loaded_now,
        "tools": details,
        "note": ("This bundle's tools are now in the tool schema for the rest of this chat. "
                 "Call them directly — no need to re-list."),
    }


