_REQUEST_TOKEN = secrets.token_urlsafe(32)
_MAX_JSON_BYTES = 32 * 1024 * 1024
_PREVIEW_SANDBOX = "sandbox allow-scripts allow-forms allow-modals allow-popups; object-src 'none'"


class RequestError(ValueError):
    def __init__(self, status: int, message: str):
        self.status = status
        super().__init__(message)


def _json_default(value: Any):
    """Last-resort encoder for API payloads. Sets (GGUF identity fingerprints)
    are the common case; anything else falls back to its string form so one odd
    field can never turn a whole endpoint into a 500."""
    if isinstance(value, (set, frozenset)):
        return sorted(str(item) for item in value)
    if isinstance(value, Path):
        return str(value)
    return str(value)


class Handler(BaseHTTPRequestHandler):
    server_version = "Accuretta/1.0"

    def log_message(self, fmt, *args):
        sys.stderr.write("[%s] %s\n" % (self.log_date_time_string(), fmt % args))

    # ---- helpers

    def _set_cors(self):
        # Same-origin only: the UI is served by this bridge and needs no CORS.
        # Access-Control-Allow-Origin:* would let any website read the agent's
        # responses or drive it from the user's browser.
        return

    def _host_ok(self) -> bool:
        # DNS-rebinding defense. Legitimate access is via localhost or an IP literal
        # (LAN or Tailscale); a Host header that is a domain name is the signature of
        # a rebinding attack aimed at this port.
        host = (self.headers.get("Host") or "").strip()
        if not host:
            return True
        if host.startswith("["):                       # IPv6, e.g. [::1]:8787
            hostname = host[1:host.find("]")] if "]" in host else host[1:]
        else:
            hostname = host.split(":", 1)[0]
        hostname = hostname.strip().lower()
        # localhost + Tailscale MagicDNS names (….ts.net is Tailscale-owned, not
        # publicly registrable, so it can't be used to rebind at your machine).
        if hostname == "localhost" or hostname.endswith(".ts.net"):
            return True
        import ipaddress
        try:
            ipaddress.ip_address(hostname)             # any IP literal is fine
            return True
        except ValueError:
            return False

    def _peer_ok(self) -> bool:
        # Only this machine (loopback) or the user's tailnet (100.64.0.0/10 and
        # fd7a:115c:a1e0::/48) may connect; everyone else on the local network is
        # refused. Tailscale already proves the device is the user's, so no password
        # is needed. client_address is the real TCP peer and can't be forged.
        import ipaddress
        try:
            ip = ipaddress.ip_address((self.client_address or ("",))[0])
        except (ValueError, IndexError, TypeError):
            return False
        if ip.is_loopback:
            return True
        for cidr in ("100.64.0.0/10", "fd7a:115c:a1e0::/48"):
            try:
                if ip in ipaddress.ip_network(cidr):
                    return True
            except ValueError:
                pass
        return False

    def _peer_is_loopback(self) -> bool:
        import ipaddress
        try:
            return ipaddress.ip_address((self.client_address or ("",))[0]).is_loopback
        except (ValueError, IndexError, TypeError):
            return False

    def _request_ok(self) -> bool:
        if not (self._peer_ok() and self._host_ok()):
            return False
        path = urllib.parse.urlsplit(self.path).path
        preview = path.startswith(("/api/wsfs/", "/api/snapshots/")) or (
            path.startswith("/api/versions/") and len(path.split("/")) == 5)
        origin = self.headers.get("Origin")
        fetch_site = self.headers.get("Sec-Fetch-Site", "")
        if self.command == "GET" and (preview or path.startswith("/assets/vendor/") or path == "/preview-runtime.js"):
            return True
        if fetch_site in {"cross-site", "same-site"}:
            return False
        if origin:
            parsed = urllib.parse.urlsplit(origin)
            if parsed.scheme not in {"http", "https"} or parsed.netloc.lower() != self.headers.get("Host", "").lower():
                return False
        if path.startswith("/api/") and self.command not in {"GET", "HEAD", "OPTIONS"}:
            supplied = self.headers.get("X-Accuretta-Token", "")
            if not secrets.compare_digest(supplied, _REQUEST_TOKEN):
                return False
        return True

    def end_headers(self):
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Referrer-Policy", "no-referrer")
        if _offline_active:
            self.send_header("Content-Security-Policy", "default-src 'self' data: blob:; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'self'; object-src 'none'; frame-src 'self' data: blob:")
        super().end_headers()

    def _send_json(self, status: int, obj: Any):
        body = json.dumps(obj, ensure_ascii=False, default=_json_default).encode("utf-8")
        accepts_gzip = "gzip" in (self.headers.get("Accept-Encoding") or "").lower()
        encoded = accepts_gzip and len(body) >= 1024
        if encoded:
            body = gzip.compress(body, compresslevel=5)
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Vary", "Accept-Encoding")
        if encoded:
            self.send_header("Content-Encoding", "gzip")
        # API payloads carry conversations, approvals and settings. Without an
        # explicit directive Chromium heuristically caches GET JSON in the WebView2
        # profile on disk (full chat histories turned up in its Cache), so never
        # store them.
        self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
        self.send_header("Pragma", "no-cache")
        self._set_cors()
        self.end_headers()
        try:
            self.wfile.write(body)
        except Exception:
            pass

    def _send_bytes(self, status: int, data: bytes, ctype: str, extra_headers: dict | None = None):
        headers = dict(extra_headers or {})
        path = urllib.parse.urlsplit(self.path).path
        if path.startswith("/api/") and ("text/html" in ctype or "image/svg+xml" in ctype or "application/xhtml+xml" in ctype):
            headers["Content-Security-Policy"] = _PREVIEW_SANDBOX
            if "text/html" in ctype and self.headers.get("Sec-Fetch-Dest") in {"iframe", "document"}:
                runtime = b'<script src="/preview-runtime.js"></script>'
                if re.search(br"<head\b[^>]*>", data, re.I):
                    data = re.sub(br"<head\b[^>]*>", lambda match: match[0] + runtime, data, count=1, flags=re.I)
                else:
                    data = runtime + data
        elif path in {"/", "/index.html"}:
            headers["Content-Security-Policy"] = "frame-ancestors 'none'; object-src 'none'; base-uri 'self'"
            headers["X-Frame-Options"] = "DENY"
        cache_control = headers.pop("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
        self.send_response(status)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", cache_control)
        if "no-cache" in cache_control or "no-store" in cache_control:
            self.send_header("Pragma", "no-cache")
        for k, v in headers.items():
            self.send_header(k, v)
        self._set_cors()
        self.end_headers()
        try:
            self.wfile.write(data)
        except Exception:
            pass

    def _read_json(self) -> dict:
        if self.headers.get_content_type() != "application/json":
            raise RequestError(415, "Content-Type must be application/json")
        if self.headers.get("Transfer-Encoding"):
            raise RequestError(400, "Transfer-Encoding is not supported")
        try:
            ln = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            raise RequestError(400, "Invalid Content-Length")
        if ln < 0 or ln > _MAX_JSON_BYTES:
            raise RequestError(413, "JSON request is too large")
        if ln <= 0:
            return {}
        raw = self.rfile.read(ln)
        try:
            value = json.loads(raw.decode("utf-8"))
        except (ValueError, UnicodeError):
            raise RequestError(400, "Invalid JSON")
        if not isinstance(value, dict):
            raise RequestError(400, "JSON body must be an object")
        return value

    def do_OPTIONS(self):
        self.send_response(204)
        self._set_cors()
        self.end_headers()

    # ---- dispatch

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        p = parsed.path
        if not self._request_ok():
            return self._send_json(403, {"error": "forbidden"})
        try:
            if p == "/" or p == "":
                return self._serve_static("index.html")
            if p == "/notch":
                return self._serve_notch_page()
            if _offline_active and p.startswith(("/api/github/", "/api/remote/", "/api/mcp", "/api/link_preview", "/api/sandbox/setup")):
                return self._send_json(409, {"error": "This integration is disabled in offline mode."})
            if p.startswith("/api/"):
                return self._handle_api_get(p, parsed)
            name = p.lstrip("/")
            vendor_path = (ROOT / name).resolve()
            is_vendor = (name.startswith("assets/vendor/")
                         and vendor_path.is_relative_to((ROOT / "assets/vendor").resolve())
                         and vendor_path.is_file())
            if name in STATIC_WHITELIST or is_vendor:
                return self._serve_static(name, versioned=bool(parsed.query))
            return self._send_json(404, {"error": "not found"})
        except Exception as e:
            traceback.print_exc()
            self._send_json(500, {"error": str(e)})

    def do_POST(self):
        parsed = urllib.parse.urlparse(self.path)
        p = parsed.path
        if not self._request_ok():
            return self._send_json(403, {"error": "forbidden"})
        try:
            if p == "/api/client-files/upload":
                return self._handle_client_file_upload()
            if _offline_active and p.startswith(("/api/github/", "/api/remote/", "/api/mcp", "/api/link_preview", "/api/sandbox/setup")):
                return self._send_json(409, {"error": "This integration is disabled in offline mode."})
            if p.startswith("/api/"):
                return self._handle_api_post(p, parsed)
            return self._send_json(404, {"error": "not found"})
        except RequestError as e:
            self._send_json(e.status, {"error": str(e)})
        except Exception as e:
            traceback.print_exc()
            self._send_json(500, {"error": str(e)})

    def do_DELETE(self):
        parsed = urllib.parse.urlparse(self.path)
        p = parsed.path
        if not self._request_ok():
            return self._send_json(403, {"error": "forbidden"})
        try:
            if p.startswith("/api/chats/"):
                cid = p.split("/")[-1]
                chats = get_chats()
                if cid in chats["chats"]:
                    chats["chats"].pop(cid)
                    chats["order"] = [x for x in chats["order"] if x != cid]
                    save_json(CHATS_FILE, chats)
                    shutil.rmtree(VERSIONS_DIR / cid, ignore_errors=True)
                    # Free this chat's in-memory state (loop-breaker history, unlocked bundles,
                    # ctx-estimate cache) so deleted chats don't leak an entry each for the life
                    # of the process.
                    with _tool_history_lock:
                        _tool_call_history.pop(cid, None)
                        _tool_write_history.pop(cid, None)
                        _tool_url_history.pop(cid, None)
                        _tool_family_history.pop(cid, None)
                    with _TOOL_BUNDLE_LOCK:
                        _unlocked_bundles_by_chat.pop(cid, None)
                    _client_context_by_chat.pop(cid, None)
                    _CTX_EST_CACHE.pop(cid, None)
                    return self._send_json(200, {"ok": True})
                return self._send_json(404, {"error": "not found"})
            if p == "/api/cmd-history":
                # Wipe the whole cmd history file; there is no per-chat delete.
                try:
                    with _cmd_history_lock:
                        if CMD_HISTORY_FILE.exists():
                            CMD_HISTORY_FILE.unlink()
                except Exception as e:
                    return self._send_json(500, {"error": str(e)})
                return self._send_json(200, {"ok": True, "cleared": True})
            return self._send_json(404, {"error": "not found"})
        except Exception as e:
            traceback.print_exc()
            self._send_json(500, {"error": str(e)})

    def _serve_static(self, name: str, *, versioned: bool = False):
        full = ROOT / name
        if not full.is_file():
            return self._send_json(404, {"error": f"missing: {name}"})
        stat = full.stat()
        source_etag = f'{stat.st_mtime_ns:x}-{stat.st_size:x}'
        if name == "index.html":
            source_etag += _REQUEST_TOKEN
        live_ui_asset = name in {
            "index.html", "app.js", "appearance.js", "app.css", "workspace-shell.css", "colors_and_type.css",
            "research-ui.js", "research-ui.css", "dropdown-menus.js",
            "glyph-field.js", "security-scan-field.js", "agent-orb.js", "ui-refresh.css", "ui-pass.css", "theme-flowlines.js",
            "dot-matrix.js", "workbench.css", "opal.css",
            "accuretta-notch.html", "notch-wire.js", "notch-markdown.js",
        }
        cache_control = ("no-cache, must-revalidate" if live_ui_asset
                         else ("public, max-age=31536000, immutable" if versioned
                               else "public, max-age=3600, must-revalidate"))
        data = full.read_bytes()
        if name == "index.html":
            bootstrap = (f'<meta name="accuretta-request-token" content="{_REQUEST_TOKEN}">'
                         '<script src="/bridge-client.js"></script>')
            data = data.replace(b"<head>", b"<head>" + bootstrap.encode("ascii"), 1)
        ctype = MIME.get(full.suffix, "application/octet-stream")
        accepts_gzip = "gzip" in (self.headers.get("Accept-Encoding") or "").lower()
        compressible = full.suffix.lower() in {
            ".html", ".js", ".css", ".json", ".svg", ".md", ".txt", ".webmanifest"
        }
        encoded = accepts_gzip and compressible and len(data) >= 256
        if encoded:
            data = gzip.compress(data, compresslevel=6)
        etag = f'"{source_etag}{"-gz" if encoded else ""}"'
        headers = {"Cache-Control": cache_control, "ETag": etag, "Vary": "Accept-Encoding"}
        if self.headers.get("If-None-Match") == etag:
            self.send_response(304)
            for key, value in headers.items():
                self.send_header(key, value)
            self._set_cors()
            self.end_headers()
            return
        if encoded:
            headers["Content-Encoding"] = "gzip"
        self._send_bytes(200, data, ctype, extra_headers=headers)

    def _serve_notch_page(self):
        """Serve accuretta-notch.html for the overlay host window.

        The file on disk stays byte-identical to the approved UI; what the host
        needs is injected into the response at serve time (as index.html gets its
        request token):
          - the per-process API token meta (the wire script authorizes POSTs with it)
          - a transparent html/body background (the host window is see-through)
          - the wiring script tag, after the page's own script so window.notch
            exists when it runs (notch-markdown.js, its reply renderer, loads first)
        Never cached: the token rotates with every bridge process."""
        full = ROOT / "accuretta-notch.html"
        if not full.is_file():
            return self._send_json(404, {"error": "notch UI missing"})
        data = full.read_bytes()
        head_inject = (
            f'<meta name="accuretta-request-token" content="{_REQUEST_TOKEN}">'
            "<style>html, body { background: transparent !important; }</style>"
        ).encode("utf-8")
        tail_inject = (b'<script src="/notch-markdown.js"></script>'
                       b'<script src="/notch-wire.js"></script>')
        if b"<head>" in data:
            data = data.replace(b"<head>", b"<head>" + head_inject, 1)
        if b"</body>" in data:
            data = data.replace(b"</body>", tail_inject + b"</body>", 1)
        headers = {
            "Cache-Control": "no-store",
            "Content-Security-Policy": ("default-src 'self'; script-src 'self' 'unsafe-inline'; "
                                        "style-src 'self' 'unsafe-inline'; connect-src 'self'; "
                                        "img-src 'self' data:; frame-ancestors 'none'"),
            "X-Frame-Options": "DENY",
        }
        self._send_bytes(200, data, "text/html; charset=utf-8", extra_headers=headers)

    # ---- API routes

    def _handle_client_file_upload(self):
        """Stream one browser-selected file into Workspace/Incoming."""
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except Exception:
            length = 0
        limit = min(_remote_payload_limit(), 250 * 1024 * 1024)
        if length <= 0:
            return self._send_json(400, {"error": "empty upload"})
        if length > limit:
            return self._send_json(413, {"error": f"file exceeds the {limit // (1024 * 1024)} MB upload limit"})
        raw_name = urllib.parse.unquote(self.headers.get("X-File-Name") or "")
        name = Path(raw_name.replace("\\", "/")).name.strip()
        name = re.sub(r"[\x00-\x1f<>:\"/\\|?*]", "_", name)[:180]
        if not name or name in {".", ".."}:
            return self._send_json(400, {"error": "invalid file name"})
        folders = get_workspace().get("folders") or []
        if not folders:
            return self._send_json(409, {"error": "No workspace folder is configured."})
        root = Path(normalize_path(folders[0]))
        try:
            incoming = (root / "Incoming").resolve()
            incoming.relative_to(root.resolve())
            incoming.mkdir(parents=True, exist_ok=True)
        except Exception as exc:
            return self._send_json(500, {"error": f"Could not prepare Incoming: {exc}"})
        target = incoming / name
        if target.exists():
            target = incoming / f"{target.stem}-{uuid.uuid4().hex[:6]}{target.suffix}"
        tmp = incoming / f".{target.name}.{uuid.uuid4().hex[:8]}.part"
        remaining = length
        try:
            with tmp.open("xb") as handle:
                while remaining:
                    chunk = self.rfile.read(min(1024 * 1024, remaining))
                    if not chunk:
                        raise IOError("upload ended early")
                    handle.write(chunk)
                    remaining -= len(chunk)
            tmp.replace(target)
        except Exception as exc:
            try:
                tmp.unlink(missing_ok=True)
            except Exception:
                pass
            return self._send_json(500, {"error": f"upload failed: {exc}"})
        return self._send_json(200, {
            "ok": True, "name": target.name, "path": str(target),
            "root": str(root), "rel": str(target.relative_to(root)).replace("\\", "/"),
            "bytes": length,
        })

    def _handle_api_get(self, p: str, parsed):
        if p == "/api/mcp/servers":
            out = _mcp_list_servers()
            out["can_edit"] = self._peer_is_loopback()
            return self._send_json(200, out)
        if p == "/api/health":
            return self._send_json(200, {
                "ok": True,
                "application": "accuretta",
                "llama": LLAMA,
                "vision_llama": VISION_LLAMA,
                "llama_up": llama_ready(timeout=1.0),
                # legacy alias so older frontend builds don't break
                "ollama": LLAMA,
            })
        if p == "/api/security/overview":
            return self._send_json(200, _security_overview.get_overview())
        if p == "/api/security/processes":
            result = _security_collect_processes()
            return self._send_json(200, {
                "processes": result.get("processes") or [],
                "error": result.get("error") or "",
            })
        if p == "/api/app-update":
            qs = urllib.parse.parse_qs(parsed.query)
            manual = (qs.get("manual") or [""])[0] == "1"
            return self._send_json(200, app_update_status(manual=manual))
        if p == "/api/llama-log":
            # Live tail of the llama.cpp backend's stdout/stderr — powers the
            # Backend terminal tab so model loads/reloads show real progress.
            qs = urllib.parse.parse_qs(parsed.query)
            try:
                tail = int(qs.get("tail", ["400"])[0])
            except Exception:
                tail = 400
            return self._send_json(200, _llama.read_log(max(1, min(tail, 800))))
        if p == "/api/session/list":
            return self._send_json(200, {"sessions": _session_mgr.list()})
        if p == "/api/session/read":
            qs = urllib.parse.parse_qs(parsed.query)
            sid = (qs.get("id", [""])[0] or "").strip()
            try:
                since = int(qs.get("since", ["0"])[0])
            except Exception:
                since = 0
            s = _session_mgr.get(sid)
            if not s:
                return self._send_json(404, {"error": "no such session", "alive": False})
            out, offset = s.read_since(since)
            return self._send_json(200, {"output": out, "offset": offset, "alive": s.alive(),
                                         "exit_code": s.exit_code(), "command": s.command})
        if p == "/api/models":
            # List .gguf files under settings.models_dir. Each entry includes a
            # `loaded` flag so the UI can highlight the active model.
            s = get_settings()
            mdir = (s.get("models_dir") or "").strip()
            files = scan_gguf_dir(mdir)
            loaded = _llama.loaded_model() or s.get("model_path") or ""
            # The remembered model is gone from disk (moved/deleted): report
            # it instead of presenting it as the active model.
            missing = "" if _llama.loaded_model() or safe_exists(loaded) else loaded
            if missing:
                loaded = ""
            for f in files:
                f["loaded"] = (f["path"] == loaded)
            reasoning_capability = _reasoning_capability(loaded, s) if loaded else _reasoning_capability("", s)
            return self._send_json(200, {
                "models_dir": mdir,
                "loaded_model": loaded,
                "missing_model": missing,
                "llama_running": _llama.is_running() or llama_ping(timeout=0.5),
                "vision_capable": _llama.is_vision_capable(),
                "loaded_mmproj": _llama.loaded_mmproj(),
                "reasoning_capability": reasoning_capability,
                "models": files,
            })
        if p == "/api/models/spec-drafts":
            # Draft GGUFs (DFlash/DSpark) available for the selected model,
            # best metadata-validated match first. `paired` is what auto-tune
            # and the spawn path would use; `drafts` feeds the settings picker.
            # `draft_path` additionally validates one explicitly chosen file.
            qs = urllib.parse.parse_qs(parsed.query)
            model_path = (qs.get("model_path") or [""])[0].strip()
            chosen = (qs.get("draft_path") or [""])[0].strip()
            target = _spec_fingerprint(model_path) if model_path and safe_exists(model_path) else {}
            paired = find_spec_draft_for(model_path) if model_path else {}
            selected: dict = {}
            if chosen and model_path and safe_exists(chosen):
                selected = draft_match_payload(
                    {"path": chosen, **spec_draft_match(model_path, chosen)})
            return self._send_json(200, {
                "model_path": model_path,
                "model": {
                    "name": target.get("name", ""),
                    "architecture": target.get("architecture", ""),
                    "vocab": target.get("vocab", 0),
                    "identities": sorted(target.get("identities") or []),
                },
                "drafts": list_spec_drafts(model_path),
                "paired": paired.get("path", ""),
                "paired_match": draft_match_payload(paired),
                "selected_match": selected,
            })
        if p == "/api/models/draft-pairs":
            # Which models in the models dir have a validated DFlash/DSpark pair
            # beside them. Cached fingerprints keep repeat calls cheap; the UI
            # fetches this once to mark model-picker rows with a badge.
            s = get_settings()
            mdir = (s.get("models_dir") or "").strip()
            pairs: dict[str, dict] = {}
            for item in (scan_gguf_dir(mdir) if mdir else []):
                found = find_spec_draft_for(item["path"])
                if found.get("matched") and found.get("path"):
                    pairs[item["path"]] = {
                        "draft": os.path.basename(found["path"]),
                        "reasons": found.get("reasons") or [],
                    }
            return self._send_json(200, {"pairs": pairs})
        if p.startswith("/api/model-info/"):
            name = urllib.parse.unquote(p[len("/api/model-info/"):])
            return self._send_json(200, recommended_settings(name))
        if p == "/api/settings":
            return self._send_json(200, get_settings())
        if p == "/api/client-context":
            qs = urllib.parse.parse_qs(parsed.query)
            hint = {
                "os": (qs.get("os") or ["unknown"])[0],
                "mobile": (qs.get("mobile") or [""])[0] == "1",
                "secure_context": (qs.get("secure") or [""])[0] == "1",
                "execution_target": (qs.get("target") or ["host"])[0],
            }
            snapshot = _tailscale_snapshot()
            peers = [p for p in snapshot.get("peers", [])
                     if str(p.get("os") or "").lower() in {"macos", "darwin"}]
            return self._send_json(200, {
                "context": _handler_client_context(self, hint),
                "machines": [_public_remote_machine(m) for m in _load_remote_machines().get("machines", [])],
                "mac_peers": peers,
                "tailscale": {
                    "ok": snapshot.get("ok", False), "state": snapshot.get("state", "unknown"),
                    "health": snapshot.get("health", []), "self_dns": snapshot.get("self_dns", ""),
                    "self_ips": snapshot.get("self_ips", []),
                },
                "serve": _tailscale_serve_status(snapshot),
                "ssh_available": bool(_ssh_exe() and _ssh_keygen_exe()),
            })
        if p == "/api/model-health":
            return self._send_json(200, _public_model_health())
        if p == "/api/savings":
            # Lifetime token totals for the "saved vs cloud" card. Server-side so
            # it survives restarts and follows the machine, not the browser.
            return self._send_json(200, _savings_get())
        if p == "/api/usage-stats":
            return self._send_json(200, _usage_stats())
        if p == "/api/workspace":
            return self._send_json(200, get_workspace())
        if p == "/api/workspace/files":
            # Flat, bounded file list across all workspace folders — powers the
            # @-mention picker in the composer. Skips heavy/vendor dirs.
            skip = ("/node_modules/", "/.git/", "/__pycache__/", "/.venv/",
                    "/venv/", "/dist/", "/build/", "/.next/", "/.cache/")
            ws = get_workspace()
            out = []
            seen = set()
            for root in (ws.get("folders") or []):
                if len(out) >= 4000:
                    break
                try:
                    base = Path(root)
                    for f in safe_rglob_files(root, "*", max_depth=8):
                        ap = str(f.resolve())
                        if ap in seen:
                            continue
                        seen.add(ap)
                        try:
                            rel = str(f.relative_to(base)).replace("\\", "/")
                        except Exception:
                            rel = f.name
                        if any(sd in ("/" + rel) for sd in skip):
                            continue
                        out.append({"name": f.name, "rel": rel, "path": ap})
                        if len(out) >= 4000:
                            break
                except Exception:
                    continue
            out.sort(key=lambda m: m["rel"].lower())
            return self._send_json(200, {"files": out, "count": len(out), "truncated": len(out) >= 4000})
        if p == "/api/workbench/status":
            return self._send_json(200, _workbench_status())
        if p == "/api/workspace/git":
            qs = urllib.parse.parse_qs(parsed.query)
            return self._send_json(200, _workspace_git_status((qs.get("path") or [""])[0]))
        if p == "/api/skills":
            # Catalog of user-curated markdown skills (frontmatter
            # name/description/budget). Names only — bodies load via load_skill.
            lst = _skills_catalog()
            return self._send_json(200, {"skills": lst, "count": len(lst)})
        if p == "/api/link_preview":
            # Hover preview for links in chat bubbles: fetch the page, pull Open Graph +
            # <title>, cache in-process. The frontend only asks on first hover.
            qs = urllib.parse.parse_qs(parsed.query)
            url = (qs.get("url", [""])[0] or "").strip()
            if not url:
                return self._send_json(400, {"error": "url required"})
            return self._send_json(200, fetch_link_preview(url))
        if p == "/api/ctx-stats":
            s = get_settings()
            # Live server ctx is the real capacity — settings.num_ctx can drift
            # from how llama-server was actually launched.
            cap = _llama_props_ctx() or int(s.get("num_ctx") or 32768)
            qs = urllib.parse.parse_qs(parsed.query)
            chat_id = (qs.get("chat_id", [""])[0] or "").strip()
            # Per-chat real count (llama-server's prompt_eval_count) is the
            # ground truth once a turn has completed. Before that, tokenize the
            # assembled prompt for an accurate cold-start number.
            real = _last_prompt_tokens_by_chat.get(chat_id, 0) if chat_id else _last_prompt_tokens
            if real > 0:
                return self._send_json(200, {"prompt_tokens": real, "capacity": cap, "source": "live"})
            est = _estimate_context_tokens(chat_id) if chat_id else 0
            return self._send_json(200, {"prompt_tokens": est, "capacity": cap,
                                         "source": "estimate" if est else "none"})
        if p == "/api/chats":
            qs = urllib.parse.parse_qs(parsed.query)
            chats = get_chat_index() if qs.get("summary", [""])[0] == "1" else get_chats()
            return self._send_json(200, chats)
        if p == "/api/chat-search":
            query = urllib.parse.parse_qs(parsed.query).get("q", [""])[0]
            return self._send_json(200, {"results": search_conversations(get_chats(), query)})
        if p == "/api/approvals":
            return self._send_json(200, {"pending": list_approvals()})
        if p.startswith("/api/versions/"):
            parts = p.split("/")
            # /api/versions/<chat_id>          -> list
            # /api/versions/<chat_id>/<vid>    -> html
            if len(parts) == 4:
                return self._send_json(200, {"versions": list_versions(parts[3])})
            if len(parts) == 5:
                html = read_version(parts[3], parts[4])
                if html is None:
                    return self._send_json(404, {"error": "not found"})
                return self._send_bytes(200, html.encode("utf-8"), "text/html; charset=utf-8")
        if p == "/api/events":
            return self._serve_sse()
        if p == "/api/system-context":
            try:
                md = ensure_system_context()
            except Exception as e:
                return self._send_json(200, {"md": "", "path": str(SYSTEM_CONTEXT_FILE), "exists": False, "error": str(e)})
            return self._send_json(200, {
                "md": md,
                "path": str(SYSTEM_CONTEXT_FILE),
                "exists": SYSTEM_CONTEXT_FILE.exists(),
            })
        if p == "/api/memories":
            return self._send_json(200, {"memories": [{**m, "kind": memory_kind(m), "legacy": "kind" not in m} for m in _load_memories()], "profile": _memory_store.profile(), "path": str(MEMORIES_FILE)})
        if p == "/api/cmd-history":
            # GET ?limit=200&chat_id=XYZ — newest entries first. Optional
            # chat_id filter scopes the list to one conversation; omit it
            # for the global view.
            ch_qs = urllib.parse.parse_qs(parsed.query)
            try:
                limit = int(ch_qs.get("limit", ["200"])[0])
            except Exception:
                limit = 200
            limit = max(1, min(limit, 2000))
            chat_id = (ch_qs.get("chat_id", [""])[0] or "").strip()
            return self._send_json(200, {
                "entries": _read_cmd_history(limit=limit, chat_id=chat_id),
                "limit": limit,
                "chat_id": chat_id,
                "cap": CMD_HISTORY_MAX,
            })
        if p.startswith("/api/desktop/chat-state/"):
            # GET the per-chat desktop-disabled flag
            cid = p.split("/", 4)[4]
            return self._send_json(200, {
                "chat_id": cid,
                "disabled": cid in _chat_desktop_disabled,
            })
        if p.startswith("/api/chats/") and p.count("/") == 3:
            # GET a single chat's metadata (for restoring last_mode on switch)
            cid = p.split("/")[3]
            chats = get_chats()
            if cid in chats["chats"]:
                chat = chats["chats"][cid]
                return self._send_json(200, {**chat, "task_state": _chat_task_state(cid, chat)})
            return self._send_json(404, {"error": "not found"})
        if p == "/api/snapshots":
            out = []
            for f in sorted(SNAPSHOTS_DIR.glob("*.html")):
                try:
                    st = f.stat()
                    out.append({"name": f.name, "size": st.st_size, "mtime": int(st.st_mtime)})
                except Exception:
                    continue
            return self._send_json(200, {"snapshots": out, "path": str(SNAPSHOTS_DIR)})
        if p.startswith("/api/snapshots/"):
            # serve a single saved snapshot by filename (no path traversal)
            fname = p.split("/", 3)[3]
            if "/" in fname or "\\" in fname or ".." in fname:
                return self._send_json(400, {"error": "bad name"})
            fp = SNAPSHOTS_DIR / fname
            if not fp.exists() or not fp.is_file():
                return self._send_json(404, {"error": "not found"})
            return self._send_bytes(200, fp.read_bytes(), "text/html; charset=utf-8")
        if p.startswith("/api/jobs/"):
            job_id = p.split("/")[3]
            with _tool_jobs_lock:
                job = _tool_jobs.get(job_id)
            if not job:
                return self._send_json(404, {"error": "not found"})
            return self._send_json(200, {
                "id": job_id,
                "status": job.get("status"),
                "result": job.get("result"),
                "started": job.get("started"),
                "finished": job.get("finished"),
            })
        if p == "/api/desktop/status":
            s = get_settings()
            vision_ready = _vision_observation_available()
            blind_ready = bool(_HAVE_UIA)
            return self._send_json(200, {
                "enabled": bool(s.get("desktop_enabled")),
                "panic": _desktop_panic.is_set(),
                "have_pyautogui": _HAVE_PYAUTOGUI,
                "have_pil": _HAVE_PIL,
                "have_pygetwindow": _HAVE_PGW,
                "have_uiautomation": _HAVE_UIA,
                "blind_control_ready": blind_ready,
                "vision_ready": vision_ready,
                "observation_mode": ("accessibility+vision" if blind_ready and vision_ready
                                     else "accessibility" if blind_ready
                                     else "vision" if vision_ready else "none"),
                "allowlist": s.get("desktop_app_allowlist") or [],
                "max_actions_per_minute": int(s.get("desktop_max_actions_per_minute") or 30),
            })
        if p.startswith("/api/wsfs/"):
            # Stream one file from inside a configured workspace folder, as
            # `/api/wsfs/<token>/<relative>`. Path-style on purpose: the browser resolves
            # an HTML file's `./style.css` against the URL path (not the query), so every
            # asset it fetches routes through this same endpoint.
            #
            # The token is urlsafe-base64 of the workspace root path, re-validated against
            # the live workspace list on every request, so removing a folder revokes
            # outstanding URLs.
            rest = p[len("/api/wsfs/"):]
            if "/" not in rest:
                return self._send_json(400, {"error": "missing path"})
            token, rel = rest.split("/", 1)
            try:
                # add padding back for b64decode (we strip it on the JS side)
                pad = "=" * (-len(token) % 4)
                root = _b64.urlsafe_b64decode((token + pad).encode("ascii")).decode("utf-8")
            except Exception:
                return self._send_json(400, {"error": "bad root token"})
            rel = urllib.parse.unquote(rel)
            target, err = resolve_workspace_file(root, rel)
            if err:
                msg = err.get("error", "")
                code = 403 if ("escape" in msg or "absolute" in msg or "not in workspace" in msg) else 404
                return self._send_json(code, err)
            try:
                size = target.stat().st_size
            except Exception:
                return self._send_json(500, {"error": "stat failed"})
            if size > _WS_FILE_MAX_BYTES:
                return self._send_json(413, {"error": f"file too large (>{_WS_FILE_MAX_BYTES // (1024*1024)} MB)"})
            try:
                data = target.read_bytes()
            except Exception as e:
                return self._send_json(500, {"error": f"read failed: {e}"})
            ct = _WS_FILE_MIME.get(target.suffix.lower(), "application/octet-stream")
            extra = {
                "X-Content-Type-Options": "nosniff",
                "Referrer-Policy": "no-referrer",
                "Cache-Control": "no-store",
            }
            qs = urllib.parse.parse_qs(parsed.query)
            if (qs.get("download") or [""])[0] == "1":
                encoded_name = urllib.parse.quote(target.name, safe="")
                extra["Content-Disposition"] = f"attachment; filename*=UTF-8''{encoded_name}"
            return self._send_bytes(200, data, ct, extra_headers=extra)
        if p == "/api/llama/detect-vram":
            # GET — best-effort GPU VRAM probe via nvidia-smi. Used by the
            # Settings drawer to pre-fill the VRAM tier dropdown.
            return self._send_json(200, detect_vram_gb())
        if p == "/api/list-folder":
            qs = urllib.parse.parse_qs(parsed.query)
            raw = (qs.get("path") or [""])[0]
            if not raw:
                return self._send_json(400, {"error": "path required"})
            target = Path(normalize_path(raw))
            # only allow listing inside configured workspace folders
            ws = get_workspace().get("folders", [])
            target_resolved = None
            try:
                target_resolved = target.resolve()
            except Exception:
                return self._send_json(400, {"error": "bad path"})
            allowed = False
            for f in ws:
                try:
                    root = Path(f).resolve()
                    if str(target_resolved).lower().startswith(str(root).lower()):
                        allowed = True
                        break
                except Exception:
                    continue
            if not allowed:
                return self._send_json(403, {"error": "path outside workspace"})
            if not target_resolved.exists() or not target_resolved.is_dir():
                return self._send_json(404, {"error": "not a directory"})
            entries = []
            try:
                for child in sorted(target_resolved.iterdir(), key=lambda p: (not p.is_dir(), p.name.lower())):
                    try:
                        is_dir = child.is_dir()
                        info = {
                            "name": child.name,
                            "path": str(child),
                            "is_dir": is_dir,
                            "size": 0 if is_dir else child.stat().st_size,
                            "ext": "" if is_dir else child.suffix.lstrip(".").lower(),
                        }
                        entries.append(info)
                    except Exception:
                        continue
            except PermissionError:
                return self._send_json(403, {"error": "permission denied"})
            return self._send_json(200, {"path": str(target_resolved), "entries": entries})
        if p == "/api/setup/sysinfo":
            info = detect_hardware_specs()
            return self._send_json(200, info)
        if p == "/api/setup/download-status":
            with DOWNLOAD_LOCK:
                return self._send_json(200, DOWNLOAD_STATE)
        if p == "/api/sandbox/status":
            return self._send_json(200, wsl_probe())
        if p == "/api/setup/detect":
            # Scan common locations for llama-server.exe and list available models for
            # the first-run setup wizard.
            s = get_settings()
            mdir = (s.get("models_dir") or "").strip()
            
            # Detect llama-server paths
            llama_paths = []
            explicit = (s.get("llama_bin") or "").strip()
            if explicit and safe_exists(explicit):
                llama_paths.append({"path": explicit, "found": True, "label": "Custom path (settings)"})
                
            # Auto-detect via find_llama_bin
            auto = find_llama_bin()
            if auto and not any(lp["path"] == auto for lp in llama_paths):
                llama_paths.append({"path": auto, "found": True, "label": "Auto-detected"})
                
            # Scan common fallback locations
            home = Path.home()
            candidates = [
                (home / ".unsloth/llama.cpp/build/bin/Release/llama-server.exe", "Unstable build (Release)"),
                (home / ".unsloth/llama.cpp/build/bin/llama-server.exe", "Unstable build"),
                (home / ".docker/bin/inference/llama-server.exe", "Docker inference"),
                (home / "llama.cpp/build/bin/Release/llama-server.exe", "llama.cpp Release"),
                (home / "llama.cpp/llama-server.exe", "llama.cpp root"),
                (Path("C:/llama.cpp/build/bin/Release/llama-server.exe"), "C:/llama.cpp Release"),
                (Path("C:/llama.cpp/llama-server.exe"), "C:/llama.cpp root"),
            ]
            for c, label in candidates:
                if safe_exists(c) and not any(lp["path"] == str(c) for lp in llama_paths):
                    llama_paths.append({"path": str(c), "found": True, "label": label})
                    
            # List models in the configured directory if any
            models = []
            if mdir and safe_exists(mdir):
                models = scan_gguf_dir(mdir)
                
            # If no models found in configured directory or models_dir is empty,
            # scan other drives/common folders to auto-suggest models
            auto_models = find_all_gguf_files()
            if not models and auto_models:
                models = auto_models
                # Suggest a default models_dir from the parent folder of the newest found model.
                if not mdir:
                    best_model_path = auto_models[0]["path"]
                    try:
                        mdir = str(Path(best_model_path).parent.resolve())
                    except Exception:
                        pass
                        
            return self._send_json(200, {
                "llama_paths": llama_paths,
                "models_dir": mdir,
                "models": models,
                "settings": s,
            })
        if p == "/api/github/status":
            cred = _github_cred()
            return self._send_json(200, {
                "connected": bool(cred.get("pat")),
                "login": cred.get("login", ""),
                "avatar_url": cred.get("avatar_url", ""),
            })
        if p == "/api/github/activity":
            return self._send_json(200, _github_activity())
        if p == "/api/github/repos":
            qs = urllib.parse.parse_qs(parsed.query)
            cursor = (qs.get("after", [""])[0] or "").strip()
            try:
                limit = int(qs.get("limit", ["12"])[0] or 12)
            except (TypeError, ValueError):
                limit = 12
            return self._send_json(200, _github_repositories(limit, cursor))
        return self._send_json(404, {"error": "not found"})

    def _handle_api_post(self, p: str, parsed):
        body = self._read_json()
        if p in {"/api/mcp/servers", "/api/mcp/servers/delete", "/api/mcp/servers/restart", "/api/mcp/import"}:
            # A server entry is a command this machine will run, so only the
            # desktop window (loopback) may change them; a paired Tailscale
            # device can look but not add.
            if not self._peer_is_loopback():
                return self._send_json(403, {"error": "MCP servers can only be changed on the machine running Accuretta."})
            try:
                if p == "/api/mcp/servers":
                    out = _mcp_save_server(body)
                elif p == "/api/mcp/servers/delete":
                    out = _mcp_delete_server(str(body.get("name") or ""))
                elif p == "/api/mcp/servers/restart":
                    out = _mcp_restart_server(str(body.get("name") or ""))
                else:
                    out = _mcp_import(body.get("text") or "")
            except ValueError as exc:
                return self._send_json(400, {"error": str(exc)})
            out["can_edit"] = True
            return self._send_json(200, out)
        if p == "/api/security/refresh":
            result = _security_overview.refresh()
            return self._send_json(202 if result.get("started") else 200, result)
        if p == "/api/security/summarize":
            result = _security_overview.summarize_now()
            return self._send_json(200 if result.get("ok") else 409, result)
        if p == "/api/security/whitelist":
            result = _security_overview.add_whitelist(
                str(body.get("alert_id") or ""),
                str(body.get("reason") or ""),
            )
            return self._send_json(200 if result.get("ok") else 400, result)
        if p == "/api/security/whitelist/remove":
            result = _security_overview.remove_whitelist(str(body.get("id") or ""))
            return self._send_json(200 if result.get("ok") else 404, result)
        if p == "/api/security/alerts/filter":
            result = _security_overview.filter_alert(
                str(body.get("alert_id") or ""), str(body.get("mode") or ""))
            return self._send_json(200 if result.get("ok") else 400, result)
        if p == "/api/security/alerts/restore":
            result = _security_overview.remove_alert_filter(str(body.get("id") or ""))
            return self._send_json(200 if result.get("ok") else 404, result)
        if p == "/api/security/investigate":
            result = _security_overview.investigate(str(body.get("alert_id") or ""))
            return self._send_json(200 if result.get("ok") else 400, result)
        if p == "/api/security/watchlist":
            conditions = body.get("conditions") if isinstance(body.get("conditions"), dict) else None
            result = _security_overview.add_process_watch(
                str(body.get("process_key") or ""),
                str(body.get("label") or ""),
                conditions,
                acknowledge_compute=body.get("acknowledge_compute") is True,
            )
            return self._send_json(200 if result.get("ok") else 400, result)
        if p == "/api/security/watchlist/remove":
            result = _security_overview.remove_process_watch(str(body.get("id") or ""))
            return self._send_json(200 if result.get("ok") else 404, result)
        if p == "/api/security/attention/ack":
            result = _security_overview.acknowledge_attention()
            return self._send_json(200, result)
        if p == "/api/setup/download-llama":
            build_type = body.get("build_type", "CPU")
            with DOWNLOAD_LOCK:
                if DOWNLOAD_STATE.get("status") in {"resolving", "downloading", "extracting"}:
                    return self._send_json(409, {"success": False, "error": "download already running"})
                DOWNLOAD_STATE.update({
                    "status": "resolving", "bytes_written": 0, "bytes_total": 0,
                    "speed": "0 KB/s", "error_msg": "", "release": "",
                })
            threading.Thread(target=download_and_extract_llama, args=(build_type,), daemon=True).start()
            return self._send_json(200, {"success": True})
        if p == "/api/sandbox/setup":
            return self._send_json(200, start_sandbox_setup(reinstall=bool(body.get("reinstall"))))
        if p == "/api/sandbox/test":
            return self._send_json(200, sandbox_selftest())
        if p == "/api/sandbox/remove":
            _wsl_run(["--terminate", SANDBOX_DISTRO], timeout=60)
            rc, out = _wsl_run(["--unregister", SANDBOX_DISTRO], timeout=120)
            try:
                if SANDBOX_STATE_FILE.exists():
                    SANDBOX_STATE_FILE.unlink()
            except Exception:
                pass
            _sbx_set(status="idle", step="", pct=0, error="", log=[])
            broadcast_event({"type": "sandbox:update"})
            return self._send_json(200, {"removed": rc == 0, "output": (out or "").strip()[:400]})
        if p == "/api/model-health/action":
            result = _model_health_action(
                str(body.get("action") or ""),
                str(body.get("recommendation_id") or ""),
            )
            return self._send_json(200 if result.get("ok") else 409, result)
        if p == "/api/github/validate":
            token = (body.get("token") or "").strip()
            if not token:
                return self._send_json(400, {"error": "token is required"})
            status, data = _github_rest("GET", "/user", token=token)
            if status != 200:
                return self._send_json(400, {"ok": False, "error": str(
                    data.get("message") or f"GitHub rejected the token (HTTP {status})")})
            login = str(data.get("login") or "")
            avatar = str(data.get("avatar_url") or "")
            _github_save_cred(token, login, avatar)
            return self._send_json(200, {"ok": True, "login": login, "avatar_url": avatar})
        if p == "/api/github/branch":
            owner = (body.get("owner") or "").strip()
            repo = (body.get("repo") or "").strip()
            branch = (body.get("branch") or "").strip()
            if not _GITHUB_OWNER_RE.fullmatch(owner) or not _GITHUB_REPO_RE.fullmatch(repo):
                return self._send_json(400, {"error": "invalid owner or repo name"})
            bname_err = _github_valid_branch_name(branch)
            if bname_err:
                return self._send_json(400, {"error": bname_err})
            result = _github_branch_flow(owner, repo, branch)
            return self._send_json(200 if result.get("ok") else 400, result)
        if p == "/api/github/project":
            result = _github_create_project(
                str(body.get("name") or ""),
                str(body.get("brief") or ""),
                str(body.get("workspace_root") or ""),
                body.get("publish") is True,
                body.get("private") is not False,
            )
            return self._send_json(200 if result.get("ok") else 400, result)
        if p == "/api/chat/note":
            result = _chat_note(str(body.get("chat_id") or ""), str(body.get("text") or ""))
            return self._send_json(200 if result.get("ok") else 400, result)
        if p == "/api/chat/goal":
            # Toggle the /goal hands-free latch for a chat without a turn. The
            # composer calls this for a bare "/goal" / "/goal off" and for the
            # chip's click-to-disable; the state is persisted and broadcast.
            cid = str(body.get("chat_id") or "").strip()[:64]
            if not cid:
                return self._send_json(400, {"error": "chat_id required"})
            active = _apply_goal_latch(cid, body.get("active") is True)
            return self._send_json(200, {"ok": True, "goal_mode": active})
        if p == "/api/ui/presence":
            # Notification-routing heartbeat: {id: tab id, focused: bool}. Sent only on
            # visibility changes or a 30 s visible-tab keepalive.
            client_id = str(body.get("id") or "").strip()
            if not client_id or len(client_id) > 64:
                return self._send_json(400, {"error": "presence id required"})
            _presence_notify.note_web(client_id, body.get("focused") is True)
            snapshot = _presence_notify.presence()
            snapshot["ok"] = True
            return self._send_json(200, snapshot)
        if p == "/api/ui/open-chat":
            # The notch's "Open in main app": the overlay host raises the
            # desktop window; this broadcast is what makes that window select
            # the session (an already-running pywebview window never sees a
            # browser deep-link).
            cid = str(body.get("chat_id") or "").strip()[:64]
            if not cid:
                return self._send_json(400, {"error": "chat_id required"})
            broadcast_event({"type": "ui:open-chat", "chat_id": cid})
            return self._send_json(200, {"ok": True})
        if p == "/api/settings":
            try:
                cur = update_settings(body)
            except ValueError as exc:
                return self._send_json(400, {"error": str(exc)})
            if {"security_scheduled", "security_interval_minutes", "security_notify_threshold"} & set(body):
                # live-apply scheduled-scan changes without a bridge restart
                _security_apply_schedule(cur)
            if "notch_enabled" in body:
                # live-apply the overlay toggle without a bridge restart
                notch_sync()
            broadcast_event({"type": "settings:update"})
            return self._send_json(200, cur)
        if p == "/api/remote/serve/enable":
            result = enable_tailscale_serve()
            return self._send_json(200 if result.get("ok") else 500, result)
        if p == "/api/remote/pair/prepare":
            result = prepare_remote_pairing(
                body.get("node_id") or "", body.get("username") or "",
                body.get("label") or "", body.get("allowed_roots"),
            )
            return self._send_json(200 if result.get("ok") else 400, result)
        if p == "/api/remote/pair/verify":
            result = verify_remote_pairing(body.get("machine_id") or "")
            return self._send_json(200 if result.get("ok") else 400, result)
        if p == "/api/remote/pair/remove":
            result = remove_remote_pairing(body.get("machine_id") or "")
            return self._send_json(200 if result.get("ok") else 404, result)
        if p == "/api/compact":
            # Manual compaction (the "compact now" button / model tool). Body: {chat_id}.
            # Folds the oldest turns into the rolling summary regardless of context fill.
            chat_id = (body.get("chat_id") or "").strip()
            if not chat_id:
                return self._send_json(400, {"error": "chat_id required"})
            return self._send_json(200, _compact_chat(chat_id, force=True))
        if p == "/api/workspace":
            folders = body.get("folders") or []
            folders = [normalize_path(f) for f in folders if isinstance(f, str) and f.strip()]
            save_json(WORKSPACE_FILE, {"folders": folders})
            resolved_ws = get_workspace()
            broadcast_event({"type": "workspace:update"})
            return self._send_json(200, resolved_ws)
        if p == "/api/save-to-workspace":
            # Save preview HTML straight to a workspace folder (the preview pane's "Save
            # to workspace" button), without another model round.
            # Body: {root: "<configured workspace folder>", filename: "x.html",
            #        html: "<!DOCTYPE...>", overwrite?: bool}
            root = (body.get("root") or "").strip()
            filename = (body.get("filename") or "").strip()
            html = body.get("html")
            overwrite = bool(body.get("overwrite"))
            if not root or not filename or not isinstance(html, str):
                return self._send_json(400, {"error": "root, filename, and html required"})
            # Filename safety: a bare name, no slashes or traversal. The extension is not
            # constrained (.html / .htm / .txt are all reasonable).
            if "/" in filename or "\\" in filename or ".." in filename:
                return self._send_json(400, {"error": "filename must be a bare name (no slashes, no ..)"})
            if not filename.strip("."):
                return self._send_json(400, {"error": "invalid filename"})
            # validate root against configured workspace
            configured = [normalize_path(f) for f in get_workspace().get("folders", [])]
            root_norm = normalize_path(root)
            if root_norm not in configured:
                return self._send_json(400, {"error": "root not in configured workspace folders"})
            try:
                root_path = Path(root_norm).resolve(strict=True)
            except Exception:
                return self._send_json(400, {"error": "workspace root unreadable"})
            target = (root_path / filename).resolve()
            # belt & braces: ensure the resolved target is still inside root
            try:
                target.relative_to(root_path)
            except ValueError:
                return self._send_json(400, {"error": "resolved path escapes workspace root"})
            if target.exists() and not overwrite:
                return self._send_json(409, {"error": "file exists", "path": str(target), "exists": True})
            try:
                target.write_text(html, encoding="utf-8")
                return self._send_json(200, {
                    "ok": True,
                    "path": str(target),
                    "bytes": len(html.encode("utf-8")),
                })
            except Exception as e:
                return self._send_json(500, {"error": str(e)})
        if p == "/api/py-check":
            # Pure syntax check: compile() validates structure without executing or
            # importing anything, and SyntaxError gives line/col/msg for the banner.
            # Accepts {root, path} (read from the workspace) or {code} (a raw snippet).
            code = body.get("code")
            file_label = "<snippet>"
            if code is None:
                root = body.get("root") or ""
                rel = body.get("path") or ""
                target, err = resolve_workspace_file(root, rel)
                if err:
                    return self._send_json(400, err)
                # 5 MB cap on Python files for the syntax check — anything
                # bigger is almost certainly not a real source file.
                try:
                    if target.stat().st_size > 5 * 1024 * 1024:
                        return self._send_json(413, {"error": "file too large for syntax check"})
                    code = target.read_text(encoding="utf-8", errors="replace")
                    file_label = target.name
                except Exception as e:
                    return self._send_json(500, {"error": f"read failed: {e}"})
            else:
                code = str(code)
            try:
                compile(code, file_label, "exec")
                return self._send_json(200, {
                    "ok": True,
                    "file": file_label,
                    "lines": code.count("\n") + 1,
                    "msg": "syntax OK",
                })
            except SyntaxError as e:
                return self._send_json(200, {
                    "ok": False,
                    "file": file_label,
                    "line": e.lineno,
                    "col": e.offset,
                    "end_line": getattr(e, "end_lineno", None),
                    "end_col": getattr(e, "end_offset", None),
                    "msg": e.msg,
                    "hint": (e.text or "").rstrip("\n"),
                })
            except ValueError as e:
                # null bytes in source etc.
                return self._send_json(200, {"ok": False, "file": file_label, "msg": str(e)})
        if p == "/api/llama/auto-tune":
            # POST {model_path?, vram_gb, min_ctx?} -> suggested llama-server
            # settings. If model_path is omitted, uses the currently configured
            # model_path from settings. If vram_gb is omitted or 0, tries
            # nvidia-smi. min_ctx makes context grow-only: the tuner honors a
            # saved ctx larger than its pick when it still fits the budget.
            mp = (body.get("model_path") or get_settings().get("model_path") or "").strip()
            vram = float(body.get("vram_gb") or 0)
            min_ctx = int(body.get("min_ctx") or 0)
            detected = None
            if vram <= 0:
                detected = detect_vram_gb()
                vram = float(detected.get("free_total_gb") or detected.get("gb") or 0)
                try:
                    _ram_mb, _vram_mb = _running_instance_mem_mb()
                    if _vram_mb > 0:
                        # A save+reload follows the suggest — that swap frees
                        # the running instance's VRAM before the new load.
                        vram += _vram_mb / 1024.0
                except Exception:
                    pass
            profile = inspect_model(mp)
            suggested = auto_tune(mp, vram, profile=profile, min_ctx=min_ctx,
                                  proven_cfg=_proven_cfg(mp))
            suggested = _preserve_manual_model_spec(mp, suggested)
            # Remember the tune for this model — the next /api/models/load
            # restores it without re-running the tuner.
            if mp and suggested.get("num_ctx"):
                _save_model_config(mp, suggested)
            return self._send_json(200, {
                "vram_gb": vram,
                "vram_source": (detected or {}).get("source", "user"),
                "vram_name": (detected or {}).get("name", ""),
                "model": profile,
                "suggested": suggested,
            })
        if p == "/api/browse-folder":
            # native OS folder picker, only on the machine running the bridge.
            title = (body.get("title") or "Pick a folder").strip()
            try:
                import tkinter as tk
                from tkinter import filedialog
                root = tk.Tk()
                root.withdraw()
                root.attributes("-topmost", True)
                path = filedialog.askdirectory(title=title)
                root.destroy()
                return self._send_json(200, {"path": path or ""})
            except Exception as e:
                return self._send_json(200, {"path": "", "error": str(e)})
        if p == "/api/models/browse-mmproj":
            title = "Pick a vision projector GGUF"
            model_path = str(body.get("model_path") or "").strip()
            initial_dir = str(Path(model_path).parent) if model_path else ""
            try:
                import tkinter as tk
                from tkinter import filedialog
                root = tk.Tk()
                root.withdraw()
                root.attributes("-topmost", True)
                path = filedialog.askopenfilename(
                    title=title,
                    initialdir=initial_dir or None,
                    filetypes=[("GGUF projector", "*.gguf"), ("All files", "*.*")],
                )
                root.destroy()
                if path and Path(path).suffix.lower() != ".gguf":
                    return self._send_json(400, {"error": "projector must be a .gguf file"})
                return self._send_json(200, {"path": path or ""})
            except Exception as e:
                return self._send_json(200, {"path": "", "error": str(e)})
        if p == "/api/models/browse-spec-draft":
            model_path = str(body.get("model_path") or "").strip()
            initial_dir = str(Path(model_path).parent) if model_path else ""
            try:
                import tkinter as tk
                from tkinter import filedialog
                root = tk.Tk()
                root.withdraw()
                root.attributes("-topmost", True)
                path = filedialog.askopenfilename(
                    title="Pick a DFlash or DSpark draft GGUF",
                    initialdir=initial_dir or None,
                    filetypes=[("GGUF draft model", "*.gguf"), ("All files", "*.*")],
                )
                root.destroy()
                if path and Path(path).suffix.lower() != ".gguf":
                    return self._send_json(400, {"error": "draft model must be a .gguf file"})
                return self._send_json(200, {"path": path or ""})
            except Exception as e:
                return self._send_json(200, {"path": "", "error": str(e)})
        if p == "/api/models/scan-dir":
            # Save settings.models_dir and immediately return the scan.
            new_dir = (body.get("path") or "").strip()
            if new_dir and not Path(new_dir).is_dir():
                return self._send_json(400, {"error": f"not a directory: {new_dir}"})
            s = get_settings()
            s["models_dir"] = new_dir
            save_json(SETTINGS_FILE, s)
            files = scan_gguf_dir(new_dir)
            loaded = _llama.loaded_model() or s.get("model_path") or ""
            for f in files:
                f["loaded"] = (f["path"] == loaded)
            broadcast_event({"type": "models:update"})
            return self._send_json(200, {
                "models_dir": new_dir,
                "loaded_model": loaded,
                "models": files,
            })
        if p == "/api/session/send":
            # The human operator typing into the shared session — no approval
            # gate here (that's the user at their own keyboard, not the model).
            sid = (body.get("id") or body.get("session_id") or "").strip()
            s = _session_mgr.get(sid)
            if not s:
                return self._send_json(404, {"error": "no such session"})
            ok = s.send(str(body.get("input", "")), enter=bool(body.get("enter", True)))
            return self._send_json(200, {"ok": ok, "alive": s.alive()})
        if p == "/api/session/stop":
            sid = (body.get("id") or body.get("session_id") or "").strip()
            return self._send_json(200, {"stopped": _session_mgr.stop(sid)})
        if p == "/api/models/unload-draft":
            # Explicit decoder unload: drop the DFlash/DSpark sidecar so its
            # VRAM goes back to context, auto-apply the best draft-less
            # strategy (source stays auto, so the user can change it later),
            # and retune immediately so the regrown ctx is visible before the
            # reload the UI triggers next.
            try:
                want = (body.get("model_path") or "").strip() if isinstance(body, dict) else ""
            except Exception:
                want = ""
            s = get_settings()
            if not want:
                want = (s.get("model_path") or "").strip() or _llama.loaded_model()
            if not want or not safe_exists(want):
                return self._send_json(400, {"error": "no model file to unload the draft for"})
            try:
                update_settings({
                    "spec_draft_model": "",
                    "spec_draft_mode": "off",
                    "spec_strategy_source": "auto",
                })
            except Exception as exc:
                return self._send_json(400, {"error": str(exc)})
            tune_applied = False
            tune_notes: list = []
            try:
                vram = float(get_settings().get("vram_tier_gb") or 0)
                if vram <= 0:
                    vram = _free_vram_gb_for_tune()
                if vram > 0:
                    profile = inspect_model(want)
                    suggested = auto_tune(want, vram, profile=profile)
                    if suggested.get("num_ctx"):
                        suggested["spec_strategy_source"] = "auto"
                        s2 = get_settings()
                        for k in _MODEL_TUNE_KEYS:
                            if k in suggested:
                                s2[k] = suggested[k]
                        save_json(SETTINGS_FILE, s2)
                        _save_model_config(want, suggested)
                        tune_applied = True
                        tune_notes = suggested.get("notes", "")
            except Exception:
                traceback.print_exc()
            try:
                # The cleared draft must also be forgotten per-model; on tune
                # failure drop the stale draft-sized tune keys too, so the
                # next load retunes fresh instead of restoring them.
                if not tune_applied:
                    try:
                        allc = _models_config()
                        ent = allc.get(want)
                        if isinstance(ent, dict):
                            for k in _MODEL_TUNE_KEYS:
                                ent.pop(k, None)
                            save_json(MODELS_CONFIG_FILE, allc)
                    except Exception:
                        pass
                _save_model_config(want, {"spec_draft_model": ""})
            except Exception:
                pass
            fin = get_settings()
            return self._send_json(200, {
                "ok": True,
                "model_path": want,
                "spec_draft_model": "",
                "spec_draft_mode": "off",
                "spec_strategy": fin.get("spec_strategy"),
                "spec_strategy_source": "auto",
                "num_ctx": fin.get("num_ctx"),
                "tune_applied": tune_applied,
                "suggested": {k: fin.get(k) for k in (
                    "num_ctx", "num_gpu", "num_batch", "n_ubatch", "n_cpu_moe",
                    "num_thread", "kv_cache_type", "kv_cache_type_v",
                    "flash_attn", "spec_strategy")},
                "notes": tune_notes,
            })
        if p == "/api/models/load":
            # Switch the active model. Kills current llama-server, spawns new.
            target = (body.get("path") or "").strip()
            if not target:
                return self._send_json(400, {"error": "path required"})
            if not safe_exists(target):
                return self._send_json(400, {"error": f"file not found: {target}"})

            # Per-model config memory + auto-tune on load: restore this model's tuned
            # flags (or compute them on first load) before the spawn reads settings, so
            # no model inherits the previous one's config.
            target_cfg = _models_config().get(target)
            target_cfg = target_cfg if isinstance(target_cfg, dict) else {}
            _auto_tune_for_load(target)
            _sampling_swap = _apply_model_sampling(target)
            if _sampling_swap:
                print(f"[llama] sampling: {'model profile applied' if _sampling_swap == 'profile' else 'baseline restored'}"
                      f" for {os.path.basename(target)}", file=sys.stderr)

            s = get_settings()
            if target != _llama.loaded_model():
                # Restore a projector choice remembered for this model. For a
                # new model with no projector profile, never carry a manual
                # path across: an incompatible projector can crash at startup.
                if not any(k in target_cfg for k in _MODEL_PROJECTOR_KEYS):
                    mode = _normalized_mmproj_mode(s)
                    if mode == "manual":
                        s["mmproj_mode"] = "off"
                        s["mmproj_auto"] = False
                        s["mmproj_path"] = ""
                        save_json(SETTINGS_FILE, s)
                
            # Big models load slowly from a cold disk (a 24 GB GGUF on an HDD takes 5-8
            # min before llama-server answers), so scale the wait with file size: floor
            # 120s, cap 15 min.
            try:
                _sz_gb = os.path.getsize(target) / 1e9
            except Exception:
                _sz_gb = 0.0
            wait_s = max(120, min(900, int(_sz_gb * 20)))
            res = _llama.start(target, wait_seconds=wait_s)
            if res.get("ok"):
                s = get_settings()
                s["model_path"] = target
                # The model id sent to llama-server is the file's stem (any id works; this
                # one reads well in logs and the UI).
                s["model"] = Path(target).stem
                save_json(SETTINGS_FILE, s)
                _start_vision_fallback_if_needed(s)
                broadcast_event({"type": "models:update", "loaded_model": target})
                # Compile the tool-call grammar now (background) so the first real turn
                # emits structured tool_calls (see _warmup_tool_grammar). Skipped for Gemma,
                # which runs text-tools.
                if not _is_gemma_model(s.get("model") or target):
                    threading.Thread(target=_warmup_tool_grammar, daemon=True).start()
            elif _sampling_swap:
                # model_path still names the previous model: give it its
                # sampling back rather than leave the failed target's profile.
                _apply_model_sampling(str(get_settings().get("model_path") or ""))
            return self._send_json(200 if res.get("ok") else 500, res)
        if p == "/api/models/stop":
            # User-initiated stop also tells the watchdog to leave it down; the next
            # /api/models/load re-arms it.
            _llama.stop_permanent()
            _vision_llama.stop_permanent()
            broadcast_event({"type": "models:update", "loaded_model": ""})
            return self._send_json(200, {"ok": True})
        if p == "/api/models/watchdog":
            return self._send_json(200, _llama.watchdog_status())
        if p == "/api/models/probe-mmproj":
            # Settings auto-detect: is there a vision projector next to this model?
            # Returns the resolved path or "".
            target = (body.get("path") or "").strip()
            if not target:
                # default to the currently loaded / configured model
                target = _llama.loaded_model() or (get_settings().get("model_path") or "")
            mmproj = find_mmproj_for(target) if target else ""
            reason = ""
            if not mmproj:
                if not target or not safe_exists(target):
                    reason = "the selected chat model file is missing"
                else:
                    nearby = []
                    mp = Path(target)
                    for folder in (mp.parent, mp.parent.parent):
                        try:
                            nearby.extend(p.name for p in folder.glob("*.gguf")
                                          if _is_mmproj_name(p.name))
                        except Exception:
                            pass
                    reason = (
                        "projector candidates were found, but their names are too ambiguous to pair safely; choose the file manually"
                        if nearby else
                        "no projector-named .gguf file was found beside the selected model"
                    )
            return self._send_json(200, {
                "ok": True,
                "model_path": target,
                "mmproj_path": mmproj,
                "reason": reason,
            })
        if p == "/api/chats":
            chat_id = body.get("id") or uuid.uuid4().hex[:12]
            chats = get_chats()
            if chat_id not in chats["chats"]:
                # `origin` records where the session was started. The chat list
                # uses it to distinguish mobile and GitHub worktree sessions.
                origin = (body.get("origin") or "desktop").strip().lower()
                if origin not in ("mobile", "desktop", "github", "project", "security"):
                    origin = "desktop"
                security_context = None
                security_alert_id = str(body.get("security_alert_id") or "").strip()
                if security_alert_id:
                    resolved = _security_overview.investigation_context(security_alert_id)
                    if not resolved.get("ok"):
                        return self._send_json(404, {"error": resolved.get("error") or "Alert not found."})
                    security_context = resolved["context"]
                    origin = "security"
                record = {
                    "id": chat_id,
                    "title": (
                        f"Investigate: {security_context.get('title') or security_context.get('entity') or 'security alert'}"
                        if security_context else str(body.get("title") or "new session")
                    )[:180],
                    "created": int(time.time()),
                    "updated": int(time.time()),
                    "messages": [],
                    "origin": origin,
                }
                if security_context:
                    record["security_investigation"] = security_context
                worktree = _github_worktree_metadata(body.get("github_worktree"))
                if worktree:
                    record["github_worktree"] = worktree
                project = _project_workspace_metadata(body.get("project_workspace"))
                if project:
                    record["project_workspace"] = project
                chats["chats"][chat_id] = record
                if chat_id in chats["order"]:
                    chats["order"].remove(chat_id)
                chats["order"].insert(0, chat_id)
                save_json(CHATS_FILE, chats)
            return self._send_json(200, chats["chats"][chat_id])
        if p.startswith("/api/chats/") and p.endswith("/rename"):
            cid = p.split("/")[3]
            chats = get_chats()
            if cid in chats["chats"]:
                chats["chats"][cid]["title"] = (body.get("title") or "").strip() or chats["chats"][cid]["title"]
                save_json(CHATS_FILE, chats)
                return self._send_json(200, chats["chats"][cid])
            return self._send_json(404, {"error": "not found"})
        if p.startswith("/api/chats/") and p.endswith("/mode"):
            cid = p.split("/")[3]
            raw_mode = str(body.get("mode") or "").strip().lower()
            if raw_mode not in {"auto", "agent", "ide", "research"}:
                return self._send_json(400, {"error": "invalid chat mode"})
            mode = _normalize_composer_mode(raw_mode)
            chats = get_chats()
            if cid in chats["chats"]:
                chats["chats"][cid]["last_mode"] = mode
                save_json(CHATS_FILE, chats)
                return self._send_json(200, {"ok": True, "mode": mode})
            return self._send_json(404, {"error": "not found"})
        if p.startswith("/api/chats/") and p.endswith("/project"):
            cid = p.split("/")[3]
            chats = get_chats()
            if cid in chats["chats"]:
                raw_project = body.get("project_workspace")
                if raw_project is None:
                    chats["chats"][cid].pop("project_workspace", None)
                else:
                    project = _project_workspace_metadata(raw_project)
                    if not project:
                        return self._send_json(400, {"error": "choose a folder inside a configured workspace folder"})
                    chats["chats"][cid]["project_workspace"] = project
                save_json(CHATS_FILE, chats)
                return self._send_json(200, chats["chats"][cid])
            return self._send_json(404, {"error": "not found"})
        if p == "/api/approvals/decide":
            ok = decide_approval(body.get("id") or "", body.get("decision") or "deny",
                                 always=bool(body.get("always")))
            return self._send_json(200 if ok else 404, {"ok": ok})
        if p == "/api/notch/reg-query":
            # Read-only helper for the notch overlay's registry-gate diff view.
            # Parses the pending command, reads the CURRENT value with
            # `reg query` (never executes the pending command itself).
            cmd = str(body.get("command") or "")
            if len(cmd) > 4096:
                return self._send_json(400, {"error": "command too long"})
            return self._send_json(200, _notch_registry_diff(cmd))
        if p == "/api/undo":
            return self._send_json(200, _undo_restore(body.get("turn_id") or "", chat_id=body.get("chat_id") or "", file_index=body.get("file_index")))
        if p == "/api/investigation-review":
            chat_id = str(body.get("chat_id") or "")
            chat = get_chats().get("chats", {}).get(chat_id)
            if not chat:
                return self._send_json(404, {"error": "Session not found"})
            mission = chat.get("mission") or {}
            mission_id = str(mission.get("authorization_id") or "")
            if not mission_id:
                return self._send_json(200, {"mission": mission, "findings": [], "planned_checks": [], "observations": [], "total": 0})
            store = EvidenceStore(DATA / "recon_evidence" / "receipts")
            try:
                if body.get("evidence_id"):
                    return self._send_json(200, {"evidence": store.read(chat_id, mission_id, str(body["evidence_id"]))})
                offset = max(0, int(body.get("offset") or 0))
                return self._send_json(200, {"mission": mission,
                    "findings": [f for f in chat.get("findings", []) if f.get("mission_id") == mission_id],
                    "planned_checks": [p for p in chat.get("security_coverage", []) if p.get("mission_id") == mission_id],
                    **store.coverage(chat_id, mission_id, offset=offset)})
            except (ValueError, OSError) as exc:
                return self._send_json(400, {"error": str(exc)})
        if p == "/api/task-review":
            result = _undo_store.review(body.get("turn_id"), body.get("chat_id"), body.get("file_index"))
            return self._send_json(404 if result.get("error") else 200, result)
        if p == "/api/open-folder":
            return self._send_json(200, _open_folder_in_file_manager(body.get("path") or ""))
        if p == "/api/tools/call":
            job_id = uuid.uuid4().hex[:12]
            name = body.get("name") or ""
            args = body.get("arguments") or {}

            def _do_job():
                with _tool_jobs_lock:
                    _tool_jobs[job_id]["status"] = "running"
                try:
                    result = invoke_tool(name, args)
                    with _tool_jobs_lock:
                        _tool_jobs[job_id]["status"] = "done"
                        _tool_jobs[job_id]["result"] = result
                except Exception as e:
                    with _tool_jobs_lock:
                        _tool_jobs[job_id]["status"] = "error"
                        _tool_jobs[job_id]["result"] = {"error": str(e)}
                finally:
                    with _tool_jobs_lock:
                        _tool_jobs[job_id]["finished"] = int(time.time())

            with _tool_jobs_lock:
                _tool_jobs[job_id] = {
                    "id": job_id,
                    "status": "queued",
                    "name": name,
                    "started": int(time.time()),
                    "finished": None,
                    "result": None,
                }
            _tool_executor.submit(_do_job)
            return self._send_json(202, {"job_id": job_id, "status": "queued"})
        if p == "/api/skills/clear":
            # Unload the active skill for a chat (route form of
            # load_skill with an empty name — emits skill:cleared to SSE).
            return self._send_json(200, tool_load_skill({"name": "", "chat_id": body.get("chat_id") or ""}))
        if p == "/api/chat":
            return self._handle_chat(body)
        if p == "/api/shutdown":
            save = bool(body.get("save"))
            if save:
                messages = body.get("messages") or []
                text_history = []
                for m in messages:
                    role = m.get("role", "")
                    if role in ("user", "assistant"):
                        text_history.append(f"{role.upper()}: {m.get('content')}")
                history_str = "\n\n".join(text_history)[-20000:]
                
                prompt = (
                    "System: You are a summarizer. Summarize this session in 1-3 sentences. "
                    "Focus on what was worked on, any decisions made, and unresolved threads. Be concise.\n\n"
                    "Conversation:\n" + history_str + "\n\n"
                    "Provide your response exactly in this format:\n"
                    "SUMMARY: <your 1-3 sentence summary>\n"
                    "TAGS: <tag1>, <tag2>, <tag3>\n"
                )
                
                settings = get_settings()
                payload = {
                    "model": settings.get("model", ""),
                    "messages": [{"role": "user", "content": prompt}],
                    "temperature": 0.3,
                    "max_tokens": 1500,
                    "stream": False,
                }
                try:
                    res = llama_post("/v1/chat/completions", payload, timeout=120)
                    content = res.get("choices", [{}])[0].get("message", {}).get("content", "")
                    summary = ""
                    tags = []
                    lines = content.strip().split("\n")
                    for line in lines:
                        if line.startswith("SUMMARY:"):
                            summary = line.replace("SUMMARY:", "").strip()
                        elif line.startswith("TAGS:"):
                            tags_str = line.replace("TAGS:", "").strip()
                            tags = [t.strip() for t in tags_str.split(",") if t.strip()]
                    
                    if not summary:
                        summary = content.strip()
                    if not summary:
                        raise ValueError("The model returned an empty session summary")

                    if summary:
                        with _memory_store.lock:
                            memories = _load_memories()
                            new_mem = {
                                "id": uuid.uuid4().hex[:12],
                                "text": summary,
                                "kind": "fact",
                                "tags": tags,
                                "created": int(time.time()),
                                "use_count": 0
                            }
                            memories.append(new_mem)
                            _save_memories(memories)
                except Exception as e:
                    print("Shutdown summary error:", e)
                    return self._send_json(500, {"ok": False, "error": "Could not save the session summary. Retry or choose Close Without Saving."})
            
            def hard_exit():
                time.sleep(1)
                _shutdown_ready.set()
                try:
                    _llama.stop()
                    _vision_llama.stop()
                except:
                    pass
                os._exit(0)
            threading.Thread(target=hard_exit, daemon=True).start()
            return self._send_json(200, {"ok": True})
        if p == "/api/chat/steer-status":
            cid, message_id = body.get("chat_id"), body.get("id")
            if not isinstance(cid, str) or not isinstance(message_id, str):
                return self._send_json(400, {"error": "chat_id and id required"})
            return self._send_json(200, {"status": _steering.status(cid, message_id)})
        if p == "/api/chat/steer":
            cid, message_id, text = body.get("chat_id"), body.get("id"), body.get("text", "")
            images = body.get("images") or []
            if (not isinstance(cid, str) or not isinstance(message_id, str) or not 1 <= len(message_id) <= 80
                    or not isinstance(text, str) or len(text) > 100000
                    or not isinstance(images, list) or len(images) > 8
                    or any(not isinstance(img, str) or not img.startswith("data:image/") for img in images)
                    or not (text.strip() or images)):
                return self._send_json(400, {"error": "Invalid task update"})
            if images and not _llama.is_vision_capable():
                return self._send_json(400, {"error": "The current model cannot read images. Send text or a file instead."})
            status = _steering.submit(cid, {"id": message_id, "text": text, "images": images})
            return self._send_json(409 if status == "inactive" else 429 if status == "full" else 200,
                                   {"status": status})
        if p == "/api/cancel":
            cid = (body.get("chat_id") or "").strip()
            if not cid:
                return self._send_json(400, {"error": "chat_id required"})
            ok = cancel_chat(cid)
            return self._send_json(200, {"ok": ok, "chat_id": cid})
        if p == "/api/kill-command":
            # Kill JUST the shell command running for this chat (not the turn).
            cid = (body.get("chat_id") or "").strip()
            if not cid:
                return self._send_json(400, {"error": "chat_id required"})
            ok = _kill_current_command(cid)
            return self._send_json(200, {"ok": ok, "chat_id": cid})
        if p == "/api/prewarm":
            # llama-server keeps the model resident after startup, so "prewarm"
            # is just a 1-token ping that forces any lazy mmap to fault in.
            model = (body.get("model") or "local").strip() or "local"
            try:
                payload = {
                    "model": model,
                    "messages": [{"role": "user", "content": "ok"}],
                    "max_tokens": 1,
                    "stream": False,
                }
                llama_post("/v1/chat/completions", payload, timeout=120)
                # Also compile the tool-call grammar so the first tool-using turn
                # is clean (see _warmup_tool_grammar). Background; non-Gemma only.
                if not _is_gemma_model(get_settings().get("model") or model):
                    threading.Thread(target=_warmup_tool_grammar, daemon=True).start()
                return self._send_json(200, {"ok": True, "model": model})
            except Exception as e:
                return self._send_json(200, {"ok": False, "error": str(e)})
        if p == "/api/desktop/panic":
            _desktop_panic.set()
            # deny every pending approval so any in-flight action unblocks fast
            with _approvals_lock:
                pending = [a["id"] for a in _approvals.values() if a.get("status") == "pending"]
            for aid in pending:
                decide_approval(aid, "deny")
            broadcast_event({"type": "desktop:panic", "on": True})
            return self._send_json(200, {"ok": True, "panic": True})
        if p == "/api/desktop/resume":
            _desktop_panic.clear()
            broadcast_event({"type": "desktop:panic", "on": False})
            return self._send_json(200, {"ok": True, "panic": False})
        if p == "/api/memories/edit":
            r = tool_edit_memory(body)
            return self._send_json(400 if r.get("error") else 200, r)
        if p == "/api/memories/forget":
            mid = (body.get("id") or "").strip()
            if not mid:
                return self._send_json(400, {"error": "id required"})
            r = tool_forget({"id": mid})
            broadcast_event({"type": "memories:update"})
            return self._send_json(200, r)
        if p == "/api/memories/clear":
            try:
                _save_memories([])
                broadcast_event({"type": "memories:update"})
                return self._send_json(200, {"ok": True})
            except Exception as e:
                return self._send_json(500, {"error": str(e)})
        if p == "/api/memories":
            # manual add from the memories panel in Settings
            text = (body.get("text") or "").strip()
            tags = body.get("tags") or []
            if not text:
                return self._send_json(400, {"error": "text required"})
            r = tool_remember({"text": text, "kind": body.get("kind", "fact"), "tags": tags if isinstance(tags, list) else []})
            broadcast_event({"type": "memories:update"})
            return self._send_json(400 if r.get("error") else 200, r)
        if p == "/api/client-error":
            try:
                _error_store.record("interface", str(body.get("type") or "Error")[:80],
                                    str(body.get("message") or "")[:500],
                                    str(body.get("location") or "interface")[:120],
                                    str(body.get("trace") or ""))
            except Exception:
                pass
            return self._send_json(200, {"ok": True})
        if p == "/api/errors/clear":
            try:
                return self._send_json(200, _error_store.clear())
            except Exception as e:
                return self._send_json(500, {"error": str(e)})
        if p == "/api/errors/report":
            try:
                result = _error_store.report(str(body.get("id") or ""))
            except Exception as e:
                return self._send_json(500, {"error": str(e)})
            return self._send_json(404 if result.get("error") else 200, result)
        if p == "/api/snapshots":
            # save the currently-rendered preview html (or any html blob the
            # client wants to keep) to data/snapshots/ with a safe filename.
            raw_name = (body.get("name") or "snapshot").strip()
            html = body.get("html") or ""
            if not html:
                return self._send_json(400, {"error": "html required"})
            safe = re.sub(r"[^A-Za-z0-9._-]+", "-", raw_name)[:60] or "snapshot"
            if not safe.lower().endswith(".html"):
                safe = safe + ".html"
            ts = time.strftime("%Y%m%d-%H%M%S")
            final_name = f"{ts}-{safe}"
            out_path = SNAPSHOTS_DIR / final_name
            out_path.write_text(html, encoding="utf-8")
            return self._send_json(200, {
                "ok": True,
                "name": final_name,
                "path": str(out_path),
                "url": f"/api/snapshots/{final_name}",
            })
        if p == "/api/desktop/chat-toggle":
            cid = (body.get("chat_id") or "").strip()
            if not cid:
                return self._send_json(400, {"error": "chat_id required"})
            disabled = bool(body.get("disabled"))
            if disabled:
                _chat_desktop_disabled.add(cid)
            else:
                _chat_desktop_disabled.discard(cid)
            return self._send_json(200, {"chat_id": cid, "disabled": disabled})
        if p == "/api/system-context/refresh":
            try:
                md = rescan_system_context()
                broadcast_event({"type": "system-context:update"})
                return self._send_json(200, {"md": md, "path": str(SYSTEM_CONTEXT_FILE)})
            except Exception as e:
                return self._send_json(500, {"error": str(e)})
        if p == "/api/system-context":
            md = (body.get("md") or "").strip()
            if not md:
                return self._send_json(400, {"error": "md empty"})
            try:
                SYSTEM_CONTEXT_FILE.parent.mkdir(parents=True, exist_ok=True)
                SYSTEM_CONTEXT_FILE.write_text(md + "\n", encoding="utf-8")
                broadcast_event({"type": "system-context:update"})
                return self._send_json(200, {"md": md, "path": str(SYSTEM_CONTEXT_FILE)})
            except Exception as e:
                return self._send_json(500, {"error": str(e)})
        return self._send_json(404, {"error": "not found"})

    # ---- SSE

    def _serve_sse(self):
        # Reconnect support: EventSource resends Last-Event-ID after a drop. Replay
        # missed events from the ring buffer, then resume live. The subscribe()
        # snapshot id is the cut-off: newer events arrive via the queue, older ones
        # were seen already or rolled off the buffer (a `lost` marker says so).
        last_id = 0
        raw = (self.headers.get("Last-Event-ID") or "").strip()
        if raw.isdigit():
            try:
                last_id = int(raw)
            except Exception:
                last_id = 0

        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.send_header("Cache-Control", "no-cache, no-transform")
        self.send_header("X-Accel-Buffering", "no")
        self.send_header("Connection", "keep-alive")
        self._set_cors()
        self.end_headers()
        q, snapshot_id = subscribe()
        try:
            # Hello includes the snapshot id so the client can detect a
            # bridge restart (snapshot_id reset to a small number).
            self._sse_send(
                {"type": "hello", "t": int(time.time()),
                 "snapshot_id": snapshot_id,
                 "replayed_from": last_id if last_id else None},
                evt_id=snapshot_id or None,
            )
            # Replay missed events.
            if last_id and last_id < snapshot_id:
                missed = replay_events_since(last_id, snapshot_id)
                if missed:
                    # If the gap exceeds the buffer, the oldest replayed id is > last_id + 1;
                    # flag it so the client can decide whether to reload.
                    oldest_replayed = missed[0][0]
                    if oldest_replayed > last_id + 1:
                        self._sse_send({
                            "type": "events:gap",
                            "lost_from": last_id + 1,
                            "lost_to": oldest_replayed - 1,
                            "note": "bridge buffer overflowed during disconnect; some events were lost",
                        })
                    for evt_id, evt in missed:
                        self._sse_send(evt, evt_id=evt_id)
            # Pending approvals are *state*, not history — always re-emit
            # so a fresh tab finds them even if the original event aged out.
            for a in list_approvals():
                self._sse_send({"type": "approval:new", "approval": a})
            # An in-flight fold's start event is transient and not in the resume ring, so
            # re-emit it on every (re)connect; a late client still draws the compaction
            # row.
            for fold_chat_id in list_inflight_folds():
                self._sse_send({"type": "summary_folding", "chat_id": fold_chat_id})
            last_ping = time.time()
            while True:
                try:
                    evt = q.get(timeout=15)
                    self._sse_send(evt, evt_id=evt.get("_id"))
                except Empty:
                    if time.time() - last_ping > 14:
                        try:
                            # A named heartbeat reaches JavaScript (a bare
                            # comment ping does not), so the client can tell a
                            # live stream from a silently dead one.
                            self._sse_send({"type": "heartbeat", "t": int(time.time())})
                            last_ping = time.time()
                        except Exception:
                            break
        except Exception:
            pass
        finally:
            unsubscribe(q)

    def _sse_send(self, obj: dict, evt_id: int = None):
        try:
            if evt_id is not None and evt_id > 0:
                self.wfile.write(f"id: {evt_id}\n".encode("utf-8"))
            self.wfile.write(b"data: ")
            self.wfile.write(json.dumps(obj, ensure_ascii=False).encode("utf-8"))
            self.wfile.write(b"\n\n")
            self.wfile.flush()
        except Exception:
            raise

    # ---- chat streaming endpoint

    def _handle_chat(self, body: dict):
        chat_id = body.get("chat_id") or uuid.uuid4().hex[:12]
        user_text = (body.get("message") or "").strip()
        # /goal latch command: strip it from the task text so the model sees a
        # clean instruction. goal_action is "on" | "off" | None.
        user_text, goal_action = _parse_goal_command(user_text)
        raw_mode = str(body.get("mode") or "agent").strip().lower()
        if raw_mode not in {"auto", "ide", "agent", "research"}:
            return self._send_json(400, {"error": "invalid chat mode"})
        mode = _normalize_composer_mode(raw_mode)
        images = body.get("images") or []  # list of base64 data URLs
        research_request = None
        resume_research_id = str(body.get("research_id") or "")
        if mode == "research":
            try:
                previous_brief = None
                if resume_research_id:
                    if chat_id in _research_runs:
                        return self._send_json(409, {"error": "This research is already running."})
                    previous_brief = _research_store.get(resume_research_id, chat_id)["brief"]
                if body.get("regenerate"):
                    previous_chat = get_chats().get("chats", {}).get(chat_id, {})
                    previous_user = next((m for m in reversed(previous_chat.get("messages", [])) if m.get("role") == "user"), {})
                    if user_text:
                        # edit & resend: the replacement text wins for the brief topic
                        previous_brief = previous_user.get("_research_brief") or {"topic": user_text}
                    else:
                        previous_brief = previous_user.get("_research_brief") or {"topic": previous_user.get("content")}
                research_request = research_brief(previous_brief or body.get("research_brief") or {"topic": user_text})
            except (ValueError, OSError) as error:
                return self._send_json(400, {"error": str(error)})
            if body.get("mission"):
                return self._send_json(400, {"error": "Research and red-team missions are separate modes."})
        regenerate = bool(body.get("regenerate"))
        # A surface that omits the effort (the notch composer) must not reset the
        # user's choice to "auto"; fall back to the saved setting.
        _effort = body.get("reasoning_effort")
        if _effort is None or not str(_effort).strip():
            _effort = get_settings().get("reasoning_effort")
        reasoning_effort = _normalize_reasoning_effort(_effort)
        client_ctx = _handler_client_context(self, body.get("client_context"))
        _client_context_by_chat[chat_id] = client_ctx
        if client_ctx.get("execution_target") != "host":
            _unlock_bundle(chat_id, "remote")
        # Bare "/goal" (or "/goal off") with no task: a latch toggle, not a
        # turn. Flip the hands-free latch and acknowledge over plain JSON — no
        # model call, no chat bubble. "/goal <task>" falls through and runs.
        if goal_action and not user_text and not images and not regenerate:
            active = _apply_goal_latch(chat_id, goal_action == "on")
            return self._send_json(200, {"ok": True, "goal_mode": active,
                "message": ("Goal mode on — this chat runs hands-free. Deletions and destructive actions still ask."
                            if active else
                            "Goal mode off — back to your standing permission mode.")})
        if not user_text and not images and not regenerate:
            return self._send_json(400, {"error": "empty message"})
        mission_panel = body.get("mission")
        if mission_panel is not None:
            if not get_settings().get("red_team_enabled"):
                return self._send_json(403, {"error": "red-team tools are disabled in Settings"})
            if (not isinstance(mission_panel, dict)
                    or mission_panel.get("authorized") is not True
                    or not str(mission_panel.get("target") or "").strip()):
                return self._send_json(400, {
                    "error": "red-team mission requires an explicit authorization confirmation and target"
                })

        # Two paths for incoming images:
        #   (a) The loaded model has its own vision tower (--mmproj): pass the images
        #       through as image_url blocks and persist the data URLs for replay.
        #   (b) Text-only model + a separate vision server (VISION_LLAMA_HOST): run
        #       each image through that side model and inline its description.
        # With neither available, fail up front rather than inlining a "[vision
        # server failed]" note the chat model would then make excuses about.
        vision_native = bool(images) and _llama.is_vision_capable()
        ocr_available = _separate_vision_server_ready()
        if images and not vision_native and not ocr_available:
            loaded = _llama.loaded_model() or "(none)"
            loaded_name = loaded.split("\\")[-1].split("/")[-1] if loaded != "(none)" else loaded
            side_configured = bool(VISION_LLAMA and VISION_LLAMA != LLAMA)
            side_note = (
                " A separate vision server is configured but is not answering."
                if side_configured else
                " No separate vision server is configured."
            )
            return self._send_json(400, {"error":
                f"This model can't see images. The loaded model "
                f"'{loaded_name}' has no active vision projector (mmproj)."
                f"{side_note}\n\n"
                f"Fix: load a vision-capable GGUF (one with a sibling "
                f"mmproj-*.gguf, e.g. Qwen2.5-VL, LLaVA, MiniCPM-V) and "
                f"point Settings → 'Vision projector (mmproj)' at the "
                f"projector file. Then relaunch the model from Settings."
            })
        if images and not vision_native:
            descriptions = []
            for i, img in enumerate(images):
                desc = describe_image(img, hint=user_text)
                descriptions.append(f"[image {i + 1} — transcribed by vision model]\n{desc}")
            vision_block = "\n\n".join(descriptions)
            user_text = (user_text + "\n\n" + vision_block).strip() if user_text else vision_block

        chats = get_chats()
        if chat_id not in chats["chats"]:
            chats["chats"][chat_id] = {
                "id": chat_id,
                "title": _title_from_prompt(user_text),
                "created": int(time.time()),
                "updated": int(time.time()),
                "messages": [],
            }
            # Tag notch-born sessions so the main app's sidebar recognizes and surfaces a
            # conversation it never created.
            if str(body.get("surface") or "").strip().lower() == "notch":
                chats["chats"][chat_id]["origin"] = "island"
            if chat_id in chats["order"]:
                chats["order"].remove(chat_id)
            chats["order"].insert(0, chat_id)
        chat = chats["chats"][chat_id]
        # An untagged session receiving notch turns is tagged too, so the sidebar
        # treatment survives a bridge restart; an explicit origin
        # (github/project/security) is never rewritten.
        if (str(body.get("surface") or "").strip().lower() == "notch"
                and not chat.get("origin")):
            chat["origin"] = "island"
        # remember the mode this chat was last used in so the client can
        # restore it on session switch
        chat["last_mode"] = mode
        # The sidebar row and the reply header name the model that ran the
        # session; the duration feeds "worked for" / "Finished" on reload.
        _turn_started_at = time.time()
        _turn_model = _turn_model_label()
        if _turn_model:
            chat["last_model"] = _turn_model
        research_id = ""
        if research_request:
            try:
                notebook = (_research_store.resume(resume_research_id, chat_id) if resume_research_id
                            else _research_store.start(chat_id, research_request))
            except (ValueError, OSError) as error:
                return self._send_json(400, {"error": str(error)})
            research_id = notebook["id"]
            chat["research_id"] = research_id
        # regenerate: drop the last assistant turn and re-run on the same prior user
        # message (only valid when the latest message is an assistant reply).
        if regenerate:
            # Pop the whole prior agentic tail (final assistant plus every intermediate
            # assistant and tool message) back to the last user turn, so the re-run starts
            # from exactly that message.
            while chat["messages"] and chat["messages"][-1].get("role") in ("assistant", "tool"):
                chat["messages"].pop()
            if not chat["messages"] or chat["messages"][-1].get("role") != "user":
                save_json(CHATS_FILE, chats)
                return self._send_json(400, {"error": "nothing to regenerate"})
            if user_text:
                # Edit & resend: replace the stored user turn's text; stored metadata
                # (_research_brief, images) stays attached.
                chat["messages"][-1]["content"] = user_text
            user_text = chat["messages"][-1].get("content", "")
        else:
            # auto-name any chat still using the default placeholder when its first
            # user message comes in
            is_first_user_msg = not any(m.get("role") == "user" for m in chat.get("messages", []))
            if is_first_user_msg and chat.get("title", "").strip().lower() in ("", "new session", "new conversation"):
                chat["title"] = _title_from_prompt(user_text)
                broadcast_event({"type": "chat:rename", "chat_id": chat_id, "title": chat["title"]})
            user_msg: dict = {"role": "user", "content": user_text, "t": int(time.time())}
            if research_request:
                user_msg["_research_brief"] = research_request
            if body.get("invisible"):
                user_msg["invisible"] = True
            if vision_native:
                # Stored as data URLs so replay on later turns (or after a reload) reattaches
                # them; clamped once here so storage and every replay stay bounded.
                user_msg["images"] = [_clamp_image_data_url(u) for u in images]
            chat["messages"].append(user_msg)
            global _last_user_text
            _last_user_text = user_text
            _update_task_anchor(chat, user_text)
        client_ctx["_user_text"] = user_text
        chat["updated"] = int(time.time())
        save_json(CHATS_FILE, chats)

        # /goal latch: apply an explicit on/off from this message, otherwise rehydrate
        # the persisted latch, so follow-up turns without /goal stay hands-free until
        # the user turns it off.
        if goal_action == "on":
            _apply_goal_latch(chat_id, True)
        elif goal_action == "off":
            _apply_goal_latch(chat_id, False)
        elif chat.get("goal_mode"):
            _set_goal_mode(chat_id, True)
        goal_active_now = _chat_in_goal_mode(chat_id)

        # An explicit request to operate a desktop app unlocks the desktop bundle
        # right away instead of making a small model discover it (and drift toward
        # PowerShell).
        if (get_settings().get("desktop_enabled")
                and _user_asked_desktop_interaction(user_text)):
            _unlock_bundle(chat_id, "desktop")

        # IDE mode keeps tools available ("save that", "read this file"). The IDE
        # prompt is what stops the model wrapping every HTML reply in write_file;
        # disabling tools entirely leaves it confused about what it may do.
        use_tools = True
        # Gemma emits a python-shaped call (```tool_code``` + name(arg=value)) that
        # llama.cpp's native parser can't decode; with the `tools` array on the wire
        # the call silently no-ops and the model narrates fake success. So Gemma runs
        # text-tools mode: tools are described in the system prompt and
        # extract_tool_calls (case 7b) parses the reply. Every model id (settings
        # name, configured path, loaded model) is checked so a stale field can't
        # misroute. See the in-app FAQ.
        native_tools = True
        tools_off_reason = ""
        _s = get_settings()
        _model_ids = (_s.get("model"), _s.get("model_path"), _llama.loaded_model())
        if use_tools and (any(_is_gemma_model(m) for m in _model_ids)
                          or _native_tools_broken()):
            native_tools = False
        # Rolling summary: fold the oldest un-kept turns into a compact summary
        # instead of letting truncate_messages delete them, so the model keeps the
        # lessons of earlier fixes. The extra model call only fires once the
        # conversation nears the context limit; on failure the prior summary stays.
        _pre_turn_compaction_failed = False
        if get_settings().get("summarize_history", True):
            try:
                _ctx_for_summary = _llama_props_ctx() or int(get_settings().get("num_ctx") or 32768)
                # Force the fold when the last round had to trim: the drop is the overflow
                # signal (the 0.85 trigger can't fire once the trimmer caps fill below it).
                _drop_force = _last_dropped_by_chat.get(chat_id, False)
                if _drop_force:
                    # A mid-turn fold has usually recovered that overflow already, and forcing
                    # anyway would compact the very next message at 10-20% fill. Only force while
                    # the prompt is still near the ceiling (above ~70% of the trigger).
                    _fill_now = _last_prompt_tokens_by_chat.get(chat_id, 0)
                    if _fill_now > 0 and _fill_now < _summary_trigger_limit(_ctx_for_summary) * 0.7:
                        _drop_force = False
                _log_compact(chat_id, f"pre_turn web: fill={_last_prompt_tokens_by_chat.get(chat_id, 0)} "
                                      f"trigger={_summary_trigger_limit(_ctx_for_summary)} ctx={_ctx_for_summary} "
                                      f"drop_flag={_last_dropped_by_chat.get(chat_id, False)} force={_drop_force}")
                _pre_turn_fold_required = (
                    _drop_force or
                    _last_prompt_tokens_by_chat.get(chat_id, 0) >=
                    _summary_trigger_limit(_ctx_for_summary)
                )
                _failure_seq_before = _summary_failure_seq_by_chat.get(chat_id, 0)
                if _maybe_roll_summary(chat, _ctx_for_summary,
                                       force=_drop_force,
                                       reason_hint="pre_turn"):
                    save_json(CHATS_FILE, chats)
                elif (_summary_failure_seq_by_chat.get(chat_id, 0) > _failure_seq_before or
                      (_pre_turn_fold_required and
                       _summary_failure_backoff_active(chat_id))):
                    _pre_turn_compaction_failed = True
            except Exception:
                traceback.print_exc()
        # Durable mission state (authorized red-team runs): seed the objective from
        # the initiating instruction, saved here so run_chat_turn's snapshot sees it.
        if get_settings().get("red_team_enabled") and get_settings().get("rt_mission_state", True):
            try:
                # Scope/auth panel data (Step 3) applied first so its explicit
                # objective wins over the auto-seed from the run instruction.
                _dirty = (_rt_mission_apply_panel(chat, mission_panel)
                          if isinstance(mission_panel, dict) else False)
                if _rt_authorized_mission(chat) and _rt_mission_seed(chat, user_text):
                    _dirty = True
                if _dirty:
                    save_json(CHATS_FILE, chats)
            except Exception:
                traceback.print_exc()
        # Native-tools turns carry the full JSON tool schemas, so the abbreviated
        # prompt list would duplicate them (~1.5K tokens); text-tools mode (Gemma)
        # needs it. The prompt is built here on the handler thread, so pin the chat
        # first, or the list falls back to core-only and misses bundles unlocked
        # earlier in the session.
        _set_current_chat(chat_id)
        system_prompt = build_system_prompt(include_tools=use_tools, chat_mode=mode,
                                            include_tool_list=not native_tools)
        system_prompt += "\n\n" + _client_context_prompt(client_ctx)
        if not research_id:
            system_prompt += _security_investigation_prompt(chat)
        if research_id:
            system_prompt += "\n\n" + RESEARCH_PROMPT
            system_prompt += "\nRESEARCH BRIEF (user-provided context):\n" + json.dumps(research_request, ensure_ascii=False)
            if resume_research_id:
                system_prompt += "\nResume the saved notebook. Read research_notebook(), then page through its notes. Preserve existing evidence and question numbers; do not restart collection. Resolve gaps and publish the presentation."
        # Mission block + pins are not spliced here: they change mid-session and
        # would invalidate llama.cpp's cached prompt prefix. run_chat_turn appends
        # them after the history instead. Only slow-changing sections stay in the
        # system prompt: the rolling summary and the static pin_note nudge below.
        _roll = chat.get("rolling_summary", "")
        if _roll:
            system_prompt += (
                "\n\n=== EARLIER IN THIS SESSION (older turns condensed to save context; "
                "treat these as established facts — do not redo work or re-ask) ===\n" + _roll
            )
        if use_tools:
            system_prompt += (
                "\n\nWhen you fix a bug, settle a design decision, or the user states a constraint, "
                "call pin_note to lock it in for this session so you never undo it or repeat the mistake."
            )
        # /goal hands-free run: tell the model to finish without pausing for
        # confirmation. Approvals auto-pass except deletions/destructive actions,
        # which the bridge still gates.
        if goal_active_now:
            system_prompt += (
                "\n\nGOAL MODE (hands-free): the user launched this task with /goal and wants it carried "
                "to completion autonomously. Do not stop to ask whether you may proceed with ordinary "
                "steps (reading, writing files, running commands, running tests) — just do them and keep "
                "going until the whole task is finished. The system auto-approves non-destructive actions; "
                "deletions and destructive actions still require the user, so when one is truly needed, do "
                "it via the proper tool (the user will be asked) and continue. Report only when done or genuinely blocked."
            )
        # Text-tools mode: pin the exact shape we can parse, in the model family's own
        # dialect, and never claim a tool ran unless a result came back.
        if not native_tools:
            system_prompt += _text_tools_prompt(any(_is_gemma_model(m) for m in _model_ids))
        msgs: list[dict] = [{"role": "system", "content": system_prompt}]
        # Replay the full stored history, including intermediate assistant turns
        # (with tool_calls) and tool results from prior agentic loops, so the model
        # resumes with its working memory instead of a bubble-only transcript.
        # On the vision-native path the model re-sees images on every replay; on the
        # text-only path descriptions were inlined into user_text at append time.
        replay_vision = _llama.is_vision_capable()
        # Replay only turns not yet folded into the rolling summary (the summary
        # stands in for them). The mapping lives in _replay_wire_msg so the mid-turn
        # fold rebuilds the exact same wire shape.
        _replay_from = int(chat.get("summary_through", 0) or 0)
        for m in chat["messages"][_replay_from:]:
            out = _replay_wire_msg(m, replay_vision)
            if out is not None:
                msgs.append(out)
        msgs = _ensure_user_anchor(msgs, chat["messages"], _replay_from)

        # set up SSE response — Connection: close so the browser reader resolves done
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.send_header("Cache-Control", "no-cache, no-transform")
        self.send_header("Connection", "close")
        self._set_cors()
        self.end_headers()

        final_sent = False

        def emit(evt: dict):
            nonlocal final_sent
            if evt.get("type") == "final":
                final_sent = True
            if research_id and evt.get("type") == "final":
                evt["message"]["_research"] = _research_store.finish(research_id, chat_id)
            evt = {**evt, "chat_id": chat_id}
            try:
                self.wfile.write(b"data: ")
                self.wfile.write(json.dumps(evt, ensure_ascii=False).encode("utf-8"))
                self.wfile.write(b"\n\n")
                self.wfile.flush()
            except Exception:
                raise
            broadcast_event(evt)

        emit({"type": "chat_start", "chat_id": chat_id})
        # Reflect the hands-free state on every surface for this turn. The latch
        # persists across turns (see _apply_goal_latch); only "/goal off" or the chip
        # clears it. Announce once when this message turned it on.
        emit({"type": "goal_mode", "active": goal_active_now})
        if goal_action == "on":
            emit({"type": "notice", "note":
                  "Goal mode on — running this chat hands-free. Deletions and destructive actions still ask."})
        if research_id:
            emit({"type": "research_update", "research": _research_store.get(research_id, chat_id)})
        if _pre_turn_compaction_failed:
            emit({"type": "error", "error": _COMPACTION_STOP_MESSAGE})
            emit({"type": "chat_end", "web_focused": _web_ui_focused()})
            return
        if tools_off_reason:
            emit({"type": "tools_unavailable", "message": tools_off_reason})
        tok = _current_chat_id.set(chat_id)
        if research_id:
            _research_runs[chat_id] = research_id
        try:
            final = run_chat_turn(chat_id, msgs, use_tools=use_tools, emit=emit,
                                  native_tools=native_tools,
                                  reasoning_effort=reasoning_effort)
        except Exception as e:
            traceback.print_exc()
            try:
                emit({"type": "error", "error": str(e)})
            except Exception:
                return
            final = None
        finally:
            _current_chat_id.reset(tok)
            _research_runs.pop(chat_id, None)

        if research_id:
            research_result = _research_store.finish(research_id, chat_id)
            if final is None:
                final = {"role": "assistant", "content": "Research ended before a presentation could be completed.", "_failed": True}
            final["_research"] = research_result
            emit({"type": "research_update", "research": research_result})

        # Several run_chat_turn paths return a reply without emitting `final`
        # themselves: a cancel at the top of a round, a cancel mid-stream, and the
        # catch-all that salvages a turn after an exception. The reply is persisted
        # below, but without this the client would see chat_start ... chat_end with
        # nothing between. Announce whatever came back, once.
        if final and not final_sent:
            try:
                # Only what a surface renders — the salvaged dict still carries
                # the tool-call working memory and stats we persist below.
                emit({"type": "final", "message": {
                    k: v for k, v in final.items()
                    if k in ("role", "content", "_stopped", "_failed", "_build", "_stats")
                }})
            except Exception:
                pass

        if final:
            chats = get_chats()
            if chat_id in chats["chats"]:
                chat = chats["chats"][chat_id]
                _completed_turn_id = str(final.pop("_turn_id", "") or "")
                # Persist the agentic loop's working memory (tool calls, results,
                # intermediate assistant messages) before the final bubble. Assistants are
                # marked _internal=true so the renderer skips them; they exist for replay.
                appended = final.pop("_appended_intermediate", None) or []
                # Mission state advanced during the turn (target host, confirmed-access
                # facts): merge onto the chat for the next turn. Already deduped/capped by
                # _rt_mission_note.
                _mu = final.pop("_mission_updates", None)
                if isinstance(_mu, dict):
                    chat["mission"] = _mu
                _au = final.pop("_activity_updates", None)
                if isinstance(_au, list):
                    chat["activity"] = [a for a in _au if isinstance(a, dict)][-_ACTIVITY_MAX:]
                _vu = final.pop("_verification_updates", None)
                if isinstance(_vu, list):
                    chat["verification_debt"] = [x for x in _vu if isinstance(x, dict)]
                _cu = final.pop("_continuity_updates", None)
                if isinstance(_cu, dict):
                    chat["continuity"] = _cu
                else:
                    _refresh_continuity_state(chat)
                now_t = int(time.time())
                for im in appended:
                    role = im.get("role")
                    if role not in ("assistant", "tool") and not (role == "user" and im.get("_steering_id")):
                        # the empty-retry "system" nudge isn't worth persisting
                        continue
                    persisted = {
                        "role": role,
                        "content": im.get("_steering_text", im.get("content", "")) or "",
                        "t": now_t,
                    }
                    if im.get("_steering_id"):
                        persisted["_steering_id"] = im["_steering_id"]
                        persisted["images"] = im.get("_steering_images", [])
                    if _completed_turn_id:
                        persisted["_turn_id"] = _completed_turn_id
                    if role == "assistant":
                        persisted["_internal"] = True
                        if im.get("tool_calls"):
                            persisted["tool_calls"] = im["tool_calls"]
                    elif role == "tool":
                        if im.get("tool_call_id"):
                            persisted["tool_call_id"] = im["tool_call_id"]
                        if im.get("name"):
                            persisted["name"] = im["name"]
                    chat["messages"].append(persisted)

                msg = {
                    "role": "assistant",
                    "content": final.get("content", ""),
                    "t": now_t,
                }
                if _turn_model:
                    msg["model"] = _turn_model
                msg["_worked_s"] = max(0, int(round(time.time() - _turn_started_at)))
                if _completed_turn_id:
                    msg["_turn_id"] = _completed_turn_id
                if final.get("_build"):
                    msg["_build"] = final["_build"]
                if final.get("_carry_diag"):
                    msg["_carry_diag"] = final["_carry_diag"]
                if final.get("_research"):
                    msg["_research"] = final["_research"]
                if final.get("_stopped"):
                    msg["_stopped"] = True
                if final.get("_failed"):
                    msg["_failed"] = True
                stats = final.get("_stats") or {}
                if stats.get("eval_count") is not None:
                    msg["tokens"] = stats["eval_count"]
                if stats.get("prompt_eval_count") is not None:
                    msg["prompt_tokens"] = stats["prompt_eval_count"]
                chat["messages"].append(msg)
                chat["updated"] = now_t
                # Retention cap (CHAT_HISTORY_MAX) to keep the JSON file bounded; anchors
                # (system + first user) are always kept.
                _enforce_chat_retention(chat)
                html = extract_html(final.get("content", ""))
                if html:
                    entry = save_version(chat_id, html, label=user_text[:80])
                    chat["last_version"] = entry["id"]
                    try:
                        emit({"type": "version_saved", "version": entry})
                    except Exception:
                        pass
                save_json(CHATS_FILE, chats)
                _turn_journal_clear(chat_id, _completed_turn_id)
        else:
            # A transport failure after one or more completed tool calls should
            # not wait for a full application restart to recover its work.
            _recover_turn_journals()

        _changes = _undo_commit_turn()
        if _changes:
            try:
                emit({"type": "turn_changes", **_changes})
            except Exception:
                pass

        try:
            emit({"type": "chat_end", "web_focused": _web_ui_focused()})
        except Exception:
            pass


# ---- llama-server management -----------------------------------------------
# The bridge owns the llama-server subprocess, so models can be swapped from
# the UI: set settings.model_path to the .gguf and it is (re)spawned.


# ---- VRAM detection + auto-tune --------------------------------------------
# Detect (or take) the VRAM tier and fill in sensible llama-server flags;
# every field can still be overridden. Conservative on purpose: leaving 10-15%
# VRAM headroom beats an OOM mid-generation.

def detect_vram_gb() -> dict:
    """Best-effort GPU VRAM probe. Returns {gb, name, source, total_gb, gpus} or
    {gb: 0, name: "", source: "none"}. `gb` is GPU 0's free VRAM (what the tuner
    can budget, since other processes' allocations are otherwise invisible),
    `total_gb` its physical total, and `gpus` lists every GPU as
    {name, total_gb, free_gb}. Uses nvidia-smi when present. Never raises."""
    out = {"gb": 0, "name": "", "source": "none"}
    # nvidia-smi --query-gpu=memory.total,memory.free,name --format=csv,noheader,nounits
    smi = shutil.which("nvidia-smi")
    if smi:
        try:
            r = subprocess.run(
                [smi, "--query-gpu=memory.total,memory.free,name", "--format=csv,noheader,nounits"],
                capture_output=True, text=True, timeout=3,
                creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0),
            )
            if r.returncode == 0 and r.stdout.strip():
                # One line per GPU: "12282, 11001, NVIDIA GeForce RTX 4070"
                gpus = []
                for line in r.stdout.strip().splitlines():
                    parts = [p.strip() for p in line.split(",")]
                    if len(parts) < 2 or not parts[0].isdigit() or not parts[1].isdigit():
                        continue
                    gpus.append({
                        "name": ", ".join(parts[2:]) if len(parts) > 2 else "NVIDIA GPU",
                        "total_gb": round(int(parts[0]) / 1024, 1),
                        "free_gb": round(int(parts[1]) / 1024, 1),
                    })
                if gpus:
                    # GPU 0 = primary. `gb` is FREE so the tuner never budgets
                    # VRAM another process already holds. `free_total_gb` sums
                    # every GPU: llama.cpp splits layers across all visible
                    # cards, so the tuner budgets all of them.
                    out["gb"] = gpus[0]["free_gb"]
                    out["free_total_gb"] = round(sum(g["free_gb"] for g in gpus), 1)
                    out["total_gb"] = gpus[0]["total_gb"]
                    out["name"] = gpus[0]["name"]
                    out["gpus"] = gpus
                    out["source"] = "nvidia-smi"
                    return out
        except Exception:
            pass
    return out


# Filename patterns that indicate a Mixture-of-Experts model. Used as a fallback
# when GGUF header parsing fails or the model file is unreachable.
_MOE_FILENAME_HINTS = (
    "moe", "mixtral", "deepseek-v2", "deepseek-v3", "deepseek-coder-v2",
    "qwen3.5-moe", "qwen3-moe", "qwen3.6", "glm-4.7", "glm-4.6", "glm-4.5",
    "phi-3.5-moe", "grok", "dbrx", "jamba", "arctic",
)
# A3B / A13B style suffix: "active 3B" or "active 13B" — also MoE.
_ACTIVE_RE = re.compile(r"-a(\d+)b", re.IGNORECASE)
# Total params: "35B", "47B", "8x7B" (treat as ~47B), etc.
_TOTAL_RE = re.compile(r"\b(\d+(?:\.\d+)?)x(\d+(?:\.\d+)?)b\b|\b(\d+(?:\.\d+)?)b\b", re.IGNORECASE)

# Quant suffix in filename, e.g. "Q4_K_M", "Q3_K_S", "IQ4_XS", "F16".
_QUANT_RE = re.compile(r"\b(IQ\d_[A-Z]{1,3}|Q\d_[KS01]?_?[MS]?|Q\d_K|F16|BF16|F32)\b", re.IGNORECASE)


def read_gguf_metadata(path: str, max_bytes: int = 4 * 1024 * 1024) -> dict:
    """Parse the GGUF v2/v3 header and return architecture-level metadata.
    Reads at most a few MB from the file's start — the metadata block lives
    right after the magic (if the KV list doesn't fit in `max_bytes`, retries
    once with a 64MB cap; the tensor-info section that follows the KV list is
    never parsed). Never raises; returns {ok: False} on any parse failure so
    callers can fall back to filename heuristics.

    Besides the structured fields below, every scalar KV entry is collected
    verbatim into out["keys"] (full key names, nothing stripped) so tuners can
    probe architecture-specific keys we don't hardcode. Arrays are recorded as
    {"__array_len__": n} — contents are skipped, the length is cheap and useful
    (e.g. tokenizer.ggml.tokens length ≈ vocab size). out["parse_status"] is
    "complete" (whole KV list read), "truncated" (buffer ran out mid-list), or
    "degraded" (unknown/nested value type — clean stop, entries so far kept).

    GGUF spec reference: https://github.com/ggerganov/ggml/blob/master/docs/gguf.md
    Layout: "GGUF" magic, uint32 version, uint64 tensor_count, uint64 kv_count,
    then kv_count entries of (str key, uint32 value_type, value).
    """
    out = {
        "ok": False,
        "architecture": "",
        "size_label": "",
        "block_count": 0,             # n_layer
        "expert_count": 0,            # 0 for dense, > 0 for MoE
        "expert_used_count": 0,       # active experts per token
        "head_count": 0,              # query heads
        "head_count_kv": 0,           # KV heads (smaller for GQA)
        "key_length": 0,              # per-head key dim
        "value_length": 0,            # per-head value dim
        "embedding_length": 0,
        "feed_forward_length": 0,
        "expert_feed_forward_length": 0,  # MoE: per-expert FFN width
        "context_length": 0,              # the model's trained max context
        "nextn_predict_layers": 0,        # >0 means the GGUF carries MTP heads
                                          # (key: "<arch>.nextn_predict_layers"). This is the same
                                          # signal llama.cpp itself uses to enable --spec-type draft-mtp.
        "has_mtp": False,                 # convenience flag: nextn_predict_layers > 0
        "keys": {},                       # all scalar metadata KV entries (see docstring)
        "parse_status": "",               # complete | truncated | degraded
    }
    if not path:
        return out
    try:
        import struct

        # GGUF value type enum
        T_UINT8, T_INT8 = 0, 1
        T_UINT16, T_INT16 = 2, 3
        T_UINT32, T_INT32 = 4, 5
        T_FLOAT32, T_BOOL, T_STRING, T_ARRAY = 6, 7, 8, 9
        T_UINT64, T_INT64, T_FLOAT64 = 10, 11, 12
        scalar_fmt = {
            T_UINT8: ("<B", 1), T_INT8: ("<b", 1),
            T_UINT16: ("<H", 2), T_INT16: ("<h", 2),
            T_UINT32: ("<I", 4), T_INT32: ("<i", 4),
            T_FLOAT32: ("<f", 4), T_BOOL: ("<?", 1),
            T_UINT64: ("<Q", 8), T_INT64: ("<q", 8),
            T_FLOAT64: ("<d", 8),
        }

        class _Degraded(Exception):
            """Unknown/nested value type hit — stop parsing at that entry."""

        def _parse_kv_list(data: bytes):
            """Parse just the metadata KV list from `data`. Returns
            (meta, status). Never raises on malformed input."""
            meta: dict = {}
            if len(data) < 24 or data[:4] != b"GGUF":
                return meta, "degraded"
            pos = 4
            version = struct.unpack_from("<I", data, pos)[0]; pos += 4
            if version < 2:
                return meta, "degraded"  # v1 had a different layout
            pos += 8  # tensor_count, unused
            kv_count = struct.unpack_from("<Q", data, pos)[0]; pos += 8

            def read_str(p):
                n = struct.unpack_from("<Q", data, p)[0]
                p += 8
                s = data[p:p + n].decode("utf-8", errors="replace")
                return s, p + n

            def read_value(p, vtype):
                if vtype in scalar_fmt:
                    fmt, sz = scalar_fmt[vtype]
                    return struct.unpack_from(fmt, data, p)[0], p + sz
                if vtype == T_STRING:
                    return read_str(p)
                if vtype == T_ARRAY:
                    etype = struct.unpack_from("<I", data, p)[0]; p += 4
                    ecount = struct.unpack_from("<Q", data, p)[0]; p += 8
                    if etype in scalar_fmt:
                        efmt, sz = scalar_fmt[etype]
                        # Small numeric arrays carry real tuning signal on newer
                        # archs (gemma4 per-layer head_count_kv / sliding_window_
                        # pattern) — keep them when they're cheap. Big arrays
                        # (tokenizer vocab etc.) stay length-only.
                        if 0 < ecount <= 1024:
                            try:
                                return list(struct.unpack_from("<" + efmt[1] * int(ecount), data, p)), p + sz * int(ecount)
                            except Exception:
                                pass
                        return {"__array_len__": int(ecount)}, p + sz * int(ecount)
                    if etype == T_STRING:
                        for _ in range(ecount):
                            n = struct.unpack_from("<Q", data, p)[0]
                            p += 8 + n
                        return {"__array_len__": int(ecount)}, p
                    # Nested arrays / unknown element type — bail cleanly.
                    raise _Degraded()
                # Unknown scalar type: stop cleanly at this entry, keeping what we have;
                # continuing from an unadvanced position would garbage-parse every later key.
                raise _Degraded()

            status = "complete"
            for _ in range(kv_count):
                if len(meta) >= 4096:
                    # Sane bound — real GGUFs carry ~50-200 KV entries.
                    status = "degraded"
                    break
                try:
                    key, pos = read_str(pos)
                    vtype = struct.unpack_from("<I", data, pos)[0]; pos += 4
                    val, pos = read_value(pos, vtype)
                    if isinstance(val, str) and len(val) > 2048:
                        # Template kwargs are the strongest model-agnostic
                        # signal for adjustable reasoning. Keep a bounded copy
                        # of chat templates; collapse unrelated giant strings.
                        if "chat_template" in key.lower():
                            val = val[:262144]
                        else:
                            val = {"__array_len__": len(val)}
                    meta[key] = val
                except _Degraded:
                    status = "degraded"
                    break
                except (struct.error, IndexError):
                    # Ran past the buffered window.
                    status = "truncated"
                    break
            return meta, status

        # First pass with the small read; if the KV list didn't fit in the
        # buffer, retry once with a much larger cap before giving up.
        meta: dict = {}
        status = "truncated"
        for cap in (max_bytes, 64 * 1024 * 1024):
            with open(path, "rb") as f:
                data = f.read(cap)
            meta, status = _parse_kv_list(data)
            if status != "truncated" or len(data) < cap:
                break
        out["keys"] = meta
        out["parse_status"] = status

        arch = str(meta.get("general.architecture", "")).strip()
        if not arch:
            return out
        out["architecture"] = arch
        out["size_label"] = str(meta.get("general.size_label", "")).strip()

        def num(*keys):
            for k in keys:
                v = meta.get(k)
                if isinstance(v, (int, float)) and v:
                    return int(v)
            return 0

        out["block_count"] = num(f"{arch}.block_count")
        out["expert_count"] = num(f"{arch}.expert_count")
        out["expert_used_count"] = num(f"{arch}.expert_used_count")
        out["head_count"] = num(f"{arch}.attention.head_count")
        out["head_count_kv"] = num(
            f"{arch}.attention.head_count_kv",
            f"{arch}.attention.head_count",  # MHA: kv = q
        )
        out["key_length"] = num(f"{arch}.attention.key_length")
        out["value_length"] = num(f"{arch}.attention.value_length")
        out["embedding_length"] = num(f"{arch}.embedding_length")
        out["feed_forward_length"] = num(f"{arch}.feed_forward_length")
        out["expert_feed_forward_length"] = num(f"{arch}.expert_feed_forward_length")
        out["context_length"] = num(f"{arch}.context_length")

        # Derive missing dims when possible
        if not out["key_length"] and out["embedding_length"] and out["head_count"]:
            out["key_length"] = out["embedding_length"] // out["head_count"]
        if not out["value_length"]:
            out["value_length"] = out["key_length"]

        # MTP detection: llama.cpp tags MTP-capable architectures (Qwen 3.5/3.6,
        # DeepSeek V3/R1, ...) with "<arch>.nextn_predict_layers", which survives
        # renames and repacks. Older GGUFs without the key get has_mtp=False.
        nextn = num(f"{arch}.nextn_predict_layers")
        if not nextn:
            # Some converters drop the arch prefix on this key. Catch the unprefixed
            # variant as a backup before giving up.
            for k, v in meta.items():
                if k.endswith(".nextn_predict_layers") or k == "nextn_predict_layers":
                    if isinstance(v, (int, float)) and v > 0:
                        nextn = int(v)
                        break
        out["nextn_predict_layers"] = int(nextn or 0)
        out["has_mtp"] = out["nextn_predict_layers"] > 0

        out["ok"] = bool(out["architecture"] and out["block_count"])
        return out
    except Exception:
        return out


def inspect_model(model_path: str) -> dict:
    """Return a profile of a GGUF model. Reads the GGUF header for accurate
    architecture data (layer count, MoE expert count, GQA config). Falls back
    to filename heuristics when the header is unavailable.
    Never raises — returns sensible defaults if anything fails.
    """
    out = {
        "path": model_path or "",
        "name": "",
        "size_gb": 0.0,
        "is_moe": False,
        "active_params_b": 0,
        "total_params_b": 0,
        "quant": "",
        # GGUF-derived (zero when header unreadable)
        "architecture": "",
        "block_count": 0,
        "expert_count": 0,
        "expert_used_count": 0,
        "head_count_kv": 0,
        "key_length": 0,
        "value_length": 0,
        "embedding_length": 0,
        "feed_forward_length": 0,
        "expert_feed_forward_length": 0,
        "context_length": 0,
        "metadata_source": "filename",  # or "gguf"
        "has_mtp": False,                 # GGUF carries built-in MTP heads (nextn_predict_layers > 0)
        "nextn_predict_layers": 0,
        "keys": {},                       # raw GGUF metadata KV scalars (empty on filename fallback)
    }
    if not model_path:
        return out
    try:
        p = Path(model_path)
        out["name"] = p.name
        out["size_gb"] = round(p.stat().st_size / (1024 ** 3), 2)
    except Exception:
        return out
    name_lc = out["name"].lower()
    qm = _QUANT_RE.search(out["name"])
    if qm:
        out["quant"] = qm.group(1).upper()

    # Try GGUF header first — authoritative when present.
    gg = read_gguf_metadata(model_path)
    if gg.get("ok"):
        out["metadata_source"] = "gguf"
        out["architecture"] = gg["architecture"]
        out["block_count"] = gg["block_count"]
        out["expert_count"] = gg["expert_count"]
        out["expert_used_count"] = gg["expert_used_count"]
        out["head_count_kv"] = gg["head_count_kv"]
        out["key_length"] = gg["key_length"]
        out["value_length"] = gg["value_length"]
        out["embedding_length"] = gg["embedding_length"]
        out["feed_forward_length"] = gg["feed_forward_length"]
        out["expert_feed_forward_length"] = gg["expert_feed_forward_length"]
        out["context_length"] = gg["context_length"]
        out["is_moe"] = gg["expert_count"] > 1
        out["has_mtp"] = bool(gg.get("has_mtp", False))
        out["nextn_predict_layers"] = int(gg.get("nextn_predict_layers", 0) or 0)
        out["keys"] = gg.get("keys") or {}
        # total/active param counts: prefer the size_label like "30B-A3B"
        sl = (gg.get("size_label") or "").lower()
        am = _ACTIVE_RE.search(sl) or _ACTIVE_RE.search(name_lc)
        if am:
            try:
                out["active_params_b"] = int(am.group(1))
            except Exception:
                pass
        for tm in _TOTAL_RE.finditer(sl + " " + name_lc):
            try:
                if tm.group(1) and tm.group(2):
                    v = float(tm.group(1)) * float(tm.group(2))
                elif tm.group(3):
                    v = float(tm.group(3))
                else:
                    continue
            except Exception:
                continue
            if v > out["total_params_b"]:
                out["total_params_b"] = int(round(v))
        return out

    # Filename-only fallback (header parse failed)
    out["is_moe"] = any(h in name_lc for h in _MOE_FILENAME_HINTS) or bool(_ACTIVE_RE.search(name_lc))
    m = _ACTIVE_RE.search(name_lc)
    if m:
        try:
            out["active_params_b"] = int(m.group(1))
        except Exception:
            pass
    largest = 0.0
    for tm in _TOTAL_RE.finditer(name_lc):
        try:
            if tm.group(1) and tm.group(2):
                v = float(tm.group(1)) * float(tm.group(2))
            elif tm.group(3):
                v = float(tm.group(3))
            else:
                continue
        except Exception:
            continue
        if v > largest:
            largest = v
    out["total_params_b"] = int(round(largest)) if largest else 0
    return out


_REASONING_LEVELS = ("auto", "low", "medium", "high")


def _normalize_reasoning_effort(value) -> str:
    value = str(value or "auto").strip().lower()
    aliases = {"med": "medium", "default": "auto", "normal": "medium"}
    value = aliases.get(value, value)
    return value if value in _REASONING_LEVELS else "auto"


def _model_reasoning_was_observed(model: str) -> bool:
    """True when a prior real response exposed a reasoning stream.

    This stores no generated text. It is just a durable capability bit, useful
    for brand-new model families whose template names Accuretta has never seen.
    """
    if not model:
        return False
    try:
        rows = (load_json(MODEL_RUNTIME_FILE, {"models": {}}).get("models") or {})
        p = Path(str(model))
        keys = {_model_profile_key(model), p.stem[:180], p.name[:180]}
        return any(bool((rows.get(k) or {}).get("reasoning_observed")) for k in keys)
    except Exception:
        return False


def _mark_model_reasoning_observed(model: str) -> None:
    """Persist a path-free, content-free fact learned from a real response."""
    if not model:
        return
    key = _model_profile_key(model)
    with _MODEL_RUNTIME_LOCK:
        try:
            data = load_json(MODEL_RUNTIME_FILE, {"version": 1, "models": {}})
            if not isinstance(data, dict):
                data = {"version": 1, "models": {}}
            row = data.setdefault("models", {}).setdefault(key, {})
            if row.get("reasoning_observed"):
                return
            row["reasoning_observed"] = True
            row["reasoning_observed_at"] = int(time.time())
            save_json(MODEL_RUNTIME_FILE, data)
            _REASONING_CAP_CACHE.clear()
        except Exception:
            pass


def _reasoning_capability(model_path: str = "", settings: dict | None = None,
                          props: dict | None = None) -> dict:
    """Describe adjustable reasoning support without trusting a single name.

    Detection prefers actual template kwargs from live llama-server /props and
    the GGUF chat template. Known-family names are only a fallback. A Settings
    override exists because new local models routinely arrive before harnesses
    know their template vocabulary.
    """
    settings = settings or get_settings()
    model_path = str(model_path or settings.get("model_path") or "").strip()
    override = str(settings.get("reasoning_capability_override") or "auto").strip().lower()
    if override not in ("auto", "off", "budget", "native_effort"):
        override = "auto"
    if not model_path:
        return {
            "supported": False, "mode": "none", "source": "no_model",
            "levels": list(_REASONING_LEVELS),
            "description": "Load a model to detect adjustable reasoning.",
        }
    if override == "off":
        return {
            "supported": False, "mode": "none", "source": "manual",
            "levels": list(_REASONING_LEVELS),
            "description": "Reasoning control is disabled in Settings.",
        }

    observed = _model_reasoning_was_observed(model_path)
    try:
        st = Path(model_path).stat()
        file_sig = (int(st.st_mtime_ns), int(st.st_size))
    except Exception:
        file_sig = (0, 0)
    props = props if isinstance(props, dict) else _llama_props_data()
    cache_key = (model_path, file_sig, override, observed, id(props))
    cached = _REASONING_CAP_CACHE.get(cache_key)
    if cached:
        return dict(cached)

    if override in ("budget", "native_effort"):
        cap = {
            "supported": True, "mode": override, "source": "manual",
            "levels": list(_REASONING_LEVELS),
            "description": ("Uses the model's native effort levels."
                            if override == "native_effort"
                            else "Uses a token budget with Accuretta's runaway guard."),
        }
        if override == "native_effort":
            cap["native_parameter"] = "reasoning_effort"
        _REASONING_CAP_CACHE[cache_key] = cap
        return dict(cap)

    # Only inspect chat-template values from GGUF metadata. Other huge metadata
    # strings cannot establish reasoning support and would just waste memory.
    gguf_template = ""
    try:
        keys = (read_gguf_metadata(model_path).get("keys") or {})
        gguf_template = "\n".join(
            str(v) for k, v in keys.items()
            if "chat_template" in str(k).lower() and isinstance(v, str)
        )
    except Exception:
        pass
    # /props also exposes generic server request defaults. Looking for an
    # arbitrary `reasoning_effort` key across that whole object would make the
    # slider appear for every model even when its template drops the value.
    # Inspect only fields explicitly belonging to a chat template/capability.
    prop_templates: list[str] = []
    def _collect_prop_templates(value, key_hint=""):
        if len(prop_templates) >= 24:
            return
        if "chat_template" in key_hint.lower():
            try:
                prop_templates.append(json.dumps(value, ensure_ascii=False)[:262144])
            except Exception:
                pass
            return
        if isinstance(value, dict):
            for k, v in value.items():
                _collect_prop_templates(v, str(k))
        elif isinstance(value, list):
            for v in value[:32]:
                _collect_prop_templates(v, key_hint)
    _collect_prop_templates(props)
    props_text = "\n".join(prop_templates)
    signal = (gguf_template + "\n" + props_text).lower()
    name = Path(model_path).name.lower()

    native_parameter = ""
    for candidate in ("reasoning_effort", "reasoning_strength",
                      "thinking_level", "reasoning_level"):
        if candidate in signal:
            native_parameter = candidate
            break
    has_native = bool(native_parameter)
    has_budget = ("thinking_budget_tokens" in signal or "thinking_budget" in signal)
    has_toggle = "enable_thinking" in signal
    advertised_native_levels = set(re.findall(
        r"['\"](minimal|low|medium|high|xhigh|max|none)['\"]", signal
    ))
    native_family = any(x in name for x in ("gpt-oss", "stepfun", "step-3", "step3"))
    budget_family = any(x in name for x in (
        "qwq", "deepseek-r1", "deepseek_r1", "r1-distill",
        "reasoner", "reasoning", "thinker",
    ))

    if has_native or native_family:
        mode = "native_effort"
        source = "chat_template" if has_native else "model_family"
        description = "The model exposes native low, medium, and high effort levels."
    elif has_budget or has_toggle or observed or budget_family:
        mode = "budget"
        if has_budget or has_toggle:
            source = "chat_template"
        elif observed:
            source = "observed_output"
        else:
            source = "model_family"
        description = "Accuretta adjusts the thinking budget and keeps its runaway guard active."
    else:
        mode = "none"
        source = "not_detected"
        description = "This model did not advertise adjustable reasoning."

    cap = {
        "supported": mode != "none", "mode": mode, "source": source,
        "levels": list(_REASONING_LEVELS), "description": description,
    }
    if mode == "native_effort":
        cap["native_parameter"] = native_parameter or "reasoning_effort"
        native_map = {}
        # The composer uses a compact, model-agnostic Auto/Low/Medium/High
        # ladder. Some templates name their deepest tier xhigh or max. Map the
        # UI tier to an actually advertised value instead of sending a string
        # the template rejects. Qwen3.8, for example, accepts low/medium/xhigh.
        if "high" not in advertised_native_levels:
            if "xhigh" in advertised_native_levels:
                native_map["high"] = "xhigh"
            elif "max" in advertised_native_levels:
                native_map["high"] = "max"
        if native_map:
            cap["native_effort_map"] = native_map
        if advertised_native_levels:
            cap["native_effort_values"] = sorted(advertised_native_levels)
    _REASONING_CAP_CACHE[cache_key] = cap
    return dict(cap)


_VERIFY_CAP_CACHE: dict[tuple, bool] = {}


def _template_supports_verification(model_path: str, props: dict | None = None) -> bool:
    """True when the chat template takes Sage-A1.5's `verification` kwarg.

    The template raises on verification=true without a non-empty system
    message, so callers only send it when the first message is a system one."""
    model_path = str(model_path or "").strip()
    if not model_path:
        return False
    try:
        st = Path(model_path).stat()
        key = (model_path, int(st.st_mtime_ns), int(st.st_size))
    except Exception:
        key = (model_path, 0, 0)
    if key in _VERIFY_CAP_CACHE:
        return _VERIFY_CAP_CACHE[key]
    texts: list[str] = []
    try:
        keys = (read_gguf_metadata(model_path).get("keys") or {})
        texts += [str(v) for k, v in keys.items()
                  if "chat_template" in str(k).lower() and isinstance(v, str)]
    except Exception:
        pass
    props = props if isinstance(props, dict) else _llama_props_data()
    tpl = props.get("chat_template") if isinstance(props, dict) else None
    if isinstance(tpl, str):
        texts.append(tpl)
    signal = "\n".join(texts)
    found = bool(re.search(r"verification\s+is\s+defined", signal))
    _VERIFY_CAP_CACHE[key] = found
    return found


def _verification_wanted(settings: dict, effort: str, model_path: str) -> bool:
    mode = str(settings.get("verification_mode") or "auto").strip().lower()
    if mode == "off" or not _template_supports_verification(model_path):
        return False
    return mode == "on" or effort == "high"


def _reasoning_budget_for_effort(level: str, ctx_limit: int) -> int:
    """Translate friendly effort levels into a context-aware reasoning cap."""
    reserve = max(min(int(max(1024, ctx_limit) * 0.25), 16000), 1024)
    available = max(256, reserve - 1024)
    if level == "low":
        return max(256, min(1024, int(available * 0.16)))
    if level == "high":
        return max(1024, min(8192, int(available * 0.72)))
    return max(512, min(4096, int(available * 0.40)))


def _resolve_reasoning_request(effort, capability: dict, settings: dict,
                               ctx_limit: int) -> dict:
    """Resolve one composer choice into template kwargs + harness limits."""
    level = _normalize_reasoning_effort(effort)
    if level != "auto" and not capability.get("supported"):
        level = "auto"
    enabled = settings.get("enable_thinking") is not False
    try:
        legacy_budget = int(settings.get("thinking_budget") if settings.get("thinking_budget") is not None else 2048)
    except (TypeError, ValueError):
        legacy_budget = 2048
    native_effort = None
    if level != "auto":
        enabled = True
        effort_headroom = _reasoning_budget_for_effort(level, ctx_limit)
        if capability.get("mode") == "native_effort":
            native_effort = (capability.get("native_effort_map") or {}).get(level, level)
            # Native-effort models decide how long Low/Medium/Deep should reason.
            # Keep enough response room for that thinking, but do not also send
            # a numeric target or trip the numeric runaway ceiling against it.
            budget = -1
            response_headroom = effort_headroom
        else:
            budget = effort_headroom
            response_headroom = max(0, budget)
    else:
        budget = legacy_budget
        response_headroom = max(0, budget)
    if not enabled:
        budget = 0
        response_headroom = 0
    return {
        "effort": level, "enabled": bool(enabled), "budget": int(budget),
        "native_effort": native_effort,
        "response_headroom": int(response_headroom),
    }


def _reasoning_payload_overrides(config: dict, capability: dict) -> dict:
    """Return only explicit, per-message top-level llama.cpp controls."""
    if config.get("effort") == "auto":
        return {}  # Preserve the painstakingly tuned legacy behavior exactly.
    if capability.get("mode") == "budget":
        # Modern llama.cpp's real per-request budget. The caller also sends a
        # template kwarg for older builds, and the stream guard remains the
        # final backstop if either is ignored.
        return {"thinking_budget_tokens": max(0, int(config.get("budget") or 0))}
    if (config.get("native_effort")
            and (capability.get("native_parameter") or "reasoning_effort") == "reasoning_effort"):
        # OpenAI-compatible clients expect this at top level, while the caller
        # mirrors it into chat_template_kwargs for model-native templates.
        return {"reasoning_effort": config["native_effort"]}
    return {}


# KV cache dtype byte costs per element (post block-quant overhead).
# q4_0/q8_0 numbers are real: 0.5 + 1/32 (delta) = ~0.5625; 1 + 1/32 = ~1.0625.
_KV_DTYPE_BYTES = {"f16": 2.0, "bf16": 2.0, "q8_0": 1.0625, "q4_0": 0.5625, "q4_1": 0.625, "q5_0": 0.6875, "q5_1": 0.75}


# Key fragments that mark hybrid recurrent/SSM + full-attention architectures
# (Mamba/SSM blocks interleaved with periodic full-attention layers). Matched
# against the raw GGUF keys dict, so no per-arch hardcoding is needed.
_HYBRID_KEY_FRAGMENTS = (".ssm.", ".recurrent.", ".linear_attention.", ".mamba")
# Candidate suffixes for the "every Nth layer is full attention" interval key.
# Probe several — different converters name it differently.
_HYBRID_INTERVAL_SUFFIXES = (
    "full_attention_interval", "global_attention_interval",
    "hybrid_attention_interval", "attention_interval",
)


def _mla_dims(profile: dict):
    """DeepSeek V2/V3-style MLA detection. Returns (kv_lora_rank,
    qk_rope_head_dim) when the GGUF metadata exposes kv_lora_rank, else None.
    llama.cpp caches the compressed latent for MLA, not per-head K/V."""
    keys = profile.get("keys") or {}
    arch = profile.get("architecture") or ""
    if not arch:
        return None
    kv_lora = keys.get(f"{arch}.attention.kv_lora_rank")
    if not isinstance(kv_lora, (int, float)) or not kv_lora:
        return None
    qk_rope = keys.get(f"{arch}.attention.qk_rope_head_dim")
    qk_rope = int(qk_rope) if isinstance(qk_rope, (int, float)) and qk_rope else 0
    return int(kv_lora), qk_rope


def _hybrid_info(profile: dict) -> dict:
    """Detect hybrid SSM/attention models purely from GGUF metadata keys.
    Returns {"hybrid": bool, "interval": int (0 = unknown), "evidence": str}.
    Known hybrid arch names (granitemoehybrid, nemotron-h, jamba, ...) only
    corroborate — key evidence is required before we treat a model as hybrid."""
    keys = profile.get("keys") or {}
    arch = (profile.get("architecture") or "").lower()
    evidence = ""
    for k in keys:
        kl = k.lower()
        if any(frag in kl for frag in _HYBRID_KEY_FRAGMENTS):
            evidence = k
            break
    interval = 0
    interval_key = ""
    for suffix in _HYBRID_INTERVAL_SUFFIXES:
        for k, v in keys.items():
            if k.lower().endswith(suffix) and isinstance(v, (int, float)) and v >= 2:
                interval = int(v)
                interval_key = k
                break
        if interval:
            break
    hybrid = bool(evidence or interval)
    if hybrid and not evidence:
        evidence = interval_key
    # Arch-name corroboration only (never triggers on its own): noted for
    # transparency when the keys and the arch name agree.
    _KNOWN_HYBRID_ARCHES = ("granitemoehybrid", "granitehybrid", "nemotron-h",
                            "nemotron_h", "jamba", "zamba", "falcon-h1", "bamba")
    arch_hit = any(a in arch for a in _KNOWN_HYBRID_ARCHES) or "hybrid" in arch
    return {"hybrid": hybrid, "interval": interval, "evidence": evidence,
            "arch_corroborates": bool(hybrid and arch_hit)}


def _kv_bytes_per_token(profile: dict, kv_dtype: str) -> int:
    """KV cache cost per token using GGUF-derived attention config.
    Standard path: n_layer * head_count_kv * (key_length + value_length) * dtype_bytes
    (value_length used when the parser actually read it; falls back to
    key_length only when absent). MLA path (DeepSeek V2/V3): llama.cpp caches
    the compressed latent, so n_layer * (kv_lora_rank + qk_rope_head_dim) *
    dtype_bytes. Hybrid SSM/attention models with a known full-attention
    interval are scaled by the attention-layer fraction. Returns 0 when GGUF
    metadata wasn't readable (caller falls back to bucket)."""
    n_layer = profile.get("block_count", 0) or 0
    if not n_layer:
        return 0
    db = _KV_DTYPE_BYTES.get(kv_dtype, 1.0625)

    mla = _mla_dims(profile)
    if mla:
        kv_lora, qk_rope = mla
        base = n_layer * (kv_lora + qk_rope) * db
    else:
        n_kv = profile.get("head_count_kv", 0) or 0
        head_dim = profile.get("key_length", 0) or 0
        if not (n_kv and head_dim):
            return 0
        # V dim can differ from K dim; use the parsed value_length, falling
        # back to key_length only when the metadata didn't carry it.
        v_dim = profile.get("value_length", 0) or head_dim
        base = n_layer * n_kv * (head_dim + v_dim) * db

    hy = _hybrid_info(profile)
    if hy["hybrid"] and hy["interval"]:
        # Full attention applies only to every Nth layer — KV cache lives on
        # those layers alone (SSM state is ctx-independent, not per-token KV).
        attn_layers = max(1, n_layer // hy["interval"])
        base *= attn_layers / n_layer
    return int(base)


def _kv_per_1k_mb(profile: dict, kv_dtype: str, file_size_gb: float) -> float:
    """Either GGUF-exact or size-bucket fallback. Returned in MB per 1k tokens."""
    bpt = _kv_bytes_per_token(profile, kv_dtype)
    if bpt > 0:
        return (bpt * 1000) / (1024 * 1024)
    # Fallback: rough bucketed estimate when GGUF header was unreadable.
    if file_size_gb < 8:
        base = 30.0
    elif file_size_gb < 20:
        base = 60.0
    elif file_size_gb < 40:
        base = 100.0
    else:
        base = 180.0
    if kv_dtype == "q4_0":
        base *= 0.55
    elif kv_dtype == "f16":
        base *= 1.9
    return base


# ---- sliding-window attention (SWA) ----------------------------------------
# Mistral, Gemma 2/3, gpt-oss and others cap the KV cache of local-attention
# layers at the sliding window. Pricing those layers as full attention
# massively overestimates KV at big ctx and starves these models of context
# they can afford. The config comes straight from GGUF keys.
_SWA_PATTERN_SUFFIXES = ("sliding_window_pattern", "swa_pattern")


def _swa_info(profile: dict) -> dict | None:
    """Sliding-window attention config from GGUF metadata keys. Returns
    {"window": w, "pattern": p} or None. pattern p >= 2 means every p-th
    layer is FULL attention and the rest are windowed (Gemma 3 style: 5:1).
    pattern 0 = unknown mix (callers pick a conservative split)."""
    keys = profile.get("keys") or {}
    w = 0
    for k, v in keys.items():
        if k.lower().endswith("attention.sliding_window") and isinstance(v, (int, float)) and v:
            w = int(v)
            break
    if not w:
        return None
    p = 0
    for k, v in keys.items():
        kl = k.lower()
        if any(kl.endswith(suf) for suf in _SWA_PATTERN_SUFFIXES) and isinstance(v, (int, float)) and v >= 2:
            p = int(v)
            break
    return {"window": w, "pattern": p}


def _kv_total_bytes(profile: dict, kv_dtype: str, ctx_tokens: int, v_dtype: str = "") -> int:
    """KV cache size in bytes for a REAL context length — not a linear
    extrapolation. Same GGUF-exact base as _kv_bytes_per_token, but
    sliding-window layers contribute min(ctx, window) tokens instead of ctx.
    Hybrid SSM models keep the attention-layer-fraction scaling (their
    full-attention layers are treated as unwindowed — conservative).
    v_dtype enables split K/V cache (--cache-type-k/--cache-type-v): K is the
    sensitive half (softmax error propagation), V tolerates 4-bit fine.
    Returns 0 when GGUF metadata is unreadable."""
    n_layer = profile.get("block_count", 0) or 0
    if not n_layer or ctx_tokens <= 0:
        return 0
    db_k = _KV_DTYPE_BYTES.get(kv_dtype, 1.0625)
    db_v = _KV_DTYPE_BYTES.get(v_dtype, db_k) if v_dtype else db_k

    mla = _mla_dims(profile)
    hy = _hybrid_info(profile)
    if mla:
        kv_lora, qk_rope = mla
        # MLA stores one combined latent tensor — llama.cpp types it by
        # cache-type-k alone (no separate V cache exists).
        return int(n_layer * (kv_lora + qk_rope) * db_k * ctx_tokens)

    n_kv = profile.get("head_count_kv", 0) or 0
    head_dim = profile.get("key_length", 0) or 0
    if not (n_kv and head_dim):
        return 0
    v_dim = profile.get("value_length", 0) or head_dim
    per_layer_per_tok = n_kv * (head_dim * db_k + v_dim * db_v)

    if hy["hybrid"] and hy["interval"]:
        # Full attention applies only to every Nth layer — KV cache lives on
        # those layers alone (SSM state is ctx-independent, not per-token KV).
        attn_layers = max(1, n_layer // hy["interval"])
        return int(attn_layers * per_layer_per_tok * ctx_tokens)

    swa = _swa_info(profile)
    if swa:
        w = swa["window"]
        # Per-layer array metadata (gemma4-style): sliding_window_pattern is a
        # bool PER LAYER (True = windowed), head_count_kv varies per layer, and
        # windowed layers use smaller head dims (key/value_length_swa). Exact
        # per-layer math — a scalar-pattern guess is wildly wrong here.
        keys = profile.get("keys") or {}
        arch = profile.get("architecture") or ""
        pat = keys.get(f"{arch}.attention.sliding_window_pattern")
        hkv_arr = keys.get(f"{arch}.attention.head_count_kv")
        if isinstance(pat, list) and len(pat) == n_layer:
            k_swa = keys.get(f"{arch}.attention.key_length_swa")
            v_swa = keys.get(f"{arch}.attention.value_length_swa")
            if not isinstance(k_swa, (int, float)) or not k_swa:
                k_swa = head_dim
            if not isinstance(v_swa, (int, float)) or not v_swa:
                v_swa = v_dim
            total = 0
            for i in range(n_layer):
                heads = hkv_arr[i] if (isinstance(hkv_arr, list) and len(hkv_arr) == n_layer) else n_kv
                if pat[i]:
                    total += heads * (k_swa * db_k + v_swa * db_v) * min(ctx_tokens, w)
                else:
                    total += heads * (head_dim * db_k + v_dim * db_v) * ctx_tokens
            return int(total)
        if swa["pattern"]:
            full_layers = max(1, n_layer // swa["pattern"])
        elif "gptoss" in (profile.get("architecture") or "").lower() or "gpt-oss" in (profile.get("architecture") or "").lower():
            full_layers = (n_layer + 1) // 2  # gpt-oss alternates SWA / full
        else:
            # Pattern unknown: assume half the layers are full attention.
            # Deliberately conservative — for all-SWA models (Mistral) this
            # OVERestimates KV (smaller ctx, safe), never under.
            full_layers = (n_layer + 1) // 2
        swa_layers = max(0, n_layer - full_layers)
        total = full_layers * per_layer_per_tok * ctx_tokens
        total += swa_layers * per_layer_per_tok * min(ctx_tokens, w)
        return int(total)

    return int(n_layer * per_layer_per_tok * ctx_tokens)


def _kv_total_mb(profile: dict, kv_dtype: str, ctx_tokens: int, file_size_gb: float, v_dtype: str = "") -> float:
    """Context-exact KV cost in MB. GGUF-exact (SWA/MLA/hybrid aware, split
    K/V dtype aware) when the header was readable; linear size-bucket
    fallback otherwise."""
    b = _kv_total_bytes(profile, kv_dtype, ctx_tokens, v_dtype)
    if b > 0:
        return b / (1024 * 1024)
    return _kv_per_1k_mb(profile, kv_dtype, file_size_gb) * (ctx_tokens / 1000.0)


# ---- quant byte costs -------------------------------------------------------
# Average bytes per weight for common GGUF quants (post block-quant overhead).
# Used by the MoE offload speed model to turn "expert layers on CPU" into
# "bytes pulled through RAM per decoded token".
_QUANT_BPW = (
    ("IQ2", 0.35), ("Q2", 0.35),
    ("IQ3", 0.44), ("Q3", 0.44),
    ("IQ4", 0.58), ("Q4", 0.60),
    ("IQ5", 0.70), ("Q5", 0.72),
    ("Q6", 0.85),
    ("Q8", 1.06),
    ("F16", 2.0), ("BF16", 2.0), ("F32", 4.0),
)


def _quant_bpw(quant: str) -> float:
    q = (quant or "").upper()
    for prefix, bpw in _QUANT_BPW:
        if q.startswith(prefix):
            return bpw
    return 0.60  # Q4-ish default — the most common quant class


# ---- system memory probes (auto-tune safety) --------------------------------

def _system_ram_info():
    """(total_gb, available_gb) of system RAM, or None. Windows via
    GlobalMemoryStatusEx, Linux via /proc/meminfo, macOS via sysctl."""
    try:
        if os.name == "nt":
            import ctypes

            class _MEMSTATUSEX(ctypes.Structure):
                _fields_ = [("dwLength", ctypes.c_ulong), ("dwMemoryLoad", ctypes.c_ulong),
                            ("ullTotalPhys", ctypes.c_ulonglong), ("ullAvailPhys", ctypes.c_ulonglong),
                            ("ullTotalPageFile", ctypes.c_ulonglong), ("ullAvailPageFile", ctypes.c_ulonglong),
                            ("ullTotalVirtual", ctypes.c_ulonglong), ("ullAvailVirtual", ctypes.c_ulonglong),
                            ("ullAvailExtendedVirtual", ctypes.c_ulonglong)]

            m = _MEMSTATUSEX()
            m.dwLength = ctypes.sizeof(_MEMSTATUSEX)
            if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(m)):
                return m.ullTotalPhys / 1e9, m.ullAvailPhys / 1e9
        elif sys.platform == "darwin":
            import subprocess as _sp
            total = int(_sp.check_output(["sysctl", "-n", "hw.memsize"], text=True).strip())
            vm = _sp.check_output(["vm_stat"], text=True)
            free_pages = 0
            for line in vm.splitlines():
                if line.startswith("Pages free") or line.startswith("Pages inactive"):
                    free_pages += int(line.split(":")[1].strip().rstrip("."))
            return total / 1e9, (free_pages * 16384) / 1e9
        else:
            info = {}
            with open("/proc/meminfo") as f:
                for line in f:
                    k, _, rest = line.partition(":")
                    parts = rest.strip().split()
                    if parts and parts[0].isdigit():
                        info[k.strip()] = int(parts[0])  # kB
            if "MemTotal" in info:
                return info["MemTotal"] / 1e6, info.get("MemAvailable", info.get("MemFree", 0)) / 1e6
    except Exception:
        pass
    return None


def _running_instance_mem_mb() -> tuple[float, float]:
    """(ram_mb, vram_mb) held by the llama-server process this bridge most
    recently spawned; (0, 0) when nothing runs or the probe fails.

    Tuning for a model swap must not count the old instance's memory as used by
    someone else, since the swap frees it. Without the add-back, tuning while a
    big MoE is loaded sees ~2 GB free RAM and writes crippled configs (ctx 4096,
    too small for the system prompt + tools)."""
    pid = 0
    try:
        proc = getattr(_llama, "_proc", None)  # defined further down; call-time resolved
        if proc is not None and proc.poll() is None:
            pid = proc.pid
    except Exception:
        pid = 0
    if not pid:
        return 0.0, 0.0
    ram_mb = 0.0
    try:
        if os.name == "nt":
            import ctypes

            class _PMC(ctypes.Structure):
                _fields_ = [("cb", ctypes.c_ulong), ("PageFaultCount", ctypes.c_ulong),
                            ("PeakWorkingSetSize", ctypes.c_size_t), ("WorkingSetSize", ctypes.c_size_t),
                            ("QuotaPeakPagedPoolUsage", ctypes.c_size_t), ("QuotaPagedPoolUsage", ctypes.c_size_t),
                            ("QuotaPeakNonPagedPoolUsage", ctypes.c_size_t), ("QuotaNonPagedPoolUsage", ctypes.c_size_t),
                            ("PagefileUsage", ctypes.c_size_t), ("PeakPagefileUsage", ctypes.c_size_t)]

            h = ctypes.windll.kernel32.OpenProcess(0x1000, False, pid)  # PROCESS_QUERY_LIMITED_INFORMATION
            if h:
                pmc = _PMC()
                pmc.cb = ctypes.sizeof(_PMC)
                if ctypes.windll.psapi.GetProcessMemoryInfo(h, ctypes.byref(pmc), pmc.cb):
                    ram_mb = pmc.WorkingSetSize / (1024 * 1024)
                ctypes.windll.kernel32.CloseHandle(h)
        else:
            with open(f"/proc/{pid}/status", "r") as f:
                for line in f:
                    if line.startswith("VmRSS:"):
                        ram_mb = float(line.split()[1]) / 1024.0
                        break
    except Exception:
        ram_mb = 0.0
    vram_mb = 0.0
    try:
        smi = shutil.which("nvidia-smi")
        if smi:
            r = subprocess.run(
                [smi, "--query-compute-apps=pid,used_memory", "--format=csv,noheader,nounits"],
                capture_output=True, text=True, timeout=3,
                creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0),
            )
            if r.returncode == 0 and r.stdout.strip():
                for line in r.stdout.strip().splitlines():
                    parts = [p.strip() for p in line.split(",")]
                    if len(parts) == 2 and parts[0] == str(pid) and parts[1].isdigit():
                        vram_mb += float(parts[1])
    except Exception:
        vram_mb = 0.0
    if vram_mb <= 0 and os.name == "nt":
        # Under WDDM nvidia-smi reports every process's memory as "[N/A]", so the
        # add-back above reads 0; Windows' own per-process counter (what Task Manager
        # shows) has the real figure.
        vram_mb = _win_gpu_process_mem_mb(pid)
    return ram_mb, vram_mb


def _win_gpu_process_mem_mb(pid: int) -> float:
    """Dedicated GPU memory (MiB) a process holds, from Windows' GPU Process
    Memory performance counter. 0 when unavailable. ~1.5 s (PowerShell)."""
    if os.name != "nt" or not pid:
        return 0.0
    hit = _WIN_GPU_MEM_CACHE.get(pid)
    if hit and time.monotonic() - hit[0] < 10.0:    # one tune asks several times
        return hit[1]
    script = (f"$s=(Get-Counter '\\GPU Process Memory(pid_{int(pid)}_*)\\Dedicated Usage' "
              f"-ErrorAction SilentlyContinue).CounterSamples; "
              f"[math]::Round(($s | Measure-Object CookedValue -Sum).Sum/1MB)")
    try:
        r = subprocess.run(["powershell", "-NoProfile", "-NonInteractive", "-Command", script],
                           capture_output=True, text=True, timeout=15,
                           creationflags=subprocess.CREATE_NO_WINDOW)
        value = (r.stdout or "").strip().splitlines()[-1] if (r.stdout or "").strip() else ""
        mb = float(value) if value.replace(".", "", 1).isdigit() else 0.0
    except Exception:
        mb = 0.0
    _WIN_GPU_MEM_CACHE[pid] = (time.monotonic(), mb)
    return mb


_WIN_GPU_MEM_CACHE: dict = {}


def _free_vram_gb_for_tune() -> float:
    """Free VRAM for a tune that precedes a model load/swap: adds back the VRAM
    the running instance holds, which the swap frees."""
    det = detect_vram_gb()
    gb = float(det.get("free_total_gb") or det.get("gb") or 0)
    try:
        _ram_mb, vram_mb = _running_instance_mem_mb()
        if vram_mb > 0:
            gb += vram_mb / 1024.0
    except Exception:
        pass
    return round(gb, 2)


def _resolve_mmproj_for_tune(model_path: str, s: dict) -> str:
    """The mmproj (if any) a load of `model_path` would boot with, so
    auto_tune can reserve its VRAM. Mirrors the spawn path exactly."""
    mode = _normalized_mmproj_mode(s or {})
    if mode == "off":
        return ""
    mp = ((s or {}).get("mmproj_path") or "").strip()
    if mode == "manual":
        return mp if mp and safe_exists(mp) else ""
    if mode == "auto":
        try:
            return find_mmproj_for(model_path) or ""
        except Exception:
            return ""
    return ""


def _resolve_spec_draft_for_tune(model_path: str, s: dict) -> str:
    """The DFlash/DSpark draft GGUF a load of `model_path` would boot with, so
    auto_tune can reserve its VRAM. Mirrors the spawn path: only DFlash/DSpark
    use a side model; draft-mtp and n-gram draft from the main model itself.
    Empty when the decoder is explicitly unloaded (spec_draft_mode=off)."""
    if str((s or {}).get("spec_draft_mode") or "auto").strip().lower() == "off":
        return ""
    strategy = str((s or {}).get("spec_strategy") or "").strip().lower()
    if strategy not in {"dflash", "dspark"}:
        return ""
    configured = str((s or {}).get("spec_draft_model") or "").strip()
    if configured and safe_exists(configured):
        return configured
    # No explicit path: fall back to the metadata-validated pair on disk, which
    # is what the UI auto-fill selects for this model.
    paired = find_spec_draft_for(model_path) if model_path else {}
    if paired.get("matched") and paired.get("path") and safe_exists(paired["path"]):
        return paired["path"]
    return ""


def _runtime_spec_strategy(spec_strategy: str, mmproj_path: str) -> str:
    """Keep the chosen decoder loaded alongside native multimodal support."""
    return str(spec_strategy or "off").strip().lower()


def _speculative_choice(settings: dict, has_mtp: bool, is_moe: bool, nextn: int,
                        pair: dict, draft_kind: str) -> tuple[str, str]:
    """Pick the speculative-decoding strategy and its auto-tune note.

    A MANUAL choice always wins — auto-tuning and the setup advisor must never
    replace what the user explicitly selected. Otherwise a metadata-validated
    DFlash/DSpark pair on disk beats MTP: measured ~+50% decode (112 vs 75
    tok/s) on the reference Qwen3.8-27B + DFlash2 pair at equal context.
    Falls back to MTP heads → n-gram (dense) → off (MoE)."""
    manual = str((settings or {}).get("spec_strategy_source") or "").strip().lower() == "manual"
    saved = str((settings or {}).get("spec_strategy") or "").strip().lower()
    if manual and saved in {"off", "ngram-mod", "draft-mtp", "dflash", "dspark"}:
        return saved, f"speculative decoding: {saved} (manual choice kept)."
    if str((settings or {}).get("spec_draft_mode") or "auto").strip().lower() == "off":
        # Decoder explicitly unloaded — a validated pair on disk must not
        # resurrect it. Fall through to the draft-less policy below.
        pair = None
    if pair:
        kind = draft_kind if draft_kind in {"dflash", "dspark"} else "dflash"
        name = os.path.basename(str(pair.get("path") or "")) or "draft"
        return kind, (f"speculative decoding: {kind} (validated draft {name}; "
                      "measured faster than draft-mtp on this setup).")
    if has_mtp:
        if nextn:
            return "draft-mtp", (
                f"speculative decoding: draft-mtp ({nextn} MTP heads detected, ~1.85x decode win).")
        return "draft-mtp", "speculative decoding: draft-mtp (MTP-capable model by name, ~1.85x decode win)."
    if is_moe:
        return "off", "speculative decoding: OFF (n-gram is net-negative on MoE per public benchmarks)."
    return "ngram-mod", "speculative decoding: ngram-mod (free win on dense models)."


def _probe_ram_bandwidth_gbps() -> float:
    """One-shot system RAM bandwidth estimate via ctypes memcpy (128 MB buffer,
    8 passes, best of 3; read+write both traverse RAM). Returns 0 on failure.
    ~0.3-1s — meant to run once per machine, then be cached in settings."""
    import ctypes
    size = 128 * 1024 * 1024
    try:
        libc = ctypes.CDLL("msvcrt" if os.name == "nt" else None)
        memcpy = libc.memcpy
        memcpy.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t]
        memcpy.restype = ctypes.c_void_p
        src = ctypes.create_string_buffer(size)
        dst = ctypes.create_string_buffer(size)
        best = 0.0
        chunk = ctypes.c_size_t(size)
        for _ in range(3):
            t0 = time.perf_counter()
            for _ in range(8):
                memcpy(dst, src, chunk)
            dt = time.perf_counter() - t0
            if dt > 0:
                best = max(best, (8 * size * 2) / dt)
        return round(best / 1e9, 1) if best > 0 else 0.0
    except Exception:
        return 0.0


def _ram_bandwidth_gbps() -> float:
    """Resolve the RAM bandwidth for the MoE speed model. A raw settings value
    OTHER than the auto sentinel (30) is a manual override and wins. Otherwise
    use the cached probe; probe once and cache if missing; 30 GB/s fallback."""
    raw = load_json(SETTINGS_FILE, {})
    if isinstance(raw, dict):
        v = raw.get("ram_bandwidth_gbps")
        if isinstance(v, (int, float)) and v > 0 and v != 30:
            return float(v)
        v = raw.get("_ram_bw_probe_gbps")
        if isinstance(v, (int, float)) and v > 0:
            return float(v)
    bw = _probe_ram_bandwidth_gbps()
    if bw > 0:
        try:
            # Merge into the raw file (not get_settings()) so a concurrent
            # settings write can't be clobbered.
            raw = load_json(SETTINGS_FILE, {})
            if isinstance(raw, dict):
                raw["_ram_bw_probe_gbps"] = bw
                save_json(SETTINGS_FILE, raw)
        except Exception:
            pass
        return bw
    return 30.0


# ---- decode speed model + exact fit (auto-tune) ------------------------------
# Decode is memory-bound: every generated token reads the GPU-resident weights
# (for MoE only the active experts), the KV cache filled so far, and whatever
# weights live in system RAM. Predicted tok/s =
#     spec_gain × calibration / (gpu_bytes / gpu_bw + cpu_bytes / ram_bw)
# where gpu_bw starts from the card's published bandwidth and calibration is
# learned from the passive per-turn telemetry (_record_model_observation), so
# the estimate converges on this machine's real speed with no benchmark run.

# Published memory bandwidth (GB/s). First match wins, so within a family the
# longer name comes first ("4070 ti super" before "4070 ti" before "4070").
_GPU_BANDWIDTH_GBPS = (
    ("rtx pro 6000", 1792), ("5090", 1792), ("5080", 960), ("5070 ti", 896), ("5070", 672),
    ("5060 ti", 448), ("5060", 448),
    ("4090", 1008), ("4080 super", 736), ("4080", 717), ("4070 ti super", 672),
    ("4070 ti", 504), ("4070 super", 504), ("4070", 504), ("4060 ti", 288), ("4060", 272),
    ("3090 ti", 1008), ("3090", 936), ("3080 ti", 912), ("3080", 760), ("3070 ti", 608),
    ("3070", 448), ("3060 ti", 448), ("3060", 360),
    ("2080 ti", 616), ("2080 super", 496), ("2080", 448), ("2070", 448), ("2060", 336),
    ("titan rtx", 672), ("6000 ada", 960), ("a6000", 768), ("a5000", 768), ("a4500", 640),
    ("a4000", 448), ("l40s", 864), ("l40", 864), ("a100", 1555), ("h200", 4800), ("h100", 2000),
    ("r9700", 640), ("7900 xtx", 960), ("7900 xt", 800), ("9070 xt", 640), ("9070", 640),
)
# Share of peak bandwidth llama.cpp decode reaches before calibration kicks in.
_DECODE_BW_EFFICIENCY = 0.72
# CPU-side expert/layer math runs well below a memcpy probe's bandwidth.
# Fitted to a measured run: a Q8 35B-A3B with 23-25 of 41 expert layers on CPU
# decodes ~45-51 tok/s on a 4090 + 82 GB/s RAM.
_CPU_DECODE_EFFICIENCY = 0.4
# Speculative drafts barely help MoE: each drafted token routes to different
# experts, so verifying a draft reads more expert weights.
_SPEC_GAIN_MOE = 1.05
# Speedup each speculative strategy is assumed to give before this model has
# measured turns (calibration then absorbs the real figure). draft-mtp's is at
# draft length 3; other lengths scale by _MTP_LEN_FACTOR, measured back to back
# on a 4090 / 27B Q4 (1 → 70, 2 → 88, 3 → 93, 4 → 92 tok/s).
_SPEC_GAIN_DEFAULT = {"off": 1.0, "ngram-mod": 1.0, "draft-mtp": 1.5, "dflash": 1.8, "dspark": 1.8}
_MTP_LEN_FACTOR = {1: 0.75, 2: 0.94, 3: 1.0, 4: 0.99, 5: 0.97, 6: 0.95}
_FIT_CTX_CAP = 262144


def _typical_fill_tokens(model_path: str) -> tuple[int, str]:
    """How full this user's chats actually get: the 90th-percentile peak
    prompt size of recorded turns on this model, else across every model,
    else 32k. The speed floor is judged here, because a bigger context window
    costs no decode speed until it's filled — only its VRAM (which on MoE
    pushes experts to RAM) slows every reply."""
    def p90(vals: list[int]) -> int:
        vals = sorted(vals)
        return vals[min(len(vals) - 1, int(len(vals) * 0.9))]
    try:
        models = (load_json(MODEL_RUNTIME_FILE, {}) or {}).get("models") or {}
    except Exception:
        models = {}
    mine_keys = {_model_profile_key(model_path), Path(str(model_path)).stem}
    mine, everyone = [], []
    for key, row in models.items():
        for cfg in (row.get("configs") or {}).values():
            for o in cfg.get("observations") or []:
                peak = int(o.get("peak_context_tokens") or 0)
                if peak > 0:
                    everyone.append(peak)
                    if key in mine_keys:
                        mine.append(peak)
    if len(mine) >= 5:
        return max(8192, p90(mine)), f"your {len(mine)} recorded turns on this model"
    if len(everyone) >= 5:
        return max(8192, p90(everyone)), "your recorded turns across all models"
    return 32768, "default — no recorded turns yet"


def _gpu_bandwidth_gbps(name: str, total_gb: float) -> tuple[float, str]:
    """(GB/s, source) for a GPU: published figure by name, else a conservative
    guess from its VRAM size. Laptop parts run well below their desktop names."""
    n = " ".join(str(name or "").lower().split())
    for key, gbps in _GPU_BANDWIDTH_GBPS:
        if key in n:
            if "laptop" in n or "mobile" in n:
                return gbps * 0.6, f"{key} laptop (est.)"
            return float(gbps), key
    gb = float(total_gb or 0)
    guess = 900.0 if gb >= 23 else 600.0 if gb >= 15 else 450.0 if gb >= 11 else 300.0 if gb >= 7 else 200.0
    return guess, f"unknown GPU, {gb:.0f} GB class (est.)"


def _tune_gpus(vram_gb: float) -> list[dict]:
    """Detected GPUs as [{name, total_gb, free_gb, bw_gbps, bw_src}]. Falls back
    to one GPU of `vram_gb` when nvidia-smi isn't available."""
    det = detect_vram_gb()
    gpus = []
    for g in det.get("gpus") or []:
        bw, src = _gpu_bandwidth_gbps(g.get("name", ""), g.get("total_gb", 0))
        gpus.append({**g, "bw_gbps": bw, "bw_src": src})
    if not gpus:
        bw, src = _gpu_bandwidth_gbps("", vram_gb)
        gpus = [{"name": "GPU", "total_gb": vram_gb, "free_gb": vram_gb, "bw_gbps": bw, "bw_src": src}]
    return gpus


def _effective_gpu_bw(gpus: list[dict]) -> float:
    """Layer split runs the GPUs one after another per token, each over its
    share of the weights (llama.cpp splits by free memory) — so the combined
    rate is the share-weighted harmonic mean of their bandwidths."""
    weights = [max(float(g.get("free_gb") or g.get("total_gb") or 0), 0.1) for g in gpus]
    total = sum(weights)
    inv = sum((w / total) / max(float(g["bw_gbps"]), 1.0) for w, g in zip(weights, gpus))
    return 1.0 / inv if inv > 0 else 300.0


def _decode_bytes_per_token(profile: dict, size_mb: float, *, kv_dtype: str, v_dtype: str,
                            fill: int, n_cpu_moe: int = 0, num_gpu: int = 99,
                            dense_share=None, active_expert_bytes: float = 0.0) -> tuple[float, float]:
    """(gpu_bytes, cpu_bytes) read per decoded token. MoE reads its dense part
    plus only the active experts; dense models read every weight. The KV read
    grows with how much of the context is filled."""
    n_layer = int(profile.get("block_count", 0) or 0)
    model_bytes = max(size_mb, 0.0) * 1048576.0
    try:
        kv_read = float(_kv_total_bytes(profile, kv_dtype, max(int(fill), 1), v_dtype) or 0)
    except Exception:
        kv_read = 0.0
    if profile.get("is_moe") and active_expert_bytes > 0 and dense_share and n_layer:
        off = min(max(int(n_cpu_moe), 0), n_layer) / n_layer
        dense_bytes = model_bytes * float(dense_share)
        return dense_bytes + active_expert_bytes * (1 - off) + kv_read, active_expert_bytes * off
    if n_layer and 0 < num_gpu < n_layer:
        frac = num_gpu / n_layer
        return model_bytes * frac + kv_read, model_bytes * (1 - frac)
    return model_bytes + kv_read, 0.0


def _decode_tok_s(gpu_bytes: float, cpu_bytes: float, *, gpu_bw_gbps: float, ram_bw_gbps: float,
                  spec_gain: float = 1.0, calib: float = 1.0) -> float:
    t = gpu_bytes / (max(gpu_bw_gbps, 1.0) * 1e9 * _DECODE_BW_EFFICIENCY)
    if cpu_bytes > 0:
        t += cpu_bytes / (max(ram_bw_gbps, 1.0) * 1e9 * _CPU_DECODE_EFFICIENCY)
    return (spec_gain * calib / t) if t > 0 else float("inf")


def _decode_observations(model_path: str) -> list[tuple[dict, dict]]:
    """(config settings, observation) pairs with enough output to time decode,
    newest last, for one model from the passive telemetry file."""
    try:
        data = load_json(MODEL_RUNTIME_FILE, {})
        models = (data or {}).get("models") or {}
        # Turns land under the chat's model name — usually the file stem ("X"
        # for X.gguf) — and some callers record the full file name. Read both.
        rows = [models.get(k) or {} for k in
                dict.fromkeys((_model_profile_key(model_path), Path(str(model_path)).stem))]
    except Exception:
        return []
    pairs = []
    for cfg in [c for row in rows for c in (row.get("configs") or {}).values()]:
        settings = cfg.get("settings") or {}
        for o in cfg.get("observations") or []:
            if int(o.get("output_tokens") or 0) >= 64 and float(o.get("eval_ms") or 0) > 0:
                pairs.append((settings, o))
    pairs.sort(key=lambda p: p[1].get("ts", 0))
    return pairs[-80:]


def _decode_calibration(model_path: str, predict) -> tuple[float, int]:
    """Median of measured ÷ predicted decode speed over this model's recorded
    turns (each predicted for its own config and context fill). (1.0, 0) until
    at least 5 usable turns exist. Clamped so one odd week can't run away."""
    ratios = []
    for settings, o in _decode_observations(model_path):
        try:
            measured = float(o["output_tokens"]) / (float(o["eval_ms"]) / 1000.0)
            predicted = predict(settings, int(o.get("peak_context_tokens") or 0))
        except Exception:
            continue
        if predicted and predicted != float("inf") and measured > 0:
            ratios.append(min(max(measured / predicted, 0.2), 5.0))
    if len(ratios) < 5:
        return 1.0, len(ratios)
    ratios.sort()
    mid = len(ratios) // 2
    med = ratios[mid] if len(ratios) % 2 else (ratios[mid - 1] + ratios[mid]) / 2
    return min(max(med, 0.4), 2.5), len(ratios)


def _draft_length_choice(model_path: str, current: int) -> tuple[int, str]:
    """MTP draft length from measured acceptance at the current length. One
    step per tune, toward whichever side the acceptance rate points:
    measured on a 4090 / 27B, 3 drafts at ~62% acceptance beat 1 (83%) by
    33% and 4 (50%) by 1%. Needs >= 200 drafted tokens at that length."""
    cur = current if current > 0 else 3
    drafted = accepted = 0
    for settings, o in _decode_observations(model_path):
        ran_n = int(settings.get("spec_draft_n_max") or settings.get("spec_draft_n_eff") or 0)
        if ran_n != cur or settings.get("spec_strategy") != "draft-mtp":
            continue
        drafted += int(o.get("draft_n") or 0)
        accepted += int(o.get("draft_accepted") or 0)
    if drafted < 200:
        return cur, (f"draft length {cur} (default; acceptance not measured yet)" if cur == 3
                     else f"draft length {cur} (kept; {drafted} drafted tokens measured, need 200)")
    rate = accepted / drafted
    nxt = cur
    if rate < 0.45 and cur > 1:
        nxt = cur - 1
    elif rate > 0.72 and cur < 6:
        nxt = cur + 1
    verdict = "kept" if nxt == cur else f"→ {nxt}"
    return nxt, f"draft length {cur} {verdict} (measured acceptance {rate:.0%} over {drafted:,} drafted tokens)"


# -- exact fit via llama-fit-params --------------------------------------------
_FIT_PARAMS_CACHE: dict = {}


def _fit_params_bin() -> str:
    """llama-fit-params beside the configured llama-server, or ''."""
    server = find_llama_bin() or ""
    if not server:
        return ""
    p = Path(server)
    for name in ("llama-fit-params.exe", "llama-fit-params"):
        cand = p.with_name(name)
        if cand.is_file():
            return str(cand)
    return ""


def _fit_params_measure(model_path: str, ctx: int, *, ngl: int, n_cpu_moe: int, kv_k: str,
                        kv_v: str, ubatch: int, batch: int, flash: bool) -> dict | None:
    """llama.cpp's own memory estimate for one configuration, without loading
    the model: {"devices": {name: total MiB}, "ctx": {name: context MiB},
    "host": MiB}. None when the tool is missing or the run fails. ~0.6 s."""
    exe = _fit_params_bin()
    if not exe or not model_path:
        return None
    args = ["-m", model_path, "-c", str(int(ctx)), "-ngl", str(int(ngl) if ngl < 99 else 999),
            "-ctk", kv_k or "f16", "-ctv", kv_v or kv_k or "f16",
            "-fa", "on" if flash else "off", "-ub", str(int(ubatch)), "-b", str(int(batch)),
            "-fit", "off", "-fitp", "on"]
    if n_cpu_moe > 0:
        args += ["--n-cpu-moe", str(int(n_cpu_moe))]
    try:
        key = (exe, os.path.getmtime(model_path), tuple(args))
    except Exception:
        key = (exe, 0, tuple(args))
    if key in _FIT_PARAMS_CACHE:
        return _FIT_PARAMS_CACHE[key]
    result = None
    try:
        r = subprocess.run([exe] + args, capture_output=True, text=True, timeout=60,
                           creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0))
        devices, ctx_mib, host = {}, {}, 0.0
        for line in (r.stdout or "").splitlines():
            m = re.fullmatch(r"\s*(\S+)\s+(\d+)\s+(\d+)\s+(\d+)\s*", line)
            if not m:
                continue
            name, model_mib, context_mib, compute_mib = m.group(1), *map(float, m.groups()[1:])
            if name.lower().startswith("host"):
                host = model_mib + context_mib + compute_mib
            else:
                devices[name] = model_mib + context_mib + compute_mib
                ctx_mib[name] = context_mib
        if devices:
            result = {"devices": devices, "ctx": ctx_mib, "host": host}
    except Exception:
        result = None
    _FIT_PARAMS_CACHE[key] = result
    return result


def auto_tune(model_path: str, vram_gb: float, profile: dict = None, min_ctx: int = 0,
              proven_cfg: dict = None) -> dict:
    """Suggest llama-server flags for a (model, VRAM) pair.

    Uses GGUF header metadata (layer count, expert count, GQA config) when
    available for accurate KV cache + MoE expert offload math. Falls back to
    size-bucket heuristics when the header is unreadable. Returns the same
    keys the Settings drawer uses plus `notes` (multi-line reasoning) and
    `quant_downshift` (banner shown when the model needs heavy offload).
    `profile` may be passed in to reuse an existing inspect_model() result.

    The (ctx, n_cpu_moe) pair is chosen by a joint optimizer: KV cache is
    priced at the EXACT context of each tier (sliding-window layers cap at
    their window, MLA caches latents, hybrid SSMs scale by attention-layer
    fraction), and expert offload is gated by a decode-speed model (RAM
    bandwidth ÷ active expert bytes per token) instead of a fixed layer cap —
    so both dense and MoE models get the largest context that still decodes
    at a usable speed. Floors/overrides: `min_tok_s_estimate`,
    `ram_bandwidth_gbps` in settings.

    `min_ctx` makes context grow-only: when it's larger than the picked tier,
    the solver re-runs pinned to the smallest tier >= min_ctx and recomputes
    the offload for THAT ctx. The pinned combo is kept only if it fits within
    the same offload caps the normal solve uses; otherwise the normal pick
    stands and a note explains the saved ctx doesn't fit. Absent/0/smaller
    min_ctx changes nothing.

    `proven_cfg` — a previously STAMPED per-model config whose server boot
    actually succeeded (see _stamp_proven_boot). When its ctx covers min_ctx,
    the budget estimate is outranked: the saved ctx and offload combo are
    honored verbatim, because a config that booted and ran beats any estimate
    of what "should" fit.

    Leaves ~8% VRAM headroom when GGUF math is exact, ~15% when falling back
    to filename heuristics. Disables speculative decoding for MoE because
    independent benchmarks show it's net-negative there.
    """
    profile = profile or inspect_model(model_path)
    notes: list[str] = []
    size_gb = profile["size_gb"] or 0.0
    is_moe = profile["is_moe"]
    n_layer = profile.get("block_count", 0) or 0
    src = profile.get("metadata_source", "filename")
    vram = max(float(vram_gb or 0), 0)

    # Default flags everyone gets
    out = {
        "num_gpu": 99,                 # all non-MoE layers on GPU
        "n_cpu_moe": 0,                # MoE-only; auto below
        "kv_cache_type": "q8_0",       # K cache — best balance
        "kv_cache_type_v": "",         # V cache — "" = same as K (mirrored at spawn). Tuner never splits
                                       # K/V (measured: q8_0/q4_0 = +1.6% PPL AND slow path on this machine);
                                       # q4_0 only as a ≤12 GB VRAM escape hatch (ladder below)
        "num_ctx": 32768,
        "num_batch": 512,
        "n_ubatch": 0,                 # auto in spawn
        "num_thread": 0,               # auto = let llama-server pick
        "flash_attn": True,
        "spec_strategy": "ngram-mod",   # off | ngram-mod | draft-mtp — set per-model below
        "no_warmup": False,
        "enable_metrics": False,
        "quant_downshift": "",          # banner string; "" = no suggestion
    }

    if vram <= 0:
        out["notes"] = "no VRAM tier set — using safe defaults. set a tier and Suggest again."
        return out
    if size_gb <= 0:
        out["notes"] = "no model selected — pick a model first, then Suggest."
        return out

    # Useable VRAM budget. With exact GGUF-derived KV math we can run hot —
    # ~8% headroom for CUDA workspace + alignment. Filename fallback is fuzzier
    # so we leave more slack. Two SEPARATE reserves:
    #   - vram_reserve_gb: minimal GPU-side safety for the Windows desktop
    #     compositor on single-GPU machines (default 0.25 GB; user-tunable to
    #     0 = give the LLM everything — the headroom still guards CUDA).
    #   - safety_reserve_gb (reserve_gb): SYSTEM RAM only, applied further
    #     down as the floor under CPU offload — the anti-bluescreen guard.
    _s_tune = get_settings()
    try:
        reserve_gb = max(float(_s_tune.get("safety_reserve_gb") or 0), 0.0)
    except Exception:
        reserve_gb = 1.0
    try:
        _vr = _s_tune.get("vram_reserve_gb")
        vram_reserve_gb = max(float(0.25 if _vr is None else _vr), 0.0)
    except Exception:
        vram_reserve_gb = 0.25
    # K / V cache types chosen in the Auto-tune panel ("auto" / "" = tuner's pick).
    kv_pref = str(_s_tune.get("autotune_kv_cache") or "auto").strip().lower()
    if kv_pref not in _AUTOTUNE_KV_CHOICES:
        kv_pref = "auto"
    kv_v_pref = str(_s_tune.get("autotune_kv_cache_v") or "").strip().lower()
    if kv_v_pref not in _AUTOTUNE_KV_CHOICES - {"auto"}:
        kv_v_pref = ""
    headroom = 0.92 if src == "gguf" else 0.85
    budget_mb = max(vram - vram_reserve_gb, 0.5) * headroom * 1024

    # Vision projector reserve: an mmproj loading alongside the model (explicit
    # path or mmproj_auto sibling) takes real VRAM that the KV/weights math must
    # not spend, or tuned loads with vision on can OOM at boot.
    mmproj_mb = 0.0
    _mp_name = ""
    try:
        _mp = _resolve_mmproj_for_tune(model_path, _s_tune)
        if _mp:
            _mp_name = os.path.basename(_mp)
            mmproj_mb = os.path.getsize(_mp) / (1024 * 1024)
            budget_mb = max(budget_mb - mmproj_mb, 256.0)
    except Exception:
        mmproj_mb = 0.0
    # Speculative intent — decided BEFORE the draft reserve so an auto-tuned
    # pick also pays for its draft:
    #   * a manual choice is honored as-is (the advisor must not nag it away);
    #   * otherwise prefer a metadata-validated DFlash/DSpark pair (measured
    #     ~+50% decode over draft-mtp on the reference box);
    #   * otherwise the existing MTP / n-gram / off policy below decides.
    _spec_manual = str(_s_tune.get("spec_strategy_source") or "").strip().lower() == "manual"
    _spec_saved = str(_s_tune.get("spec_strategy") or "").strip().lower()
    _spec_valid = {"off", "ngram-mod", "draft-mtp", "dflash", "dspark"}
    if _spec_saved not in _spec_valid:
        _spec_manual = False
        _spec_saved = ""
    _auto_pair: dict = {}
    _pairing_off = str(_s_tune.get("spec_draft_mode") or "auto").strip().lower() == "off"
    if not _spec_manual and not _pairing_off and model_path:
        try:
            _candidate = find_spec_draft_for(model_path)
            if _candidate.get("matched") and _candidate.get("path"):
                _auto_pair = _candidate
        except Exception:
            _auto_pair = {}
    draft_mb = 0.0
    _draft_name = ""
    _draft_kind = ""
    try:
        _draft = _resolve_spec_draft_for_tune(model_path, _s_tune)
        if not _draft and _auto_pair.get("path"):
            _draft = str(_auto_pair["path"])
        if _draft:
            _draft_name = os.path.basename(_draft)
            try:
                _draft_kind = str(_spec_fingerprint(_draft).get("architecture") or "").lower()
            except Exception:
                _draft_kind = ""
            draft_mb = os.path.getsize(_draft) / (1024 * 1024)
            # The draft needs its own small KV cache and compute graph too.
            # Five-layer sliding-window drafts (DFlash) are only a few hundred
            # MB there, so reserve a bounded extra rather than a flat guess.
            draft_mb += max(192.0, draft_mb * 0.15)
            budget_mb = max(budget_mb - draft_mb, 256.0)
    except Exception:
        draft_mb = 0.0
    if src == "gguf":
        moe_tag = ""
        if is_moe:
            moe_tag = (f" · MoE {profile['expert_count']} experts, "
                       f"{profile['expert_used_count']} active/token")
        notes.append(
            f"GGUF: {profile['architecture']} · {n_layer} layers · "
            f"GQA head_kv={profile['head_count_kv']} key_len={profile['key_length']}{moe_tag}"
        )
    else:
        notes.append("GGUF header unreadable — using size-bucket fallback (less accurate).")
    notes.append(
        f"VRAM budget: {vram:.1f} GB − {vram_reserve_gb:.2f} GB GPU reserve · "
        f"usable {budget_mb/1024:.1f} GB ({int(headroom*100)}%). "
        f"System-RAM reserve {reserve_gb:.1f} GB applies to CPU offload only."
    )
    if mmproj_mb:
        notes.append(
            f"vision projector: {mmproj_mb:.0f} MB reserved "
            f"({_mp_name} loads alongside the model — disable mmproj to reclaim it)."
        )
    if draft_mb:
        notes.append(
            f"speculative draft: {draft_mb:.0f} MB reserved "
            f"({_draft_name} loads alongside the model — context sized to fit it)."
        )

    # -- KV cache dtype --
    # q8_0 is the quality/cost sweet spot; f16 only with obvious headroom. An
    # explicit choice in the Auto-tune panel overrides both.
    if kv_pref != "auto":
        out["kv_cache_type"] = kv_pref
        notes.append(f"KV cache: K {kv_pref} (your choice in Auto-tune).")
    elif vram >= 24 and size_gb < vram * 0.4:
        out["kv_cache_type"] = "f16"
        notes.append("KV cache: f16 (you have headroom).")
    else:
        out["kv_cache_type"] = "q8_0"
        notes.append("KV cache: q8_0 (zero perplexity loss baseline).")
    if kv_v_pref and kv_v_pref != out["kv_cache_type"]:
        out["kv_cache_type_v"] = kv_v_pref
        notes.append(f"KV cache: V {kv_v_pref} (your choice in Auto-tune). Mixed K/V types run on "
                     f"llama.cpp's slower attention path.")

    # -- MTP detection (hoisted above the context solver: the draft-mtp choice
    # feeds the compute-overhead reserve below, and the speculative section
    # further down reuses this result) --
    # Primary signal: GGUF metadata key "<arch>.nextn_predict_layers" set by
    # llama.cpp's own converter for MTP-capable arches. Reliable — no false
    # positives from filenames, no false negatives from non-canonical names.
    has_mtp = bool(profile.get("has_mtp", False))
    if not has_mtp and profile.get("metadata_source") != "gguf":
        # Fallback: filename / arch heuristic, for GGUFs that lost the metadata
        # during conversion or third-party repacks that didn't carry it through.
        name_blob = ((profile.get("name") or "") + " " + (profile.get("architecture") or "")).lower()
        _MTP_HINTS = (
            "qwen3.5", "qwen3.6", "qwen-3.5", "qwen-3.6", "qwen_3.5", "qwen_3.6",
            "qwen3_5", "qwen3_6", "qwen_3_5", "qwen_3_6",
            "deepseek-v3", "deepseek_v3", "deepseekv3",
            "deepseek-r1", "deepseek_r1", "deepseekr1",
        )
        has_mtp = any(h in name_blob for h in _MTP_HINTS)
        if has_mtp:
            _EXCLUDE_MTP = ("distil", "distill", "distilled", "glm")
            if any(e in name_blob for e in _EXCLUDE_MTP):
                has_mtp = False

    # -- Context window + n_cpu_moe (joint optimization) --
    # Bigger ctx eats KV VRAM, which forces more expert offload, which slows
    # decoding. Pick the largest ctx whose required offload stays tolerable
    # (<=70% of layers). KV is priced per tier at the exact context via
    # _kv_total_mb (SWA layers cap at their window), and the notes say which KV
    # path is in use (MLA latent cache / hybrid scaling / sliding window).
    mla = _mla_dims(profile)
    hy = _hybrid_info(profile)
    swa = _swa_info(profile)
    if src == "gguf":
        if mla:
            notes.append(
                f"KV math: MLA latent cache (kv_lora_rank={mla[0]} + qk_rope={mla[1]}, "
                f"not per-head K/V)."
            )
        if hy["hybrid"]:
            if hy["interval"] and n_layer:
                attn_layers = max(1, n_layer // hy["interval"])
                pct = int(round(100.0 * attn_layers / n_layer))
                notes.append(
                    f"hybrid SSM/attention detected ({hy['evidence']}): full attention every "
                    f"{hy['interval']} layers — KV scaled to ~{pct}% of layers."
                )
            else:
                notes.append(
                    f"hybrid SSM/attention detected ({hy['evidence']}) but attention-layer "
                    f"fraction unknown — KV kept conservative (all layers treated as full attention)."
                )
        if swa and not mla and not (hy["hybrid"] and hy["interval"]):
            _w = swa["window"]
            _pat_arr = (profile.get("keys") or {}).get(
                f"{profile.get('architecture') or ''}.attention.sliding_window_pattern")
            if swa["pattern"] and n_layer:
                _full = max(1, n_layer // swa["pattern"])
                notes.append(
                    f"sliding-window attention: window {_w:,} tokens, every "
                    f"{swa['pattern']} layers full ({n_layer - _full} of {n_layer} layers "
                    f"windowed) — their KV caps at the window, so long context is cheap."
                )
            elif isinstance(_pat_arr, list) and n_layer and len(_pat_arr) == n_layer:
                _full = sum(1 for x in _pat_arr if not x)
                notes.append(
                    f"sliding-window attention: window {_w:,} tokens, per-layer pattern from "
                    f"GGUF ({_full} full + {n_layer - _full} windowed, windowed layers use "
                    f"smaller head dims) — exact KV math."
                )
            elif n_layer:
                _full = (n_layer + 1) // 2
                notes.append(
                    f"sliding-window attention: window {_w:,} tokens "
                    f"(layer pattern unknown — conservatively treated as {_full} full + "
                    f"{n_layer - _full} windowed layers)."
                )

    size_mb = size_gb * 1024
    # Tier ladder. The GGUF-reported trained context is deliberately not
    # enforced: many GGUFs report a conservative value the model handles fine past
    # (RoPE/YaRN), so it is shown in notes only.
    trained_max = int(profile.get("context_length", 0) or 0)
    ctx_tiers = (262144, 131072, 98304, 65536, 49152, 32768, 24576, 16384, 12288, 8192, 4096)

    # -- Compute buffer + runtime overhead reserve --
    # Three deterministic parts:
    #   1. compute buffer: 256MB floor, scaled by batch tokens x embedding width
    #      (activations, scratch, attention work area), sized for the largest
    #      batch we might pick (2048). Flat 1536MB when embd is unknown.
    #   2. runtime allowance: fixed 400MB for CUDA context + driver on GPU tiers.
    #   3. MTP overhead, from measured breakdowns (4090, 27B qwen35 hybrid, one
    #      slot): head weights (nextn x per-layer size) + 3 extra copies of the
    #      recurrent state on hybrids (~150 MiB each) + two draft compute buffers
    #      of ~196 MiB per 512 of ubatch each. The draft's own f16 KV cache grows
    #      with context, so it is priced per tier (_kvx).
    embd = profile.get("embedding_length", 0) or 0
    if embd:
        compute_mb = 256.0 + (2048.0 / 512.0) * (embd / 4096.0) * 384.0
    else:
        compute_mb = 1536.0  # no embd from GGUF — keep the old flat reserve
    runtime_mb = 400.0
    mtp_mb = 0.0
    draft_kv_per_tok = 0.0       # bytes/token of the MTP draft's own KV cache
    _tune_caps = llama_caps(find_llama_bin() or "")
    nextn = int(profile.get("nextn_predict_layers", 0) or 0)
    mtp_fixed_mb = 0.0           # MTP head weights + extra recurrent state
    mtp_compute_per_512 = 0.0    # MTP draft compute, per 512 tokens of ubatch
    # The ubatch the batch heuristics below will settle on (full GPU: 1024
    # from 24 GB up, else 512) — the exact fit re-prices with the real one.
    _ub_assumed = 1024 if vram >= 24 else 512
    if has_mtp and nextn and n_layer and size_mb > 0:
        mtp_fixed_mb = nextn * (size_mb / n_layer) + (3 * 150.0 if hy["hybrid"] else 0.0)
        mtp_compute_per_512 = 2 * 200.0
        mtp_mb = mtp_fixed_mb + mtp_compute_per_512 * _ub_assumed / 512
        _bpe = 2.0               # f16 draft KV (see the spawn note on -ctkd)
        _hkv = profile.get("head_count_kv") or 0
        _hkv = max(_hkv) if isinstance(_hkv, list) and _hkv else _hkv
        _kl = int(profile.get("key_length") or 0)
        if _hkv and _kl:
            draft_kv_per_tok = nextn * 2 * int(_hkv) * _kl * _bpe
    compute_buf_mb = compute_mb + runtime_mb + mtp_mb
    notes.append(
        f"overhead reserve: {compute_buf_mb:.0f} MB "
        f"(compute buffer {compute_mb:.0f} MB scaled to batch 2048 × embd {embd or 'unknown'}"
        f" + runtime {runtime_mb:.0f} MB"
        + (f" + MTP {mtp_mb:.0f} MB ({nextn} heads)" if mtp_mb else "") + ")."
        + (f" MTP draft KV: {draft_kv_per_tok / 1024:.1f} KB/token, priced per context tier."
           if draft_kv_per_tok else "")
    )

    def _kvx(kv_dtype: str, tier: int, v_dtype: str = "") -> float:
        """KV MB at `tier` tokens, including the MTP draft's own KV cache."""
        return (_kv_total_mb(profile, kv_dtype, tier, size_gb, v_dtype)
                + draft_kv_per_tok * tier / (1024 * 1024))

    # -- MoE dense/expert split (analytic when GGUF carries the fields) --
    keys = profile.get("keys") or {}
    arch_name = profile.get("architecture") or ""
    dense_share = None
    if is_moe and n_layer > 0:
        exp_cnt = profile.get("expert_count", 0) or 0
        exp_ffn = profile.get("expert_feed_forward_length", 0) or 0
        if embd and exp_cnt and exp_ffn:
            # Element counts; the dtype factor cancels in the ratio.
            # attention ≈ 4·embd² (q/k/v/o projections — documented
            # approximation; exact head dims rarely move the ratio much).
            attn_per_layer = 4 * embd * embd
            shared_per_layer = 0
            shared_ffn = keys.get(f"{arch_name}.expert_shared_feed_forward_length")
            shared_cnt = keys.get(f"{arch_name}.expert_shared_count")
            if isinstance(shared_ffn, (int, float)) and shared_ffn:
                shared_per_layer = 3 * int(shared_ffn) * embd
            elif isinstance(shared_cnt, (int, float)) and shared_cnt:
                shared_per_layer = int(shared_cnt) * 3 * exp_ffn * embd
            dense_per_layer = attn_per_layer + shared_per_layer
            expert_per_layer = exp_cnt * 3 * exp_ffn * embd
            dense_share = max(0.03, min(0.50, dense_per_layer / (dense_per_layer + expert_per_layer)))
            notes.append(
                f"MoE dense share: {dense_share*100:.1f}% (analytic: attention 4·embd²"
                f"{' + shared expert' if shared_per_layer else ''} "
                f"vs {exp_cnt} experts × 3·{exp_ffn}·embd)."
            )
        else:
            # Heuristic fallback (~10-15% for big MoEs, more for small ones), used only
            # when the GGUF lacks the fields above.
            dense_share = max(0.08, min(0.20, 1.5 / max(profile.get("expert_count", 8), 1) + 0.08))
            notes.append(
                f"MoE dense share: {dense_share*100:.1f}% (heuristic fallback — "
                f"GGUF lacks embd/expert-FFN fields for the analytic split)."
            )

    # Embedding + LM head are never offloaded by --n-cpu-moe — reserve them as
    # fixed VRAM when we can size them. vocab × embd × 2 tensors × ~2 bytes
    # (f16-ish: a conservative overestimate for quantized embedding tables).
    embed_mb = 0.0
    if is_moe and embd:
        vocab = keys.get(f"{arch_name}.vocab_size")
        if not (isinstance(vocab, (int, float)) and vocab):
            tok = keys.get("tokenizer.ggml.tokens")
            vocab = tok.get("__array_len__", 0) if isinstance(tok, dict) else 0
        if vocab:
            embed_mb = (int(vocab) * embd * 2 * 2) / (1024 * 1024)
            notes.append(
                f"embedding + LM head reserve: {embed_mb:.0f} MB "
                f"(vocab {int(vocab):,} × embd {embd} × 2 tensors, not offloadable)."
            )

    # -- MoE offload speed model --
    # --n-cpu-moe moves whole layers' experts to CPU RAM, but every decoded
    # token still activates expert_used_count experts in those layers — so the
    # CPU share decodes at roughly RAM-bandwidth / bytes-per-token. We estimate
    # that and refuse (ctx, offload) combos that decode below the user's floor:
    # context you can only read at 2 tok/s is not a win, it's a trap.
    # The user's floor (Settings → Minimum speed). Applies to dense and MoE.
    try:
        min_tok_s = max(float(_s_tune.get("min_decode_tok_s") or 45), 1.0)
    except Exception:
        min_tok_s = 45.0
    expert_tok_bytes = 0.0
    if is_moe and n_layer > 0 and embd:
        _eu = profile.get("expert_used_count", 0) or 0
        _ef = profile.get("expert_feed_forward_length", 0) or 0
        if _eu and _ef:
            # Bytes per weight from the file itself (size ÷ parameter count from
            # the same element counts as the dense/expert split), not the quant
            # name: many GGUFs carry no quant label, and the Q4-ish fallback
            # under-counted a Q8 35B-A3B's expert reads ~1.8× (predicted 141
            # tok/s vs ~51 measured).
            _bpw = _quant_bpw(profile.get("quant", ""))
            _ecnt = profile.get("expert_count", 0) or 0
            _vocab = keys.get(f"{arch_name}.vocab_size") or 0
            if not (isinstance(_vocab, (int, float)) and _vocab):
                _tok = keys.get("tokenizer.ggml.tokens")
                _vocab = _tok.get("__array_len__", 0) if isinstance(_tok, dict) else 0
            if _ecnt and size_mb > 0:
                _params = n_layer * (4 * embd * embd + _ecnt * 3 * _ef * embd) + int(_vocab or 0) * embd * 2
                if _params > 0:
                    _bpw = min(max(size_mb * 1048576 / _params, 0.25), 2.2)
            expert_tok_bytes = _eu * 3 * _ef * embd * _bpw
    # RAM bandwidth: auto-probed (memcpy benchmark, cached per machine) unless
    # the user pinned a manual value. Probed lazily — only when the speed
    # model will actually run; the benchmark costs ~0.5s once per machine.
    # expert_tok_bytes is ONE layer's active experts; a token crosses every
    # layer. (The old estimate scaled the single-layer figure by the offloaded
    # SHARE, under-counting CPU bytes ~n_layer× — so the floor never fired.)
    active_expert_bytes = expert_tok_bytes * n_layer if expert_tok_bytes > 0 else 0.0
    ram_bw_gbps = 30.0
    if expert_tok_bytes > 0 or size_mb > budget_mb:
        ram_bw_gbps = _ram_bandwidth_gbps()
        notes.append(f"RAM bandwidth: {ram_bw_gbps:.0f} GB/s (auto-probed unless pinned in settings).")

    # System-RAM safety cap: CPU-offloaded experts (and dense partial-offload
    # layers) live in system RAM. Cap offload at (available − OS reserve) × 0.9
    # so Windows never starts thrashing to fit the model.
    ram_cap_mb = None
    ram_info = _system_ram_info()
    if ram_info:
        total_ram_gb, avail_ram_gb = ram_info
        # Swap-aware: a tune almost always precedes a load that stops the running
        # instance first, so add its RSS back to available RAM (otherwise a re-tune
        # with a big MoE loaded sees almost nothing free).
        inst_ram_mb, _inst_vram_mb = _running_instance_mem_mb()
        if inst_ram_mb > 0:
            avail_ram_gb += inst_ram_mb / 1024.0
            notes.append(
                f"running instance holds {inst_ram_mb/1024:.1f} GB RAM — counted as free "
                f"(a model swap releases it before the new load allocates)."
            )
        ram_cap_mb = max((avail_ram_gb - reserve_gb) * 1024 * 0.9, 0)
        if is_moe or size_mb > budget_mb:
            notes.append(
                f"system RAM: {avail_ram_gb:.1f} GB free of {total_ram_gb:.0f} GB — "
                f"CPU offload capped at {ram_cap_mb/1024:.1f} GB (OS reserve kept)."
            )

    # -- decode speed prediction (see _decode_tok_s) --
    tune_gpus = _tune_gpus(vram)
    gpu_bw_gbps = _effective_gpu_bw(tune_gpus)
    spec_for_speed, _ = _speculative_choice(_s_tune, has_mtp, is_moe, nextn, _auto_pair, _draft_kind)

    def _predict(fill: int, *, n_off: int = 0, num_gpu: int = 99, kv_k: str = "", kv_v: str = "",
                 spec: str = "", draft_n: int = 3, calib_factor: float = 1.0) -> float:
        kv_k = kv_k or out.get("kv_cache_type") or "q8_0"
        gpu_b, cpu_b = _decode_bytes_per_token(
            profile, size_mb, kv_dtype=kv_k, v_dtype=kv_v, fill=fill, n_cpu_moe=n_off,
            num_gpu=num_gpu, dense_share=dense_share, active_expert_bytes=active_expert_bytes)
        gain = _SPEC_GAIN_DEFAULT.get(spec or spec_for_speed, 1.0)
        if (spec or spec_for_speed) == "draft-mtp":
            gain *= _MTP_LEN_FACTOR.get(min(max(int(draft_n or 3), 1), 6), 1.0)
        if is_moe:
            gain = min(gain, _SPEC_GAIN_MOE)
        return _decode_tok_s(gpu_b, cpu_b, gpu_bw_gbps=gpu_bw_gbps, ram_bw_gbps=ram_bw_gbps,
                             spec_gain=gain, calib=calib_factor)

    def _predict_settings(cfg: dict, fill: int) -> float:
        """Uncalibrated prediction for a recorded config (calibration input). Turns
        recorded before the launch draft length was tracked ran MTP at the GGUF
        head count, usually 1."""
        _dn = int(cfg.get("spec_draft_n_eff") or cfg.get("spec_draft_n_max") or (nextn or 1))
        return _predict(fill, n_off=int(cfg.get("n_cpu_moe") or 0),
                        num_gpu=int(cfg.get("num_gpu") or 99),
                        kv_k=str(cfg.get("kv_cache_type") or "q8_0"),
                        kv_v=str(cfg.get("kv_cache_type_v") or ""),
                        spec=str(cfg.get("spec_strategy") or "off"), draft_n=_dn)

    calib, calib_n = _decode_calibration(model_path, _predict_settings)
    typical_fill, fill_src = _typical_fill_tokens(model_path)
    notes.append(
        f"speed model: {gpu_bw_gbps:.0f} GB/s GPU ({', '.join(g['bw_src'] for g in tune_gpus)})"
        + (f", calibrated ×{calib:.2f} from {calib_n} measured turns" if calib_n >= 5
           else f", uncalibrated ({calib_n} measured turns, needs 5)")
        + f"; floor {min_tok_s:g} tok/s judged at your usual chat size, ~{typical_fill:,} tokens "
          f"({fill_src})."
    )

    def _est_tok_s(n_off: int, ctx_tokens: int = 0) -> float:
        """Predicted decode tok/s (calibrated) with n_off expert layers on CPU,
        at the user's usual chat size (never more than the window holds)."""
        fill = min(typical_fill, ctx_tokens) if ctx_tokens > 0 else typical_fill
        return _predict(fill, n_off=n_off, calib_factor=calib)

    def _kv_marginal_mb_per_tok(k_dt: str, v_dt: str = "") -> float:
        """Marginal KV cost (MB) per extra context token, from a finite
        difference taken high above any sliding window — so windowed layers
        contribute their true marginal (zero past the window) instead of an
        average. 0 when GGUF metadata is unreadable."""
        draft_mb_tok = draft_kv_per_tok / (1024 * 1024)
        b_hi = _kv_total_bytes(profile, k_dt, 131072, v_dt)
        b_lo = _kv_total_bytes(profile, k_dt, 65536, v_dt)
        if b_hi > b_lo:
            return (b_hi - b_lo) / (131072 - 65536) / (1024 * 1024) + draft_mb_tok
        b = _kv_total_bytes(profile, k_dt, 65536, v_dt)
        return ((b / 65536) / (1024 * 1024) + draft_mb_tok) if b else 0.0

    # Exact-fit top-up guard: keep this much budget unspent for CUDA
    # fragmentation/allocation jitter when converting leftover VRAM into
    # extra context tokens.
    _TOPUP_GUARD_MB = 96.0

    def _topup_ctx(base_ctx: int, leftover_mb: float, k_dt: str, v_dt: str = "") -> int:
        """Spend leftover budget on context directly — the tier ladder is
        coarse (64k → 96k → 128k) and would otherwise leave real tokens on
        the table. Returns the exact-fit ctx (rounded down to a 4096-token
        multiple), or base_ctx when the gain isn't worth it (<5%)."""
        marg = _kv_marginal_mb_per_tok(k_dt, v_dt)
        if marg <= 0 or leftover_mb <= _TOPUP_GUARD_MB:
            return base_ctx
        extra = int((leftover_mb - _TOPUP_GUARD_MB) / marg)
        exact = min(ctx_tiers[0], (base_ctx + extra) // 4096 * 4096)
        return exact if exact >= int(base_ctx * 1.05) else base_ctx

    def _solve(kv_dtype: str, pinned_tier: int = 0, v_dtype: str = ""):
        """Pick (ctx, n_cpu_moe) for a KV dtype pair (v_dtype="" mirrors kv_dtype).

        KV is priced at the exact context of each tier (_kv_total_mb). With
        pinned_tier=0 the ladder is scanned for the largest ctx that fits and
        decodes at or above the speed floor, then an exact-fit top-up spends the
        leftover budget on tokens beyond the coarse tier; with a pinned tier only
        that tier is evaluated. Returns (ctx, n_cpu_moe, note_lines, fits); fits is
        False only for a pinned tier that busts the budget or needs more offload
        than the caps allow. May set out["quant_downshift"]."""
        tier_notes: list[str] = []
        kv_tag = f"{kv_dtype}/{v_dtype}" if v_dtype and v_dtype != kv_dtype else kv_dtype
        if is_moe and n_layer > 0:
            expert_total_mb = max(size_mb * (1 - dense_share) - embed_mb, size_mb * 0.1)
            expert_per_layer_mb = expert_total_mb / n_layer
            # Hard offload ceiling: 85% of layers when the speed model can
            # price the tradeoff (past that almost no compute stays on the
            # GPU anyway), 70% when it can't (missing GGUF expert fields).
            max_offload_layers = int(n_layer * (0.85 if expert_tok_bytes > 0 else 0.7))
            # System-RAM clamp: offloaded experts live in RAM — never offload
            # more than (available RAM − OS reserve) can actually hold.
            if ram_cap_mb is not None and expert_per_layer_mb > 0:
                max_offload_layers = min(max_offload_layers,
                                         int(ram_cap_mb // expert_per_layer_mb))
            # Fast zone: offload at or below this share is always acceptable
            # without consulting the speed floor — the hit is modest.
            fast_zone_layers = int(n_layer * 0.30)

            chosen_ctx = 0
            chosen_n_cpu_moe = 0
            rejected_slow: list = []   # (tier, need_offload, est_tok_s) — fit but slow
            for tier in ([pinned_tier] if pinned_tier else ctx_tiers):
                kv_mb = _kvx(kv_dtype, tier, v_dtype)
                available_for_model = budget_mb - kv_mb - compute_buf_mb - embed_mb
                if available_for_model <= 0:
                    continue  # KV alone busts the budget
                if available_for_model >= size_mb:
                    # Whole model + KV + compute fits. No offload, max speed.
                    chosen_ctx = tier
                    chosen_n_cpu_moe = 0
                    break
                shortfall = size_mb - available_for_model
                need_offload = int((shortfall + expert_per_layer_mb - 1) // expert_per_layer_mb)
                if need_offload > max_offload_layers:
                    continue
                est = _est_tok_s(need_offload, tier)
                # A pinned tier is the user's saved ctx — speed never vetoes it.
                # The fast zone only stands in when the speed model has no
                # expert sizes to work with.
                if est >= min_tok_s or pinned_tier or (
                        expert_tok_bytes <= 0 and need_offload <= fast_zone_layers):
                    chosen_ctx = tier
                    chosen_n_cpu_moe = need_offload
                    break
                rejected_slow.append((tier, need_offload, est))
            if not chosen_ctx and rejected_slow and not pinned_tier:
                # Every fitting tier decodes under the floor: take the fastest one (smallest
                # ctx, least offload). Usable context beats unusable context.
                tier, need_offload, est = rejected_slow[-1]
                chosen_ctx, chosen_n_cpu_moe = tier, need_offload
                tier_notes.append(
                    f"speed floor relaxed: larger tiers all decoded under "
                    f"{min_tok_s:g} tok/s est. — took {tier:,} tokens at ~{est:.0f} tok/s instead."
                )
            if not chosen_ctx:
                if pinned_tier:
                    # Pinned tier doesn't fit within the offload caps.
                    return pinned_tier, n_layer, [], False
                chosen_ctx = ctx_tiers[-1]  # smallest as fallback
                # Most offload the caps allow — never past the RAM cap, or
                # we'd fix a VRAM problem by creating a system-RAM problem.
                chosen_n_cpu_moe = max_offload_layers
            # Fit reality check: if the model doesn't fit even at the caps, say so with
            # the quant-downshift banner instead of a config that OOMs at boot.
            if chosen_n_cpu_moe > 0 and chosen_n_cpu_moe >= max_offload_layers and expert_per_layer_mb > 0:
                kv_check = _kvx(kv_dtype, chosen_ctx, v_dtype)
                avail_check = budget_mb - kv_check - compute_buf_mb - embed_mb
                shortfall_check = size_mb - avail_check
                need_check = int((shortfall_check + expert_per_layer_mb - 1) // expert_per_layer_mb)
                if need_check > max_offload_layers:
                    cur_q = profile.get("quant", "Q4_K_M")
                    suggest_q = "Q3_K_S" if cur_q.upper().startswith("Q4") else "IQ3_XS"
                    out["quant_downshift"] = (
                        f"This model can't fit on this machine: even offloading the max "
                        f"{max_offload_layers}/{n_layer} expert layers it falls "
                        f"{shortfall_check/1024:.1f} GB short at {chosen_ctx:,} ctx. "
                        f"Grab the {suggest_q} quant, free up VRAM/RAM, or raise the OS reserve tradeoff."
                    )
                    out["does_not_fit"] = True
                    tier_notes.append(
                        f"WARNING: model does not fit — {need_check} expert layers would need "
                        f"offloading but caps allow {max_offload_layers}. Expect boot failure."
                    )
            kv_at_chosen = _kvx(kv_dtype, chosen_ctx, v_dtype)
            # Exact-fit top-up: spend leftover budget on context beyond the
            # coarse tier. Offload stays valid — the fit math above guarantees
            # the total (KV + compute + embed + on-GPU weights) stays within
            # budget, and the top-up guard keeps 96 MB unspent for jitter.
            if not pinned_tier and chosen_ctx < ctx_tiers[0] and expert_per_layer_mb > 0:
                vram_used = (kv_at_chosen + compute_buf_mb + embed_mb
                             + size_mb - chosen_n_cpu_moe * expert_per_layer_mb)
                topped = _topup_ctx(chosen_ctx, budget_mb - vram_used, kv_dtype, v_dtype)
                if topped != chosen_ctx:
                    tier_notes.append(
                        f"exact-fit top-up: ctx {chosen_ctx:,} → {topped:,} "
                        f"(spent leftover budget at "
                        f"{_kv_marginal_mb_per_tok(kv_dtype, v_dtype)*1024:.1f} KB/token marginal KV)."
                    )
                    chosen_ctx = topped
                    kv_at_chosen = _kvx(kv_dtype, chosen_ctx, v_dtype)
            if chosen_n_cpu_moe == 0:
                tier_notes.append(
                    f"context: {chosen_ctx:,} tokens · n_cpu_moe: 0 "
                    f"(model fits fully in VRAM at this context, KV ≈ {kv_at_chosen:.0f} MB)."
                )
            else:
                est = _est_tok_s(chosen_n_cpu_moe, chosen_ctx)
                est_txt = (f"; est. decode ~{est:.0f} tok/s at {ram_bw_gbps:.0f} GB/s RAM"
                           if est != float("inf") else "")
                tier_notes.append(
                    f"context: {chosen_ctx:,} tokens · n_cpu_moe: {chosen_n_cpu_moe} of {n_layer} "
                    f"(KV ≈ {kv_at_chosen:.0f} MB; offloading {chosen_n_cpu_moe} expert layers to fit + leave room{est_txt})."
                )
            # Offloading more than half the layers even at the chosen context leaves real
            # throughput on the table; suggest a smaller quant.
            if chosen_n_cpu_moe > n_layer * 0.5:
                cur_q = profile.get("quant", "Q4_K_M")
                suggest_q = "Q3_K_S" if cur_q.upper().startswith("Q4") else "IQ3_XS"
                out["quant_downshift"] = (
                    f"Offloading {chosen_n_cpu_moe}/{n_layer} layers at {cur_q or 'this quant'}. "
                    f"Grab the {suggest_q} variant for ~3-5x throughput with full context."
                )
            return chosen_ctx, chosen_n_cpu_moe, tier_notes, True
        if is_moe:
            # No layer count from GGUF — fall back to ratio formula + old context calc.
            if pinned_tier:
                est_ctx = pinned_tier
                # Fit check: KV + compute must leave something for the model.
                fits = budget_mb - _kvx(kv_dtype, est_ctx, v_dtype) - compute_buf_mb > 0
            else:
                ctx_budget_mb = budget_mb * 0.45
                est_ctx = ctx_tiers[-1]
                for tier in ctx_tiers:
                    if _kvx(kv_dtype, tier, v_dtype) <= ctx_budget_mb:
                        est_ctx = tier
                        break
                fits = True
            shortfall_gb = (size_gb * 1.1) - vram
            ratio = max(0.0, min(1.0, shortfall_gb / max(size_gb, 1)))
            est_n_cpu_moe = max(0, min(int(round(ratio * 50)), 60))
            tier_notes.append(f"context: {est_ctx:,} tokens (estimated — no layer count from GGUF).")
            tier_notes.append(f"n_cpu_moe: {est_n_cpu_moe} (estimated).")
            return est_ctx, est_n_cpu_moe, tier_notes, fits
        # Dense model: max context that fits alongside model weights. KV is
        # priced exactly per tier, so SWA dense models (Gemma, Mistral) get
        # the big windows their windowed layers make nearly free.
        if pinned_tier:
            kv_mb = _kvx(kv_dtype, pinned_tier, v_dtype)
            if size_mb + kv_mb + compute_buf_mb > budget_mb:
                return pinned_tier, 0, [], False
            dense_ctx = pinned_tier
        else:
            dense_ctx = ctx_tiers[-1]
            fits_any = False
            for tier in ctx_tiers:
                kv_mb = _kvx(kv_dtype, tier, v_dtype)
                if size_mb + kv_mb + compute_buf_mb <= budget_mb:
                    dense_ctx = tier
                    fits_any = True
                    break
            if not fits_any and not pinned_tier:
                # Even the smallest tier busts VRAM. The num_gpu section can still split
                # dense layers GPU/CPU, but if VRAM + offloadable RAM can't hold the weights,
                # say so instead of persisting a config that OOMs at boot.
                _ram_hold = ram_cap_mb if ram_cap_mb is not None else size_mb
                if size_mb + compute_buf_mb > budget_mb + _ram_hold:
                    cur_q = profile.get("quant", "Q4_K_M")
                    suggest_q = "Q3_K_M" if cur_q.upper().startswith("Q4") else "Q4_K_S"
                    out["does_not_fit"] = True
                    out["quant_downshift"] = (
                        f"This model can't fit on this machine: {size_mb/1024:.1f} GB of weights "
                        f"vs {budget_mb/1024:.1f} GB VRAM + {_ram_hold/1024:.1f} GB offloadable RAM. "
                        f"Grab a smaller quant ({suggest_q}) or free up memory."
                    )
        # Exact-fit top-up: the tier ladder is coarse — spend the leftover
        # budget on context directly instead of leaving it on the table.
        if not pinned_tier and dense_ctx < ctx_tiers[0]:
            kv_at_chosen = _kvx(kv_dtype, dense_ctx, v_dtype)
            leftover = budget_mb - (size_mb + kv_at_chosen + compute_buf_mb)
            topped = _topup_ctx(dense_ctx, leftover, kv_dtype, v_dtype)
            if topped != dense_ctx:
                tier_notes.append(
                    f"exact-fit top-up: ctx {dense_ctx:,} → {topped:,} "
                    f"(spent {leftover:.0f} MB leftover budget at "
                    f"{_kv_marginal_mb_per_tok(kv_dtype, v_dtype)*1024:.1f} KB/token marginal KV)."
                )
                dense_ctx = topped
        kv_at_chosen = _kvx(kv_dtype, dense_ctx, v_dtype)
        tier_notes.append(
            f"context: {dense_ctx:,} tokens "
            f"(KV ≈ {kv_at_chosen:.0f} MB at {kv_tag})."
        )
        return dense_ctx, 0, tier_notes, True

    chosen_ctx, chosen_n_cpu_moe, tier_notes, _ = _solve(out["kv_cache_type"],
                                                         v_dtype=out.get("kv_cache_type_v") or "")

    # -- KV dtype policy --
    # K cache is q8_0 by default, f16 only with obvious VRAM headroom (pass 1
    # above). The tuner never emits a split K/V and never q4_0 on its own, except
    # the escape hatch below for GPUs with <=12 GB where context is genuinely
    # scarce. A K/V choice made in the Auto-tune panel is used as given.
    # Same-machine measurements (llama-perplexity, Qwen3.6-27B-Q4_K_M, 5x8192
    # chunks, 150k-char corpus):
    #   q8_0/q8_0  +0.2% PPL vs f16 (noise) and fast (~4 s/pass)
    #   q8_0/q4_0  +1.6% PPL and a slow mixed-dtype path (~184 s/pass); the KIVI
    #               "free V quant" claim (arXiv:2402.02750) does not hold here
    #   q8_0/f16   +1.8% PPL, slow path (~70 s/pass)
    #   q4_0/f16   +2.6% PPL, slow path (~67 s/pass)
    #   q4_0/q4_0  never measured to completion (slow path)
    # So q8_0/q8_0 is both the accuracy pick and the fast pick.
    if (kv_pref == "auto" and not kv_v_pref and out["kv_cache_type"] != "f16"
            and vram <= 12.0 and chosen_ctx < 32768):
        # Escape hatch: q4_0 only on small GPUs (≤12 GB VRAM) with starved
        # context — below 16k we accept a 1.5× gain, between 16k and 32k we
        # demand 2×. Above 32k the conversation already has room to work, and
        # on bigger GPUs q8_0 KV fits — the quality cost is never worth it.
        gain_needed = 1.5 if chosen_ctx < 16384 else 2.0
        prev_downshift = out["quant_downshift"]
        out["quant_downshift"] = ""
        ctx_q4, moe_q4, q4_tier_notes, _ = _solve("q4_0", v_dtype="q4_0")
        if ctx_q4 >= int(chosen_ctx * gain_needed):
            out["kv_cache_type"] = "q4_0"
            out["kv_cache_type_v"] = ""
            chosen_ctx, chosen_n_cpu_moe, tier_notes = ctx_q4, moe_q4, q4_tier_notes
            notes.append(
                f"KV cache: switched to q4_0 (≤12 GB VRAM) — context was starved at q8_0 and "
                f"q4_0 buys ≥{gain_needed:g}× context (now {chosen_ctx:,} tokens)."
            )
        else:
            out["quant_downshift"] = prev_downshift
            notes.append(
                f"KV cache: kept {out['kv_cache_type']} — q4_0 retry only buys "
                f"{ctx_q4 / max(chosen_ctx, 1):.1f}× context (<{gain_needed:g}× threshold)."
            )

    # -- Grow-only context (min_ctx) --
    # Callers pass their saved num_ctx so a re-tune never silently downgrades
    # context, and never pairs a big saved ctx with offload computed for a smaller
    # one (a combo the solver rejected, which can OOM at boot). If the saved ctx
    # beats our pick, re-solve pinned to the smallest tier >= min_ctx and keep it
    # only when that ctx's offload stays within the normal caps.
    #
    # Proven configs outrank the estimate: a ctx llama-server actually booted with
    # on this machine (stamped by _stamp_proven_boot) fits by definition. When
    # proven covers min_ctx, the offload keys come straight from the proven combo.
    min_ctx = int(min_ctx or 0)
    proven = proven_cfg if isinstance(proven_cfg, dict) else {}
    if ((kv_pref != "auto" and str(proven.get("kv_cache_type") or "q8_0").lower() != kv_pref)
            or (kv_v_pref and str(proven.get("kv_cache_type_v") or proven.get("kv_cache_type") or "q8_0").lower()
                != kv_v_pref)):
        proven = {}      # it booted with other cache types, so it proves nothing here
    honored_proven = False
    if min_ctx > chosen_ctx:
        p_ctx_saved = int(proven.get("proven_ctx") or proven.get("num_ctx") or 0)
        pinned = min((t for t in ctx_tiers if t >= min_ctx), default=None)
        if p_ctx_saved >= min_ctx:
            # Honor the proven ctx outright; the offload keys are re-applied after the
            # batch/thread heuristics below.
            chosen_ctx = min_ctx
            chosen_n_cpu_moe = max(0, int(proven.get("n_cpu_moe") or 0))
            honored_proven = True
            notes.append(f"honored proven ctx {min_ctx:,} — this exact combo booted "
                         f"successfully on this machine, so it outranks the VRAM "
                         f"budget estimate.")
        elif pinned is not None:
            p_ctx, p_moe, p_tier_notes, p_fits = _solve(out["kv_cache_type"], pinned_tier=pinned,
                                                        v_dtype=out.get("kv_cache_type_v") or "")
            if p_fits:
                chosen_ctx, chosen_n_cpu_moe, tier_notes = p_ctx, p_moe, p_tier_notes
                notes.append(
                    f"honored existing ctx {min_ctx:,} (pinned tier {pinned:,}; "
                    f"offload recomputed for that context)."
                )
            else:
                kv_pinned = _kv_total_mb(profile, out["kv_cache_type"], pinned, size_gb,
                                         out.get("kv_cache_type_v") or "")
                notes.append(
                    f"saved ctx {min_ctx:,} doesn't fit the current VRAM budget "
                    f"(KV alone ≈ {kv_pinned:.0f} MB at tier {pinned:,}) — "
                    f"not honored; using {chosen_ctx:,} instead."
                )
        else:
            notes.append(
                f"saved ctx {min_ctx:,} exceeds the tuner's {ctx_tiers[0]:,} ceiling — "
                f"not honored; using {chosen_ctx:,} instead."
            )

    out["num_ctx"] = chosen_ctx
    out["n_cpu_moe"] = chosen_n_cpu_moe
    notes.extend(tier_notes)
    if trained_max:
        notes.append(f"GGUF reports trained max {trained_max:,} tokens (informational, not enforced).")

    # -- num_gpu (dense partial offload) --
    if not is_moe and size_gb * 1024 > budget_mb:
        frac_on_gpu = max(0.2, budget_mb / (size_gb * 1024))
        if ram_cap_mb is not None:
            # Offloaded dense layers live in system RAM — raise the GPU share
            # if the CPU side would bust (available RAM − OS reserve).
            min_frac = 1.0 - ram_cap_mb / (size_gb * 1024)
            if min_frac > frac_on_gpu:
                frac_on_gpu = min(min_frac, 1.0)
                notes.append(
                    f"system RAM cap raised GPU share to {int(frac_on_gpu*100)}% — "
                    f"more CPU offload than this would exceed free RAM + OS reserve."
                )
        if n_layer > 0:
            out["num_gpu"] = max(8, int(n_layer * frac_on_gpu))
            notes.append(
                f"num_gpu: {out['num_gpu']} of {n_layer} layers "
                f"(dense model too big — partial offload, expect slow tok/s)."
            )
            # Quant downshift hint for dense too
            if frac_on_gpu < 0.6:
                cur_q = profile.get("quant", "")
                suggest_q = "Q3_K_M" if cur_q.upper().startswith("Q4") else "Q4_K_S"
                out["quant_downshift"] = (
                    f"Only {int(frac_on_gpu*100)}% of layers fit on GPU. "
                    f"A smaller quant ({suggest_q}) would run much faster."
                )
        else:
            out["num_gpu"] = max(8, int(80 * frac_on_gpu))
            notes.append(f"num_gpu: {out['num_gpu']} layers (dense partial offload).")

    # -- Speculative decoding --
    # One decision table (see _speculative_choice): manual wins, then a
    # validated DFlash/DSpark pair, then MTP, then n-gram/off.
    out["spec_strategy"], _spec_note = _speculative_choice(
        _s_tune, has_mtp, is_moe, nextn, _auto_pair, _draft_kind)
    notes.append(_spec_note)

    # -- batch / ubatch / threads --
    # With CPU offload, bigger batches dramatically improve prompt eval because
    # the PCIe transfer is amortized over more tokens; 512 is too small there.
    cpu_offload = out["n_cpu_moe"] > 0 or (not is_moe and out["num_gpu"] < 99)
    if cpu_offload:
        out["num_batch"] = 2048
        notes.append("batch: 2048 (offloading).")
    elif vram >= 24:
        out["num_batch"] = 2048
    elif vram >= 16:
        out["num_batch"] = 1024

    # Sanity: batch must never exceed ctx (llama.cpp rejects n_batch > n_ctx).
    if out["num_batch"] > out["num_ctx"]:
        out["num_batch"] = max(512, out["num_ctx"])
        notes.append(f"batch: clamped to {out['num_batch']} (was larger than ctx {out['num_ctx']:,}).")

    # Micro-batch: 512 only with CPU offload (larger values thrash L3 and RAM
    # bandwidth on CPU-offloaded MoEs). Full-GPU runs get 0 = auto, and the spawn
    # path picks min(max(n_batch//2, 512), 1024).
    if cpu_offload:
        out["n_ubatch"] = 512
        notes.append("n_ubatch: 512 (CPU offload active — larger ubatch thrashes L3/RAM bandwidth).")
    else:
        out["n_ubatch"] = 0
        notes.append("n_ubatch: 0 (auto — spawn path picks min(max(n_batch//2, 512), 1024) for full-GPU runs).")

    # Threads matter when part of the model lives on CPU. Physical-core
    # heuristic: half the logical count, floor 4. 0 = llama-server default.
    if cpu_offload:
        out["num_thread"] = max(4, (os.cpu_count() or 8) // 2)
        notes.append(f"threads: {out['num_thread']} (CPU offload active — physical-core heuristic).")
    else:
        out["num_thread"] = 0
        notes.append("threads: 0 (server default — full GPU offload).")

    # An honored proven combo re-applies last, so the heuristics above can't
    # recompute away values that demonstrably booted.
    if honored_proven:
        for _pk in ("num_gpu", "kv_cache_type", "kv_cache_type_v",
                    "num_batch", "n_ubatch", "num_thread"):
            if proven.get(_pk) is not None:
                out[_pk] = proven[_pk]
        # Same sanity llama.cpp enforces on its own flags.
        if out["num_batch"] > out["num_ctx"]:
            out["num_batch"] = max(512, out["num_ctx"])
            notes.append(f"batch: clamped to {out['num_batch']} (was larger than ctx {out['num_ctx']:,}).")

    # -- MTP draft length (from measured acceptance) --
    if out["spec_strategy"] == "draft-mtp":
        try:
            _cur_n = int(_s_tune.get("spec_draft_n_max") or 0)
        except (TypeError, ValueError):
            _cur_n = 0
        out["spec_draft_n_max"], _dl_note = _draft_length_choice(model_path, _cur_n)
        notes.append(f"speculative: {_dl_note}.")
    else:
        out["spec_draft_n_max"] = 0

    # -- MoE expert cache (llama.cpp #29887) --
    # Never switched on by the tuner. Measured on a 4090 (PCIe 4.0 x16, 82 GB/s
    # RAM) with a Q8 35B-A3B, 25 of 41 expert layers on CPU, warm A/B/A runs:
    # a 2.5 GB cache decoded ~40% SLOWER (27 vs 45-50 tok/s). The PR's gains
    # came from much larger caches on bigger cards, which here would cost the
    # context. A value set by hand is kept, and its VRAM is priced below.
    try:
        cache_mb = float(max(int(_s_tune.get("moe_cache_mib") or 0), 0)) if out["n_cpu_moe"] > 0 else 0.0
    except (TypeError, ValueError):
        cache_mb = 0.0
    if cache_mb:
        notes.append(f"MoE expert cache: {cache_mb:.0f} MiB kept from Settings (its VRAM comes out of context).")

    # -- Exact fit (llama-fit-params) --
    # llama.cpp's own estimate of model + KV + compute per device for this exact
    # config (no model load, ~0.6 s). It replaces the ~8% blanket headroom with
    # a measured number, and the slack becomes context. Things the tool can't
    # see (vision projector, speculative drafts, the MoE cache) are added on.
    _ctx_floor_exact = min_ctx if min_ctx > 0 else 4096
    exact_mem = None          # (used MiB, usable MiB) when llama-fit-params ran
    if bool(_s_tune.get("exact_fit", True)) and src == "gguf" and not out.get("does_not_fit"):
        _b = int(out.get("num_batch") or 512)
        _ub = int(out.get("n_ubatch") or 0) or min(max(_b // 2, 512), 4096)
        _kk = out.get("kv_cache_type") or "q8_0"
        _kv2 = out.get("kv_cache_type_v") or _kk
        _flash = bool(_s_tune.get("flash_attn", True))

        def _fit(c: int, ub: int = _ub, b: int = _b):
            return _fit_params_measure(model_path, c, ngl=int(out.get("num_gpu") or 99),
                                       n_cpu_moe=int(out.get("n_cpu_moe") or 0), kv_k=_kk,
                                       kv_v=_kv2, ubatch=ub, batch=b, flash=_flash)

        c0 = int(out["num_ctx"])
        m0 = _fit(c0)
        if m0:
            devs = list(m0["devices"])
            # Memory the new load may use on each device: free now, plus what
            # the running instance holds (a reload frees it), capped by a
            # user-set VRAM tier, minus a small margin (+ the GPU reserve on
            # the display card).
            try:
                _inst_vram = _running_instance_mem_mb()[1]
            except Exception:
                _inst_vram = 0.0
            tier_gb = float(_s_tune.get("vram_tier_gb") or 0)
            avail: dict = {}
            for i, d in enumerate(devs):
                g = tune_gpus[i] if i < len(tune_gpus) else tune_gpus[-1]
                free_mb = float(g.get("free_gb") or 0) * 1024
                if i == 0:
                    free_mb += _inst_vram
                    if tier_gb > 0 and len(devs) == 1:
                        others = float(g.get("total_gb") or tier_gb) * 1024 - free_mb
                        free_mb = min(free_mb, tier_gb * 1024 - max(others, 0.0))
                avail[d] = free_mb - 320.0 - (vram_reserve_gb * 1024 if i == 0 else 0.0)
            _mtp_now = (mtp_fixed_mb + mtp_compute_per_512 * _ub / 512) if mtp_mb else 0.0
            extras_fixed = mmproj_mb + draft_mb + _mtp_now + cache_mb
            draft_mb_tok = draft_kv_per_tok / (1024 * 1024)

            def _need(m: dict, c: int) -> dict:
                return {d: m["devices"][d] + ((extras_fixed + draft_mb_tok * c) if i == 0 else 0.0)
                        for i, d in enumerate(devs)}

            alt = max(4096, c0 // 2) if c0 > 8192 else c0 * 2
            m1 = _fit(alt)
            slopes = {}
            if m1:
                for i, d in enumerate(devs):
                    s_ = (m0["devices"][d] - m1["devices"].get(d, m0["devices"][d])) / (c0 - alt)
                    slopes[d] = s_ + (draft_mb_tok if i == 0 else 0.0)
            n0 = _need(m0, c0)
            room = {d: avail[d] - n0[d] for d in devs}
            grow = min((room[d] / slopes[d] for d in devs if slopes.get(d, 0) > 0), default=0.0)
            target = int((c0 + grow) // 1024 * 1024)
            target = min(max(target, _ctx_floor_exact), _FIT_CTX_CAP)
            if honored_proven:
                target = max(target, c0)          # a booted combo is trusted, never shrunk
            # Verify the extrapolation and back off if it overshoots.
            for _ in range(3):
                if target == c0:
                    over = max(n0[d] - avail[d] for d in devs)
                    break
                mt = _fit(target)
                if not mt:
                    over, target = 0.0, c0
                    break
                nt = _need(mt, target)
                over = max(nt[d] - avail[d] for d in devs)
                if over <= 0:
                    break
                step = max(slopes.values(), default=0.0) or 0.05
                target = max(_ctx_floor_exact, int((target - over / step - 1024) // 1024 * 1024))
            if over > 0 and target != c0 and all(n0[d] <= avail[d] for d in devs):
                target, over = c0, 0.0            # unverified growth: keep the plan that fits
            if over > 0 and not honored_proven and n_layer:
                # Context is already at its floor and the plan still doesn't
                # fit: move weights off the GPU (dense layers or MoE expert
                # layers) until llama.cpp's own estimate says it does.
                shed_from = (out["num_gpu"], out["n_cpu_moe"])
                for _ in range(5):
                    if is_moe and dense_share:
                        per_layer = size_mb * (1 - dense_share) / n_layer
                        if out["n_cpu_moe"] >= n_layer:
                            break
                        out["n_cpu_moe"] = min(n_layer, out["n_cpu_moe"]
                                               + int((over + 256) // max(per_layer, 1)) + 1)
                    else:
                        per_layer = size_mb / n_layer
                        cur = out["num_gpu"] if out["num_gpu"] < 99 else n_layer
                        if cur <= 1:
                            break
                        out["num_gpu"] = max(1, cur - int((over + 256) // max(per_layer, 1)) - 1)
                    mt = _fit(target)
                    if not mt:
                        break
                    over = max(v - avail[d] for d, v in _need(mt, target).items())
                    if over <= 0:
                        break
                if (out["num_gpu"], out["n_cpu_moe"]) != shed_from:
                    what = (f"n_cpu_moe {shed_from[1]} → {out['n_cpu_moe']}" if is_moe
                            else f"GPU layers {min(shed_from[0], n_layer)} → {out['num_gpu']} of {n_layer}")
                    notes.append(f"exact fit: still over at {target:,} tokens — moved weights off the "
                                 f"GPU ({what}) until llama.cpp's estimate fits.")
            if over > 0 and not honored_proven:
                notes.append(
                    f"exact fit: even {target:,} tokens needs {over:.0f} MiB more than this GPU has "
                    f"free — expect a boot failure; free VRAM or lower the context.")
            used = sum(_need(_fit(target) or m0, target).values())
            total_avail = sum(avail.values())
            exact_mem = (used, total_avail)
            if target != c0:
                notes.append(
                    f"exact fit (llama-fit-params): ctx {c0:,} → {target:,} — "
                    f"{used:,.0f} of {total_avail:,.0f} MiB usable across {len(devs)} device(s), "
                    f"replacing the ~8% estimate headroom with measured memory.")
                out["num_ctx"] = target
            else:
                notes.append(f"exact fit (llama-fit-params): {c0:,} tokens confirmed — "
                             f"{used:,.0f} of {total_avail:,.0f} MiB usable.")
            # Context is at the ceiling and memory is left: on MoE, pull expert
            # layers back from system RAM — every reply gets faster.
            if (is_moe and dense_share and n_layer and out["n_cpu_moe"] > 0
                    and out["num_ctx"] >= _FIT_CTX_CAP):
                per_layer = size_mb * (1 - dense_share) / n_layer
                shed_from_moe = out["n_cpu_moe"]

                def _fits_now() -> bool:
                    mt = _fit(out["num_ctx"])
                    return bool(mt) and all(v <= avail[d] for d, v in _need(mt, out["num_ctx"]).items())

                mt = _fit(out["num_ctx"])
                if mt:
                    spare = min(avail[d] - v for d, v in _need(mt, out["num_ctx"]).items())
                    back = int(spare // max(per_layer, 1))
                    if back > 0:
                        out["n_cpu_moe"] = max(0, out["n_cpu_moe"] - back)
                        # llama.cpp has the last word: step back until it fits.
                        while out["n_cpu_moe"] < shed_from_moe and not _fits_now():
                            out["n_cpu_moe"] += 1
                if out["n_cpu_moe"] < shed_from_moe:
                    _mf = _fit(out["num_ctx"])
                    if _mf:
                        exact_mem = (sum(_need(_mf, out["num_ctx"]).values()), total_avail)
                    notes.append(f"context is at the {_FIT_CTX_CAP:,} ceiling, so spare VRAM pulled expert "
                                 f"layers back from RAM: n_cpu_moe {shed_from_moe} → {out['n_cpu_moe']}.")
            # Context is maxed and memory is left: spend it on prompt speed.
            # ubatch 2048 roughly doubles prefill on big cards but its compute
            # buffer costs ~2 GB, so it only wins when context can't grow.
            cpu_off = out["n_cpu_moe"] > 0 or (not is_moe and out["num_gpu"] < 99)
            if out["num_ctx"] >= _FIT_CTX_CAP and not cpu_off and _ub < 2048:
                mu = _fit(out["num_ctx"], ub=2048, b=2048)
                if mu and all(v <= avail[d] for d, v in _need(mu, out["num_ctx"]).items()):
                    out["num_batch"], out["n_ubatch"] = 2048, 2048
                    notes.append("prompt batch: ubatch 2048 — context is at the ceiling and memory "
                                 "is left over, so it buys faster prompt processing instead.")
        else:
            notes.append("exact fit: llama-fit-params unavailable — using the analytic estimate.")

    out["moe_cache_mib"] = int(cache_mb)

    # -- Speed verdict --
    # Judged at the user's usual chat size: past the offload the solver already
    # traded against context (MoE), the window size itself costs no decode
    # speed — so falling short here means the model is the limit, and cutting
    # context wouldn't help.
    def _pred_out(ctx_tokens: int) -> float:
        return _predict(min(typical_fill, int(ctx_tokens)), n_off=out["n_cpu_moe"],
                        num_gpu=out["num_gpu"], kv_k=out.get("kv_cache_type") or "q8_0",
                        kv_v=out.get("kv_cache_type_v") or "", spec=out["spec_strategy"],
                        calib_factor=calib)

    pred_now = _pred_out(int(out["num_ctx"]))
    if pred_now < min_tok_s:
        out["speed_floor_unreachable"] = True
        notes.append(
            f"speed floor not met: ≈ {pred_now:.0f} tok/s at your usual chat size (floor {min_tok_s:g}). "
            f"The weights are the limit, not the context window — a smaller context wouldn't be "
            f"faster at the same chat size; only a smaller model or quant would.")
    out["predicted_tok_s"] = round(pred_now, 1)
    notes.append(f"predicted decode ≈ {pred_now:.0f} tok/s at your usual chat size (~{typical_fill:,} tokens).")

    # -- Plain-language summary (the notes are the full reasoning) --
    summary = [f"Context: {out['num_ctx']:,} tokens"
               + (f" (was {min_ctx:,})" if min_ctx and min_ctx != out["num_ctx"] else "")]
    _usual = f"{typical_fill / 1000:.0f}k" if typical_fill >= 1000 else str(typical_fill)
    if out.get("speed_floor_unreachable"):
        summary.append(f"Speed: about {pred_now:.0f} tok/s at your usual chat size (~{_usual} tokens) — "
                       f"below your {min_tok_s:g} tok/s minimum; this model can't go faster on this GPU")
    else:
        summary.append(f"Speed: about {pred_now:.0f} tok/s at your usual chat size (~{_usual} tokens; "
                       f"your minimum: {min_tok_s:g})")
    if out["n_cpu_moe"] > 0 and n_layer:
        summary.append(f"{out['n_cpu_moe']} of {n_layer} expert layers run from system RAM")
    elif not is_moe and n_layer and out["num_gpu"] < 99 and out["num_gpu"] < n_layer:
        summary.append(f"{n_layer - out['num_gpu']} of {n_layer} layers run from system RAM (slow)")
    if out["spec_strategy"] == "draft-mtp":
        summary.append(f"MTP drafting {out.get('spec_draft_n_max') or 3} tokens ahead")
    summary.append(f"Memory checked with llama.cpp's own estimate ({exact_mem[0] / 1024:.1f} of "
                   f"{exact_mem[1] / 1024:.1f} GB)" if exact_mem
                   else "Memory estimated (llama-fit-params not available)")
    out["summary"] = summary
    if out["num_batch"] > out["num_ctx"]:
        out["num_batch"] = max(512, out["num_ctx"])

    out["notes"] = " ".join(notes)
    return out


# ---- llama-server flag capability probe --------------------------------------
# Builds understand different flags, and an unknown flag makes llama-server
# exit at startup (--n-cpu-moe, the ngram flag rename, draft-mtp,
# rope-scaling). Probe --help once per binary and gate every optional flag on
# the answer.
_LLAMA_CAPS_CACHE: dict = {}


def llama_caps(bin_path: str = "") -> dict:
    """Probe a llama-server binary's --help and report which optional flags it
    understands. Cached per (path, mtime). On probe failure assume everything
    is supported — identical to the pre-probe behavior."""
    caps = {"n_cpu_moe": True, "override_tensor": True, "ngram_mod": False,
            "ngram_legacy": False, "draft_mtp": True, "dflash": False,
            "dspark": False, "rope_scaling": True,
            "flash_attn": True, "probed": False,
            # Context checkpoints default off: unlike the flags above (True for
            # pre-probe parity), they are new enough that assuming them on an old binary
            # would make the server exit at boot.
            "ctx_checkpoints": False, "checkpoint_min_step": False,
            "checkpoint_every_n": False,
            # Newer flags: fail-closed until seen in --help (an unknown flag
            # hard-exits the server at boot).
            "moe_cache": False, "fit_target": False}
    if not bin_path:
        return caps
    try:
        mtime = os.path.getmtime(bin_path)
    except Exception:
        mtime = 0
    key = (bin_path, mtime)
    if key in _LLAMA_CAPS_CACHE:
        return _LLAMA_CAPS_CACHE[key]
    try:
        r = subprocess.run(
            [bin_path, "--help"], capture_output=True, text=True, timeout=8,
            creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0),
        )
        help_txt = (r.stdout or "") + "\n" + (r.stderr or "")
        if help_txt.strip():
            caps["probed"] = True
            caps["n_cpu_moe"] = ("--n-cpu-moe" in help_txt) or ("ncmoe" in help_txt)
            caps["override_tensor"] = ("--override-tensor" in help_txt) or (" -ot" in help_txt)
            caps["ngram_mod"] = "--spec-ngram-mod-n-match" in help_txt
            # Removed flags still appear in --help annotated "the argument has
            # been removed" — exclude those so old builds keep their working
            # legacy names and new builds don't think the old flag is real.
            caps["ngram_legacy"] = ("--spec-ngram-size-n" in help_txt) and (
                "the argument has been removed" not in help_txt)
            caps["draft_mtp"] = "draft-mtp" in help_txt
            # Self-speculative decoding types (llama.cpp #21930): DFlash / DSpark draft
            # from the model's own hidden states. Fail-closed until seen in --help, since
            # an unknown --spec-type value makes the server exit at boot.
            caps["dflash"] = "dflash" in help_txt
            caps["dspark"] = "dspark" in help_txt
            caps["rope_scaling"] = "--rope-scaling" in help_txt
            caps["flash_attn"] = ("--flash-attn" in help_txt) or ("-fa" in help_txt)
            caps["ctx_checkpoints"] = ("--ctx-checkpoints" in help_txt) or ("--swa-checkpoints" in help_txt)
            # llama.cpp renamed --checkpoint-every-n-tokens → --checkpoint-min-step
            caps["checkpoint_min_step"] = "--checkpoint-min-step" in help_txt
            caps["checkpoint_every_n"] = "--checkpoint-every-n-tokens" in help_txt
            caps["moe_cache"] = "--moe-cache-mib" in help_txt
            caps["fit_target"] = "--fit-target" in help_txt
    except Exception:
        pass
    _LLAMA_CAPS_CACHE[key] = caps
    return caps


def _checkpoint_spawn_flags(caps: dict, profile: dict) -> list[str]:
    """Explicit compatibility override for hybrid/SWA context checkpoints.

    On current llama.cpp builds (measured on Qwen 3.8 and Qwen35 hybrids) these
    flags disable ordinary slot-prefix reuse, turning warm 32K/62K follow-ups
    into full prefills. Kept available for future builds, but never enabled
    just because a model is hybrid."""
    try:
        s = get_settings()
        if not bool(s.get("ctx_checkpoints_enabled", False)):
            return []
        n_ck = int(1 if s.get("ctx_checkpoints") is None else s.get("ctx_checkpoints"))
    except Exception:
        return []
    if n_ck <= 0 or not caps.get("ctx_checkpoints"):
        return []
    hy = _hybrid_info(profile)
    swa = _swa_info(profile)
    if not (hy["hybrid"] or swa):
        return []
    # Host-RAM guard: each checkpoint costs about ctx-filled x KV-bytes/token of
    # host RAM (8 checkpoints at 262k ctx on a hybrid MoE would be ~22 GB). Cap
    # total checkpoint RAM at ~2 GB by shrinking the count for big contexts; even
    # one checkpoint gives the prefix-restore win.
    try:
        ctx_now = max(int(s.get("num_ctx") or 32768), 1)
        kv_t = (s.get("kv_cache_type") or "q8_0").strip().lower()
        kv_v = (s.get("kv_cache_type_v") or "").strip().lower()
        per_tok = _kv_total_bytes(profile, kv_t, 65536, kv_v) / 65536.0
        if per_tok > 0:
            max_ck = int(2_000_000_000 / (per_tok * ctx_now))
            n_ck = max(1, min(n_ck, max_ck)) if max_ck >= 1 else 1
    except Exception:
        pass
    flags = ["--ctx-checkpoints", str(n_ck)]
    try:
        step = int(s.get("checkpoint_min_step") or 4096)
    except Exception:
        step = 4096
    if step > 0:
        if caps.get("checkpoint_min_step"):
            flags += ["--checkpoint-min-step", str(step)]
        elif caps.get("checkpoint_every_n"):
            flags += ["--checkpoint-every-n-tokens", str(step)]
    return flags


def find_llama_bin() -> str:
    """Locate llama-server.exe — settings override > env > PATH > known dirs > recursive scan."""
    s = get_settings()
    explicit = (s.get("llama_bin") or "").strip()
    if explicit and safe_exists(explicit):
        return explicit
    env = (os.environ.get("ACCURETTA_LLAMA_BIN") or "").strip()
    if env and safe_exists(env):
        return env
    found = shutil.which("llama-server.exe") or shutil.which("llama-server")
    if found:
        return found
    
    home = Path.home()
    search_roots = [
        ROOT,
        home / "Downloads",
        home / "Desktop",
        home / "Documents",
        Path("C:/llama.cpp"),
    ]
    
    # Scan other drive letters for common top-level llama folders
    if os.name == "nt":
        for letter in "CDEFGHIJKLMNOPQRSTUVWXYZ":
            drive = Path(f"{letter}:\\")
            if safe_exists(drive):
                for candidate_folder in ["llama.cpp", "llama", "bin"]:
                    cand = drive / candidate_folder
                    if safe_exists(cand) and safe_is_dir(cand):
                        search_roots.append(cand)
                        
    seen_roots = set()
    valid_roots = []
    for r in search_roots:
        try:
            r_abs = str(r.resolve())
            if r_abs not in seen_roots and safe_exists(r) and safe_is_dir(r):
                seen_roots.add(r_abs)
                valid_roots.append(r)
        except Exception:
            continue
            
    pattern = "llama-server.exe" if os.name == "nt" else "llama-server"
    for root in valid_roots:
        depth = 3
        try:
            matches = safe_rglob_files(root, pattern, max_depth=depth)
            if matches:
                # Prioritize Release builds
                for m in matches:
                    if "release" in str(m).lower():
                        return str(m.resolve())
                return str(matches[0].resolve())
        except Exception:
            continue
            
    candidates = [
        home / ".unsloth/llama.cpp/build/bin/Release/llama-server.exe",
        home / ".unsloth/llama.cpp/build/bin/llama-server.exe",
        home / ".docker/bin/inference/llama-server.exe",
        home / "llama.cpp/build/bin/Release/llama-server.exe",
        home / "llama.cpp/llama-server.exe",
        Path("C:/llama.cpp/build/bin/Release/llama-server.exe"),
        Path("C:/llama.cpp/llama-server.exe"),
    ]
    for c in candidates:
        if safe_exists(c):
            return str(c)
            
    return ""



def _parse_llama_port() -> int:
    m = re.search(r":(\d+)", LLAMA)
    return int(m.group(1)) if m else 8080


def _gguf_model_identities(path: str | Path, keys: dict | None = None) -> set[str]:
    """Return normalized model identities from GGUF metadata, including mmproj files."""
    try:
        if keys is None:
            meta = read_gguf_metadata(str(path))
            keys = meta.get("keys") if isinstance(meta, dict) else {}
        if not isinstance(keys, dict):
            return set()
        values = []
        for key, value in keys.items():
            lower = str(key).lower()
            if (lower in {"general.name", "general.basename"}
                    or (lower.startswith("general.base_model.") and lower.endswith(".name"))):
                if isinstance(value, str) and value.strip():
                    values.append(value)
        return {re.sub(r"[^a-z0-9]+", "", value.lower()) for value in values
                if len(re.sub(r"[^a-z0-9]+", "", value.lower())) >= 5}
    except Exception:
        return set()


def find_mmproj_for(model_path: str) -> str:
    """Look for a vision projector .gguf sitting next to the chosen model.
    Heuristic: scan the model's directory (and one level up) for files whose
    name contains 'mmproj' or 'mm-proj'. Returns the absolute path of the
    closest match, or '' when nothing plausible is on disk.
    Common upstream naming: `mmproj-Qwen2.5-VL-7B-Instruct-f16.gguf`,
    `model.mmproj.gguf`, `mm-projector.gguf`."""
    if not model_path:
        return ""
    mp = Path(model_path)
    if not safe_exists(mp):
        return ""
    candidates: list[Path] = []
    search_dirs = [mp.parent]
    if mp.parent.parent and mp.parent.parent != mp.parent:
        search_dirs.append(mp.parent.parent)
    seen: set[str] = set()
    for d in search_dirs:
        try:
            for p in d.glob("*.gguf"):
                key = str(p.resolve()).lower()
                if key in seen:
                    continue
                seen.add(key)
                lname = p.name.lower()
                if "mmproj" in lname or "mm-proj" in lname or "mm_proj" in lname:
                    candidates.append(p)
        except Exception:
            continue
    if not candidates:
        return ""
    # Generic upstream names such as mmproj-F16.gguf carry the real pairing in
    # GGUF metadata. Prefer an exact metadata identity match before filename
    # heuristics; this is both safer and more useful in a crowded flat folder.
    model_ids = _gguf_model_identities(mp)
    if model_ids:
        metadata_matches = [p for p in candidates if model_ids & _gguf_model_identities(p)]
        if metadata_matches:
            metadata_matches.sort(key=lambda p: (p.parent != mp.parent, len(p.name)))
            return str(metadata_matches[0].resolve())
    # Prefer same-directory matches; then prefer names that share a token
    # with the model file (e.g. "qwen2.5-vl-7b" shows up in both).
    model_stem = mp.stem.lower()
    def score(p: Path) -> tuple[int, int, int]:
        same_dir = 0 if p.parent == mp.parent else 1
        # crude shared-substring score
        shared = 0
        for tok in re.split(r"[-_.]", model_stem):
            if len(tok) >= 3 and tok in p.stem.lower():
                shared += 1
        return (same_dir, -shared, len(p.name))
    candidates.sort(key=score)
    best = candidates[0]
    best_same_dir, best_neg_shared, _ = score(best)
    
    # If the projector shares at least one token with the model, it's a safe match.
    if best_neg_shared < 0:
        return str(best.resolve())
        
    # A projector sharing no name tokens (e.g. generic "mmproj-BF16.gguf") is only
    # auto-loaded when it is the only other .gguf in the directory; attaching a
    # generic projector to every model in a crowded folder causes crashes.
    try:
        ggufs_in_dir = list(mp.parent.glob("*.gguf"))
        if len(ggufs_in_dir) <= 2:
            return str(best.resolve())
    except Exception:
        pass
        
    print(f"[llama] skipped generic projector {best.name} for {mp.name} (too ambiguous in a crowded directory)")
    return ""


def _is_mmproj_name(name: str) -> bool:
    """A vision projector (mmproj) is a .gguf that belongs to a multimodal model
    — it's loaded via --mmproj alongside the real model, not runnable on its own.
    Match the common naming so these stay out of the model picker."""
    l = (name or "").lower()
    return "mmproj" in l or "mm-proj" in l or "mm_proj" in l


# ---- speculative draft models (DFlash / DSpark) -----------------------------
# A draft GGUF is a small network trained against one specific target model; it
# runs alongside it via --spec-draft-model and is not loadable on its own. The
# picker must hide it, and auto-tune must pair it by metadata — never by name
# alone, because pairing a mismatched draft wastes VRAM and can crash the server.

_DRAFT_NAME_RE = re.compile(r"(^|[^a-z0-9])(dflash|dspark|spec[-_]?draft|draft)(?![a-z])",
                            re.IGNORECASE)
_SPEC_FINGERPRINT_CACHE: dict[tuple[str, int, int], dict] = {}
_SPEC_FINGERPRINT_CACHE_MAX = 64


def _is_draft_name(name: str) -> bool:
    """Filename hint that a .gguf is a speculative draft rather than a chat model."""
    return bool(_DRAFT_NAME_RE.search((name or "").lower()))


def _spec_fingerprint(path: str | Path) -> dict:
    """Cheap metadata fingerprint used to pair a draft with its target model.

    DFlash/DSpark GGUFs ship `general.basename` / `general.base_model.*.name`
    alongside the target's tokenizer identity (same vocab size, merges and
    tokenizer model). Cache keyed by path + size + mtime so repeated UI scans
    don't re-read GGUF headers."""
    try:
        p = Path(path)
        st = p.stat()
    except Exception:
        return {}
    key = (str(p), int(st.st_size), int(st.st_mtime))
    cached = _SPEC_FINGERPRINT_CACHE.get(key)
    if cached is not None:
        return cached
    meta = read_gguf_metadata(str(p))
    keys = meta.get("keys") if isinstance(meta.get("keys"), dict) else {}

    def array_len(name: str) -> int:
        value = keys.get(name)
        if isinstance(value, dict) and isinstance(value.get("__array_len__"), int):
            return int(value["__array_len__"])
        return 0

    out = {
        "path": str(p),
        "name": p.name,
        "size": int(st.st_size),
        "ok": bool(meta.get("ok")),
        "architecture": str(meta.get("architecture") or "").lower(),
        "vocab": array_len("tokenizer.ggml.tokens"),
        "tokenizer": str(keys.get("tokenizer.ggml.model") or "").lower(),
        "embedding_length": int(meta.get("embedding_length") or 0),
        "block_count": int(meta.get("block_count") or 0),
        "identities": _gguf_model_identities(p, keys),
        "is_draft": str(meta.get("architecture") or "").lower() in {"dflash", "dspark"},
    }
    if len(_SPEC_FINGERPRINT_CACHE) >= _SPEC_FINGERPRINT_CACHE_MAX:
        _SPEC_FINGERPRINT_CACHE.pop(next(iter(_SPEC_FINGERPRINT_CACHE)))
    _SPEC_FINGERPRINT_CACHE[key] = out
    return out


def _identity_match(target_ids: set[str], draft_ids: set[str]) -> tuple[int, list[str]]:
    """Normalized base-model identities: exact intersection is decisive;
    containment catches publishers that suffix the identity differently."""
    exact = sorted(target_ids & draft_ids)
    if exact:
        return 100, exact
    contained: list[str] = []
    for target in target_ids:
        for draft in draft_ids:
            if not target or not draft:
                continue
            if (target in draft or draft in target) and min(len(target), len(draft)) >= 6:
                contained.append(draft if len(draft) >= len(target) else target)
    if contained:
        return 60, sorted(set(contained))
    return 0, []


def spec_draft_match(model_path: str, draft_path: str) -> dict:
    """Compare a draft GGUF against a target model. Returns
    {matched, score, reasons, draft}. A draft is trusted when:
      * both sides name the same base model (identity intersection), or
      * neither side carries identities but tokenizer vocab, tokenizer model
        and embedding length all match.
    Positive evidence of a different base model always rejects the pair."""
    target = _spec_fingerprint(model_path) if model_path else {}
    draft = _spec_fingerprint(draft_path)
    if not draft:
        return {"matched": False, "score": 0, "reasons": ["draft file unreadable"], "draft": {}}
    reasons: list[str] = []
    score = 0
    ids_score, ids = _identity_match(target.get("identities") or set(), draft.get("identities") or set())
    if ids_score:
        score += ids_score
        reasons.append("base model match: " + ", ".join(ids))
    if target.get("vocab") and target["vocab"] == draft.get("vocab"):
        score += 40
        reasons.append(f"tokenizer vocab {draft['vocab']:,}")
    if target.get("tokenizer") and target["tokenizer"] == draft.get("tokenizer"):
        score += 10
        reasons.append(f"tokenizer {draft['tokenizer']}")
    if target.get("embedding_length") and target["embedding_length"] == draft.get("embedding_length"):
        score += 20
        reasons.append(f"embedding {draft['embedding_length']}")

    matched = score >= 60
    identity_known = bool(target.get("identities")) and bool(draft.get("identities"))
    if identity_known and not ids_score:
        matched = False
        reasons.append("different base model")
    if draft.get("ok") and not draft.get("is_draft"):
        # Readable metadata wins over the filename: a full model that happens
        # to be named "…draft…" is not a loadable speculative companion.
        matched = False
        reasons.append("not a DFlash/DSpark draft")
    if not reasons:
        reasons.append("no shared tokenizer or base-model identity")
    return {"matched": matched, "score": score, "reasons": reasons, "draft": draft}


def _draft_candidates(model_path: str) -> list[Path]:
    """Draft-named .gguf files next to the model (same dir, then one level up),
    plus the configured models directory."""
    candidates: list[Path] = []
    seen: set[str] = set()

    def add_dir(folder: Path) -> None:
        try:
            for p in folder.glob("*.gguf"):
                key = str(p).lower()
                if key in seen:
                    continue
                seen.add(key)
                if _is_draft_name(p.name):
                    candidates.append(p)
        except Exception:
            return

    if model_path:
        mp = Path(model_path)
        if safe_exists(mp):
            add_dir(mp.parent)
            if mp.parent.parent and mp.parent.parent != mp.parent:
                add_dir(mp.parent.parent)
    mdir = str(get_settings().get("models_dir") or "").strip()
    if mdir and safe_exists(mdir):
        add_dir(Path(mdir))
    return candidates


def find_spec_draft_for(model_path: str) -> dict:
    """Best **validated** DFlash/DSpark draft for a model, or {} when there is
    none. Auto-tune and the spawn path use this strict result: a mismatched or
    unverified draft must never be enabled silently. Unverified candidates are
    surfaced by list_spec_drafts() for the settings picker instead."""
    if not model_path or not safe_exists(model_path):
        return {}
    scored: list[tuple[int, int, int, Path, dict]] = []
    for candidate in _draft_candidates(model_path):
        if str(candidate) == str(model_path):
            continue
        match = spec_draft_match(model_path, str(candidate))
        if match["matched"]:
            same_dir = 0 if candidate.parent == Path(model_path).parent else 1
            scored.append((match["score"], same_dir, len(candidate.name), candidate, match))
    if not scored:
        return {}
    scored.sort(key=lambda item: (-item[0], item[1], item[2]))
    _, _, _, best, match = scored[0]
    return {"path": str(best.resolve()), **match}


def draft_match_payload(match: dict) -> dict:
    """JSON-safe summary of a draft match (the full match carries a fingerprint
    with a set of identities; API responses only need these four fields)."""
    return {
        "path": str((match or {}).get("path") or ""),
        "matched": bool((match or {}).get("matched")),
        "score": int((match or {}).get("score") or 0),
        "reasons": list((match or {}).get("reasons") or []),
    }


def list_spec_drafts(model_path: str = "") -> list[dict]:
    """Draft GGUFs available for the settings picker, best match first."""
    out: list[dict] = []
    seen: set[str] = set()
    for candidate in _draft_candidates(model_path):
        key = str(candidate).lower()
        if key in seen:
            continue
        seen.add(key)
        fingerprint = _spec_fingerprint(candidate)
        match = spec_draft_match(model_path, str(candidate)) if model_path else {
            "matched": False, "score": 0, "reasons": []}
        out.append({
            "path": str(candidate.resolve()),
            "name": fingerprint.get("name") or candidate.name,
            "size": fingerprint.get("size", 0),
            "architecture": fingerprint.get("architecture", ""),
            "base": ", ".join(sorted(fingerprint.get("identities") or []))[:160],
            "matched": bool(match.get("matched")),
            "score": int(match.get("score", 0)),
            "reasons": match.get("reasons", []),
        })
    out.sort(key=lambda row: (-row["matched"], -row["score"], row["name"].lower()))
    return out


def scan_gguf_dir(root: str, include_drafts: bool = False) -> list[dict]:
    """List selectable .gguf models under root (recursive). Vision projectors
    (mmproj) and speculative drafts (DFlash/DSpark) are excluded — both are
    companions of another model, not something you can load on their own.
    Returns [{name,path,size,modified_at}]."""
    if not root:
        return []
    try:
        files = safe_rglob_files(root, "*.gguf", max_depth=6)
    except Exception:
        return []
    out = []
    for p in files:
        if _is_mmproj_name(p.name):
            continue
        if not include_drafts and _is_draft_name(p.name):
            continue
        try:
            st = p.stat()
            out.append({
                "name": p.name,
                "path": str(p.resolve()),
                "size": st.st_size,
                "modified_at": int(st.st_mtime),
            })
        except Exception:
            continue
    out.sort(key=lambda m: m["name"].lower())
    return out


def find_all_gguf_files() -> list[dict]:
    """Scan common locations for .gguf files to offer frictionless onboarding.
    Returns list of dicts: [{name, path, size, modified_at}].
    """
    s = get_settings()
    mdir = (s.get("models_dir") or "").strip()
    
    search_roots = []
    
    # 1. Configured models_dir
    if mdir and safe_exists(mdir) and safe_is_dir(mdir):
        search_roots.append(Path(mdir))
        
    # 2. Home directories
    home = Path.home()
    for sub in ["models", "Downloads", "Desktop", "Documents"]:
        search_roots.append(home / sub)
        
    # 3. LM Studio locations
    search_roots.append(home / ".lmstudio" / "models")
    search_roots.append(home / ".cache" / "lm-studio" / "models")
    
    # 4. HuggingFace hub cache
    search_roots.append(home / ".cache" / "huggingface" / "hub")
    
    # 5. Ollama models
    search_roots.append(home / ".ollama" / "models")
    
    # 6. AccuTEST workspace (ROOT) and sibling folders (ROOT.parent)
    search_roots.append(ROOT)
    if ROOT.parent and ROOT.parent != ROOT:
        search_roots.append(ROOT.parent)
        
    # 7. Top-level folders named MODELS or models on all available drives
    if os.name == "nt":
        for letter in "CDEFGHIJKLMNOPQRSTUVWXYZ":
            drive = Path(f"{letter}:\\")
            if safe_exists(drive):
                # Smart candidate directories on non-OS/other drives
                for folder in [
                    "MODELS", "models", 
                    "llama.cpp", "llama", 
                    "LM Studio", "LM-Studio", "lmstudio", 
                    "Ollama", "ollama", 
                    "Downloads", "Documents", "Desktop"
                ]:
                    cand = drive / folder
                    if safe_exists(cand) and safe_is_dir(cand):
                        search_roots.append(cand)
    else:
        for folder in ["/models", "/MODELS"]:
            if safe_exists(folder) and safe_is_dir(folder):
                search_roots.append(Path(folder))

    # De-duplicate and validate search roots
    seen_roots = set()
    valid_roots = []
    for r in search_roots:
        try:
            r_abs = str(r.resolve())
            if r_abs not in seen_roots and safe_exists(r) and safe_is_dir(r):
                seen_roots.add(r_abs)
                valid_roots.append(r)
        except Exception:
            continue
            
    # Scan for *.gguf in all valid roots
    all_files = []
    seen_files = set()
    
    for root in valid_roots:
        try:
            found = safe_rglob_files(root, "*.gguf", max_depth=6)
            for p in found:
                if _is_mmproj_name(p.name):
                    continue   # vision projector, not a selectable model
                p_abs = str(p.resolve())
                if p_abs not in seen_files:
                    seen_files.add(p_abs)
                    try:
                        st = p.stat()
                        all_files.append({
                            "name": p.name,
                            "path": p_abs,
                            "size": st.st_size,
                            "modified_at": int(st.st_mtime),
                        })
                    except Exception:
                        continue
        except Exception:
            continue
            
    # Sort models by modified_at descending (newest first)
    all_files.sort(key=lambda m: (-m["modified_at"], m["name"].lower()))
    return all_files



def _watchdog_self_heal(attempt: int) -> None:
    """Progressive degrade for a crash-looping config. The usual crash cause is
    resource exhaustion, which identical retries can't fix, so:
      attempt 2 -> halve num_ctx (floor 4096); KV cache is the usual OOM driver.
      attempt 3 -> speculative decoding off + more CPU offload (MoE: n_cpu_moe
                  up; dense: num_gpu down).
    Degraded settings are persisted: a config that boots beats a "perfect" one
    that crash-loops. The user can re-tune upward from Settings."""
    try:
        s = get_settings()
        changed: list[str] = []
        bad_draft = ""
        if attempt == 2:
            cur = int(s.get("num_ctx") or 32768)
            new = max(4096, cur // 2)
            if new != cur:
                s["num_ctx"] = new
                changed.append(f"num_ctx {cur:,} → {new:,}")
        elif attempt >= 3:
            if (s.get("spec_strategy") or "off") != "off":
                s["spec_strategy"] = "off"
                changed.append("speculative decoding → off")
            bad_draft = str(s.get("spec_draft_model") or "").strip()
            if bad_draft:
                # A draft that helped crash the server three times must not be
                # retried silently on every restart: drop it here and remember
                # the failure in this model's saved config.
                s["spec_draft_model"] = ""
                changed.append(f"speculative draft {os.path.basename(bad_draft)} disabled")
            try:
                mp = s.get("model_path") or ""
                prof = inspect_model(mp) if mp else {}
            except Exception:
                prof = {}
            if prof.get("is_moe") and (prof.get("block_count") or 0) > 0:
                cur = int(s.get("n_cpu_moe") or 0)
                new = min(prof["block_count"], max(cur + 8, int(prof["block_count"] * 0.75)))
                if new != cur:
                    s["n_cpu_moe"] = new
                    changed.append(f"n_cpu_moe {cur} → {new}")
            else:
                cur = int(s.get("num_gpu") or 99)
                new = 40 if cur >= 99 else max(8, int(cur * 0.7))
                if new != cur:
                    s["num_gpu"] = new
                    changed.append(f"num_gpu {cur} → {new}")
        if changed:
            save_json(SETTINGS_FILE, s)
            # Sync the degraded flags into this model's remembered config too, or
            # _apply_model_config restores the pre-heal ctx on the next load.
            # _MODEL_CONFIG_KEYS includes the spec keys, so a disabled draft is remembered
            # the same way.
            try:
                _save_model_config(str(s.get("model_path") or ""),
                                   {k: s[k] for k in globals().get("_MODEL_CONFIG_KEYS", ())
                                    if k in s})
            except Exception:
                pass
            msg = f"watchdog self-heal (attempt {attempt}): " + "; ".join(changed)
            print(f"[watchdog] {msg}", file=sys.stderr)
            broadcast_event({"type": "llama:auto_degraded", "message": msg, "changes": changed})
    except Exception as e:
        print(f"[watchdog] self-heal failed: {e!r}", file=sys.stderr)


# ---- per-model config memory -------------------------------------------------
# llama flags that are model-specific (what fits THIS model on THIS machine).
# Remembered per GGUF path so switching models restores each model's own best
# config instead of inheriting the previous model's leftovers.
_MODEL_TUNE_KEYS = ("num_ctx", "n_cpu_moe", "kv_cache_type", "kv_cache_type_v", "num_gpu",
                    "num_batch", "n_ubatch", "num_thread", "spec_strategy", "spec_strategy_source",
                    "spec_draft_n_max", "moe_cache_mib")
# Tune keys newer than many saved per-model configs: when a model's saved
# config lacks one, it falls back to the default instead of inheriting the
# previously loaded model's value (a draft length tuned for one model is
# meaningless for the next).
_MODEL_TUNE_RESET_KEYS = ("spec_draft_n_max", "moe_cache_mib")
_MODEL_PROJECTOR_KEYS = ("mmproj_mode", "mmproj_path")
_MODEL_PREFERENCE_KEYS = ("reasoning_effort", "spec_draft_model")
_MODEL_CONFIG_KEYS = _MODEL_TUNE_KEYS + _MODEL_PROJECTOR_KEYS + _MODEL_PREFERENCE_KEYS


def _models_config() -> dict:
    cfg = load_json(MODELS_CONFIG_FILE, {})
    return cfg if isinstance(cfg, dict) else {}


# ---- per-model sampling profiles ----------------------------------------------
# Sampling is global (the Settings sliders), which is right for the models it
# was tuned on. A few models ship vendor sampling that is part of how they were
# trained to run (Sage-A1.5: temp 1.0 + presence 1.5). Loading one of those
# stashes the global sliders in settings["sampling_baseline"] and applies the
# profile; loading any model without a profile puts the baseline back. Edits
# made while a profiled model is loaded are remembered for that model only
# (models_config.json → "sampling"), so the baseline is never overwritten.
_SAMPLING_KEYS = ("temperature", "top_p", "top_k", "min_p",
                  "repeat_penalty", "presence_penalty", "frequency_penalty")
# (filename pattern, vendor sampling, model features, no-tools overrides).
# Features: "subagents" exposes spawn_subagent (the model was trained on that
# exact orchestration schema); "vendor_agentic_sampling" keeps the profile on
# tool turns instead of the generic agentic clamp in run_chat_turn;
# "native_prior_thinking" sends earlier reasoning verbatim, for templates that
# render it back as reasoning (Nanbeige4.3: its card recommends keeping it for
# multi-turn tool use, and its template keeps it by default). The
# no-tools overrides apply to turns without tools (IDE mode) for vendors that
# publish separate chat and agentic sampling.
_MODEL_SAMPLING_PRESETS: tuple[tuple[re.Pattern, dict, frozenset, dict], ...] = (
    (re.compile(r"sage[-_ ]?a1[._-]?5", re.I),
     {"temperature": 1.0, "top_p": 0.95, "top_k": 20, "min_p": 0.0,
      "repeat_penalty": 1.0, "presence_penalty": 1.5, "frequency_penalty": 0.0},
     frozenset({"subagents", "vendor_agentic_sampling"}),
     {}),
    # Nanbeige4.3 model card: agentic / tool use temp 1.0, top_p 0.95; reasoning
    # and chat temp 0.6, top_p 0.95. Nothing else is set, so the other samplers
    # are off, as on the vendor's vLLM / SGLang setups (top_k 0 = disabled).
    # "4.3" as a version only: Nanbeige4-3B is a different (3B) model.
    (re.compile(r"nanbeige[-_ ]?4[._]3(?![\db])", re.I),
     {"temperature": 1.0, "top_p": 0.95, "top_k": 0, "min_p": 0.0,
      "repeat_penalty": 1.0, "presence_penalty": 0.0, "frequency_penalty": 0.0},
     frozenset({"vendor_agentic_sampling", "native_prior_thinking"}),
     {"temperature": 0.6}),
)


def _model_preset_entry(model_path: str) -> tuple[dict, frozenset, dict]:
    name = Path(str(model_path or "")).name
    for pattern, sampling, features, no_tools in _MODEL_SAMPLING_PRESETS:
        if name and pattern.search(name):
            return dict(sampling), features, dict(no_tools)
    return {}, frozenset(), {}


def _model_preset(model_path: str) -> tuple[dict, frozenset]:
    sampling, features, _no_tools = _model_preset_entry(model_path)
    return sampling, features


def _model_no_tools_sampling(model_path: str = "") -> dict:
    """Vendor chat sampling for turns without tools, minus any key the user
    has set for this model themselves (their edit wins)."""
    if not model_path:
        try:
            model_path = str(get_settings().get("model_path") or "")
        except Exception:
            return {}
    no_tools = _model_preset_entry(model_path)[2]
    saved = (_models_config().get(model_path) or {}).get("sampling")
    if isinstance(saved, dict):
        no_tools = {k: v for k, v in no_tools.items() if k not in saved}
    return no_tools


def _model_features(model_path: str = "") -> frozenset:
    """Feature flags for the given (default: currently selected) model."""
    if not model_path:
        try:
            model_path = str(get_settings().get("model_path") or "")
        except Exception:
            model_path = ""
    return _model_preset(model_path)[1]


def _model_sampling_profile(model_path: str) -> dict:
    """Remembered per-model sampling, else the built-in preset, else {}."""
    preset, _features = _model_preset(model_path)
    saved = (_models_config().get(model_path) or {}).get("sampling")
    if isinstance(saved, dict) and saved:
        return {**preset, **{k: saved[k] for k in _SAMPLING_KEYS if k in saved}}
    return preset


def _apply_model_sampling(model_path: str) -> str:
    """Swap the global sampling sliders for this model. Returns "profile",
    "baseline" or "" (nothing changed)."""
    try:
        with _SETTINGS_LOCK:
            s = get_settings()
            profile = _model_sampling_profile(model_path)
            if profile:
                if not isinstance(s.get("sampling_baseline"), dict):
                    s["sampling_baseline"] = {k: s.get(k) for k in _SAMPLING_KEYS}
                s.update(profile)
                save_json(SETTINGS_FILE, s)
                return "profile"
            baseline = s.pop("sampling_baseline", None)
            if isinstance(baseline, dict):
                s.update({k: baseline[k] for k in _SAMPLING_KEYS if k in baseline})
                save_json(SETTINGS_FILE, s)
                return "baseline"
    except Exception:
        traceback.print_exc()
    return ""


def _model_sampling_remember_edit(cur: dict, allowed: dict) -> None:
    """Called from update_settings: while a profiled model is loaded, store a
    changed sampling value as that model's own (the baseline stays as is)."""
    if not isinstance(cur.get("sampling_baseline"), dict):
        return
    model_path = str(cur.get("model_path") or "").strip()
    if not model_path or not any(k in allowed for k in _SAMPLING_KEYS):
        return
    profile = _model_sampling_profile(model_path)
    edited = {k: cur.get(k) for k in _SAMPLING_KEYS
              if k in allowed and str(cur.get(k)) != str(profile.get(k))}
    if not edited:
        return
    try:
        allc = _models_config()
        ent = allc.get(model_path)
        ent = dict(ent) if isinstance(ent, dict) else {}
        sampling = ent.get("sampling") if isinstance(ent.get("sampling"), dict) else {}
        sampling.update(edited)
        ent["sampling"] = sampling
        allc[model_path] = ent
        save_json(MODELS_CONFIG_FILE, allc)
    except Exception:
        pass


def _preserve_manual_model_spec(model_path: str, suggested: dict) -> dict:
    """Keep background tuning from replacing a user's decoder choice."""
    out = dict(suggested or {})
    saved = _models_config().get(model_path)
    if isinstance(saved, dict) and saved.get("spec_strategy_source") == "manual":
        out.pop("spec_strategy", None)
        out["spec_strategy_source"] = "manual"
    return out


def _apply_model_config(model_path: str) -> bool:
    """Apply this model's saved tuned flags to settings; returns True if a saved
    config existed. Saved configs below the usable floor (8192 ctx; the system
    prompt + tools don't fit in 4k) are leftovers from crash loops or tunes
    taken while another instance held the RAM, so they are deleted and retuned.
    Same for stale KV dtypes (split K/V or q4_0) that the tuner no longer emits."""
    cfg = _models_config().get(model_path)
    if isinstance(cfg, dict):
        saved_ctx = int(cfg.get("num_ctx") or 0)
        saved_kv = str(cfg.get("kv_cache_type") or "").strip().lower()
        saved_kvv = str(cfg.get("kv_cache_type_v") or "").strip().lower()
        # Split K/V and q4_0 K only came from older tuner versions; if q4_0 is
        # warranted (<=12 GB VRAM + starved ctx) a fresh tune reproduces it. Either
        # way: delete and re-tune.
        stale_kv = (saved_kvv not in ("", saved_kv)) or saved_kv == "q4_0"
        if 0 < saved_ctx < 8192 or stale_kv:
            try:
                allc = _models_config()
                allc.pop(model_path, None)
                save_json(MODELS_CONFIG_FILE, allc)
            except Exception:
                pass
            reason = (f"ctx {saved_ctx:,} is below the usable floor (scar from a bad tune)"
                      if 0 < saved_ctx < 8192 else
                      f"KV dtype {saved_kv}/{saved_kvv or 'same'} is no longer auto-emitted (stale tuner config)")
            print(f"[llama] ignoring saved config for {os.path.basename(model_path)}: "
                  f"{reason} — re-tuning", file=sys.stderr)
            return False
    if not isinstance(cfg, dict):
        return False
    s = get_settings()
    for k in _MODEL_CONFIG_KEYS:
        if k in cfg:
            s[k] = cfg[k]
    for k in _MODEL_TUNE_RESET_KEYS:
        if k not in cfg:
            s[k] = DEFAULT_SETTINGS[k]
    s["mmproj_mode"] = _normalized_mmproj_mode(s)
    s["mmproj_auto"] = s["mmproj_mode"] == "auto"
    if "spec_strategy" in cfg:
        s["enable_speculative"] = str(s.get("spec_strategy") or "off") != "off"
    save_json(SETTINGS_FILE, s)
    return True


def _save_model_config(model_path: str, flags: dict) -> None:
    """Merge tuned flags into this model's remembered config. Give-up results
    (does_not_fit) are never persisted: they were computed under transient
    conditions (low free RAM/VRAM, a running instance) and would poison every
    future load with a config that can't work."""
    if not model_path:
        return
    if flags.get("does_not_fit"):
        return
    try:
        allc = _models_config()
        ent = allc.get(model_path)
        if not isinstance(ent, dict):
            ent = {}
        for k in _MODEL_CONFIG_KEYS:
            if k in flags:
                ent[k] = flags[k]
        ent["tuned_at"] = int(time.time())
        allc[model_path] = ent
        save_json(MODELS_CONFIG_FILE, allc)
    except Exception:
        pass


def _stamp_proven_boot(model_path: str, ctx: int) -> None:
    """Record that this model booted successfully on this machine at this ctx.

    The tuner's VRAM budget is an estimate; llama-server starting and answering
    is proof it fits. Boot-time retunes use that proof so grow-only can beat the
    estimate instead of clamping a working config back down."""
    if not model_path or not ctx or ctx <= 0:
        return
    try:
        allc = _models_config()
        ent = allc.get(model_path)
        ent = dict(ent) if isinstance(ent, dict) else {}
        if int(ent.get("proven_ctx") or 0) == int(ctx) and ent.get("booted_at"):
            return                       # nothing to learn — no disk churn per reload
        ent["proven_ctx"] = int(ctx)
        ent["booted_at"] = int(time.time())
        allc[model_path] = ent
        save_json(MODELS_CONFIG_FILE, allc)
    except Exception:
        pass


def _proven_cfg(model_path: str) -> dict:
    """The proven-boot metadata for a model, or {} — tiny passthrough so
    callers pass it straight into auto_tune()."""
    if not model_path:
        return {}
    cfg = _models_config().get(model_path)
    return cfg if isinstance(cfg, dict) else {}


def _auto_tune_for_load(model_path: str) -> bool:
    """Auto-tune on model load: restore the model's remembered config if we
    have one; otherwise run the tuner against live free VRAM and remember the
    result (opt-out via auto_tune_on_load). Returns True if settings were
    updated by either path. Never raises — a tuner hiccup must not block a
    model the user explicitly asked to load."""
    try:
        if _apply_model_config(model_path):
            return True
        if not get_settings().get("auto_tune_on_load", True):
            return False
        vram = float(get_settings().get("vram_tier_gb") or 0)
        if vram <= 0:
            vram = _free_vram_gb_for_tune()  # FREE VRAM + what the running instance holds
        if vram <= 0:
            return False
        profile = inspect_model(model_path)
        # A fresh tune (no remembered config): still grow-only vs the saved
        # num_ctx so a user's raised context survives a re-tune here too.
        _min_ctx_saved = int(get_settings().get("num_ctx") or 0)
        suggested = auto_tune(model_path, vram, profile=profile, min_ctx=_min_ctx_saved)
        if not suggested.get("num_ctx"):
            return False
        suggested["spec_strategy_source"] = "auto"
        s = get_settings()
        for k in _MODEL_TUNE_KEYS:
            if k in suggested:
                s[k] = suggested[k]
        save_json(SETTINGS_FILE, s)
        _save_model_config(model_path, suggested)
        _kv_disp = suggested.get("kv_cache_type") or ""
        if suggested.get("kv_cache_type_v") and suggested["kv_cache_type_v"] != _kv_disp:
            _kv_disp += "/" + suggested["kv_cache_type_v"]
        print(f"[llama] auto-tuned on load: ctx {suggested['num_ctx']:,} · "
              f"n_cpu_moe {suggested.get('n_cpu_moe', 0)} · {_kv_disp} KV",
              file=sys.stderr)
        try:
            broadcast_event({"type": "llama:auto_tuned", "model": model_path,
                             "notes": suggested.get("notes", ""),
                             "ctx": suggested.get("num_ctx"),
                             "n_cpu_moe": suggested.get("n_cpu_moe", 0),
                             "kv_cache_type": suggested.get("kv_cache_type"),
                             "kv_cache_type_v": suggested.get("kv_cache_type_v") or "",
                             "quant_downshift": suggested.get("quant_downshift") or ""})
        except Exception:
            pass
        return True
    except Exception:
        traceback.print_exc()
        return False


class _KillOnCloseJob:
    """Windows job object that ties llama-server's lifetime to the bridge.

    atexit cleanup only runs on a clean interpreter exit. Closing the desktop
    app mid-boot, a crash or Task Manager skipped it and left llama-server
    holding port 8080 and the VRAM, so the next launch refused to start a
    model. With KILL_ON_JOB_CLOSE, Windows kills every assigned process the
    moment the last handle to the job closes, i.e. when this process ends.
    Best effort: elsewhere, or if Windows refuses the assignment, the atexit
    path still applies."""

    _KILL_ON_JOB_CLOSE = 0x2000
    _EXTENDED_LIMIT_INFORMATION = 9

    def __init__(self):
        self._lock = threading.Lock()
        self._handle = None
        self._failed = sys.platform != "win32"

    def _create(self):
        import ctypes
        from ctypes import wintypes

        class _BasicLimits(ctypes.Structure):
            _fields_ = [("PerProcessUserTimeLimit", ctypes.c_int64),
                        ("PerJobUserTimeLimit", ctypes.c_int64),
                        ("LimitFlags", wintypes.DWORD),
                        ("MinimumWorkingSetSize", ctypes.c_size_t),
                        ("MaximumWorkingSetSize", ctypes.c_size_t),
                        ("ActiveProcessLimit", wintypes.DWORD),
                        ("Affinity", ctypes.c_size_t),
                        ("PriorityClass", wintypes.DWORD),
                        ("SchedulingClass", wintypes.DWORD)]

        class _IoCounters(ctypes.Structure):
            _fields_ = [(name, ctypes.c_uint64) for name in (
                "ReadOperationCount", "WriteOperationCount", "OtherOperationCount",
                "ReadTransferCount", "WriteTransferCount", "OtherTransferCount")]

        class _ExtendedLimits(ctypes.Structure):
            _fields_ = [("BasicLimitInformation", _BasicLimits),
                        ("IoInfo", _IoCounters),
                        ("ProcessMemoryLimit", ctypes.c_size_t),
                        ("JobMemoryLimit", ctypes.c_size_t),
                        ("PeakProcessMemoryUsed", ctypes.c_size_t),
                        ("PeakJobMemoryUsed", ctypes.c_size_t)]

        k32 = ctypes.WinDLL("kernel32", use_last_error=True)
        k32.CreateJobObjectW.restype = wintypes.HANDLE
        k32.CreateJobObjectW.argtypes = [ctypes.c_void_p, wintypes.LPCWSTR]
        k32.SetInformationJobObject.restype = wintypes.BOOL
        k32.SetInformationJobObject.argtypes = [wintypes.HANDLE, ctypes.c_int,
                                                ctypes.c_void_p, wintypes.DWORD]
        k32.AssignProcessToJobObject.restype = wintypes.BOOL
        k32.AssignProcessToJobObject.argtypes = [wintypes.HANDLE, wintypes.HANDLE]
        handle = k32.CreateJobObjectW(None, None)
        if not handle:
            raise OSError(ctypes.get_last_error(), "CreateJobObjectW failed")
        info = _ExtendedLimits()
        info.BasicLimitInformation.LimitFlags = self._KILL_ON_JOB_CLOSE
        if not k32.SetInformationJobObject(handle, self._EXTENDED_LIMIT_INFORMATION,
                                           ctypes.byref(info), ctypes.sizeof(info)):
            raise OSError(ctypes.get_last_error(), "SetInformationJobObject failed")
        self._k32 = k32
        # Deliberately never closed: the OS closes it when this process ends,
        # which is exactly the moment the children must die.
        self._handle = handle

    def assign(self, proc: "subprocess.Popen") -> bool:
        with self._lock:
            if self._failed:
                return False
            try:
                if self._handle is None:
                    self._create()
                if self._k32.AssignProcessToJobObject(self._handle, int(proc._handle)):
                    return True
                import ctypes
                print(f"[llama] could not tie llama-server to the app (error "
                      f"{ctypes.get_last_error()}); it relies on exit cleanup instead",
                      file=sys.stderr)
            except Exception as e:
                self._failed = True
                print(f"[llama] kill-on-close job unavailable: {e}", file=sys.stderr)
            return False


_child_job = _KillOnCloseJob()


class LlamaProcess:
    """Single llama-server subprocess; thread-safe start / stop / swap-model.

    A watchdog thread polls every WATCHDOG_POLL_S and respawns the subprocess
    with the args of the last successful start(), healing silent crashes (OOM,
    signal, segfault). Guardrails:

      1. _watchdog_disabled, set by stop_permanent() (user stopped the server),
         cleared by the next user-initiated start().
      2. Circuit breaker: >= WATCHDOG_MAX_CRASHES deaths within
         WATCHDOG_WINDOW_S suspends auto-restart, so a doomed config (bad model
         file, wrong mmproj, OOM at this ctx) can't loop forever. It
         self-recovers a bounded number of times after a cooldown.
      3. _watchdog_stop, set by shutdown_watchdog() at bridge exit; checked
         before and after every sleep so the thread exits within ~5s."""

    WATCHDOG_POLL_S = 5.0
    WATCHDOG_MAX_CRASHES = 3
    WATCHDOG_WINDOW_S = 60.0

    def __init__(self):
        self._lock = threading.RLock()
        self._start_lock = threading.Lock()
        self._proc: subprocess.Popen | None = None
        self._loaded_model: str = ""
        # mmproj path the current process started with ("" = text-only), so the chat
        # handler can skip the describe_image side-trip when the model sees images
        # natively.
        self._loaded_mmproj: str = ""
        # Watchdog bookkeeping.
        self._last_start_args: dict | None = None
        self._watchdog_thread: threading.Thread | None = None
        self._watchdog_stop = threading.Event()
        self._watchdog_disabled = False
        self._restart_failed = False
        self._restart_history: list[float] = []
        # Breaker auto-recovery: a tripped breaker retries a bounded number of times
        # after a cooldown instead of waiting for a manual restart.
        self._breaker_trip_at = 0.0
        self._breaker_recoveries = 0
        # True while a user-initiated start() is in flight, so the watchdog doesn't
        # see the brief dead window between stop() and the new spawn and launch a
        # second process with the old args. Released in a finally.
        self._starting = False
        # Ring buffer of the child's combined stdout/stderr, drained by a daemon
        # reader thread, so the UI can show the llama.cpp backend (model-load
        # progress, errors) instead of a hidden or stray console window.
        self._log_lines: list[str] = []
        self._log_lock = threading.Lock()
        self._log_reader: threading.Thread | None = None

    def loaded_model(self) -> str:
        with self._lock:
            return self._loaded_model

    def loaded_mmproj(self) -> str:
        with self._lock:
            return self._loaded_mmproj

    def is_vision_capable(self) -> bool:
        with self._lock:
            return bool(self._loaded_mmproj) and self._proc is not None and self._proc.poll() is None

    def is_running(self) -> bool:
        with self._lock:
            return self._proc is not None and self._proc.poll() is None

    def _append_log(self, line: str) -> None:
        with self._log_lock:
            self._log_lines.append(line)
            if len(self._log_lines) > 800:
                del self._log_lines[:-800]

    def _start_log_reader(self, proc: "subprocess.Popen") -> None:
        # Drain the child's combined stdout/stderr into the ring buffer. Daemon
        # thread; ends on EOF when the process exits or is respawned.
        def _pump():
            try:
                if not proc.stdout:
                    return
                for raw in iter(proc.stdout.readline, ""):
                    self._append_log(raw.rstrip("\r\n"))
            except Exception:
                pass
        t = threading.Thread(target=_pump, name="llama-log", daemon=True)
        t.start()
        self._log_reader = t

    def read_log(self, tail: int = 400) -> dict:
        running = self.is_running()
        model = self.loaded_model()
        with self._log_lock:
            lines = list(self._log_lines[-tail:])
        return {"running": running, "model": model, "lines": lines}

    def stop(self, timeout: float = 5.0) -> bool:
        with self._lock:
            p = self._proc
            self._proc = None
            self._loaded_model = ""
            self._loaded_mmproj = ""
        _llama_props_ctx_invalidate()
        if not p:
            return True
        try:
            p.terminate()
            try:
                p.wait(timeout=timeout)
            except subprocess.TimeoutExpired:
                p.kill()
                p.wait(timeout=2.0)
        except Exception:
            pass
        return True

    # ---- watchdog --------------------------------------------------------
    def stop_permanent(self, timeout: float = 5.0) -> bool:
        """User-initiated stop: terminate llama-server AND tell the watchdog
        not to respawn it. Use this for the UI 'Stop server' action. The next
        successful start() re-enables the watchdog automatically."""
        self._watchdog_disabled = True
        self._restart_history = []
        self._restart_failed = False
        return self.stop(timeout=timeout)

    def watchdog_status(self) -> dict:
        """Snapshot for the UI / debug endpoint."""
        return {
            "enabled": bool(get_settings().get("watchdog_enabled", True)),
            "disabled_by_user": self._watchdog_disabled,
            "circuit_tripped": self._restart_failed,
            "recent_crashes": len(self._restart_history),
            "max_crashes": self.WATCHDOG_MAX_CRASHES,
            "window_s": self.WATCHDOG_WINDOW_S,
            "running": self.is_running(),
            "thread_alive": self._watchdog_thread is not None and self._watchdog_thread.is_alive(),
            "has_last_args": self._last_start_args is not None,
        }

    def reset_circuit_breaker(self) -> None:
        """Clear the crash history so the watchdog will try again. Called
        implicitly by every user-initiated start()."""
        self._restart_history = []
        self._restart_failed = False
        self._breaker_trip_at = 0.0
        self._breaker_recoveries = 0
        self._watchdog_disabled = False

    def shutdown_watchdog(self) -> None:
        """Called from atexit / Ctrl+C handlers. Stops the watchdog thread
        cleanly so it doesn't try to respawn during process teardown."""
        self._watchdog_stop.set()
        t = self._watchdog_thread
        if t is not None and t.is_alive():
            t.join(timeout=2.0)

    def _ensure_watchdog(self) -> None:
        """Lazy-start the polling thread on the first successful start()."""
        if self._watchdog_thread is not None and self._watchdog_thread.is_alive():
            return
        self._watchdog_stop.clear()
        t = threading.Thread(target=self._watchdog_loop, name="llama-watchdog", daemon=True)
        self._watchdog_thread = t
        t.start()

    def _watchdog_loop(self) -> None:
        """Poll loop. Sleeps via Event.wait() so shutdown_watchdog() gets a
        prompt response. Exceptions are logged and swallowed — a watchdog
        that crashes itself defeats the whole point."""
        while not self._watchdog_stop.is_set():
            if self._watchdog_stop.wait(self.WATCHDOG_POLL_S):
                return
            try:
                self._maybe_restart()
            except Exception as e:
                print(f"[watchdog] error: {e!r}", file=sys.stderr)

    def _maybe_restart(self) -> None:
        """Per-tick check. Returns silently in any of the suspend states."""
        # Global settings toggle, checked every tick so it takes effect on the next
        # poll.
        try:
            if not bool(get_settings().get("watchdog_enabled", True)):
                return
        except Exception:
            pass
        if self._watchdog_disabled or self._restart_failed:
            return
        if self._starting:
            return  # user-initiated start() in flight; the brief proc-is-dead
                    # window between stop() and the new spawn is not a crash
        if self._last_start_args is None:
            return  # never had a successful start to remember
        if self.is_running():
            return  # process is fine

        # Process is dead. Apply the circuit breaker.
        now = time.time()
        self._restart_history = [t for t in self._restart_history if now - t < self.WATCHDOG_WINDOW_S]
        if len(self._restart_history) >= self.WATCHDOG_MAX_CRASHES:
            # Breaker tripped: self-recover a bounded number of times after a fresh
            # cooldown (whatever wedged the first boot, such as VRAM held by another app,
            # is usually gone by then); only a persistent crash loop stays suspended.
            if (now - self._breaker_trip_at >= self.WATCHDOG_WINDOW_S + 30.0
                    and self._breaker_recoveries < 2):
                self._breaker_recoveries += 1
                self._restart_history = []
                self._restart_failed = False
                self._breaker_trip_at = 0.0
                msg = (f"llama-server stayed down after {self.WATCHDOG_MAX_CRASHES} crashes — "
                       f"auto-recovery attempt {self._breaker_recoveries}/2 "
                       "(fresh circuit-breaker cycle, self-healing launch args)")
                print(f"[watchdog] {msg}", file=sys.stderr)
                try:
                    broadcast_event({"type": "llama:watchdog_restart",
                                     "attempt": 4, "delay": 0,
                                     "recovery": self._breaker_recoveries})
                except Exception:
                    pass
            else:
                if self._breaker_trip_at == 0.0:
                    self._breaker_trip_at = now
                self._restart_failed = True
                msg = (
                    f"llama-server crashed {len(self._restart_history)} times in "
                    f"{int(self.WATCHDOG_WINDOW_S)}s; auto-restart suspended. "
                    f"Fix the config (model path, ctx size, mmproj), then pick "
                    f"the model again in the model menu to resume."
                )
                print(f"[watchdog] {msg}", file=sys.stderr)
                try:
                    broadcast_event({"type": "llama:watchdog_stuck", "message": msg})
                except Exception:
                    pass
                return

        self._restart_history.append(now)
        # Exponential backoff: 2s, 4s, 8s. The wait is cancellable so a
        # graceful shutdown during backoff still exits in ~1s.
        delay = float(1 << len(self._restart_history))  # 2, 4, 8
        attempt = len(self._restart_history)
        print(
            f"[watchdog] llama-server is dead — restart attempt {attempt}/"
            f"{self.WATCHDOG_MAX_CRASHES} in {delay:.0f}s",
            file=sys.stderr,
        )
        # The exit code and the last output lines tell an out-of-memory kill from
        # an assert or a bad flag; the record used to carry neither.
        try:
            with self._lock:
                code = self._proc.poll() if self._proc is not None else None
            with self._log_lock:
                tail = list(self._log_lines[-40:])
            _error_store.record("backend", "ModelServerCrash",
                                f"llama-server died (exit code {code}); restart attempt {attempt}",
                                "llama-server",
                                f"exit code: {code}\nlast llama-server output:\n" + "\n".join(tail))
        except Exception:
            pass
        try:
            broadcast_event({
                "type": "llama:watchdog_restart",
                "attempt": attempt,
                "delay": delay,
            })
        except Exception:
            pass
        if self._watchdog_stop.wait(delay):
            return  # bridge shutting down, abort restart

        try:
            args = dict(self._last_start_args)
        except Exception:
            args = {}
        # Self-heal BEFORE the respawn: restart reads settings fresh, so a
        # degrade here takes effect on this very attempt. Attempt 1 is always
        # a plain retry (transient crash); 2+ steps the config down.
        if attempt >= 2:
            _watchdog_self_heal(attempt)
            # An explicit ctx override rides the replayed args, not settings —
            # step it down too or the degrade above would be bypassed.
            if int(args.get("ctx_override") or 0) > 0:
                args["ctx_override"] = max(4096, int(args["ctx_override"]) // 2)
        # _last_start_args was captured at successful-start time. The circuit breaker
        # is deliberately not reset here, so each respawn counts toward the limit.
        try:
            res = self.start(_from_watchdog=True, **args)
        except Exception as e:
            print(f"[watchdog] restart raised: {e!r}", file=sys.stderr)
            return
        if res.get("ok"):
            print(f"[watchdog] llama-server back up (pid {res.get('pid')})", file=sys.stderr)
            try:
                broadcast_event({"type": "llama:watchdog_restored", "pid": res.get("pid")})
            except Exception:
                pass
        else:
            print(f"[watchdog] restart failed: {res.get('error')}", file=sys.stderr)

    def start(self, model_path: str, wait: bool = True, wait_seconds: int = 120,
              _from_watchdog: bool = False,
              port_override: int = 0, mmproj_override: str = None,
              ctx_override: int = 0, ngl_override: int = -1) -> dict:
        # Guard the call with the _starting flag so the watchdog leaves a transition
        # alone. Setting it before reset_circuit_breaker() and the inner stop() closes
        # the race where a settings-driven reload is caught mid-load by a watchdog
        # tick that spawns a duplicate with the old args. Released in a finally.
        if not self._start_lock.acquire(blocking=False):
            return {"ok": False, "error": "A model is already starting. Wait for it to finish."}
        self._starting = True
        try:
            return self._start_impl(model_path=model_path, wait=wait,
                                    wait_seconds=wait_seconds,
                                    _from_watchdog=_from_watchdog,
                                    port_override=port_override,
                                    mmproj_override=mmproj_override,
                                    ctx_override=ctx_override,
                                    ngl_override=ngl_override)
        finally:
            self._starting = False
            self._start_lock.release()

    def _start_impl(self, model_path: str, wait: bool = True,
                    wait_seconds: int = 120,
                    _from_watchdog: bool = False,
                    port_override: int = 0, mmproj_override: str = None,
                    ctx_override: int = 0, ngl_override: int = -1) -> dict:
        # A user-initiated start clears the circuit breaker and re-enables the
        # watchdog; watchdog retries skip this so each attempt counts toward the
        # crash limit.
        if not _from_watchdog:
            self.reset_circuit_breaker()
        bin_path = find_llama_bin()
        if not bin_path:
            return {"ok": False, "error": "llama-server.exe not found. Set llama_bin in Settings or install llama.cpp."}
        if not model_path or not safe_exists(model_path):
            return {"ok": False, "error": f"model not found: {model_path}"}
        # Which optional flags does THIS build understand? Gates every
        # spawn-time flag decision below (unknown flags hard-exit the server).
        caps = llama_caps(bin_path)

        s = get_settings()
        port = port_override if port_override > 0 else _parse_llama_port()
        # Context size: 32k default, hard ceiling 1M tokens. Large windows are viable
        # because --n-cpu-moe spills weights rather than KV cache; the KV cost at big
        # ctx is the user's call.
        ctx_raw = ctx_override if ctx_override > 0 else int(s.get("num_ctx") or 32768)
        ctx = min(max(ctx_raw, 512), 1_048_576) if ctx_raw > 0 else 32768
        n_batch = max(int(s.get("num_batch") or 2048), 32)
        n_ubatch_raw = int(s.get("n_ubatch") or 0)
        n_ubatch = n_ubatch_raw if n_ubatch_raw > 0 else min(max(n_batch // 2, 512), 4096)
        ngl_setting = ngl_override if ngl_override >= 0 else int(s.get("num_gpu") or 99)
        ngl = -1 if ngl_setting >= 99 else ngl_setting
        n_threads = int(s.get("num_thread") or 0)  # 0 = let llama-server pick
        n_parallel = max(int(s.get("n_parallel") or 1), 1)
        n_cpu_moe = max(int(s.get("n_cpu_moe") or 0), 0)
        kv_type = (s.get("kv_cache_type") or "q8_0").strip().lower()
        if kv_type not in ("f16", "bf16", "f32", "q8_0", "q4_0", "q5_0", "q5_1", "q4_1"):
            kv_type = "q8_0"
        # Split K/V: V cache may be typed separately ("" = mirror K). K is the
        # sensitive half; V at 4-bit is near-lossless (llama.cpp KV-quant data).
        kv_type_v = (s.get("kv_cache_type_v") or "").strip().lower()
        if kv_type_v not in ("f16", "bf16", "f32", "q8_0", "q4_0", "q5_0", "q5_1", "q4_1"):
            kv_type_v = kv_type
        flash_on = bool(s.get("flash_attn", True))
        # Speculative strategy, honoring the legacy flag. get_settings() merges
        # DEFAULTS (spec_strategy="ngram-mod") into `s`, so a true legacy settings.json
        # (only enable_speculative) must be detected on the raw file. The legacy
        # `enable_speculative=false` veto applies only when the raw file has no
        # spec_strategy key; once one exists on disk it wins, since auto-tune and the
        # UI write it deliberately.
        spec_strategy = (s.get("spec_strategy") or "").strip().lower()
        _raw_settings = load_json(SETTINGS_FILE, {})
        _has_spec_key = isinstance(_raw_settings, dict) and "spec_strategy" in _raw_settings
        if s.get("enable_speculative") is False and not _has_spec_key:
            spec_strategy = "off"
        elif spec_strategy not in ("off", "ngram-mod", "draft-mtp", "dflash", "dspark"):
            spec_strategy = "ngram-mod" if bool(s.get("enable_speculative", True)) else "off"
            
        if spec_strategy == "draft-mtp" and model_path:
            # Fall back to ngram-mod or off if the model has no MTP layers, the
            # build lacks draft-mtp, or it's a known distilled model.
            model_lower = os.path.basename(model_path).lower()
            _EXCLUDE_MTP = ("distil", "distill", "distilled", "glm")
            forced_fallback = False
            if not caps.get("draft_mtp", True):
                forced_fallback = True
                print("[llama] this llama-server build has no draft-mtp support — falling back", file=sys.stderr)
            elif any(e in model_lower for e in _EXCLUDE_MTP):
                forced_fallback = True
            else:
                try:
                    gg = read_gguf_metadata(model_path)
                    if gg.get("ok") and not gg.get("has_mtp"):
                        forced_fallback = True
                except Exception as e:
                    print(f"[llama] failed to read GGUF metadata for MTP verification: {e}")
            
            if forced_fallback:
                # Determine fallback: disable speculative decoding entirely for MoE,
                # use ngram-mod speculative decoding for dense models.
                is_moe = False
                try:
                    gg = read_gguf_metadata(model_path)
                    if gg.get("ok"):
                        is_moe = gg.get("expert_count", 0) > 1
                    else:
                        is_moe = any(x in model_lower for x in ("moe", "mixtral", "deepseek", "qwen-moe", "qwen_moe"))
                except Exception:
                    pass
                
                spec_strategy = "off" if is_moe else "ngram-mod"
                print(f"[llama] forcing spec_strategy='{spec_strategy}' fallback for model lacking MTP layers: {os.path.basename(model_path)}")
                
        _RUNTIME_LAUNCH["spec_draft_n"] = 0      # set again below if MTP drafts
        no_warmup = bool(s.get("no_warmup", False))
        enable_metrics = bool(s.get("enable_metrics", False))
        extra_args_raw = (s.get("llama_extra_args") or "").strip()

        # Projector mode is explicit; "off" must never fall through to
        # auto-detection.
        if mmproj_override is not None:
            mmproj_path = mmproj_override if safe_exists(mmproj_override) else ""
        else:
            mode = _normalized_mmproj_mode(s)
            configured_mmproj = str(s.get("mmproj_path") or "").strip()
            mmproj_path = _resolve_mmproj_for_tune(model_path, s)
            if mode == "manual" and configured_mmproj and not mmproj_path:
                print(f"[llama] WARN manual mmproj_path is missing: {configured_mmproj}")
            elif mode == "auto" and mmproj_path:
                print(f"[llama] auto-detected vision projector: {mmproj_path}")
        spec_strategy = _runtime_spec_strategy(spec_strategy, mmproj_path)
        spec_draft_model = str(s.get("spec_draft_model") or "").strip()

        # Stop any existing instance first.
        with self._lock:
            running = self._proc is not None and self._proc.poll() is None
        if running:
            self.stop()

        # If something *else* is squatting on the port (e.g. user launched
        # llama-server manually before bridge), refuse rather than fight it.
        try:
            with socket.create_connection(("127.0.0.1", port), timeout=0.8):
                return {"ok": False, "error": f"Port {port} is already in use. The existing process was left running; no model was started."}
        except OSError:
            pass

        cmd = [
            bin_path,
            "-m", model_path,
            "--host", "127.0.0.1",
            "--port", str(port),
            "--jinja",
            "--no-context-shift",
            "-ngl", str(ngl),
            "-c", str(ctx),
            "-b", str(n_batch),
            "-ub", str(n_ubatch),
            "--cache-type-k", kv_type,
            "--cache-type-v", kv_type_v,
            # --cache-reuse is deliberately not passed: its KV-shift reuse corrupts
            # positional info on some models (repetition / looping), most visibly after a
            # large tool result reshapes the middle of the context, and llama-server
            # disables it anyway for MTP contexts. No explicit --cache-ram either (the
            # 8192 MiB default is fine). Prompt prefix caching (cache_prompt) stays on.
            "--parallel", str(n_parallel),
            "--reasoning-format", "deepseek",
        ]
        # -ngl -1 lets llama.cpp's --fit (on by default) place layers, and its
        # default 1024 MiB per-device margin quietly pushed weights and KV to system
        # RAM whenever the tuner's exact fit left less free (176k ctx on a 4090: 2.6
        # GB offloaded, 93 -> 28 tok/s). The tuner keeps its own margin, so fit stays
        # only as a safety net for a real shortage at boot.
        if ngl == -1 and caps.get("fit_target"):
            cmd += ["--fit-target", "384"]
        if caps.get("flash_attn", True):
            cmd += ["--flash-attn", "on" if flash_on else "off"]
        elif flash_on:
            print("[llama] this build has no --flash-attn flag; using the binary default", file=sys.stderr)
        try:
            # Context checkpoints are a manual compatibility override (see
            # _checkpoint_spawn_flags).
            _ck_flags = _checkpoint_spawn_flags(caps, inspect_model(model_path))
            if _ck_flags:
                cmd += _ck_flags
                print(f"[llama] context checkpoints on (hybrid/SWA model): {' '.join(_ck_flags)}",
                      file=sys.stderr)
        except Exception:
            pass
        if mmproj_path:
            # Loads the vision tower + projector. After this, /v1/chat/completions
            # accepts {type:"image_url", image_url:{url:"data:..."}} content blocks.
            cmd += ["--mmproj", mmproj_path]
            if "moondream" in Path(model_path).stem.lower():
                # Moondream 2 has no built-in jinja template that works with llama.cpp's
                # multimodal message extraction; without one it emits a stop token at once or
                # hallucinates.
                cmd += ["--chat-template", "Question: {{messages[0].content}}\n\nAnswer:"]
        if n_threads > 0:
            cmd += ["-t", str(n_threads)]
        if n_cpu_moe > 0:
            if caps.get("n_cpu_moe", True):
                # --n-cpu-moe (alias -ncmoe) keeps `n` MoE expert tensors on the CPU, so giant
                # MoE models run on small VRAM at a latency cost instead of OOMing.
                cmd += ["--n-cpu-moe", str(n_cpu_moe)]
                # GPU cache for the offloaded experts (llama.cpp #29887): hot
                # experts run on the GPU, only misses cross PCIe. Sized by the
                # tuner; 0 = off.
                try:
                    moe_cache = int(s.get("moe_cache_mib") or 0)
                except (TypeError, ValueError):
                    moe_cache = 0
                if moe_cache > 0 and caps.get("moe_cache"):
                    cmd += ["--moe-cache-mib", str(moe_cache)]
            elif caps.get("override_tensor"):
                # Older build without --n-cpu-moe: -ot pushes ALL expert tensors
                # to CPU (coarser — no per-layer count — but the model boots).
                cmd += ["-ot", ".ffn_.*_exps.=CPU"]
                print("[llama] build lacks --n-cpu-moe; falling back to -ot .ffn_.*_exps.=CPU (all experts on CPU)",
                      file=sys.stderr)
            else:
                print("[llama] WARN build supports neither --n-cpu-moe nor -ot; "
                      "expert offload skipped — big MoEs may OOM", file=sys.stderr)
        if spec_strategy == "ngram-mod":
            # llama.cpp renamed --spec-ngram-size-n to --spec-ngram-mod-n-match
            # in recent builds. The capability probe picks the flag this binary
            # actually understands; with neither, speculative turns itself off
            # instead of hard-exiting the server at startup.
            if caps.get("ngram_mod", False):
                cmd += [
                    "--spec-type", "ngram-mod",
                    "--spec-ngram-mod-n-match", "24",
                    "--spec-ngram-mod-n-min", "48",
                    "--spec-ngram-mod-n-max", "64",
                ]
            elif caps.get("ngram_legacy"):
                cmd += [
                    "--spec-type", "ngram-mod",
                    "--spec-ngram-size-n", "24",
                    "--spec-draft-n-min", "48",
                    "--spec-draft-n-max", "64",
                ]
                print("[llama] using legacy n-gram flag names (older build)", file=sys.stderr)
            else:
                print("[llama] this build supports no n-gram speculative flags — spec_strategy→off",
                      file=sys.stderr)
        elif spec_strategy == "draft-mtp":
            # Multi-token prediction draft. Needs MTP heads in the model (Qwen 3.5/3.6,
            # DeepSeek V3/R1) and a llama.cpp build with PR #22673; without heads
            # llama-server exits at startup with "no MTP layers found".
            # Draft length: the tuner's per-model pick (spec_draft_n_max), else 3. Not the
            # GGUF head count: one MTP head drafts several tokens in a row (4090 / 27B Q4,
            # chained with ngram-mod: n-max 1 -> 70 tok/s, 2 -> 88, 3 -> 93, 4 -> 92).
            # Every draft is verified by the full model, so length only trades speed.
            try:
                spec_n_max = int(s.get("spec_draft_n_max") or 0)
            except (TypeError, ValueError):
                spec_n_max = 0
            spec_n_max = min(max(spec_n_max, 1), 8) if spec_n_max > 0 else 3
            _RUNTIME_LAUNCH["spec_draft_n"] = spec_n_max
            if caps.get("ngram_mod", False):
                # Chained drafters (llama.cpp PR #20981 / #23269): MTP drafts a few
                # high-quality tokens per step and n-gram backs it up with longer, cheaper
                # drafts. Per-type length flags: the n-gram range lives on
                # --spec-ngram-mod-n-*, --spec-draft-n-max sets the MTP length. Chaining gains
                # nothing on builds older than #23269 and has a reported CUDA OOM (#23154);
                # spec_strategy=draft-mtp is the safe fallback.
                cmd += [
                    "--spec-type", "draft-mtp,ngram-mod",
                    "--spec-draft-n-max", str(spec_n_max),
                    "--spec-ngram-mod-n-match", "24",
                    "--spec-ngram-mod-n-min", "48",
                    "--spec-ngram-mod-n-max", "64",
                ]
            else:
                cmd += [
                    "--spec-type", "draft-mtp",
                    "--spec-draft-n-max", str(spec_n_max),
                ]
        elif spec_strategy in ("dflash", "dspark"):
            # DFlash and DSpark use a separate draft network trained for the exact target
            # model. Validate a configured path against the target before trusting it,
            # and otherwise fall back to the validated on-disk pair, unless the decoder
            # was explicitly unloaded (spec_draft_mode=off): then no draft is attached.
            resolved_draft = ""
            _pairing_off = str(s.get("spec_draft_mode") or "auto").strip().lower() == "off"
            if _pairing_off:
                print(f"[llama] {spec_strategy}: decoder unloaded by user — "
                      f"spec_strategy→off", file=sys.stderr)
            else:
                if spec_draft_model and safe_exists(spec_draft_model):
                    match = spec_draft_match(model_path, spec_draft_model)
                    draft_readable = bool((match.get("draft") or {}).get("ok"))
                    target_readable = bool(_spec_fingerprint(model_path).get("ok"))
                    if match.get("matched") or not (draft_readable and target_readable):
                        resolved_draft = spec_draft_model
                        if not match.get("matched"):
                            print(f"[llama] {spec_strategy}: draft metadata unreadable — "
                                  f"using configured {os.path.basename(spec_draft_model)} unverified",
                                  file=sys.stderr)
                    else:
                        print(f"[llama] {spec_strategy}: configured draft does not match the model "
                              f"({'; '.join(match.get('reasons') or [])}) — trying auto-pair",
                              file=sys.stderr)
                if not resolved_draft:
                    paired = find_spec_draft_for(model_path) if model_path else {}
                    if paired.get("matched"):
                        resolved_draft = paired.get("path") or ""
                        if resolved_draft:
                            note = (f"{spec_strategy.upper()}: auto-paired {os.path.basename(resolved_draft)} "
                                    f"({'; '.join(paired.get('reasons') or [])})")
                            print(f"[llama] {note}", file=sys.stderr)
                            try:
                                broadcast_event({"type": "notice", "note": note, "quiet": False})
                            except Exception:
                                pass
            if caps.get(spec_strategy) and resolved_draft:
                # CLI type names are prefixed draft- (draft-dflash / draft-dspark)
                # even though the settings value is the short form.
                cmd += ["--spec-draft-model", resolved_draft, "--spec-type",
                        {"dflash": "draft-dflash", "dspark": "draft-dspark"}.get(
                            spec_strategy, spec_strategy)]
                print(f"[llama] speculative decoding: {spec_strategy} ({os.path.basename(resolved_draft)})",
                      file=sys.stderr)
            else:
                print(f"[llama] {spec_strategy} needs a supported build and matching draft GGUF — spec_strategy→off",
                      file=sys.stderr)
        # "off" emits nothing.
        # The MTP draft's KV cache stays at llama.cpp's f16 default on purpose: q8_0
        # (-ctkd/-ctvd) saves 240 MiB of draft KV but grows the two draft compute
        # buffers 392 -> 928 MiB each, a net 830 MiB loss (4090, 27B, 131k, ub 1024).
        # Auto-YaRN: running ctx past the trained context without rope scaling
        # degrades long-range attention on many architectures. When the saved ctx
        # exceeds the GGUF-trained max and the build supports it, enable YaRN; a rope
        # flag in llama_extra_args always wins.
        if caps.get("rope_scaling") and "rope" not in extra_args_raw.lower():
            try:
                _gg_yarn = read_gguf_metadata(model_path)
                _trained = int(_gg_yarn.get("context_length") or 0)
                if _trained > 0 and ctx > _trained:
                    cmd += ["--rope-scaling", "yarn"]
                    print(f"[llama] ctx {ctx:,} > trained max {_trained:,} — auto-enabling YaRN rope scaling",
                          file=sys.stderr)
            except Exception:
                pass
        if no_warmup:
            cmd += ["--no-warmup"]
        if enable_metrics:
            cmd += ["--metrics"]
        if extra_args_raw:
            # A whitespace split covers the typical extras (--alias foo, --rope-scaling
            # linear, ...).
            try:
                import shlex
                cmd += shlex.split(extra_args_raw, posix=False)
            except Exception:
                cmd += extra_args_raw.split()
        # Log the exact command before spawning so unknown-flag crashes are
        # debuggable: it can be pasted into a shell to see the real error.
        try:
            import shlex as _shlex
            print(f"[llama] launch: {_shlex.join(cmd) if hasattr(_shlex, 'join') else ' '.join(cmd)}")
        except Exception:
            print(f"[llama] launch: {cmd}")
        try:
            creationflags = 0
            # Always run windowless and capture stdout+stderr so the backend's
            # load progress and errors surface in the app's Backend tab, instead
            # of a hidden (desktop app) or stray (browser mode) console window.
            creationflags = subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0
            with self._log_lock:
                self._log_lines.clear()
            self._append_log("[accuretta] launching: " + " ".join(cmd))
            p = subprocess.Popen(
                cmd,
                cwd=str(Path(bin_path).parent),
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                bufsize=1,
                encoding="utf-8",
                errors="replace",
                creationflags=creationflags,
            )
            _child_job.assign(p)
            self._start_log_reader(p)
        except Exception as e:
            return {"ok": False, "error": f"spawn failed: {e}"}

        with self._lock:
            self._proc = p
            self._loaded_model = model_path
            self._loaded_mmproj = mmproj_path
        if not port_override:
            _last_prompt_tokens_by_chat.clear()
            _CTX_EST_CACHE.clear()
        # Remember exactly how to respawn this configuration. The watchdog replays
        # these args verbatim (the last known-good launch), deliberately ignoring
        # settings changed in between. wait=False keeps the watchdog non-blocking.
        self._last_start_args = {
            "model_path": model_path,
            "wait": False,
            "wait_seconds": wait_seconds,
            "port_override": port_override,
            "mmproj_override": mmproj_override,
            "ctx_override": ctx_override,
            "ngl_override": ngl_override,
        }
        self._ensure_watchdog()

        if not wait:
            return {"ok": True, "pid": p.pid, "model": model_path,
                    "ready": False, "mmproj": mmproj_path,
                    "vision_capable": bool(mmproj_path)}
        base_url = f"http://127.0.0.1:{port}"
        if wait_for_llama(wait_seconds, base_url=base_url):
            # The launched ctx is now proven to fit on this machine; stamp it so
            # boot-time retunes honor it. Prefer the server's own reported ctx (it can
            # clamp below the request).
            if not port_override:
                try:
                    _live_ctx = _llama_props_ctx()
                except Exception:
                    _live_ctx = None
                _stamp_proven_boot(model_path, int(_live_ctx or ctx))
            return {"ok": True, "pid": p.pid, "model": model_path,
                    "ready": True, "mmproj": mmproj_path,
                    "vision_capable": bool(mmproj_path)}
        # if we waited but nothing came up, the child likely died
        if p.poll() is not None:
            with self._lock:
                self._proc = None
                self._loaded_model = ""
                self._loaded_mmproj = ""
            return {"ok": False, "error": f"llama-server exited (code {p.returncode}) — check the model file or VRAM."}
        return {"ok": False, "error": "llama-server didn't answer in time. Still loading; check the spawned window."}


_llama = LlamaProcess()
_vision_llama = LlamaProcess()


def llama_ping(timeout: float = 2.0, base_url: str = None) -> bool:
    """Return whether a llama-server process is answering HTTP requests."""
    if base_url is None:
        base_url = LLAMA
    try:
        with urllib.request.urlopen(f"{base_url}/v1/models", timeout=timeout) as r:
            r.read(1)
        return True
    except Exception:
        return False


def llama_ready(timeout: float = 2.0, base_url: str = None) -> bool:
    """Return true only after llama.cpp reports that model loading is done."""
    if base_url is None:
        base_url = LLAMA
    try:
        with urllib.request.urlopen(f"{base_url}/health", timeout=timeout) as response:
            payload = response.read(1024)
            if response.status != 200:
                return False
            if not payload:
                return True
            try:
                status = str(json.loads(payload.decode("utf-8")).get("status") or "").lower()
            except Exception:
                return True
            return status in {"", "ok", "ready"}
    except urllib.error.HTTPError as exc:
        # Older llama.cpp builds did not expose /health. Their model-list
        # endpoint is the best readiness signal available.
        if exc.code == 404:
            return llama_ping(timeout=timeout, base_url=base_url)
        return False
    except Exception:
        return False




def wait_for_llama(wait_seconds: int = 30, base_url: str = None) -> bool:
    """Poll llama-server up to wait_seconds. Returns True once it's up."""
    if base_url is None:
        base_url = LLAMA
    if llama_ready(base_url=base_url):
        return True
    t0 = time.time()
    printed = False
    while time.time() - t0 < wait_seconds:
        time.sleep(0.6)
        if llama_ready(timeout=1.5, base_url=base_url):
            print(f"  llama-server up in {time.time() - t0:.1f}s")
            return True
        if not printed and time.time() - t0 > 2:
            print(f"  waiting for llama-server at {base_url} ...")
            printed = True
    return False


def _start_vision_fallback_if_needed(s: dict) -> None:
    global VISION_LLAMA
    v_model = (s.get("vision_model") or "").strip()
    if os.environ.get("VISION_LLAMA_HOST"):
        return
    # Clear the side server address when fallback vision is removed or the main
    # model has native vision; a stale URL would block the next image turn.
    if _llama.is_vision_capable() or not v_model or not safe_exists(v_model):
        try:
            _vision_llama.stop_permanent()
        except Exception:
            pass
        VISION_LLAMA = LLAMA
        return
    
    main_port = _parse_llama_port()
    v_port = main_port + 1
    
    v_stem = Path(v_model).stem.lower()
    if "qwen2-vl" in v_stem or "qwen2.5-vl" in v_stem or "pixtral" in v_stem or "llava" in v_stem:
        v_mmproj = ""
    else:
        try:
            v_mmproj = find_mmproj_for(v_model)
        except Exception:
            v_mmproj = ""
        
    print(f"  spawning vision fallback server with {os.path.basename(v_model)} on port {v_port} ...")
    res = _vision_llama.start(
        model_path=v_model,
        wait=False,
        wait_seconds=60,
        port_override=v_port,
        mmproj_override=v_mmproj,
        ctx_override=4096,
        ngl_override=0
    )
    if res.get("ok"):
        VISION_LLAMA = f"http://127.0.0.1:{v_port}"
        print(f"  vision fallback: started (pid {res.get('pid')}) at {VISION_LLAMA}")
    else:
        print(f"  [warn] vision fallback didn't start: {res.get('error')}")


