# ============================================================
# DISCORD REMOTE BRIDGE (optional)
# DM accuretta from your phone, with native push notifications, and approve
# risky actions by reacting. Connects OUTBOUND to Discord (no port forwarding,
# no inbound exposure — your PC stays closed). Locked to ONE owner Discord user
# id; everyone else is ignored. Requires: pip install discord.py
# ============================================================
DISCORD_CHAT_ID = "discord"
_discord_state: dict = {"client": None, "loop": None, "running": False}
_discord_approvals: dict = {}          # discord message id -> approval id
_discord_approvals_lock = threading.Lock()


def _discord_split(text: str, limit: int = 1900) -> list[str]:
    """Split a reply into Discord's 2000-char message limit (with headroom)."""
    text = (text or "").strip()
    if not text:
        return ["(empty reply)"]
    out = []
    while text:
        out.append(text[:limit])
        text = text[limit:]
    return out


def _discord_strip_think(text: str) -> str:
    """Discord-only display filter: return the visible answer, hiding reasoning.

    Used only on the Discord reply path (_run_discord_turn) and mirrors the web
    UI's splitThinking boundary (app.js). Chats saved by older builds separate
    reasoning with a bare " response" marker and no closing </think>; that form
    is closed first, so an answer line such as `ResponseEntity<T>` is never
    taken for the boundary."""
    buf = _close_think_marker(text or "")
    if not buf:
        return ""
    # 1. Strip closed reasoning blocks, preserving surrounding prose.
    cleaned = buf
    cleaned = re.sub(r"<\s*think\s*>[\s\S]*?<\s*/\s*think\s*>", "", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(
        r"<\s*(?:thinking|reasoning)\s*>[\s\S]*?<\s*/\s*(?:thinking|reasoning)\s*>",
        "", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(
        r"<\|\s*thinking\s*\|>[\s\S]*?<\|\s*/\s*thinking\s*\|>",
        "", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(
        r"\[(?:thought|thinking|reasoning|scratchpad)\][\s\S]*?\[/(?:thought|thinking|reasoning|scratchpad)\]",
        "", cleaned, flags=re.IGNORECASE)
    if cleaned != buf:
        cleaned = re.sub(
            r"</?(?:think|thinking|reasoning)>|<\|\/?thinking\|>|\[/?(?:thought|thinking|reasoning|scratchpad)\]",
            "", cleaned, flags=re.IGNORECASE)
        return cleaned.strip()
    # 2. Bare closer with no opener, e.g. "planning</think>Answer".
    _closes = list(re.finditer(
        r"<\s*/\s*(?:think|thinking|reasoning)\s*>|<\|\s*/\s*thinking\s*\|>"
        r"|\[/\s*(?:thought|thinking|reasoning|scratchpad)\s*\]",
        buf, flags=re.IGNORECASE))
    if _closes:
        tail = buf[_closes[-1].end():]
        tail = re.sub(
            r"</?(?:think|thinking|reasoning)>|<\|\/?thinking\|>|\[/?(?:thought|thinking|reasoning|scratchpad)\]",
            "", tail, flags=re.IGNORECASE)
        return tail.strip()
    # 3. Unclosed opener (in-flight thinking, no answer yet) -> prefix only.
    _open = re.search(
        r"<\s*(?:think|thinking|reasoning)\s*>|<\|\s*thinking\s*\|>"
        r"|\[(?:thought|thinking|reasoning|scratchpad)\]",
        buf, flags=re.IGNORECASE)
    if _open:
        return buf[:_open.start()].strip()
    return buf.strip()


_DISCORD_FRIEND_PROMPT = (
    "you are accuretta, a local AI running on the owner's machine, chatting casually in a discord "
    "server with the owner's friends. keep replies short and friendly. you have NO tools: you cannot "
    "read, write, or delete files, run commands, scan anything, or touch the machine in any way. if "
    "someone asks you to do work like that, tell them only the owner can ask you to do real work."
)


def _run_discord_turn(user_text: str, chat_id: str, use_tools: bool) -> str:
    """Run one Discord turn. The owner (use_tools=True) gets the full agent with
    tools; everyone else gets a locked chat-only turn that cannot touch the
    machine. Tool approvals fire on the event bus and mirror to Discord. Returns
    the visible reply. Never raises."""
    try:
        if not llama_ping(timeout=2.0):
            return "im offline right now"
        chats = get_chats()
        chat = chats["chats"].setdefault(chat_id, {
            "id": chat_id, "title": chat_id, "messages": [],
            "created": int(time.time()),
        })
        chat.setdefault("messages", [])
        chat["messages"].append({"role": "user", "content": user_text})
        global _last_user_text
        _last_user_text = user_text
        discord_ctx = dict(_client_context_by_chat.get(chat_id) or {})
        discord_ctx.setdefault("execution_target", "host")
        discord_ctx["_user_text"] = user_text
        _client_context_by_chat[chat_id] = discord_ctx
        _update_task_anchor(chat, user_text)
        _enforce_chat_retention(chat)
        chat["updated"] = int(time.time())
        save_json(CHATS_FILE, chats)
        if (use_tools and get_settings().get("desktop_enabled")
                and _user_asked_desktop_interaction(user_text)):
            _unlock_bundle(chat_id, "desktop")

        replay_from = 0
        # Gemma over discord gets the same text-tools routing as the web UI:
        # llama-server can't parse its dialect, so keep tools in the prompt but
        # off the wire and let extract_tool_calls handle the tool_code shape.
        _gm = any(_is_gemma_model(m) for m in
                  (get_settings().get("model"), get_settings().get("model_path"), _llama.loaded_model()))
        _text_tools = _gm or _native_tools_broken()

        if use_tools:
            # Owner path: same long-session memory as the web UI (token-aware rolling
            # summary + pins, replaying only the un-folded tail).
            ctx_limit = _llama_props_ctx() or int(get_settings().get("num_ctx") or 32768)
            if get_settings().get("summarize_history", True):
                try:
                    _drop_force = _last_dropped_by_chat.get(chat_id, False)
                    if _drop_force:
                        # Same gate as the web pre-turn: a mid-turn fold usually recovered the
                        # overflow already, so don't force-fold the next message at low fill.
                        _fill_now = _last_prompt_tokens_by_chat.get(chat_id, 0)
                        if _fill_now > 0 and _fill_now < _summary_trigger_limit(ctx_limit) * 0.7:
                            _drop_force = False
                    _log_compact(chat_id, f"pre_turn discord: fill={_last_prompt_tokens_by_chat.get(chat_id, 0)} "
                                          f"trigger={_summary_trigger_limit(ctx_limit)} ctx={ctx_limit} "
                                          f"drop_flag={_last_dropped_by_chat.get(chat_id, False)} force={_drop_force}")
                    if _maybe_roll_summary(chat, ctx_limit,
                                           force=_drop_force,
                                           reason_hint="pre_turn"):
                        save_json(CHATS_FILE, chats)
                except Exception:
                    traceback.print_exc()
            if get_settings().get("red_team_enabled") and get_settings().get("rt_mission_state", True):
                try:
                    if _rt_authorized_mission(chat) and _rt_mission_seed(chat, user_text):
                        save_json(CHATS_FILE, chats)
                except Exception:
                    traceback.print_exc()
            _set_current_chat(chat_id)
            system_prompt = build_system_prompt(include_tools=True, chat_mode="agent",
                                                include_tool_list=_text_tools)
            # Mission block + pins are not spliced here; run_chat_turn appends them after
            # the history (see its volatile-tail block). Only the rolling summary and the
            # static pin_note nudge stay in the system prompt.
            _roll = chat.get("rolling_summary", "")
            if _roll:
                system_prompt += ("\n\n=== EARLIER IN THIS SESSION (older turns condensed to save context; "
                                  "treat as established facts — do not redo work or re-ask) ===\n" + _roll)
            system_prompt += ("\n\nWhen you fix a bug, settle a design decision, or the user states a constraint, "
                              "call pin_note to lock it in for this session so you never undo it or repeat the mistake.")
            if _text_tools:
                system_prompt += _text_tools_prompt(_gm)
            replay_from = int(chat.get("summary_through", 0) or 0)
        else:
            system_prompt = _DISCORD_FRIEND_PROMPT
        msgs = [{"role": "system", "content": system_prompt}]
        for m in chat["messages"][replay_from:]:
            role = m.get("role")
            if role not in ("user", "assistant", "tool"):
                continue
            out = {"role": role, "content": m.get("content", "") or ""}
            if role == "assistant" and m.get("tool_calls"):
                out["tool_calls"] = m["tool_calls"]
            if role == "tool":
                if m.get("tool_call_id"):
                    out["tool_call_id"] = m["tool_call_id"]
                if m.get("name"):
                    out["name"] = m["name"]
            msgs.append(out)
        msgs = _ensure_user_anchor(msgs, chat["messages"], replay_from)

        final = run_chat_turn(chat_id, msgs, use_tools=use_tools, emit=lambda e: None,
                              native_tools=not _text_tools)
        if not final:
            return "(no reply — stopped or empty)"

        # persist intermediate tool rounds + the final assistant message so the
        # next message has continuity.
        chats = get_chats()
        chat = chats["chats"].get(chat_id)
        if chat is not None:
            _completed_turn_id = str(final.pop("_turn_id", "") or "")
            _mu = final.get("_mission_updates")
            if isinstance(_mu, dict):
                chat["mission"] = _mu
            _au = final.get("_activity_updates")
            if isinstance(_au, list):
                chat["activity"] = [a for a in _au if isinstance(a, dict)][-_ACTIVITY_MAX:]
            _vu = final.get("_verification_updates")
            if isinstance(_vu, list):
                chat["verification_debt"] = [x for x in _vu if isinstance(x, dict)]
            _cu = final.get("_continuity_updates")
            if isinstance(_cu, dict):
                chat["continuity"] = _cu
            else:
                _refresh_continuity_state(chat)
            for im in (final.get("_appended_intermediate") or []):
                if _completed_turn_id and isinstance(im, dict):
                    im = {**im, "_turn_id": _completed_turn_id}
                chat["messages"].append(im)
            amsg = {"role": "assistant", "content": final.get("content", "")}
            if _completed_turn_id:
                amsg["_turn_id"] = _completed_turn_id
            if final.get("tool_calls"):
                amsg["tool_calls"] = final["tool_calls"]
            chat["messages"].append(amsg)
            chat["updated"] = int(time.time())
            save_json(CHATS_FILE, chats)
            _turn_journal_clear(chat_id, _completed_turn_id)
        return _discord_strip_think(final.get("content", "")) or "(done)"
    except Exception as e:
        traceback.print_exc()
        return f"error: {e}"


def _discord_approval_listener(client) -> None:
    """Subscribe to the event bus and mirror every approval:new to the owner's
    DM as a ✅/❌ reaction prompt. A reaction resolves the same approval the
    browser would — first responder wins."""
    import asyncio
    owner_id = str(get_settings().get("discord_owner_id") or "").strip()
    q, _snap = subscribe()

    async def post_approval(entry):
        try:
            owner = await client.fetch_user(int(owner_id))
            ch = owner.dm_channel or await owner.create_dm()
            title = entry.get("title", "approval")
            cmd = str(entry.get("command", ""))[:1500]
            msg = await ch.send(f"approve: **{title}**\n```\n{cmd}\n```\nreact ✅ approve · ❌ deny")
            await msg.add_reaction("✅")
            await msg.add_reaction("❌")
            with _discord_approvals_lock:
                _discord_approvals[msg.id] = entry.get("id")
        except Exception as e:
            print(f"[discord] approval post failed: {e}", flush=True)

    while _discord_state.get("running"):
        try:
            evt = q.get(timeout=1.0)
        except Exception:
            continue
        if isinstance(evt, dict) and evt.get("type") == "approval:new":
            loop = _discord_state.get("loop")
            entry = evt.get("approval") or {}
            if loop and entry:
                approval_id = str(entry.get("id") or "")

                def _send_approval_dm(e=entry) -> bool:
                    try:
                        asyncio.run_coroutine_threadsafe(post_approval(e), loop).result(timeout=30)
                        return True
                    except Exception as err:
                        print(f"[discord] approval post failed: {err}", flush=True)
                        return False

                # Suppress-then-escalate: held while the user looks active, delivered as soon
                # as they look absent or at the escalation deadline. The pending approval is
                # durable bridge state, so a held DM can never lose a gate.
                _presence_notify.post_external(
                    key=f"approval:{approval_id}",
                    kind="approval",
                    title=str(entry.get("title") or "approval"),
                    body=str(entry.get("command") or "")[:1500],
                    send=_send_approval_dm,
                    resolved=lambda aid=approval_id: aid and all(
                        str(a.get("id")) != aid for a in list_approvals()
                    ),
                )
        elif isinstance(evt, dict) and evt.get("type") == "approval:decided":
            _presence_notify.resolve(f"approval:{evt.get('id')}")
    unsubscribe(q)


def _discord_start() -> None:
    """Run the Discord bot (blocking — call in a daemon thread). Outbound only."""
    s = get_settings()
    token = (s.get("discord_bot_token") or "").strip()
    owner_id = str(s.get("discord_owner_id") or "").strip()
    if not token or not owner_id:
        print("[discord] enabled but bot token / owner id missing — not starting.", flush=True)
        return
    try:
        import discord
    except Exception:
        print("[discord] discord.py not installed. run: pip install discord.py", flush=True)
        return

    intents = discord.Intents.default()
    intents.message_content = True  # requires Message Content Intent in the dev portal
    intents.reactions = True        # ✅/❌ approval taps (in default already; explicit to be sure)
    client = discord.Client(intents=intents)
    _discord_state["client"] = client
    _discord_state["running"] = True
    _discord_state["approval_listener_started"] = False   # reset per bot start

    @client.event
    async def on_ready():
        _discord_state["loop"] = client.loop
        print(f"[discord] connected as {client.user}. obeying owner id {owner_id}.", flush=True)
        # on_ready fires on every reconnect/resume; start the approval listener once
        # per bot run, or every approval gets DM'd once per reconnect.
        if not _discord_state.get("approval_listener_started"):
            _discord_state["approval_listener_started"] = True
            threading.Thread(target=_discord_approval_listener, args=(client,), daemon=True).start()

    @client.event
    async def on_message(message):
        try:
            if client.user and message.author.id == client.user.id:
                return
            is_owner = str(message.author.id) == owner_id
            is_dm = message.guild is None
            mentioned = bool(client.user) and client.user in getattr(message, "mentions", [])
            # DMs are always handled; in a server channel only respond when the
            # bot is actually @mentioned (so it ignores normal chatter).
            if not is_dm and not mentioned:
                return
            print(f"[discord] incoming author={message.author.id} owner={owner_id!r} "
                  f"is_owner={is_owner} is_dm={is_dm} mentioned={mentioned} "
                  f"content={(message.content or '')[:40]!r}", flush=True)
            text = (message.content or "").strip()
            if client.user:
                text = text.replace(f"<@{client.user.id}>", "").replace(f"<@!{client.user.id}>", "").strip()
            if not text:
                return
            # owner => full agent with tools; everyone else => locked chat-only,
            # in their own per-user chat so friends never touch the owner's
            # context (or the machine).
            use_tools = is_owner
            chat_id = DISCORD_CHAT_ID if is_owner else f"discord-{message.author.id}"
            async with message.channel.typing():
                reply = await client.loop.run_in_executor(
                    None, _run_discord_turn, text, chat_id, use_tools)
            for chunk in _discord_split(reply):
                await message.channel.send(chunk)
        except Exception as e:
            print(f"[discord] on_message error: {e}", flush=True)

    @client.event
    async def on_raw_reaction_add(payload):
        # raw event fires for EVERY reaction regardless of message cache —
        # on_reaction_add silently missed approval taps (uncached DM messages).
        try:
            if client.user and payload.user_id == client.user.id:
                return  # our own ✅/❌ seeding on the card
            emoji = str(payload.emoji)
            # accept the exact card emojis plus common near-misses a phone
            # keyboard offers (✔️ ☑️ ❎ ✖️) — variation selectors don't matter
            is_yes = any(mark in emoji for mark in ("✅", "✔", "☑"))
            is_no = any(mark in emoji for mark in ("❌", "❎", "✖"))
            if str(payload.user_id) != owner_id:
                # Log ignored reactions so a reaction from a non-owner account isn't a silent
                # dead end.
                print(f"[discord] reaction ignored: user {payload.user_id} is not "
                      f"the configured owner {owner_id} (emoji={emoji!r})", flush=True)
                return
            if not (is_yes or is_no):
                print(f"[discord] reaction ignored: {emoji!r} is not an approve/deny "
                      f"emoji — tap ✅ or ❌ on the approval card", flush=True)
                return
            with _discord_approvals_lock:
                aid = _discord_approvals.get(payload.message_id)
            # message_author_id is on the raw payload (discord.py 2.4+); lets us
            # tell "stale approval prompt of ours" from "some other message".
            own_msg = bool(client.user) and getattr(payload, "message_author_id", None) == client.user.id
            try:
                print(f"[discord] reaction user={payload.user_id} msg={payload.message_id} "
                      f"emoji={emoji!r} matched_approval={aid} own_msg={own_msg}", flush=True)
            except Exception:
                pass  # a hostile console must never kill the decision below

            async def _reply(text):
                try:
                    owner = await client.fetch_user(int(owner_id))
                    ch = owner.dm_channel or await owner.create_dm()
                    await ch.send(text)
                except Exception as _e:
                    print(f"[discord] reaction reply failed: {_e}", flush=True)

            if not aid:
                # No live approval for this message: only reply if it is clearly one of our
                # own stale prompts, so a restart or timeout isn't a silent dead end.
                if own_msg:
                    await _reply("that approval is no longer active — the bridge restarted or it timed out. "
                                 "re-run the action to get a fresh prompt.")
                return
            ok = decide_approval(aid, "approve" if is_yes else "deny")
            with _discord_approvals_lock:
                _discord_approvals.pop(payload.message_id, None)
            await _reply(("✅ approved — continuing." if is_yes else "❌ denied.") if ok
                         else "that approval already resolved or expired.")
        except Exception as e:
            print(f"[discord] reaction error: {e}", flush=True)

    try:
        client.run(token, log_handler=None)
    except Exception as e:
        print(f"[discord] bot stopped: {e}", flush=True)
    finally:
        _discord_state["running"] = False


def _prune_red_team_evidence(settings: dict, now: float | None = None) -> dict:
    """Apply the configured evidence retention policy at startup."""
    ev_dir = DATA / "recon_evidence"
    if not ev_dir.exists():
        return {"removed": 0, "kept": 0, "days": None}
    try:
        days = max(0, min(3650, int(settings.get("rt_evidence_retention_days", 30))))
    except (TypeError, ValueError):
        days = 30
    now = time.time() if now is None else float(now)
    cutoff = now - days * 86400
    removed = 0
    kept = 0
    try:
        for item in ev_dir.rglob("*"):
            try:
                if not item.is_file():
                    continue
                expired = days == 0 or item.stat().st_mtime < cutoff
                if not expired:
                    kept += 1
                    continue
                if item.is_file():
                    item.unlink()
                elif item.is_dir():
                    shutil.rmtree(item)
                removed += 1
            except Exception:
                kept += 1
    except Exception:
        pass
    return {"removed": removed, "kept": kept, "days": days}


_WORKSPACE_WATCH_STOP = threading.Event()
_WORKSPACE_WATCH_LOCK = threading.Lock()
_WORKSPACE_WATCHERS: dict[str, object] = {}
_WORKSPACE_EVENT_TIMER: threading.Timer | None = None


def _workspace_roots() -> set[str]:
    roots: set[str] = set()
    for raw in get_workspace().get("folders") or []:
        try:
            path = Path(raw).resolve()
            if path.is_dir():
                roots.add(os.path.normcase(str(path)))
        except Exception:
            continue
    return roots


def _broadcast_workspace_update_debounced(delay: float = 0.4) -> None:
    global _WORKSPACE_EVENT_TIMER

    def _fire() -> None:
        global _WORKSPACE_EVENT_TIMER
        with _WORKSPACE_WATCH_LOCK:
            _WORKSPACE_EVENT_TIMER = None
        if not _WORKSPACE_WATCH_STOP.is_set():
            broadcast_event({"type": "workspace:update"})

    with _WORKSPACE_WATCH_LOCK:
        if _WORKSPACE_EVENT_TIMER is not None:
            _WORKSPACE_EVENT_TIMER.cancel()
        _WORKSPACE_EVENT_TIMER = threading.Timer(delay, _fire)
        _WORKSPACE_EVENT_TIMER.daemon = True
        _WORKSPACE_EVENT_TIMER.start()


class _WindowsWorkspaceWatcher:
    """Recursive ReadDirectoryChangesW watcher for one workspace root."""

    def __init__(self, root: str):
        self.root = root
        self._stop = threading.Event()
        self._handle_lock = threading.Lock()
        self._handle = None
        self._thread = threading.Thread(
            target=self._run, name=f"workspace-watch:{Path(root).name}", daemon=True)

    def start(self) -> None:
        self._thread.start()

    def is_alive(self) -> bool:
        return self._thread.is_alive()

    def stop(self) -> None:
        self._stop.set()
        try:
            import ctypes
            from ctypes import wintypes
            kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
            cancel_io = kernel32.CancelIoEx
            cancel_io.argtypes = (wintypes.HANDLE, wintypes.LPVOID)
            cancel_io.restype = wintypes.BOOL
            with self._handle_lock:
                handle = self._handle
            if handle:
                cancel_io(handle, None)
        except Exception:
            pass

    def _run(self) -> None:
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        create_file = kernel32.CreateFileW
        create_file.argtypes = (
            wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD, wintypes.LPVOID,
            wintypes.DWORD, wintypes.DWORD, wintypes.HANDLE)
        create_file.restype = wintypes.HANDLE
        read_changes = kernel32.ReadDirectoryChangesW
        read_changes.argtypes = (
            wintypes.HANDLE, wintypes.LPVOID, wintypes.DWORD, wintypes.BOOL,
            wintypes.DWORD, wintypes.LPDWORD, wintypes.LPVOID, wintypes.LPVOID)
        read_changes.restype = wintypes.BOOL
        close_handle = kernel32.CloseHandle
        close_handle.argtypes = (wintypes.HANDLE,)
        close_handle.restype = wintypes.BOOL

        invalid = ctypes.c_void_p(-1).value
        notify_filter = 0x00000001 | 0x00000002 | 0x00000008 | 0x00000010 | 0x00000040
        while not self._stop.is_set() and not _WORKSPACE_WATCH_STOP.is_set():
            handle = create_file(
                self.root, 0x0001, 0x00000001 | 0x00000002 | 0x00000004,
                None, 3, 0x02000000, None)
            if not handle or handle == invalid:
                if self._stop.wait(10):
                    return
                continue
            with self._handle_lock:
                self._handle = handle
            try:
                buffer = ctypes.create_string_buffer(65536)
                while not self._stop.is_set() and not _WORKSPACE_WATCH_STOP.is_set():
                    returned = wintypes.DWORD()
                    ok = read_changes(
                        handle, buffer, len(buffer), True, notify_filter,
                        ctypes.byref(returned), None, None)
                    if self._stop.is_set() or _WORKSPACE_WATCH_STOP.is_set():
                        break
                    if ok:
                        # A zero-byte success means the kernel buffer overflowed.
                        # Refresh anyway; the slow scanner below repairs any gap.
                        _broadcast_workspace_update_debounced()
                    else:
                        break
            finally:
                with self._handle_lock:
                    self._handle = None
                close_handle(handle)
            if not self._stop.is_set():
                self._stop.wait(1)


def _workspace_native_supervisor() -> None:
    while not _WORKSPACE_WATCH_STOP.is_set():
        wanted = _workspace_roots()
        with _WORKSPACE_WATCH_LOCK:
            current = set(_WORKSPACE_WATCHERS)
            for root in current - wanted:
                watcher = _WORKSPACE_WATCHERS.pop(root)
                watcher.stop()
            for root in wanted:
                watcher = _WORKSPACE_WATCHERS.get(root)
                if watcher is None or not watcher.is_alive():
                    if watcher is not None:
                        watcher.stop()
                    watcher = _WindowsWorkspaceWatcher(root)
                    _WORKSPACE_WATCHERS[root] = watcher
                    watcher.start()
        _WORKSPACE_WATCH_STOP.wait(2)


def _workspace_fallback_scanner() -> None:
    """Slow repair pass for unsupported filesystems and lost native events."""
    snapshot: dict[str, tuple[float, int]] = {}
    skip_dirs = {
        ".git", ".hg", ".svn", ".idea", ".vscode", "node_modules",
        "__pycache__", ".pytest_cache", ".mypy_cache", ".ruff_cache",
        ".venv", "venv", ".tox", "dist", "build", ".next", ".nuxt",
        ".cache", "coverage", "target",
    }
    first_scan = True
    while not _WORKSPACE_WATCH_STOP.is_set():
        try:
            current: dict[str, tuple[float, int]] = {}
            for root in _workspace_roots():
                for dirpath, dirnames, filenames in os.walk(root):
                    dirnames[:] = [d for d in dirnames
                                   if not d.startswith(".") and d.lower() not in skip_dirs]
                    for filename in filenames:
                        name = filename.lower()
                        if name.startswith(".") or name.endswith((".pyc", ".log")):
                            continue
                        path = Path(dirpath) / filename
                        try:
                            stat = path.stat()
                            current[str(path)] = (stat.st_mtime, stat.st_size)
                        except Exception:
                            continue
            if not first_scan and current != snapshot:
                _broadcast_workspace_update_debounced()
            snapshot = current
            first_scan = False
        except Exception:
            pass
        _WORKSPACE_WATCH_STOP.wait(60)


def _start_workspace_watching() -> None:
    _WORKSPACE_WATCH_STOP.clear()
    threading.Thread(
        target=_workspace_fallback_scanner, name="workspace-safety-scan", daemon=True).start()
    if os.name == "nt":
        threading.Thread(
            target=_workspace_native_supervisor, name="workspace-watch-supervisor",
            daemon=True).start()


def _stop_workspace_watching() -> None:
    global _WORKSPACE_EVENT_TIMER
    _WORKSPACE_WATCH_STOP.set()
    with _WORKSPACE_WATCH_LOCK:
        for watcher in _WORKSPACE_WATCHERS.values():
            watcher.stop()
        _WORKSPACE_WATCHERS.clear()
        if _WORKSPACE_EVENT_TIMER is not None:
            _WORKSPACE_EVENT_TIMER.cancel()
            _WORKSPACE_EVENT_TIMER = None


class AccurettaHTTPServer(ThreadingHTTPServer):
    allow_reuse_address = False
    daemon_threads = True

    def server_bind(self):
        if hasattr(socket, "SO_EXCLUSIVEADDRUSE"):
            self.socket.setsockopt(socket.SOL_SOCKET, socket.SO_EXCLUSIVEADDRUSE, 1)
        super().server_bind()


def _bootstrap_skill_assets() -> None:
    """Ship bundled skill templates (skill_assets/<name>/) into the user's
    workspace, copy-if-missing so user edits are never clobbered. Kept out of the
    skills/ catalogue: this is raw file material the agent copies per project
    (the code-driven-motion-graphics engine), not a loadable .md procedure."""
    try:
        src_root = ROOT / "skill_assets"
        if not src_root.is_dir():
            return
        folders = [f for f in (get_workspace().get("folders") or []) if str(f).strip()]
        if not folders:
            return
        target_root = Path(folders[0])
        for src_dir in sorted(src_root.iterdir()):
            if not src_dir.is_dir():
                continue
            dst_dir = target_root / src_dir.name
            if dst_dir.exists():
                continue
            shutil.copytree(
                src_dir, dst_dir,
                ignore=shutil.ignore_patterns("node_modules", "out", "__pycache__", ".venv"),
            )
            print(f"  [skills] provisioned template into workspace: {dst_dir}", flush=True)
    except Exception as exc:
        print(f"  [skills] template provision failed: {exc}", flush=True)


def main():
    # Binding is the process-wide ownership check, before MCP or model startup.
    try:
        httpd = AccurettaHTTPServer(("0.0.0.0", PORT), Handler)
    except OSError:
        print(f"Port {PORT} is already in use. No model was started. Check the existing Accuretta window or choose another port.")
        return
    try:
        _main_owned(httpd)
    finally:
        httpd.server_close()


def _main_owned(httpd):
    if _offline_active:
        install_offline_guard()
    else:
        _load_mcp_servers()
    print("accuretta bridge")
    print(f"  root:    {ROOT}")
    print(f"  llama:   {LLAMA}")
    if VISION_LLAMA and VISION_LLAMA != LLAMA:
        print(f"  vision:  {VISION_LLAMA}")
    print(f"  port:    {PORT}")
    print("  bind:    0.0.0.0  (reachable over LAN / Tailscale)")

    _jr = _recover_turn_journals()
    if _jr.get("recovered") or _jr.get("stale") or _jr.get("invalid"):
        print(f"  recovery: {_jr['recovered']} interrupted turn(s), "
              f"{_jr['entries']} tool entries; {_jr['stale']} stale, {_jr['invalid']} invalid")

    # Evidence must survive a restart long enough to verify the report that cites
    # it: kept 30 days by default; 0 wipes it on boot.
    _ev_ret = _prune_red_team_evidence(get_settings())
    if _ev_ret.get("days") is not None:
        print(f"  evidence: kept {_ev_ret['kept']}, removed {_ev_ret['removed']} "
              f"(retention {_ev_ret['days']} day(s))")

    # first-run system context scan (creates data/ACCURETTA.md if missing)
    if not SYSTEM_CONTEXT_FILE.exists():
        print("  scanning system (first run) ...")
        ensure_system_context()
        print(f"  wrote:   {SYSTEM_CONTEXT_FILE}")
    else:
        print(f"  context: {SYSTEM_CONTEXT_FILE} (edit or delete to rescan)")

    # Make the spawned llama-server die with us. atexit runs callbacks in reverse
    # order, so stop() registers first (runs last) and shutdown_watchdog() second
    # (runs first): the watchdog must not be polling when the subprocess is killed,
    # or it races to respawn it. Registered before the boot spawn below, which can
    # block up to 120s, so quitting during it doesn't orphan llama-server.
    import atexit
    try:
        _install_error_hooks()
    except Exception:
        pass
    atexit.register(_session_mgr.stop_all)   # kill any interactive sessions on exit
    atexit.register(_stop_workspace_watching)
    atexit.register(notch_stop)              # the overlay dies with the bridge
    atexit.register(_llama.stop)
    atexit.register(_llama.shutdown_watchdog)
    atexit.register(_vision_llama.stop)
    atexit.register(_vision_llama.shutdown_watchdog)

    # Auto-spawn llama-server with the last-loaded model, unless something already
    # answers on LLAMA_HOST (a user-launched server is left alone).
    s_initial = get_settings()
    last_model = (s_initial.get("model_path") or "").strip()
    if llama_ping(timeout=1.0):
        print(f"  llama-server: already running at {LLAMA} (using existing instance)")
        try:
            info = llama_get("/v1/models")
            names = [m.get("id") for m in (info.get("data") or []) if m.get("id")]
            if names and not s_initial.get("model"):
                s_initial["model"] = names[0]
                save_json(SETTINGS_FILE, s_initial)
        except Exception:
            pass
    elif last_model and safe_exists(last_model):
        model_name = os.path.basename(last_model)
        print(f"  spawning llama-server with {model_name} ...")
        res = _llama.start(last_model, wait=True, wait_seconds=120)
        if res.get("ok"):
            print(f"  llama-server: ready (pid {res.get('pid')})")
            _start_vision_fallback_if_needed(s_initial)
        else:
            print(f"  [warn] llama-server didn't start: {res.get('error')}")
            print("         pick a different model or update settings via the UI.")
    elif last_model:
        # The remembered model was moved or deleted. Say so where the user
        # looks (Backend tab, model pill) instead of a console nobody sees.
        print(f"  [warn] last model not found: {last_model}")
        print("         pick another model from the model menu.")
        _llama._append_log(f"[accuretta] last model not found: {last_model}")
        _llama._append_log("[accuretta] it was moved or deleted, so no model was started. "
                           "Pick a model from the model menu to start the backend.")
    else:
        bin_path = find_llama_bin()
        if not bin_path:
            print("  [warn] llama-server.exe not found.")
            print("         install llama.cpp or set llama_bin in Settings.")
        elif not s_initial.get("models_dir"):
            print("  [info] no models folder set yet.")
            print("         open Settings -> Models folder, pick where your .gguf files live.")
        else:
            print("  [info] no model loaded yet. Pick one in Settings -> Models.")

    httpd.daemon_threads = True
    url = f"http://localhost:{PORT}"
    print(f"\nopen {url}  — or from phone, http://<tailscale-ip>:{PORT}")

    # Open the browser shortly after bind, in a thread so serve_forever owns the
    # main thread. ACCURETTA_BROWSER picks the browser:
    #   chrome | firefox | edge | brave | opera | vivaldi | none | default
    def _open_browser():
        time.sleep(0.8)
        choice = (os.environ.get("ACCURETTA_BROWSER") or "").strip().lower()
        if choice in ("none", "off", "skip", "no"):
            print(f"  [info] ACCURETTA_BROWSER={choice} — not auto-opening a browser. Visit {url} in any browser.")
            return
        # Map short names to common Windows install paths + executable names.
        candidates = {
            "chrome":  ["chrome.exe", r"C:\Program Files\Google\Chrome\Application\chrome.exe", r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe"],
            "firefox": ["firefox.exe", r"C:\Program Files\Mozilla Firefox\firefox.exe", r"C:\Program Files (x86)\Mozilla Firefox\firefox.exe"],
            "edge":    ["msedge.exe", r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe", r"C:\Program Files\Microsoft\Edge\Application\msedge.exe"],
            "brave":   ["brave.exe", r"C:\Program Files\BraveSoftware\Brave-Browser\Application\brave.exe", r"C:\Program Files (x86)\BraveSoftware\Brave-Browser\Application\brave.exe"],
            "opera":   ["opera.exe", os.path.expandvars(r"%LOCALAPPDATA%\Programs\Opera\opera.exe")],
            "vivaldi": ["vivaldi.exe", os.path.expandvars(r"%LOCALAPPDATA%\Vivaldi\Application\vivaldi.exe")],
        }
        if choice and choice in candidates:
            import shutil, subprocess
            exe = None
            for c in candidates[choice]:
                p = shutil.which(c) if not os.path.sep in c else (c if os.path.exists(c) else None)
                if p:
                    exe = p
                    break
            if exe:
                try:
                    subprocess.Popen([exe, url], close_fds=True)
                    print(f"  [info] opened {choice} -> {url}")
                    return
                except Exception as e:
                    print(f"  [warn] failed to launch {choice} ({e}); falling back to default browser.")
            else:
                print(f"  [warn] ACCURETTA_BROWSER={choice} but {choice} not found; falling back to default browser.")
        try:
            webbrowser.open(url)
        except Exception:
            pass
    threading.Thread(target=_open_browser, daemon=True).start()

    _start_workspace_watching()
    _bootstrap_skill_assets()

    # Notch overlay: spawn the host process when enabled. It waits patiently
    # for this server to start answering, so launching before serve_forever
    # is fine.
    try:
        if get_settings().get("notch_enabled"):
            if notch_start():
                print("  notch:   overlay host started")
            else:
                print("  notch:   enabled but host unavailable (Windows + WebView2, or macOS + PyObjC/WebKit)")
    except Exception:
        pass

    # Discord remote bridge — outbound only, owner-locked. Daemon thread so it
    # never blocks shutdown; fully optional and self-disabling if misconfigured.
    if not _offline_active and get_settings().get("discord_enabled"):
        threading.Thread(target=_discord_start, daemon=True).start()
        print("  discord: bridge starting (DM the bot from your phone)")

    # Scheduled security overviews — background read-only scans while the app
    # runs; notable alerts surface in the popup near the security button and
    # (optionally) the owner's Discord DM.
    if not _offline_active:
        _security_apply_schedule(get_settings())
        _security_overview.start_scheduler()
        if _security_overview.schedule_seconds():
            print(f"  security: scheduled overview every "
                  f"{_security_overview.schedule_seconds() // 60} min")
        threading.Thread(target=_security_boot_scan, daemon=True).start()

    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\nstopping.")
    finally:
        _stop_workspace_watching()
        # Stop the watchdog FIRST so it doesn't observe the impending
        # subprocess death and try to "heal" it during shutdown.
        try:
            _llama.shutdown_watchdog()
            _vision_llama.shutdown_watchdog()
        except Exception:
            pass
        try:
            _llama.stop()
            _vision_llama.stop()
        except Exception:
            pass


if __name__ == "__main__":
    try:
        main()
    except Exception:
        try:
            with open("crash_log.txt", "w", encoding="utf-8") as f:
                traceback.print_exc(file=f)
        except Exception:
            pass
        raise
